-- Fourteen corrected TCF reading banks. Immutable inserts and guarded publication pointers only.
-- Preserve early Q1-24, historical banks, attempts, user state and all other modules.
begin;
do $preflight$ begin
 if (select count(*) from academy_tcf_reading.published_papers)<>20 then raise exception 'Expected twenty published reading papers'; end if;
 if (select count(*) from academy_tcf_reading.published_papers where test_id in ('tcf-reading-07','tcf-reading-08','tcf-reading-09','tcf-reading-10','tcf-reading-11','tcf-reading-12','tcf-reading-13','tcf-reading-14','tcf-reading-15','tcf-reading-16','tcf-reading-17','tcf-reading-18','tcf-reading-19','tcf-reading-20') and version='tcf-reading-2026-11-reference-v3')<>14 then raise exception 'All fourteen prior pointers must be reviewed v3'; end if;
 if exists(select 1 from academy_tcf_reading.papers where id in ('tcf-reading-07','tcf-reading-08','tcf-reading-09','tcf-reading-10','tcf-reading-11','tcf-reading-12','tcf-reading-13','tcf-reading-14','tcf-reading-15','tcf-reading-16','tcf-reading-17','tcf-reading-18','tcf-reading-19','tcf-reading-20') and version='tcf-reading-2026-11-close-reading-v4') then raise exception 'Do not overwrite immutable v4 papers'; end if;
end $preflight$;

insert into academy_tcf_reading.papers(id,version,content) values
('tcf-reading-07','tcf-reading-2026-11-close-reading-v4',$paper_7${"id":"tcf-reading-07","title":"TCF Reading · Test 07","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["L'ouverture de la poissonnerie","Le retrait de commandes payées","La livraison sans commande","L'achat libre sur tous les stands"],"passage":"Le marché couvert ferme à quatorze heures aujourd'hui. Les commandes déjà payées pourront être retirées jusqu'à quinze heures à l'entrée nord.\n\nPrésentez votre reçu au personnel chargé des retraits. Les stands alimentaires ne reprendront pas de vente après la fermeture annoncée.","question":"Quel service reste disponible après la fermeture ?","explanation":"Le passage indique : « Le marché couvert ferme à quatorze heures aujourd'hui. Les commandes déjà payées pourront être retirées jusqu'à quinze heures à l'entrée nord. » Cela justifie la réponse : Le retrait de commandes payées."},{"number":2,"points":3,"correct":"C","options":["De la levure","De la farine","Un saladier","Un four"],"passage":"Pour l'atelier pain, apportez un saladier. La farine et la levure sont fournies.\n\nLes participants travailleront par petits groupes. Un rangement collectif est prévu à la fin de la séance.","question":"Que doit apporter le participant ?","explanation":"Le passage indique : « Pour l'atelier pain, apportez un saladier. La farine et la levure sont fournies. » Cela justifie la réponse : Un saladier."},{"number":3,"points":3,"correct":"A","options":["Utiliser un contenant propre","Apporter un sac en papier","Acheter uniquement en espèces","Réserver une semaine avant"],"passage":"Le distributeur de lait ne fonctionne qu'avec des bouteilles propres. Des bouteilles neuves sont vendues à côté.\n\nUn membre de l'équipe peut montrer comment remplir le récipient. Merci de laisser l'espace propre après votre passage.","question":"Quelle condition faut-il respecter ?","explanation":"Le passage indique : « Le distributeur de lait ne fonctionne qu'avec des bouteilles propres. Des bouteilles neuves sont vendues à côté. » Cela justifie la réponse : Utiliser un contenant propre."},{"number":4,"points":3,"correct":"D","options":["À l'entrée de la salle","Le lendemain du repas","Après le dessert","Au moment de l'inscription"],"passage":"Le menu végétarien doit être demandé lors de l'inscription au repas associatif, pas à l'arrivée.\n\nL'équipe préparera les quantités selon les demandes reçues. Elle ne pourra pas garantir un remplacement de plat au dernier moment.","question":"Quand faut-il signaler ce choix ?","explanation":"Le passage indique : « Le menu végétarien doit être demandé lors de l'inscription au repas associatif, pas à l'arrivée. » Cela justifie la réponse : Au moment de l'inscription."},{"number":5,"points":9,"correct":"D","options":["La personne préparant la salade","Le nombre d'invités","Le jour du rendez-vous","Le lieu du repas"],"passage":"J'ai remplacé le pique-nique par un déjeuner chez moi : la pluie est annoncée. Apporte toujours la salade, je préparerai le plat chaud.\n\nLes autres invités ont déjà été prévenus et garderont le même horaire. Nous mangerons autour de la grande table, puis pourrons sortir si le temps s'améliore.","question":"Qu'est-ce qui change dans le programme ?","explanation":"Le passage indique : « J'ai remplacé le pique-nique par un déjeuner chez moi : la pluie est annoncée. Apporte toujours la salade, je préparerai le plat chaud. » Cela justifie la réponse : Le lieu du repas."},{"number":6,"points":9,"correct":"C","options":["Un restaurant réservé aux adhérents","Un cours obligatoire de jardinage","Des conseils pour préparer les légumes","Un remboursement de tous les achats"],"passage":"Votre panier contient des légumes moins habituels. Une fiche de préparation est jointe ; vous pouvez aussi échanger un produit au point de retrait.\n\nLes bénévoles indiquent également les quantités habituelles pour éviter de préparer trop de nourriture.","question":"Quelle aide accompagne le panier ?","explanation":"Le passage indique : « Votre panier contient des légumes moins habituels. Une fiche de préparation est jointe ; vous pouvez aussi échanger un produit au point de retrait. » Cela justifie la réponse : Des conseils pour préparer les légumes."},{"number":7,"points":9,"correct":"C","options":["Une place en terrasse","Un repas gratuit","Une table en salle","Une heure de départ libre"],"passage":"Le restaurant ne réserve plus sa terrasse. Les tables sont attribuées sur place ; la réservation reste possible à l'intérieur.\n\nSi le temps reste agréable, vous pourrez demander une table extérieure à votre arrivée. Le personnel expliquera les disponibilités sans pouvoir les promettre à l'avance.","question":"Que garantit une réservation ?","explanation":"Le passage indique : « Le restaurant ne réserve plus sa terrasse. Les tables sont attribuées sur place ; la réservation reste possible à l'intérieur. » Cela justifie la réponse : Une table en salle."},{"number":8,"points":9,"correct":"B","options":["Prévoir deux desserts par personne","Adapter la quantité aux personnes qui en mangeront","Conserver tout le gâteau pour le lendemain","Réduire le nombre d'invités"],"passage":"Je préfère commander le petit gâteau pour six personnes. Nous serons huit, mais deux invités ne prennent jamais de dessert.\n\nNous partagerons les autres plats sans changer le reste du repas ni demander un format plus grand.","question":"Pourquoi choisir ce format ?","explanation":"Le passage indique : « Je préfère commander le petit gâteau pour six personnes. Nous serons huit, mais deux invités ne prennent jamais de dessert. » Cela justifie la réponse : Adapter la quantité aux personnes qui en mangeront."},{"number":9,"points":9,"correct":"A","options":["Acheter une huile","Respecter l'heure du rendez-vous","S'inscrire à la dégustation","Goûter dans le lieu prévu"],"passage":"La dégustation permet de goûter trois huiles avant achat. Aucun achat n'est imposé aux participants.\n\nLes organisateurs présenteront l'origine des produits et quelques usages possibles. Le rendez-vous est destiné aux curieux comme aux clients habituels du magasin.","question":"Quelle obligation est absente ?","explanation":"Le passage indique : « La dégustation permet de goûter trois huiles avant achat. Aucun achat n'est imposé aux participants. » Cela justifie la réponse : Acheter une huile."},{"number":10,"points":9,"correct":"D","options":["Pour réserver les aliments aux commerçants","Pour interdire les dons gratuits","Pour privilégier les emballages décoratifs","Pour disposer d'informations vérifiables sur les produits"],"passage":"Merci de ne pas déposer de plats faits maison dans le réfrigérateur solidaire. Seuls les produits dont la composition et la date sont identifiables sont acceptés.\n\nUne affiche rappelle les conditions d'accueil pour éviter que des aliments inutilisables soient déposés à côté du réfrigérateur.","question":"Pourquoi certains dépôts sont-ils exclus ?","explanation":"Le passage indique : « Merci de ne pas déposer de plats faits maison dans le réfrigérateur solidaire. Seuls les produits dont la composition et la date sont identifiables sont acceptés. » Cela justifie la réponse : Pour disposer d'informations vérifiables sur les produits."},{"number":11,"points":15,"correct":"B","options":["Un choix toujours identique","La variation saisonnière du panier","Une livraison quotidienne obligatoire","L'absence de légumes locaux"],"passage":"Une ferme vend ses légumes selon les récoltes disponibles. Le contenu des paniers change chaque semaine ; un assortiment identique toute l'année n'est pas promis.\n\nLes adhérents choisissent un point de retrait et reçoivent les informations quelques jours avant la livraison. Une récolte abondante peut permettre un produit supplémentaire, tandis qu'un épisode de grêle oblige à revoir l'assortiment. Le producteur explique ces changements au lieu de remplacer systématiquement les légumes par des achats lointains. Le groupe souhaite conserver une relation claire entre ce qui pousse sur les terres et ce qui arrive dans les paniers.","question":"Quelle caractéristique faut-il accepter ?","explanation":"Le passage indique : « Une ferme vend ses légumes selon les récoltes disponibles. Le contenu des paniers change chaque semaine ; un assortiment identique toute l'année n'est pas promis. » Cela justifie la réponse : La variation saisonnière du panier."},{"number":12,"points":15,"correct":"A","options":["Une découverte progressive","Un changement de menu quotidien imposé","Une consommation forcée","La suppression de tout choix"],"passage":"Une cantine présente un nouvel aliment en petite quantité avant de l'ajouter au menu. Les élèves peuvent le goûter sans devoir finir une grande portion.\n\nLe personnel de cuisine observe les retours et recueille les remarques sans distribuer de note. Les enseignants peuvent préparer la découverte en parlant de l'origine du produit. L'équipe souhaite distinguer le refus d'un goût inconnu et celui d'une préparation particulière.","question":"Quelle approche est choisie ?","explanation":"Le passage indique : « Une cantine présente un nouvel aliment en petite quantité avant de l'ajouter au menu. Les élèves peuvent le goûter sans devoir finir une grande portion. » Cela justifie la réponse : Une découverte progressive."},{"number":13,"points":15,"correct":"A","options":["Une attention continue à la préparation","Le remplacement de la farine par de l'eau","L'absence de toute organisation","L'arrêt définitif des fournées"],"passage":"Le boulanger conserve une pâte d'une fournée à l'autre. Cette pratique demande un suivi régulier ; elle ne permet pas de laisser la préparation sans surveillance.\n\nLe boulanger vérifie l'odeur, la texture et le temps écoulé avant de préparer la suite. Il ajuste certains gestes selon la température de l'atelier. Les apprentis découvrent qu'une recette écrite ne suffit pas toujours à décider du bon moment. Le responsable leur demande de noter leurs observations et de comparer plusieurs fournées. Il souhaite transmettre cette attention au processus, plutôt que promettre une méthode qui fonctionnerait de manière identique sans aucun contrôle des conditions réelles.","question":"Que nécessite cette méthode ?","explanation":"Le passage indique : « Le boulanger conserve une pâte d'une fournée à l'autre. Cette pratique demande un suivi régulier ; elle ne permet pas de laisser la préparation sans surveillance. » Cela justifie la réponse : Une attention continue à la préparation."},{"number":14,"points":15,"correct":"C","options":["L'accès sans limite aux stocks des autres","La fermeture aux nouveaux producteurs","Le respect des créneaux et du nettoyage","La préparation simultanée sans réservation"],"passage":"Une association partage une cuisine entre plusieurs petites entreprises. Les utilisateurs réservent des plages distinctes et nettoient après chaque passage.\n\nLes réservations passent par un tableau commun et les produits restent dans des espaces identifiés. Le responsable présente les équipements à chaque nouveau groupe. Il souhaite éviter qu'un gain économique sur le local entraîne des difficultés de propreté ou de rangement. Les utilisateurs ont donc rédigé des règles simples après avoir essayé plusieurs organisations. Un bilan mensuel permettra de revoir les points qui posent problème sans attendre qu'une dispute entre deux entreprises bloque l'ensemble du fonctionnement de la cuisine.","question":"Quelle règle rend le partage possible ?","explanation":"Le passage indique : « Une association partage une cuisine entre plusieurs petites entreprises. Les utilisateurs réservent des plages distinctes et nettoient après chaque passage. » Cela justifie la réponse : Le respect des créneaux et du nettoyage."},{"number":15,"points":15,"correct":"A","options":["Les ingrédients peuvent changer","La cuisine refuse toute question","Les allergies disparaissent au restaurant","Les indications sont volontairement fausses"],"passage":"Le chef ajoute des indications d'allergènes au menu. Il demande néanmoins aux clients concernés d'en parler à l'équipe, car certaines préparations peuvent évoluer.\n\nLes serveurs disposent d'une fiche commune, mais sont invités à demander confirmation lorsqu'une information manque. Le restaurant souhaite que les clients puissent exprimer leurs besoins sans recevoir une assurance improvisée. Les responsables expliquent aussi les limites liées au travail dans une même cuisine. Ils préfèrent donner une réponse précise, même si elle oblige à renoncer à un plat, plutôt que présenter le menu comme une garantie identique pour toutes les situations ou toutes les modifications demandées pendant le service.","question":"Pourquoi un échange reste-t-il nécessaire ?","explanation":"Le passage indique : « Le chef ajoute des indications d'allergènes au menu. Il demande néanmoins aux clients concernés d'en parler à l'équipe, car certaines préparations peuvent évoluer. » Cela justifie la réponse : Les ingrédients peuvent changer."},{"number":16,"points":15,"correct":"C","options":["Éviter toute dégustation","Mémoriser le prix des serres","Reconnaître une diversité au sein d'un aliment","Choisir uniquement la plus grosse tomate"],"passage":"Un jardin pédagogique cultive plusieurs variétés d'une même tomate. Les enfants comparent formes et goûts plutôt que classer toutes les tomates dans une seule catégorie.\n\nChaque groupe suit quelques plants et note leurs changements avant les récoltes. Une dégustation sera organisée lorsque les fruits seront mûrs. Les enseignants demandent aux enfants de décrire ce qu'ils observent avec leurs propres mots. Ils ne souhaitent pas désigner une variété gagnante une fois pour toutes : certaines conviennent mieux à une salade, d'autres à une sauce.","question":"Quel apprentissage est visé ?","explanation":"Le passage indique : « Un jardin pédagogique cultive plusieurs variétés d'une même tomate. Les enfants comparent formes et goûts plutôt que classer toutes les tomates dans une seule catégorie. » Cela justifie la réponse : Reconnaître une diversité au sein d'un aliment."},{"number":17,"points":15,"correct":"C","options":["L'absence totale de matières premières","Le besoin d'importer tous les légumes","La perte de récoltes difficiles à écouler immédiatement","Le manque de magasins d'électroménager"],"passage":"Une conserverie collecte les surplus de plusieurs fermes. Les producteurs récupèrent une partie des bocaux pour les vendre plus tard.\n\nLes volumes sont annoncés par les exploitants avant chaque tournée. L'équipe vérifie l'état des produits et choisit des recettes adaptées aux quantités disponibles. Les agriculteurs ne récupèrent donc pas nécessairement un produit identique à celui qu'ils ont apporté, mais une préparation qu'ils pourront conserver. Une étiquette indique l'origine et la composition. Le projet cherche à donner une valeur aux excédents, sans encourager volontairement une production inutile.","question":"Quel problème cette activité aide-t-elle à résoudre ?","explanation":"Le passage indique : « Une conserverie collecte les surplus de plusieurs fermes. Les producteurs récupèrent une partie des bocaux pour les vendre plus tard. » Cela justifie la réponse : La perte de récoltes difficiles à écouler immédiatement."},{"number":18,"points":15,"correct":"D","options":["Masquer l'origine des produits","Utiliser tous les restes sans distinction","Supprimer les réfrigérateurs","Vérifier la sécurité des aliments"],"passage":"Un atelier apprend à cuisiner avec des restes. Il distingue les aliments encore utilisables de ceux dont la conservation a été insuffisante.\n\nLes participants apportent des exemples de leur quotidien et discutent des délais au réfrigérateur. Les animateurs insistent sur l'importance de noter les dates et de refroidir correctement certaines préparations. Ils ne présentent pas toute transformation comme une manière d'effacer un défaut de conservation. Les recettes proposées restent simples, afin que les familles puissent les refaire avec leur équipement courant.","question":"Quelle précaution accompagne l'économie ?","explanation":"Le passage indique : « Un atelier apprend à cuisiner avec des restes. Il distingue les aliments encore utilisables de ceux dont la conservation a été insuffisante. » Cela justifie la réponse : Vérifier la sécurité des aliments."},{"number":19,"points":15,"correct":"D","options":["Augmenter les pertes en cuisine","Supprimer tous les produits frais","Fermer plusieurs jours par semaine","Simplifier la gestion des approvisionnements"],"passage":"Un restaurateur raccourcit sa carte pour acheter moins de références et mieux suivre ses stocks. Le nombre de plats diminue, pas celui des services.\n\nLes cuisiniers connaissent mieux les quantités préparées et peuvent utiliser certains ingrédients dans plusieurs recettes. Il suivra les ventes avant de modifier de nouveau la carte. L'objectif est de conserver une offre cohérente avec la taille de l'équipe, plutôt que d'afficher de nombreuses possibilités dont une partie serait souvent indisponible ou préparée sans le soin nécessaire.","question":"Quel objectif guide ce changement ?","explanation":"Le passage indique : « Un restaurateur raccourcit sa carte pour acheter moins de références et mieux suivre ses stocks. Le nombre de plats diminue, pas celui des services. » Cela justifie la réponse : Simplifier la gestion des approvisionnements."},{"number":20,"points":21,"correct":"A","options":["Plus de prévisibilité contre moins de choix instantané","Un prix changeant après chaque livraison","Une suppression de toute relation avec les fermes","Des commandes sans engagement pour les producteurs"],"passage":"Un groupement de consommateurs commande directement à des producteurs. Les prix sont discutés à l'avance pour donner de la visibilité aux deux parties. Les acheteurs acceptent en échange un choix moins immédiat qu'au supermarché. Les volumes sont précisés avant la saison, avec les conditions de retrait et les possibilités d'absence. Les producteurs peuvent ainsi préparer certains investissements et les consommateurs comprendre les engagements pris. Le groupe accepte quelques variations liées à la récolte. Il préfère discuter ces aléas dans un cadre connu plutôt que découvrir une nouvelle condition à chaque commande.","question":"Quel compromis est décrit ?","explanation":"Le passage indique : « Un groupement de consommateurs commande directement à des producteurs. Les prix sont discutés à l'avance pour donner de la visibilité aux deux parties. Les acheteurs acceptent en échange un choix moins immédiat qu'au supermarché. » Cela justifie la réponse : Plus de prévisibilité contre moins de choix instantané."},{"number":21,"points":21,"correct":"B","options":["Les mêmes produits restent disponibles partout","Le menu suit davantage les saisons","Les clients doivent apporter tous leurs légumes","Le service devient uniquement estival"],"passage":"Un restaurant privilégie des légumes de proximité. En hiver, il remplace certains plats plutôt que transporter les mêmes ingrédients de très loin. Les clients retrouveront une indication sur les substitutions, afin de comprendre pourquoi une recette connue évolue. Le chef échange régulièrement avec plusieurs fournisseurs pour prévoir les quantités. Il ne promet pas que tout ingrédient pourra toujours venir du même périmètre. Il souhaite surtout que ses choix suivent une logique expliquée, plutôt que conserver à tout prix une carte identique sans regarder les conditions d'approvisionnement.","question":"Quelle conséquence le choix local a-t-il ?","explanation":"Le passage indique : « Un restaurant privilégie des légumes de proximité. En hiver, il remplace certains plats plutôt que transporter les mêmes ingrédients de très loin. » Cela justifie la réponse : Le menu suit davantage les saisons."},{"number":22,"points":21,"correct":"A","options":["L'aménagement pratique influence les usages","Les enfants refusent tous les verres","La fontaine est inutile","L'eau doit être payante pour être bue"],"passage":"Une école installe une fontaine à eau dans son réfectoire. La consommation augmente surtout après le déplacement des verres à portée des enfants. Les enfants hésitaient auparavant à demander un verre ou devaient quitter leur table pour le trouver. Le changement ne nécessitait pas une autre fontaine, mais une meilleure organisation du service. L'école vérifiera si cette facilité reste effective pendant les périodes d'affluence et si les plus petits peuvent se servir sans difficulté.","question":"Que suggère cette observation ?","explanation":"Le passage indique : « Une école installe une fontaine à eau dans son réfectoire. La consommation augmente surtout après le déplacement des verres à portée des enfants. » Cela justifie la réponse : L'aménagement pratique influence les usages."},{"number":23,"points":21,"correct":"D","options":["L'indépendance complète vis-à-vis du climat","Une quantité identique garantie chaque jour","La disparition du besoin de travail","L'incertitude inhérente à certaines productions"],"passage":"Des agriculteurs accueillent des visiteurs pendant une journée de récolte. Ils expliquent que les volumes varient avec la météo. La rencontre montre un travail soumis à des aléas, et non une production parfaitement prévisible. Les visiteurs voient aussi les préparations et les tâches qui continuent lorsque la météo empêche de travailler dehors. Les agriculteurs expliquent leurs décisions et les possibilités de report. Ils souhaitent éviter qu'une journée agréable à la ferme donne l'image d'un métier toujours prévisible.","question":"Quelle idée la visite aide-t-elle à comprendre ?","explanation":"Le passage indique : « Des agriculteurs accueillent des visiteurs pendant une journée de récolte. Ils expliquent que les volumes varient avec la météo. La rencontre montre un travail soumis à des aléas, et non une production parfaitement prévisible. » Cela justifie la réponse : L'incertitude inhérente à certaines productions."},{"number":24,"points":21,"correct":"C","options":["Démontrer l'inutilité de tous les outils","Réserver l'activité aux professionnels","Faciliter le réemploi des apprentissages à domicile","Augmenter le coût des recettes"],"passage":"Un atelier de cuisine ouvre sans matériel sophistiqué. Les participants refont les gestes avec des ustensiles courants, afin de pouvoir reproduire les recettes chez eux. Les recettes sont choisies pour pouvoir être refaites dans une cuisine ordinaire, avec des quantités faciles à modifier. Les participants discutent de leurs propres contraintes : temps, place et nombre de convives. Le centre préfère une technique réellement réutilisée à une démonstration impressionnante mais impossible à reproduire.","question":"Pourquoi ce choix de matériel ?","explanation":"Le passage indique : « Un atelier de cuisine ouvre sans matériel sophistiqué. Les participants refont les gestes avec des ustensiles courants, afin de pouvoir reproduire les recettes chez eux. » Cela justifie la réponse : Faciliter le réemploi des apprentissages à domicile."},{"number":25,"points":21,"correct":"D","options":["La taille du paquet permet d'estimer les économies, même lorsque la quantité achetée dépasse les besoins du foyer.","La promotion affichée sur un grand format compense normalement les aliments qui restent inutilisés à la fin.","Le prix par kilo permet de classer les formats sans examiner les quantités réellement consommées.","Le prix unitaire aide à comparer, mais les pertes peuvent annuler le gain."],"passage":"Une épicerie affiche le prix au kilo à côté des promotions. Cette information aide à comparer des formats différents, car le paquet le plus gros n'est pas toujours le plus économique. Le commerçant affiche la même unité pour chaque référence et explique où la lire. Les clients peuvent ainsi vérifier si une promotion correspond à leur besoin. Un grand paquet peut rester intéressant pour une famille nombreuse, mais devenir inutile pour une personne qui n'en consommera qu'une partie. Lors d'un essai, un lot familial affiche un prix unitaire inférieur mais entraîne des pertes chez les petits ménages. Le responsable conserve les deux informations côte à côte: coût par kilo et quantité que chacun pense réellement consommer.","question":"Pourquoi le responsable refuse-t-il de classer les offres à partir de la seule taille des emballages ?","explanation":"D associe prix par unité et part réellement utilisée. A/B supposent qu'un grand format demeure avantageux malgré les pertes; C néglige la quantité consommée."},{"number":26,"points":21,"correct":"C","options":["Il privilégie le nombre de convives puis attribue la même portion aux groupes ayant des profils différents.","Il fixe les portions à partir des réservations et élimine la marge afin de réduire les restes.","Croiser effectif, habitudes et marge mesurée afin de limiter les restes sans sous-estimer les besoins.","Il établit le volume de préparation à partir des portions servies lors du précédent événement de même taille."],"passage":"Un traiteur propose des portions modulables selon les convives. Il demande les effectifs définitifs deux jours avant le repas pour ajuster les achats. Les clients peuvent préciser les âges et les habitudes alimentaires de leurs invités. Le traiteur propose ensuite une estimation, sans présenter chaque personne comme une consommation identique. Une petite marge reste prévue pour les imprévus. Les organisateurs souhaitent réduire les restes sans risquer de manquer, et discutent aussi du rangement de ce qui pourrait être conservé après le repas. Deux événements comptant le même nombre d'invités ont récemment produit des besoins très différents parce que la répartition entre enfants et adultes n'était pas la même. Le traiteur ajuste donc le volume prévu, tout en gardant une réserve limitée.","question":"Quel raisonnement guide le calcul des portions du traiteur ?","explanation":"C croise effectif, habitudes et petite marge. A/D infèrent que deux événements de même taille se ressemblent; B supprime la réserve prévue."},{"number":27,"points":21,"correct":"B","options":["Pour organiser les versions familiales selon leur ancienneté et reconnaître ensuite celles jugées les plus authentiques.","Documenter une tradition vivante sans hiérarchiser les variantes transmises entre les familles.","Pour identifier les étapes où la transmission orale a transformé une recette initiale considérée comme stable.","Pour comparer les variantes avec une préparation de référence avant de déterminer celles qui conservent la tradition."],"passage":"Un livre de recettes recueille les plats transmis dans plusieurs familles. Les variantes sont conservées : le comité ne cherche pas une version unique déclarée supérieure aux autres. Ces remarques accompagnent les recettes. Le livre ne cherche pas à séparer une version pure et des copies dégradées, mais à montrer comment une pratique se transmet entre personnes et se transforme avec leurs conditions de vie. Une famille a remplacé un ingrédient introuvable dans sa région d'accueil; une autre l'a conservé en changeant seulement la cuisson. Le comité publie les deux récits avec leur contexte au lieu d'en faire une succession d'erreurs par rapport à une version officielle.","question":"Pourquoi le comité conserve-t-il des récits différents d'un même plat ?","explanation":"B conserve les variantes comme expressions situées d'une tradition, sans hiérarchie canonique. A/D reconstruisent un classement d'authenticité, C présume une recette originelle stable alors que le projet reconnaît les adaptations."},{"number":28,"points":21,"correct":"B","options":["Les différences de durée de pause montrent que les salariés n'expriment pas leurs préférences avec la même précision.","Des contraintes peuvent expliquer des pratiques différentes malgré des préférences déclarées semblables.","La pause courte indique une préférence pour les préparations rapides que les salariés n'avaient pas déclarée.","Les deux services ont reçu des informations nutritionnelles différentes, ce qui explique leurs pratiques malgré les réponses."],"passage":"Une enquête sur les repas au travail mesure la durée disponible autant que les choix alimentaires. Certains salariés disent manger vite, non par préférence, mais à cause de pauses courtes. Les chercheurs regardent les horaires, la distance du lieu de restauration et les possibilités de conserver un repas. Les réponses aideront à choisir des améliorations concrètes, plutôt qu'à adresser uniquement des conseils généraux sans effet sur les conditions du déjeuner. Dans un service, les salariés expriment la même préférence pour un repas préparé que dans un autre, mais disposent de quinze minutes de pause au lieu de quarante-cinq. Le projet prévoit de comparer l'offre et les horaires avant d'interpréter leurs réponses comme de simples choix personnels.","question":"Quelle conclusion l'enquête peut-elle tirer de la différence entre les deux services ?","explanation":"B relie des comportements différents aux contraintes de temps malgré des goûts proches. A/C réinterprètent sans preuve les préférences; D suppose une différence de formation non mentionnée."},{"number":29,"points":21,"correct":"B","options":["À garantir la rotation des producteurs même lorsqu'un candidat démontre une activité déjà soutenable à long terme.","Tester les ventes et les capacités du producteur avant un engagement durable.","À mesurer principalement la popularité immédiate du produit avant de décider du développement des capacités de production.","À retenir les candidats qui vendent le plus rapidement, indépendamment de leurs possibilités de fabrication ultérieures."],"passage":"Un marché prévoit un stand pour les petits producteurs débutants. Les emplacements tournent chaque mois pour leur permettre de tester la vente avant un engagement plus long. Les participants bénéficient d'un accompagnement pour présenter leurs prix et leurs produits. Ils peuvent ensuite comparer les retours des clients avec leurs capacités de production. Les candidats discuteront de ce qu'ils ont appris avant de décider d'une présence plus régulière. La rotation empêche un participant de monopoliser une place, mais elle ne constitue pas une promesse de clientèle. Un producteur qui reçoit de nombreux compliments peut encore décider de ne pas revenir si ses volumes de fabrication ne suivent pas.","question":"À quoi sert la période de présence limitée au marché ?","explanation":"B propose un essai évaluant retours et capacité de production. A fait de la rotation une fin permanente; C/D privilégient les ventes sans vérifier la soutenabilité."},{"number":30,"points":26,"correct":"C","options":["Deux assiettes portant la même mention ont une composition comparable, même si leurs portions individuelles peuvent varier.","La mention permet de conclure à un choix nutritionnel cohérent, mais ne renseigne pas sur la provenance des ingrédients.","La mention n'établit seule ni l'origine ni la composition du repas.","Les produits disponibles au moment de la préparation définissent l'équilibre du repas davantage que sa présentation."],"passage":"L'étiquette « fait maison » rassure certains clients, mais ne décrit pas à elle seule l'origine des produits ni l'équilibre d'un repas. Une diététicienne invite à poser plusieurs questions plutôt qu'à déduire toutes les qualités d'une seule mention. Elle propose notamment de regarder les quantités et les ingrédients effectivement servis. Le sens d'une mention doit rester précis, pour éviter qu'un seul mot remplace l'ensemble des informations nécessaires à un choix. Deux assiettes portent la même mention, mais l'une utilise une grande part de produits transformés et l'autre comporte davantage de légumes. La mention peut être exacte dans les deux cas, sans résoudre la question de l'équilibre nutritionnel ni celle de l'approvisionnement.","question":"Que montre la comparaison des deux assiettes portant la même mention ?","explanation":"C constate que la mention ne suffit à établir ni composition ni origine. A infère une composition similaire, B un équilibre nutritionnel non prouvé, D remplace l'analyse de composition par la disponibilité de produits."},{"number":31,"points":26,"correct":"D","options":["L'absence de détails sur la rémunération de l'un des fournisseurs explique directement la similitude des tarifs affichés.","Des tarifs proches indiquent généralement des coûts de production comparables, sauf lorsque les volumes vendus diffèrent.","Les achats groupés réduisent les frais fixes; l'autre fournisseur doit donc appliquer une marge plus faible pour s'aligner.","Des prix similaires peuvent masquer des mécanismes de production différents."],"passage":"Un prix bas peut être obtenu par de grands volumes, une organisation efficace ou des conditions défavorables aux fournisseurs. Sans information sur ces facteurs, il serait imprudent d'attribuer la même cause à tous les produits bon marché. Des comparaisons entre produits proches et des informations sur les fournisseurs peuvent aider à comprendre ces différences. Le prix reste un repère important pour le budget, sans être une explication complète du fonctionnement de la production. Deux fournisseurs proposent un tarif similaire. L'un annonce un achat groupé avec de faibles frais fixes; pour l'autre, les conditions de rémunération ne sont pas documentées. L'acheteur ne peut déduire de l'égalité des prix une égalité des conditions de production.","question":"Quelle lecture des deux tarifs respecte le mieux les informations disponibles ?","explanation":"D refuse d'inférer les conditions de production à partir de prix similaires. A/B attribuent des causes sans documents, C calcule implicitement une marge non indiquée."},{"number":32,"points":26,"correct":"B","options":["L'adaptation locale fait perdre à la recette sa mémoire familiale, même si les gestes et les occasions restent proches.","Il conserve des usages transmis en adaptant la recette à un nouveau contexte.","Une texture semblable suffit à considérer que les ingrédients essentiels ont été préservés lors de la transmission.","Le changement de céréale conserve surtout le nom du plat, mais les pratiques ne peuvent plus être rapprochées."],"passage":"Les recettes d'un patrimoine culinaire sont souvent adaptées aux produits accessibles dans le lieu où vivent les familles. Cette transformation n'efface pas nécessairement leur histoire. Elle peut être précisément la manière dont la transmission continue dans un contexte différent. Les familles racontent les substitutions qu'elles ont essayées et les goûts qu'elles souhaitaient retrouver. Ces récits montrent une continuité vivante, dont les changements peuvent être décrits plutôt que dissimulés sous l'idée d'une recette restée toujours identique. Pour une famille, changer de céréale a permis de retrouver la texture recherchée malgré l'absence du produit ancien. Le récit précise le changement au lieu de présenter la recette comme intacte; la parenté avec la pratique antérieure se lit aussi dans les gestes et les occasions de partage.","question":"Dans quel sens le changement d'ingrédient peut-il faire partie de la transmission ?","explanation":"B retient la continuité de repères pratiques malgré la substitution explicitée. A/D nient les usages conservés; C infère des ingrédients identiques de la seule texture."},{"number":33,"points":26,"correct":"A","options":["Une préférence initialement faible peut refléter la méconnaissance du plat plutôt qu'un rejet après dégustation.","La première mesure révélait une moindre qualité gustative, que la dégustation a ensuite permis de corriger.","La hausse de la note moyenne montre que le plat nouveau sera apprécié de la même manière par tous les élèves.","La dégustation permet d'annuler l'effet des habitudes chez les participants lorsqu'ils comparent les recettes anciennes."],"passage":"Une cantine veut améliorer ses menus à partir d'un vote. Les plats peu connus risquent d'obtenir peu de voix avant même d'avoir été goûtés. L'équipe ajoute des dégustations aux questionnaires pour éviter que la consultation ne reproduise seulement les habitudes existantes. L'équipe comparera leurs avis avant et après l'essai pour voir si le menu futur doit être ajusté ou simplement mieux présenté. Un plat nouveau reçoit peu de votes lors d'un premier sondage. Après dégustation, sa note moyenne augmente fortement, alors que celle des plats déjà connus varie peu. L'équipe distingue désormais la réaction à un nom de plat de l'appréciation après expérience.","question":"Que permet d'interpréter la seconde mesure des préférences ?","explanation":"A distingue un jugement sur un plat inconnu de l'appréciation après dégustation. B attribue à la recette une modification non mentionnée; C/D généralisent abusivement les observations."},{"number":34,"points":26,"correct":"A","options":["Adapter les livraisons aux produits, au stockage et aux pertes constatées.","Réduire le nombre de trajets permet d'évaluer le gain du dispositif, les pertes de cuisine appartenant au budget alimentaire.","Une cadence fixe pour chaque catégorie de produit rend les livraisons prévisibles et compense les contraintes de stockage.","Les commandes supplémentaires de produits fragiles peuvent être laissées au choix des restaurants, sans comptage des trajets."],"passage":"Un producteur remplace des livraisons quotidiennes par deux tournées hebdomadaires. Les trajets diminuent, mais certains restaurants doivent adapter leurs capacités de stockage. L'économie logistique suppose donc une coordination entre ceux qui livrent et ceux qui reçoivent. Le calendrier sera discuté à l'avance avec les cuisines. Certains produits nécessiteront un autre rythme, tandis que d'autres pourront être livrés ensemble sans difficulté. L'essai devra donc être évalué pour chaque type d'approvisionnement. Un restaurant peut conserver deux livraisons groupées de conserves mais doit encore recevoir certains produits fragiles plus souvent. La baisse globale des kilomètres parcourus ne serait pas une économie durable si les nouvelles contraintes provoquaient des pertes en cuisine.","question":"Quelle condition rend la réduction des tournées réellement pertinente ?","explanation":"A requiert une coordination des catégories, des stocks et des pertes. B/D retirent certains coûts du bilan, C applique une cadence unique malgré des contraintes différentes."},{"number":35,"points":26,"correct":"D","options":["Les deux cuisines ont un rendement équivalent contre le gaspillage, car elles compostent la même quantité de restes à la fin du service.","La seconde cuisine valorise davantage d'aliments par repas, puisque son poids de déchets compostés est identique malgré un surplus moindre.","La différence de onze kilos prouve que toutes les matières restantes dans la première cuisine étaient comestibles et auraient pu être évitées.","À nombre de repas égal, la seconde cuisine produit moins de surplus; le même tonnage de compost ne mesure donc pas la prévention."],"passage":"La lutte contre le gaspillage en cuisine est parfois réduite au recyclage des restes. Un collectif insiste d'abord sur les prévisions, les achats et les portions. Le traitement final reste utile, mais intervient après que des décisions évitables ont déjà produit un surplus. Ces informations peuvent conduire à modifier l'organisation du service avant même de chercher de nouvelles recettes pour transformer les aliments non consommés. Dans deux cuisines, la même quantité de déchets est compostée. La première produit beaucoup de restes et la seconde ajuste ses achats au nombre de repas, ce qui réduit la quantité jetée avant le compostage. Le collectif considère ces deux résultats comme distincts. Le bilan chiffré précise les mêmes cent repas préparés dans les deux cuisines. Dans la première, vingt-cinq kilos d'aliments non servis restent à la fin du service, dont dix sont compostés. Dans la seconde, les responsables ont revu les achats et les portions: quatorze kilos restent, dont dix sont également compostés. Les deux cuisines annoncent donc le même poids valorisé, mais la seconde a évité onze kilos de surplus en amont. L'équipe de mesure avertit que les restes ne sont pas tous comestibles et qu'une comparaison entre services devrait distinguer les épluchures des aliments préparés non servis. Le comité veut publier des indicateurs séparés: masse de surplus pour cent repas, nature des restes et part finalement valorisée. Il refuse un classement fondé sur le seul tonnage du compost, tout comme un calcul qui considérerait tous les déchets résiduels comme évitables.","question":"Quelle comparaison le bilan permet-il de soutenir sans assimiler prévention et valorisation ?","explanation":"D s'appuie sur les 25 et 14 kilos restants pour cent repas et sur les 10 kilos compostés dans chaque cuisine. La prévention porte sur la quantité produite en amont, non sur le tonnage valorisé. A confond égalité du compost et réduction des surplus; B transforme une égalité de masse en valorisation plus grande; C ignore la distinction explicitement demandée entre restes comestibles et non comestibles."},{"number":36,"points":33,"correct":"B","options":["Le nombre de commandes communes a diminué après une modification du choix disponible au moment de la réservation.","Le surcoût matériel de choix très individualisés, en préservant les adaptations jugées essentielles.","La préférence pour les paniers différents explique à elle seule la totalité des trajets et des emballages.","Les paniers communs rendent les commandes plus efficaces en empêchant toute prise en compte des contraintes alimentaires."],"passage":"Un service de paniers « personnalisés » promet de répondre à chaque préférence. Pour y parvenir, il multiplie les petites commandes et les emballages séparés. Les clients gagnent en choix, mais le système perd une partie de l'efficacité du panier commun. La personnalisation peut déplacer les coûts matériels vers l'organisation qui la rend possible. Pour préserver une partie de cette souplesse, le service propose désormais quelques choix communs plutôt qu'une composition entièrement différente pour chaque foyer. Les clients peuvent indiquer des contraintes essentielles, mais toutes les préférences ne donneront plus lieu à un emballage séparé. Le responsable souhaite mesurer les volumes réellement transportés et jetés, pas seulement la satisfaction au moment de la commande. Il espère ainsi conserver un service utile, tout en rendant visibles les ressources mobilisées derrière une offre qui semblait simplement apporter davantage de liberté à chacun. Le responsable compare deux mois: le nombre de clients reste stable, mais les petites commandes individualisées multiplient les trajets et les cartons. Une formule intermédiaire supprime certaines variantes sans toucher aux contraintes alimentaires que les clients jugent indispensables.","question":"Que cherche principalement à corriger la formule intermédiaire ?","explanation":"B réduit les ressources mobilisées par des choix individualisés tout en conservant les contraintes essentielles. A ajoute une évolution des commandes non constatée; C attribue tous les coûts aux préférences sans les autres facteurs; D nie les adaptations conservées."},{"number":37,"points":33,"correct":"B","options":["Elle privilégie les produits de saison mais laisse les exceptions hors du menu pour garder un message simple.","Elle explique la priorité locale et les exceptions, rendant les choix vérifiables.","Elle établit qu'un fournisseur local peut remplacer tous les ingrédients même lorsque certaines épices ne sont pas régionales.","Elle publie la provenance des légumes sans préciser les raisons du choix des ingrédients venus d'ailleurs."],"passage":"Un restaurant annonce une cuisine locale. Son menu comporte surtout des produits de proximité, mais certains ingrédients complémentaires viennent d'ailleurs. Le chef publie ces exceptions et leurs raisons. La cohérence de son engagement repose sur des choix expliqués, plutôt que sur une formule absolue que la pratique démentirait. Il indique les fournisseurs principaux et la période à laquelle certains produits deviennent disponibles. Les clients peuvent ainsi comprendre pourquoi une recette change ou pourquoi une épice n'est pas produite dans la région. Le restaurateur souhaite éviter qu'une promesse trop générale transforme chaque exception en soupçon de tromperie. Cette précision n'empêche pas la discussion sur ses choix. Elle permet au contraire de les comparer avec d'autres possibilités, en distinguant une priorité réelle d'une affirmation commerciale qui paraîtrait valable pour chaque ingrédient et pendant toute l'année. Sur un menu, le chef indique qu'une épice vient de loin alors que les légumes sont achetés dans la région selon la saison. Un autre établissement affiche simplement « 100 % local » sans préciser ses achats. Les clients ne peuvent pas vérifier les mêmes choses à partir des deux annonces.","question":"En quoi la démarche du premier chef rend-elle son engagement plus crédible ?","explanation":"B rend la promesse locale vérifiable en précisant sa portée et ses exceptions. A et D omettent des explications importantes; C transforme une priorité locale en approvisionnement intégral alors que des exceptions subsistent."},{"number":38,"points":33,"correct":"C","options":["Le contenu de la brochure doit être reformulé pour adapter les recommandations à des préférences nutritionnelles différentes.","Les deux foyers connaissent les conseils mais ne souhaitent pas adopter les mêmes habitudes de préparation.","Une connaissance identique des recommandations n'implique pas une capacité identique à les mettre en pratique.","Le programme doit remplacer ses recommandations par des listes d'aliments imposées selon le quartier de résidence."],"passage":"Une ville distribue des brochures pour encourager une alimentation variée. Une enquête montre cependant que plusieurs ménages disposent d'un équipement de cuisson limité et de peu de commerces accessibles. La connaissance des recommandations n'est pas leur principale difficulté. Des conseils utiles doivent s'accompagner d'une attention aux conditions concrètes qui permettent de les suivre. Les associations proposent de compléter la campagne par des ateliers utilisant le matériel réellement disponible dans les logements. Elles demandent aussi que l'accès aux commerces et aux lieux de conservation soit examiné. Certaines personnes connaissent déjà les conseils et souhaitent les suivre, mais doivent composer avec un budget ou un horaire peu compatible avec l'offre locale. Les responsables veulent donc éviter un message qui ferait de ces contraintes une faute personnelle. La réussite du programme dépendra de ce qu'il rend effectivement possible dans le quotidien des familles auxquelles il s'adresse. Deux ménages connaissent les mêmes recommandations. Le premier dispose d'une cuisine équipée et de commerces proches; le second ne peut conserver certains aliments ni se déplacer aux heures d'ouverture. Répéter la brochure ne modifierait pas ces différences concrètes.","question":"Quel défaut du programme l'exemple des deux ménages révèle-t-il ?","explanation":"C reconnaît que le même savoir ne donne pas les mêmes capacités d'action face aux obstacles matériels. A/B infèrent des préférences différentes non établies; D introduit une prescription uniforme qui ne résout pas les contraintes observées."},{"number":39,"points":33,"correct":"D","options":["Chaque diminution de poids ouvre droit à un ajustement monétaire, tandis que l'information sur les récoltes relève du libre choix du producteur.","Le financement anticipé transfère aux membres les risques agricoles et la responsabilité du soin apporté aux parcelles durant la saison.","Une contribution identique garantit une quantité égale de paniers; les substitutions servent à neutraliser tous les écarts de rendement.","L'aléa climatique peut modifier la quantité reçue sans remboursement automatique, mais la ferme demeure tenue aux soins et informations prévus."],"passage":"Une ferme propose aux clients de partager les risques d'une saison en payant un panier à l'avance. Certains craignent de recevoir moins lors d'une mauvaise récolte. Le producteur explique que le contrat n'est pas une garantie de volume identique, mais une relation différente avec l'activité agricole. Le prix finance aussi une continuité de production confrontée à l'incertitude. Le groupe prévoit une visite des cultures et une information régulière sur l'évolution de la saison. Les membres pourront discuter des substitutions possibles, tout en comprenant qu'un engagement ne fait pas disparaître les aléas du climat. Le producteur garde la responsabilité d'expliquer ses choix et de travailler avec soin. Les acheteurs, eux, acceptent que leur contribution ne corresponde pas toujours au même poids de produits. L'année suivante, deux membres ayant payé le même montant reçoivent des volumes différents selon les récoltes des parcelles concernées. Le contrat précise les modalités d'information et les choix de remplacement, mais ne promet pas d'ajuster rétroactivement chaque contribution au poids reçu. Au terme d'une autre saison, la ferme a connu une baisse de rendement sur certaines parcelles malgré les soins documentés. Les membres avaient réglé des contributions identiques, mais leurs paniers, répartis selon les parcelles et les produits disponibles, ont varié en poids. Le contrat prévoit une réunion pour expliquer les aléas, un remplacement possible par d'autres légumes et un remboursement seulement si la ferme n'a pas assuré les engagements de production et d'information précisés au départ. Il n'introduit aucune régularisation automatique au kilogramme manquant. Un membre estime que toute variation de poids prouve un défaut de service; un autre fait remarquer que l'acceptation du risque climatique ne retire pas au producteur ses obligations de diligence et de transparence. Les deux conviennent que la description des récoltes et des substitutions doit pouvoir être vérifiée, même lorsque le montant versé n'est pas recalculé.","question":"Quelle interprétation distingue correctement le risque partagé des obligations que le producteur conserve ?","explanation":"D combine la répartition du risque de rendement avec les obligations séparées de soin, d'explication et de substitution prévues au contrat. Aucun ajustement au poids n'est automatique. A introduit précisément la régularisation exclue et rend l'information facultative; B supprime à tort les engagements du producteur; C suppose une garantie de volume contredite par les parcelles et les paniers variables."}]}$paper_7$::jsonb),
('tcf-reading-08','tcf-reading-2026-11-close-reading-v4',$paper_8${"id":"tcf-reading-08","title":"TCF Reading · Test 08","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["Dix-neuf heures trente","Dix-neuf heures quinze","Dix-huit heures quarante-cinq","Vingt heures"],"passage":"La piscine ferme ses bassins à dix-neuf heures. Les vestiaires restent accessibles quinze minutes supplémentaires.\n\nMerci de prévoir le temps nécessaire avant la fermeture des vestiaires. Le personnel rappellera cette règle à l'entrée de chaque séance.","question":"Jusqu'à quand peut-on se changer ?","explanation":"Le passage indique : « La piscine ferme ses bassins à dix-neuf heures. Les vestiaires restent accessibles quinze minutes supplémentaires. » Cela justifie la réponse : Dix-neuf heures quinze."},{"number":2,"points":3,"correct":"B","options":["Un ballon","Un tapis","Une chaise","Un casque"],"passage":"Le cours de yoga est déplacé au gymnase. Apportez votre tapis ; les chaises seront fournies aux personnes qui en ont besoin.\n\nL'animateur accueillera les participants devant la salle.","question":"Quel matériel est demandé ?","explanation":"Le passage indique : « Le cours de yoga est déplacé au gymnase. Apportez votre tapis ; les chaises seront fournies aux personnes qui en ont besoin. » Cela justifie la réponse : Un tapis."},{"number":3,"points":3,"correct":"C","options":["Uniquement les livreurs","Les visiteurs sans motif","Les patients ayant rendez-vous","Toute personne souhaitant s'inscrire"],"passage":"L'accueil du cabinet sera fermé mardi matin. Les consultations déjà prévues sont maintenues ; sonnez à la porte latérale.\n\nLes demandes non urgentes seront traitées dès le retour de l'équipe d'accueil.","question":"Qui peut venir mardi matin ?","explanation":"Le passage indique : « L'accueil du cabinet sera fermé mardi matin. Les consultations déjà prévues sont maintenues ; sonnez à la porte latérale. » Cela justifie la réponse : Les patients ayant rendez-vous."},{"number":4,"points":3,"correct":"D","options":["Une sortie sans chaussures","Une course plus rapide","L'accès au parcours glissant","Un itinéraire alternatif"],"passage":"Le parcours de marche est glissant après la pluie. Utilisez provisoirement la boucle courte sur sol stabilisé.\n\nDes panneaux indiquent la déviation à l'entrée du parc. Les équipes vérifieront l'état du terrain avant de rouvrir le passage habituel.","question":"Que conseille l'annonce ?","explanation":"Le passage indique : « Le parcours de marche est glissant après la pluie. Utilisez provisoirement la boucle courte sur sol stabilisé. » Cela justifie la réponse : Un itinéraire alternatif."},{"number":5,"points":9,"correct":"D","options":["Une route inconnue de nuit","Une compétition chronométrée","Une ascension difficile","Un trajet sans montée importante"],"passage":"Je reprends doucement le vélo après ma pause. Pour dimanche, choisissons le trajet plat ; nous réserverons les côtes à une autre sortie.\n\nLe groupe peut conserver une allure tranquille et s'arrêter lorsque ce sera nécessaire. Je veux reprendre régulièrement sans transformer cette première sortie en épreuve trop difficile.","question":"Quel parcours est souhaité ?","explanation":"Le passage indique : « Je reprends doucement le vélo après ma pause. Pour dimanche, choisissons le trajet plat ; nous réserverons les côtes à une autre sortie. » Cela justifie la réponse : Un trajet sans montée importante."},{"number":6,"points":9,"correct":"A","options":["Contacter le secrétariat","Venir sans prévenir un autre jour","Annuler tous les soins","Demander à un voisin de consulter"],"passage":"Votre rendez-vous de contrôle est avancé à jeudi. Prévenez le secrétariat si ce nouvel horaire ne vous convient pas.\n\nLe cabinet proposera un autre créneau selon les disponibilités. Merci de signaler votre réponse rapidement pour éviter de laisser une place inutilisée.","question":"Que faire en cas d'indisponibilité ?","explanation":"Le passage indique : « Votre rendez-vous de contrôle est avancé à jeudi. Prévenez le secrétariat si ce nouvel horaire ne vous convient pas. » Cela justifie la réponse : Contacter le secrétariat."},{"number":7,"points":9,"correct":"B","options":["Recevoir un équipement définitif","Essayer avant de s'équiper","Participer sans jamais s'inscrire","Éviter toute séance encadrée"],"passage":"L'association prête des bâtons de marche pendant les trois premières séances. Ensuite, chacun choisira s'il souhaite continuer l'activité.\n\nUn animateur vérifiera leur taille et expliquera les gestes de base. Vous pourrez ensuite poser vos questions avant de vous engager dans une pratique régulière.","question":"Quel est l'intérêt du prêt ?","explanation":"Le passage indique : « L'association prête des bâtons de marche pendant les trois premières séances. Ensuite, chacun choisira s'il souhaite continuer l'activité. » Cela justifie la réponse : Essayer avant de s'équiper."},{"number":8,"points":9,"correct":"B","options":["Un départ sans accompagnateur","Des arrêts plus fréquents","Une distance doublée","La suppression des boissons"],"passage":"Nous maintenons la randonnée, mais avec davantage de pauses à cause de la chaleur. Emportez de l'eau et prévenez si vous préférez renoncer.\n\nLe guide vérifiera les points d'eau et adaptera l'allure au groupe.","question":"Quelle adaptation est prévue ?","explanation":"Le passage indique : « Nous maintenons la randonnée, mais avec davantage de pauses à cause de la chaleur. Emportez de l'eau et prévenez si vous préférez renoncer. » Cela justifie la réponse : Des arrêts plus fréquents."},{"number":9,"points":9,"correct":"B","options":["Aux enfants accompagnés","Aux adultes qui apprennent","Aux nageurs en compétition seulement","Aux entraîneurs professionnels"],"passage":"La séance découverte de natation est réservée aux adultes débutants. Il n'est pas nécessaire de savoir nager pour s'inscrire.\n\nLes exercices commenceront dans une zone où chacun peut garder ses repères. Un échange permettra de préciser les attentes avant le premier passage dans l'eau.","question":"À qui s'adresse la séance ?","explanation":"Le passage indique : « La séance découverte de natation est réservée aux adultes débutants. Il n'est pas nécessaire de savoir nager pour s'inscrire. » Cela justifie la réponse : Aux adultes qui apprennent."},{"number":10,"points":9,"correct":"D","options":["Un projet de compétition","Un déménagement en montagne","Une interdiction de courir","Une meilleure organisation du quotidien"],"passage":"Je vais marcher le midi plutôt que courir tard le soir. Cela s'accorde mieux avec mes horaires et me laisse du temps en famille.\n\nJe compte aussi préparer mes affaires à l'avance pour ne pas renoncer au dernier moment.","question":"Qu'est-ce qui motive ce changement ?","explanation":"Le passage indique : « Je vais marcher le midi plutôt que courir tard le soir. Cela s'accorde mieux avec mes horaires et me laisse du temps en famille. » Cela justifie la réponse : Une meilleure organisation du quotidien."},{"number":11,"points":15,"correct":"A","options":["Elle n'est pas l'objectif principal","Elle exclut les nouveaux membres","Elle détermine le droit d'entrer","Elle impose un temps identique"],"passage":"Un club organise une séance sans classement. Les participants choisissent leur rythme et peuvent interrompre l'exercice avant la fin.\n\nLes animateurs proposent plusieurs exercices au même endroit et expliquent les adaptations possibles. Une personne qui débute n'a pas à suivre exactement le programme d'un habitué. Le club souhaite que chacun trouve une manière de participer sans craindre de ralentir les autres. Les responsables observeront les inscriptions, mais aussi les retours après plusieurs semaines. Une séance accueillante n'atteint pas son objectif si les nouveaux venus se sentent encore incapables de revenir seuls ou de demander une pause.","question":"Quelle place est donnée à la performance ?","explanation":"Le passage indique : « Un club organise une séance sans classement. Les participants choisissent leur rythme et peuvent interrompre l'exercice avant la fin. » Cela justifie la réponse : Elle n'est pas l'objectif principal."},{"number":12,"points":15,"correct":"A","options":["L'atelier ne remplace pas un suivi individuel","Les animateurs prescrivent systématiquement un traitement","Aucune question ne peut être posée","Les participants reçoivent tous un diagnostic"],"passage":"Une résidence propose des rencontres autour du sommeil. Les animateurs donnent des informations générales et orientent les situations particulières vers un professionnel.\n\nLes participants peuvent parler de leurs habitudes, mais ne sont pas invités à dévoiler un dossier médical devant le groupe. Les séances abordent notamment l'organisation de la soirée et les conditions du logement. Les intervenants rappellent que des difficultés persistantes peuvent demander une consultation.","question":"Quelle limite est précisée ?","explanation":"Le passage indique : « Une résidence propose des rencontres autour du sommeil. Les animateurs donnent des informations générales et orientent les situations particulières vers un professionnel. » Cela justifie la réponse : L'atelier ne remplace pas un suivi individuel."},{"number":13,"points":15,"correct":"A","options":["Permettre différentes capacités de participation","Supprimer les explications","Réserver le parc aux spécialistes","Imposer une difficulté unique"],"passage":"Le parcours sportif du parc comporte des variantes assises et debout. Les panneaux montrent plusieurs niveaux pour un même mouvement.\n\nLes indications ne supposent pas que l'on connaisse déjà les appareils. Des dessins montrent les positions et rappellent qu'une pause est possible. Le service souhaite accueillir les personnes qui ne fréquentent pas les salles, autant que les sportifs habituels. Les usagers pourront signaler un mouvement difficile à comprendre. Une première évaluation regardera la variété des participants et la facilité d'utilisation du parcours, plutôt que le seul nombre d'équipements installés ou la vitesse à laquelle ils sont utilisés.","question":"Quel objectif poursuit l'aménagement ?","explanation":"Le passage indique : « Le parcours sportif du parc comporte des variantes assises et debout. Les panneaux montrent plusieurs niveaux pour un même mouvement. » Cela justifie la réponse : Permettre différentes capacités de participation."},{"number":14,"points":15,"correct":"D","options":["Pour imposer un classement plus strict","Pour limiter l'accès aux nouveaux venus","Pour remplacer toutes les sorties","Pour diversifier les façons de pratiquer"],"passage":"Un club de course accueille un groupe de marche rapide. Certains membres souhaitent bouger régulièrement sans rechercher la vitesse.\n\nLes rendez-vous gardent une progression et un encadrement, mais les distances sont adaptées aux objectifs annoncés par les participants. Certains cherchent une activité après le travail ; d'autres veulent retrouver une habitude interrompue. Le responsable souhaite éviter qu'une même image de la performance fasse croire que le club n'accueille que des coureurs rapides. Les deux groupes pourront partager des rencontres et quelques exercices, sans que l'un soit considéré comme une version moins valable de l'autre.","question":"Pourquoi ce groupe est-il créé ?","explanation":"Le passage indique : « Un club de course accueille un groupe de marche rapide. Certains membres souhaitent bouger régulièrement sans rechercher la vitesse. » Cela justifie la réponse : Pour diversifier les façons de pratiquer."},{"number":15,"points":15,"correct":"C","options":["L'existence d'un accueil","La diversité des horaires","La dépendance aux outils numériques","Le besoin d'un rendez-vous"],"passage":"Les consultations d'un centre se réservent aussi par téléphone. Le site internet n'est pas l'unique moyen d'obtenir un créneau.\n\nLes personnes qui appellent reçoivent les mêmes informations sur les créneaux et les documents utiles. Les secrétaires peuvent expliquer une étape incomprise sans demander l'aide d'un proche équipé. Le centre ne veut pas supprimer les démarches en ligne, pratiques pour une partie du public. Il souhaite simplement conserver une possibilité réelle pour ceux qui ne peuvent pas les utiliser seuls. Les responsables suivront les attentes sur chaque canal pour éviter qu'un accès annoncé reste beaucoup plus difficile que l'autre.","question":"Quel obstacle cherche-t-on à réduire ?","explanation":"Le passage indique : « Les consultations d'un centre se réservent aussi par téléphone. Le site internet n'est pas l'unique moyen d'obtenir un créneau. » Cela justifie la réponse : La dépendance aux outils numériques."},{"number":16,"points":15,"correct":"B","options":["Remplacer tous les meubles par des écrans","Agir sur l'organisation et les pauses","Exiger l'immobilité toute la journée","Supprimer les changements de tâche"],"passage":"Une entreprise réorganise ses postes pour éviter de rester longtemps dans la même position. Les pauses courtes complètent cet aménagement.\n\nLes salariés ont participé aux essais en indiquant les gestes qui provoquaient une gêne. Certaines tâches seront alternées et quelques équipements déplacés pour faciliter les changements de position. L'entreprise veut observer le travail réel avant de distribuer uniquement des recommandations individuelles. Une affiche pourra rappeler des repères, mais ne remplacera pas une organisation permettant effectivement de bouger.","question":"Quelle approche est adoptée ?","explanation":"Le passage indique : « Une entreprise réorganise ses postes pour éviter de rester longtemps dans la même position. Les pauses courtes complètent cet aménagement. » Cela justifie la réponse : Agir sur l'organisation et les pauses."},{"number":17,"points":15,"correct":"B","options":["Comparer uniquement les chaussures","Mieux comprendre l'effort réellement ressenti","Remplacer tout mouvement par un questionnaire","Garantir des progrès identiques"],"passage":"Un entraîneur fait noter les sensations après l'exercice, pas seulement la distance parcourue. Une même distance peut représenter un effort différent selon les jours.\n\nLe carnet reste personnel et sert de base à une discussion avec l'entraîneur. Les participants peuvent y signaler un sommeil court, une reprise après une absence ou un effort inhabituel dans la journée. Le club souhaite ainsi éviter une comparaison trop mécanique entre deux sorties. Les chiffres restent utiles pour suivre une progression, mais prennent un autre sens lorsqu'ils sont rapprochés des conditions dans lesquelles ils ont été obtenus.","question":"Pourquoi recueillir ces sensations ?","explanation":"Le passage indique : « Un entraîneur fait noter les sensations après l'exercice, pas seulement la distance parcourue. Une même distance peut représenter un effort différent selon les jours. » Cela justifie la réponse : Mieux comprendre l'effort réellement ressenti."},{"number":18,"points":15,"correct":"D","options":["Une participation obligatoirement gratuite","Une réservation réservée aux donateurs","Une portion proportionnelle au paiement","Un accueil indépendant de la contribution financière"],"passage":"Le centre social propose un atelier cuisine et santé à prix libre. Le montant versé n'influence pas la taille de la portion servie.\n\nLes participants cuisinent ensemble avant de partager le repas. Le centre souhaite préserver une activité commune plutôt que distinguer plusieurs catégories de convives. Les recettes sont pensées pour être reproduites avec un équipement courant. Le bilan prendra en compte l'équilibre financier de l'atelier, mais aussi la possibilité pour des personnes aux budgets différents de s'y retrouver régulièrement dans les mêmes conditions d'accueil.","question":"Quel principe est appliqué ?","explanation":"Le passage indique : « Le centre social propose un atelier cuisine et santé à prix libre. Le montant versé n'influence pas la taille de la portion servie. » Cela justifie la réponse : Un accueil indépendant de la contribution financière."},{"number":19,"points":15,"correct":"C","options":["Distribuer les dossards avant le départ","Remplacer les vestiaires","Faciliter la récupération dans un environnement apaisé","Organiser une seconde course"],"passage":"Pour une course locale, les organisateurs installent un espace calme après l'arrivée. Les participants peuvent récupérer sans rester dans la foule.\n\nL'organisation rappelle que cet espace ne remplace pas les secours prévus pour un problème particulier. Il répond surtout au besoin de se poser après l'effort et de retrouver ses proches tranquillement. Les responsables interrogeront les participants sur sa localisation, car un équipement utile en principe peut être délaissé s'il reste difficile à trouver au milieu des autres installations.","question":"À quoi sert cet espace ?","explanation":"Le passage indique : « Pour une course locale, les organisateurs installent un espace calme après l'arrivée. Les participants peuvent récupérer sans rester dans la foule. » Cela justifie la réponse : Faciliter la récupération dans un environnement apaisé."},{"number":20,"points":21,"correct":"C","options":["Remplacer tous les déplacements quotidiens","Sélectionner les marcheurs les plus rapides","Soutenir une pratique régulière et partagée","Atteindre une distance maximale"],"passage":"Un quartier propose des promenades accompagnées pour les personnes qui hésitent à sortir seules. Le programme varie selon le groupe : le lien social et la régularité importent davantage que le nombre de kilomètres. Les animateurs préparent plusieurs possibilités de trajet et demandent aux nouveaux venus ce qui leur paraît réalisable. Les pauses offrent un moment pour échanger avec les autres habitants. Le centre souhaite que les personnes puissent ensuite proposer elles-mêmes une sortie. Il suivra la régularité des rencontres et les relations qui se maintiennent, sans transformer le programme en concours de distance ou de vitesse.","question":"Quelle priorité est donnée ?","explanation":"Le passage indique : « Un quartier propose des promenades accompagnées pour les personnes qui hésitent à sortir seules. Le programme varie selon le groupe : le lien social et la régularité importent davantage que le nombre de kilomètres. » Cela justifie la réponse : Soutenir une pratique régulière et partagée."},{"number":21,"points":21,"correct":"C","options":["Aucune donnée n'a été recueillie","Les réponses concernent uniquement les enfants","Le profil des participants peut influencer les résultats","Les clubs refusent toute enquête"],"passage":"Une étude locale sur l'activité physique repose sur des volontaires déjà membres de clubs. Ses auteurs signalent que leurs réponses ne représentent pas forcément les personnes éloignées du sport. Les chercheurs chercheront ensuite à rencontrer d'autres habitants, y compris ceux qui ne disposent pas d'un équipement adapté ou n'aiment pas les activités proposées. Ces réponses permettront de distinguer les préférences et les obstacles. Le premier questionnaire reste utile pour comprendre la vie des clubs, mais sa portée doit être clairement annoncée.","question":"Quelle limite est reconnue ?","explanation":"Le passage indique : « Une étude locale sur l'activité physique repose sur des volontaires déjà membres de clubs. Ses auteurs signalent que leurs réponses ne représentent pas forcément les personnes éloignées du sport. » Cela justifie la réponse : Le profil des participants peut influencer les résultats."},{"number":22,"points":21,"correct":"B","options":["Confirmer que chacun l'utilise déjà","Comprendre les obstacles à une participation plus large","Supprimer toutes les activités gratuites","Fermer le terrain aux usagers actuels"],"passage":"Une commune rénove un terrain, puis observe surtout une fréquentation masculine. Elle consulte les autres habitants sur les horaires, l'éclairage et les activités proposées. Les réponses évoquent parfois la difficulté de venir sans connaître quelqu'un, ou l'absence d'une activité souhaitée. Il ne souhaite pas simplement compter les entrées et déclarer le projet terminé. La consultation doit aider à comprendre qui utilise le lieu, qui reste à l'écart et quelles modifications pourraient changer cette situation.","question":"Pourquoi poursuivre la consultation ?","explanation":"Le passage indique : « Une commune rénove un terrain, puis observe surtout une fréquentation masculine. Elle consulte les autres habitants sur les horaires, l'éclairage et les activités proposées. » Cela justifie la réponse : Comprendre les obstacles à une participation plus large."},{"number":23,"points":21,"correct":"D","options":["Celle entre débutants et entraîneurs uniquement","Celle entre les jours ouvrés et les congés scolaires","Celle entre deux vestiaires","Celle entre activité personnelle et évaluation au travail"],"passage":"Un employeur propose un cours sportif facultatif pendant la pause. Les salariés demandent que la participation ne soit pas utilisée comme signe d'engagement professionnel. Des personnes apprécient l'offre tout en préférant se reposer ou régler une démarche pendant la pause. Elles souhaitent pouvoir choisir sans craindre un jugement sur leur attitude. La direction précisera donc le caractère facultatif du cours et demandera aux responsables de ne pas le commenter dans les entretiens.","question":"Quelle séparation souhaitent-ils préserver ?","explanation":"Le passage indique : « Un employeur propose un cours sportif facultatif pendant la pause. Les salariés demandent que la participation ne soit pas utilisée comme signe d'engagement professionnel. » Cela justifie la réponse : Celle entre activité personnelle et évaluation au travail."},{"number":24,"points":21,"correct":"C","options":["Une augmentation des obstacles matériels","Un classement plus précis","Un accompagnement humain","Une fermeture des inscriptions"],"passage":"Un club prête du matériel adapté, mais manque de personnel pour accompagner les nouveaux membres. L'équipement élargit les possibilités sans suffire à assurer l'accueil. Les nouveaux pratiquants peuvent avoir besoin d'explications, de repères ou d'une présence rassurante lors des premières séances. L'association cherche donc des personnes formées à cet accueil et réorganise quelques horaires. Le bilan distinguera les prêts effectués et les séances que les personnes ont pu suivre dans de bonnes conditions.","question":"Quel besoin reste présent ?","explanation":"Le passage indique : « Un club prête du matériel adapté, mais manque de personnel pour accompagner les nouveaux membres. L'équipement élargit les possibilités sans suffire à assurer l'accueil. » Cela justifie la réponse : Un accompagnement humain."},{"number":25,"points":21,"correct":"C","options":["L'augmentation de la fréquentation tardive suffit à confirmer la réussite même si les délais du matin augmentent.","La diminution des absences mesure l'effet du nouvel horaire, sans qu'il soit nécessaire de distinguer les publics concernés.","Une fréquentation de nouveaux publics compatible avec des délais et une qualité d'accueil acceptables.","La durée d'ouverture supplémentaire devient l'indicateur central, indépendamment du nombre de consultations effectivement réalisées."],"passage":"Un centre propose des horaires de consultation plus tardifs. Il mesure ensuite les annulations et le temps d'attente, afin de vérifier que l'ouverture répond réellement à un besoin. Les responsables regarderont notamment si de nouveaux publics peuvent venir sans demander un arrangement exceptionnel. Les équipes expliqueront aussi les contraintes rencontrées après l'ouverture. L'augmentation du nombre d'heures ne sera pas présentée comme un résultat suffisant si les créneaux restent vides ou si la qualité de l'accueil diminue. Après deux mois, les réservations tardives augmentent, mais l'attente moyenne s'allonge le lendemain matin. Les responsables séparent donc la fréquentation des nouveaux créneaux, l'arrivée de personnes auparavant empêchées et les éventuelles conséquences sur le reste du service.","question":"Quel bilan permettrait de conclure à une amélioration réelle du service ?","explanation":"C exige de toucher de nouveaux publics tout en préservant un service acceptable. A/B/D retiennent un indicateur isolé et ignorent les conséquences sur les autres créneaux."},{"number":26,"points":21,"correct":"A","options":["Parce que les rappels peuvent encourager certains utilisateurs mais exercer une pression sur d'autres.","L'utilisation des rappels mesure mieux l'assiduité que les choix de rythme ou de rendez-vous collectifs.","Des rendez-vous de groupe apportent à chacun une motivation supérieure aux messages de rappel individuels.","Les personnes ayant désactivé les messages semblent moins désireuses de poursuivre une pratique régulière."],"passage":"Une application de sport envoie des rappels quotidiens. Certains utilisateurs les trouvent utiles ; d'autres désactivent les messages pour éviter une pression supplémentaire. Elle recueillera les retours sur l'usage dans la durée, pas seulement lors de l'inscription. Les responsables veulent éviter qu'un outil présenté comme encourageant devienne une source de culpabilité. Ils rappellent qu'une notification ne remplace pas les conditions pratiques, le plaisir ou le soutien qui permettent de conserver une activité. Dans un groupe suivi six semaines, les utilisateurs qui désactivent les rappels ne sont pas tous moins actifs: certains préfèrent des rendez-vous collectifs. Ceux qui gardent les rappels ne les trouvent pas tous encourageants à chaque période.","question":"Pourquoi l'équipe ne peut-elle pas utiliser l'activation des rappels comme mesure directe de motivation ?","explanation":"A montre que le réglage des messages dépend aussi de la pression ressentie et du mode de pratique. B/D déduisent une motivation des notifications, C infère une supériorité générale du groupe non établie."},{"number":27,"points":21,"correct":"C","options":["Les questions sur les traitements peuvent être abordées collectivement si les situations comparées paraissent médicalement proches.","La comparaison de deux dossiers serait possible en groupe si l'identité des patients était omise dans la discussion.","Les questions générales peuvent être abordées publiquement, tandis que les situations médicales identifiables requièrent un cadre confidentiel.","Les informations pratiques peuvent être données pendant la réunion, mais les questions liées au fonctionnement des consultations doivent rester privées."],"passage":"Un médecin participe à une réunion publique sur la prévention. Il refuse de commenter les dossiers personnels dans la salle et propose des échanges confidentiels dans un autre cadre. Les personnes peuvent poser des questions sur l'organisation générale du service et sur les ressources disponibles. Les cas individuels seront abordés par les canaux habituels, dans des conditions permettant un échange adapté. Pendant la réunion, une personne demande si le traitement prescrit à son voisin convient à son propre cas. Le médecin explique le fonctionnement des consultations, mais reporte toute comparaison de dossiers à un entretien individuel.","question":"Quelle limite le médecin trace-t-il entre information collective et conseil individuel ?","explanation":"C autorise l'information générale et réserve les situations médicales individuelles au cadre confidentiel. A/B transforment la réunion en comparaison clinique; D classe à tort l'organisation des consultations comme sujet privé."},{"number":28,"points":21,"correct":"A","options":["L'accès réel dépend aussi des possibilités de transport pour rentrer chez soi.","Les personnes motorisées bénéficient moins des nouveaux créneaux parce qu'elles partent avant la fermeture des transports.","Les utilisateurs non motorisés quittent les lieux plus tôt principalement parce qu'ils préfèrent les séances courtes.","L'extension du gymnase réduit la demande de transport public le soir chez les usagers de tous les quartiers."],"passage":"Un gymnase reste ouvert plus longtemps, mais l'arrêt de bus ferme tôt. Les habitants sans voiture ne profitent pas des nouveaux créneaux. Les associations proposent de comparer les horaires du réseau et les sorties réelles du gymnase. Une meilleure coordination pourrait être plus utile qu'une nouvelle campagne d'inscription. Elle souhaite éviter que l'ouverture soit annoncée comme une amélioration identique pour tous, alors que certains habitants ne disposent pas du moyen de rentrer chez eux. Une enquête montre que les derniers utilisateurs du gymnase quittent les lieux avant la fermeture de l'établissement, précisément pour attraper le dernier autobus. Les résidents motorisés utilisent davantage le nouveau créneau que les autres.","question":"Pourquoi la simple extension de l'ouverture ne produit-elle pas les mêmes effets selon les habitants ?","explanation":"A constate que l'accès dépend du trajet retour et pas seulement de la salle ouverte. B inverse les groupes, C attribue une préférence sans preuve, D généralise un effet non mesuré."},{"number":29,"points":21,"correct":"D","options":["Les activités restent identiques pour tous mais leurs fréquences sont adaptées à l'âge et au niveau des participants.","Le programme renonce à mesurer les progrès individuels afin de ne pas réintroduire une comparaison liée au poids.","La perte de poids demeure la principale mesure, tandis que les exercices possibles varient selon les préférences.","Il suit plusieurs pratiques choisies en fonction des besoins, plutôt qu'un indicateur corporel unique."],"passage":"Une association remplace son défi de perte de poids par un suivi de pratiques choisies avec les participants. Elle veut éviter de réduire le bien-être à un seul chiffre. Les participants discutent de ce qu'ils souhaitent rendre plus facile dans leur quotidien. Certains choisissent une promenade régulière, d'autres un moment de préparation des repas ou une reprise progressive d'activité. Le suivi sera ajusté à ces objectifs. Deux participants souhaitent des activités très différentes et fixent chacun un rythme réaliste. L'association évalue leur participation par rapport à leurs propres objectifs, au lieu de les classer à partir d'une variation de poids commune.","question":"Quel changement introduit le nouveau suivi par rapport à l'ancien défi ?","explanation":"D suit des pratiques choisies à partir des besoins et non un indicateur corporel unique. A conserve une pratique uniforme, B supprime le suivi pourtant individualisé, C maintient l'ancien critère."},{"number":30,"points":26,"correct":"D","options":["Une séance gratuite devient suffisante pour les personnes travaillant tard lorsque son programme correspond à leurs attentes.","La fréquence de présence permet de distinguer les personnes motivées avant d'examiner les contraintes familiales.","L'absence malgré la gratuité indique surtout une préférence pour des activités individuelles sans calendrier fixe.","Les modalités proposées peuvent rester incompatibles avec le travail ou les responsabilités familiales."],"passage":"Les campagnes qui invitent chacun à bouger supposent parfois que le temps disponible est librement choisi. Les emplois du temps irréguliers et les charges familiales peuvent rendre difficile une activité régulière. Adapter les propositions suppose de comprendre ces contraintes plutôt que d'attribuer toute absence à un manque de volonté. Ils évaluent ensuite si ces possibilités touchent effectivement les personnes jusqu'alors absentes, au lieu de supposer que l'affichage d'une offre suffit à la rendre accessible. L'association organise une séance gratuite à 18 heures; elle constate que les mêmes personnes restent absentes lorsque leur travail finit après cette heure. Elle teste ensuite deux horaires et une formule pouvant être suivie en famille avant d'évaluer l'engagement.","question":"Quelle hypothèse l'association cherche-t-elle à distinguer du simple manque de volonté ?","explanation":"D identifie horaires et responsabilités comme des barrières d'accès. A suppose la gratuité suffisante, B/C infèrent une motivation ou une préférence de l'absence."},{"number":31,"points":26,"correct":"D","options":["L'évolution du nombre de nouveaux inscrits suffit pour comparer deux saisons, même lorsque les anciens ne reviennent pas.","La taille maximale de chaque groupe indique la part des participants qui pourront continuer une activité durable.","Le renouvellement des cartes donne la mesure de fidélité même si elles ne sont pas utilisées ensuite.","La proportion des participants encore actifs et les obstacles qui expliquent les départs."],"passage":"Une salle sportive mesure le succès d'un programme par le nombre d'inscriptions. Des animateurs proposent aussi de regarder qui continue après trois mois et pour quelles raisons. Attirer un public et lui permettre de rester actif sont deux résultats liés, mais distincts. Ces échanges permettent de comprendre les obstacles et d'ajuster les séances plutôt que présenter le nombre d'inscrits comme une preuve complète de réussite. À l'inscription, deux groupes ont le même effectif. Trois mois plus tard, le premier conserve la moitié de ses membres et l'autre presque tous. Les animateurs souhaitent comprendre non seulement ce qui attire, mais ce qui rend la participation soutenable.","question":"Quelle information complète utilement le nombre initial d'inscriptions ?","explanation":"D suit la présence réelle et les causes de départ. A se limite au recrutement, B à une capacité potentielle, C à un acte administratif sans usage."},{"number":32,"points":26,"correct":"C","options":["Étendre l'observation à plusieurs utilisateurs afin de déterminer si les progrès se retrouvent avec des pratiques diverses.","Vérifier quels participants avaient bénéficié d'un accompagnement pendant l'essai avant d'interpréter ses résultats.","Généraliser à tous les acheteurs un effet obtenu sous des conditions accompagnées particulières.","Présenter l'outil comme une aide possible dont l'effet dépend de l'usage régulier, selon les limites connues."],"passage":"Une publicité promet une amélioration rapide grâce à un équipement. Un professionnel rappelle que les effets dépendent de l'usage, de la régularité et des situations individuelles. L'achat n'est donc pas en lui-même une preuve de bénéfice. L'utilisateur doit notamment savoir dans quelles conditions la comparaison a été réalisée. Une amélioration observée dans un essai précis ne se transforme pas automatiquement en promesse identique pour chaque personne achetant le produit. L'essai cité dans la publicité a été mené avec un accompagnement régulier, tandis que l'annonce vend seulement l'objet. Le professionnel demande de distinguer les conditions du test, la façon dont l'équipement est utilisé et la situation de la personne.","question":"Quelle inférence publicitaire le professionnel juge-t-il insuffisamment fondée ?","explanation":"C est l'extrapolation injustifiée d'un essai accompagné à tous les acheteurs. A/B/D sont des précautions ou interprétations compatibles avec les preuves disponibles."},{"number":33,"points":26,"correct":"D","options":["Le chemin est adopté presque uniquement par les habitants déjà inscrits à une activité sportive organisée.","Les programmes en salle perdent leur utilité, puisque la voie publique remplace la pratique d'entraînement.","Les trajets deviennent plus sûrs et encouragent surtout les anciens membres des clubs à pratiquer plus souvent.","Il facilite des marches quotidiennes sans inscription à un programme sportif."],"passage":"Des aménagements urbains favorisent les déplacements à pied. Leur effet dépasse les personnes qui s'inscrivent volontairement à une activité : un chemin sûr et agréable modifie aussi les trajets ordinaires. La promotion du mouvement peut ainsi passer par le cadre quotidien plutôt que par des programmes spécialisés. Les services observent donc les trajets ordinaires et les points où les habitants renoncent à marcher. Le nouveau chemin est surtout fréquenté pour rejoindre les commerces et les transports. Une partie de ses utilisateurs ne participe à aucun programme sportif, mais marche plus régulièrement parce que le trajet est devenu sûr.","question":"Quel mécanisme explique que l'aménagement touche des personnes non inscrites à une activité ?","explanation":"D décrit une activité physique utilitaire créée par un trajet plus sûr, y compris chez les non-inscrits. A/C ramènent l'effet aux sportifs, B nie abusivement l'intérêt des clubs."},{"number":34,"points":26,"correct":"A","options":["Elle permet une reprise accompagnée et adaptée sans effacer le parcours déjà engagé.","Une interruption oblige le participant à revalider son parcours, même lorsque ses acquis restent documentés.","La reprise suit le même protocole pour tous afin que la difficulté du retour soit évaluée de façon comparable.","Le maintien de l'ancien dossier dispense la personne de discuter avec l'animateur des capacités au retour."],"passage":"Un programme de reprise d'activité accepte les interruptions. Les participants peuvent revenir sans recommencer toutes les démarches. Les animateurs considèrent les parcours irréguliers comme une réalité à accompagner, et non comme une faute qui justifierait l'exclusion. Les animateurs demandent simplement de reprendre contact pour adapter le retour. Ils veulent maintenir une porte ouverte, tout en organisant un groupe qui puisse accueillir les personnes sans ignorer les contraintes réelles de chacune. Une participante s'interrompt plusieurs semaines pour s'occuper d'un proche. À son retour, elle reprend à un rythme réduit après un échange avec l'animateur; son ancien dossier reste valable et ses besoins sont réévalués.","question":"En quoi l'organisation favorise-t-elle une pratique durable ?","explanation":"A réunit continuité du parcours et adaptation au retour. B efface les acquis, C uniformise les besoins, D supprime l'accompagnement prévu."},{"number":35,"points":26,"correct":"C","options":["Ils permettent de distinguer les salariés concernés par l'indicateur, mais pas les différences de causes selon les services.","Ils servent surtout à confirmer que des notes semblables appellent des améliorations de même nature.","Ils montrent que des scores identiques peuvent recouvrir des mécanismes différents nécessitant des réponses distinctes.","Ils corrigent les scores trop élevés lorsqu'une équipe signale des interruptions fréquentes durant le travail."],"passage":"Une enquête mesure le stress au travail avec un questionnaire très court. Elle permet de repérer des tendances, mais ne décrit pas les causes précises dans chaque service. Les responsables complètent donc les chiffres par des échanges avec les équipes. Les équipes peuvent alors expliquer les interruptions, les priorités concurrentes et les moments difficiles. Le service souhaite construire des pistes d'amélioration à partir de ce dialogue, sans considérer chaque score comme une explication déjà complète. Dans deux services, la même proportion de salariés signale un stress élevé. Les entretiens révèlent pourtant des sources différentes: interruptions fréquentes dans l'un, échéances contradictoires dans l'autre. Les responsables ne veulent pas prescrire une réponse uniforme à partir du score seul.","question":"Quel apport spécifique les échanges fournissent-ils après les questionnaires ?","explanation":"C montre que deux scores similaires peuvent correspondre à des causes différentes, interruptions ou priorités contradictoires. A nie l'apport causal des entretiens; B présume une réponse identique; D transforme l'explication qualitative en correction de notes."},{"number":36,"points":33,"correct":"A","options":["Des freins économiques et sociaux peuvent se cumuler, d'où l'intérêt de réponses complémentaires.","Une baisse de cotisation résout la difficulté d'accès, tandis que l'accompagnement ne fait qu'améliorer le confort.","La présence d'un proche durant la première séance explique aussi le budget disponible pour continuer à venir.","Le nombre de demandes augmente suffisamment pour conclure que les freins sociaux ont diminué chez tous."],"passage":"Un club veut rendre ses activités accessibles à tous en réduisant les cotisations. Les demandes augmentent, mais des personnes restent absentes : certaines n'osent pas venir seules, d'autres ne se reconnaissent pas dans les images utilisées. L'obstacle financier est réel, sans être la seule barrière à une pratique accueillante. L'association cherche désormais des relais dans les lieux fréquentés par ces habitants et propose des premières séances accompagnées. Elle conserve aussi les tarifs réduits, car les contraintes se cumulent souvent au lieu de se remplacer. Les responsables souhaitent éviter de conclure que les absents ne s'intéressent pas à l'activité. Ils vérifieront plutôt si les nouveaux moyens d'accueil changent les expériences des personnes qui viennent pour la première fois. L'objectif reste d'ouvrir des possibilités concrètes, sans transformer une mesure utile en réponse présentée comme suffisante à toutes les difficultés. Après la réduction du prix, davantage d'habitants consultent le programme mais certains n'entrent toujours pas dans la salle. Des séances accompagnées les amènent à essayer une première fois, tandis que d'autres participants ont encore besoin du tarif réduit pour continuer.","question":"Que révèle la combinaison des tarifs réduits et des premières séances accompagnées ?","explanation":"A reconnaît des obstacles économiques et sociaux cumulables, traités par des aides complémentaires. B et D présument qu'une mesure efface l'autre difficulté; C relie sans preuve accompagnement et budget."},{"number":37,"points":33,"correct":"B","options":["La fatigue perçue doit remplacer les pas comme indicateur unique dès que les membres ressentent un changement.","Parce que des chiffres semblables peuvent recouvrir des expériences individuelles différentes.","Le plaisir déclaré fournit une échelle commune permettant de comparer directement les résultats de tous les participants.","La durée de marche indique mieux que le total des pas si la personne peut retrouver une activité sociale."],"passage":"Les outils de suivi comptent facilement les pas ou les minutes d'exercice. Ils décrivent moins bien le plaisir, la fatigue ou la confiance retrouvée. Un animateur utilise les chiffres comme point de discussion, sans en faire la définition complète du progrès. Ce qui se mesure simplement n'épuise pas ce qui compte pour la personne. Une personne peut marcher moins longtemps qu'une autre tout en retrouvant la possibilité de sortir de chez elle. Une autre cherche surtout à partager une activité avec des amis. L'animateur souhaite pouvoir entendre ces objectifs sans les remplacer par un classement unique. Il ne rejette pas les mesures, mais demande qu'elles restent des outils de compréhension. Les participants pourront choisir ce qu'ils veulent suivre et expliquer ce qu'ils ressentent. Deux membres atteignent le même nombre de pas. L'une se fatigue davantage qu'avant; l'autre se sent capable de reprendre un trajet qu'elle évitait. L'animateur conserve la mesure, mais discute de ce qu'elle représente réellement pour chacun.","question":"Pourquoi l'animateur ne classe-t-il pas les progrès à partir du seul nombre de pas ?","explanation":"B constate que des totaux égaux peuvent correspondre à des situations distinctes de fatigue ou d'autonomie. A/C substituent un autre classement unique, et D attribue à la durée un pouvoir de description non démontré."},{"number":38,"points":33,"correct":"A","options":["Sur l'adaptation de l'aménagement à des usages observés mais non prévus.","Sur une hausse générale de l'activité physique due aux bancs, mesurée avant les premières rencontres du quartier.","Sur la nécessité de réserver les appareils aux usagers qui les utilisent selon les exercices du plan initial.","Sur un objectif de fréquentation sportive qui demeure inchangé malgré les rencontres spontanées observées."],"passage":"Une ville installe des équipements sportifs dans un parc. Les services observent des usages imprévus : certains habitants s'y retrouvent pour discuter et font quelques mouvements ensemble. Plutôt que restreindre cet usage, ils ajoutent des bancs. Un aménagement peut produire des bénéfices différents de ceux que ses concepteurs avaient précisément anticipés. Les agents constatent que les rencontres régulières encouragent parfois des personnes jusque-là hésitantes à essayer les appareils. Ils vont donc continuer à observer le lieu à différentes heures avant de fixer de nouvelles règles. Les usagers pourront proposer de petits changements et signaler les difficultés. La commune ne veut pas transformer chaque usage imprévu en erreur à corriger. Elle cherche à comprendre ce que l'installation rend possible dans la vie du quartier, au-delà du programme exact qui avait été imaginé sur le plan initial. Lorsque les bancs sont installés, des personnes qui venaient d'abord pour discuter commencent à utiliser les appareils avec des voisins. Les agents notent cette évolution sans la traiter comme le résultat nécessairement prévu dès la conception.","question":"Sur quoi repose l'adaptation décidée par la ville ?","explanation":"A décrit l'adaptation à des usages réels, notamment les échanges et l'essai progressif des appareils. B affirme un effet général non mesuré, C restreint les usages que la ville accueille, D ignore l'ajustement du projet."},{"number":39,"points":33,"correct":"A","options":["Les séances semblent améliorer le ressenti immédiat dans les deux services; la réduction durable des heures supplémentaires coïncide avec une réorganisation, sans preuve causale isolée.","La baisse des heures supplémentaires dans le premier service montre que les séances de relaxation y ont fonctionné plus efficacement que dans le second, même si les salariés décrivent des charges de travail initiales différentes.","La révision des délais explique à elle seule l'écart observé, puisque les effectifs des deux services étaient proches pendant l'expérience.","Les déclarations positives dans les deux services établissent une amélioration comparable des contraintes de travail, malgré la divergence des heures supplémentaires."],"passage":"Une organisation souhaite prévenir l'épuisement professionnel en proposant des séances de relaxation. Les salariés apprécient l'offre, mais demandent aussi de revoir une répartition de tâches devenue irréaliste. Un soutien individuel peut être utile sans remplacer la transformation des conditions collectives qui produisent la difficulté. Certains décrivent des journées où les demandes s'ajoutent sans que les priorités soient revues. D'autres évoquent des interruptions qui rendent difficile l'achèvement d'une tâche. Les représentants souhaitent que ces éléments soient discutés avec les responsables du service. Ils ne demandent pas de supprimer les séances proposées, mais de ne pas les utiliser comme preuve que le problème serait désormais traité. Le programme sera donc accompagné d'un examen des effectifs, des délais et des possibilités de récupération. Son intérêt dépendra aussi de cette cohérence entre aide personnelle et fonctionnement quotidien du travail. Dans un service, une séance de relaxation a lieu chaque semaine, mais la quantité de dossiers urgents ne change pas et les heures supplémentaires continuent d'augmenter. Le comité propose d'évaluer séparément les bénéfices ressentis de la séance et les effets d'une révision des délais. Pour vérifier ce qui change réellement, deux services de taille proche conservent les mêmes séances hebdomadaires pendant huit semaines. Dans le premier, les responsables révisent également les délais et répartissent les urgences; dans le second, le nombre de dossiers et les interruptions restent inchangés. Dans les deux services, les participants déclarent se sentir plus détendus immédiatement après la séance. Mais seul le premier présente une baisse durable des heures supplémentaires. Les salariés de ce premier service disent aussi avoir pu refuser certaines urgences sans justification individuelle. La direction signale que les deux équipes n'étaient pas constituées par tirage au sort et que les volumes de dossiers avaient déjà légèrement divergé avant le début de l'observation. Le comité refuse donc d'attribuer avec certitude toute la différence à la réorganisation, tout en refusant d'assimiler le ressenti à une réduction de la surcharge.","question":"Quelle interprétation des observations reste la mieux justifiée sans attribuer abusivement les résultats à une seule mesure ?","explanation":"A distingue le bénéfice déclaré immédiatement après les séances, commun aux deux services, de la baisse durable des heures supplémentaires observée seulement là où les tâches ont été réorganisées. Les équipes non randomisées et les tendances initiales différentes empêchent d'isoler un effet causal. B attribue à la relaxation l'écart sans élément comparatif; C transforme une coïncidence en preuve exclusive; D confond soulagement ressenti et réduction objective de la surcharge."}]}$paper_8$::jsonb),
('tcf-reading-09','tcf-reading-2026-11-close-reading-v4',$paper_9${"id":"tcf-reading-09","title":"TCF Reading · Test 09","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["Acheter un billet obligatoire","Assister à la séance de quinze heures","Revenir uniquement le mois prochain","Visiter gratuitement une autre ville"],"passage":"Le planétarium annule la séance de midi pour réparation. Les billets restent valables pour celle de quinze heures.\n\nLes personnes indisponibles pourront contacter l'accueil pour un échange. La boutique restera ouverte pendant les horaires habituels du musée.","question":"Quelle solution est proposée ?","explanation":"Le passage indique : « Le planétarium annule la séance de midi pour réparation. Les billets restent valables pour celle de quinze heures. » Cela justifie la réponse : Assister à la séance de quinze heures."},{"number":2,"points":3,"correct":"A","options":["Un carnet","Un tournevis","Une perceuse","Un robot terminé"],"passage":"L'atelier robotique prête des tournevis. Apportez seulement un carnet pour noter vos essais.\n\nLes animateurs montreront comment utiliser chaque outil. Aucun montage ne devra être commencé avant la présentation des consignes communes.","question":"Quel objet faut-il apporter ?","explanation":"Le passage indique : « L'atelier robotique prête des tournevis. Apportez seulement un carnet pour noter vos essais. » Cela justifie la réponse : Un carnet."},{"number":3,"points":3,"correct":"B","options":["Uniquement les chercheurs","Des enfants accompagnés et inscrits","Des classes sans réservation","Des mineurs obligatoirement seuls"],"passage":"Le laboratoire ouvre ses portes samedi sur inscription. Les enfants doivent être accompagnés ; les groupes scolaires ont un autre créneau.\n\nUne confirmation précisera l'entrée et la durée du parcours.","question":"Qui peut venir samedi ?","explanation":"Le passage indique : « Le laboratoire ouvre ses portes samedi sur inscription. Les enfants doivent être accompagnés ; les groupes scolaires ont un autre créneau. » Cela justifie la réponse : Des enfants accompagnés et inscrits."},{"number":4,"points":3,"correct":"D","options":["Tout le matériel est vendu","L'horaire est reporté d'un an","Les participants montent seuls sur le toit","L'activité se poursuit à l'intérieur"],"passage":"L'observation des étoiles dépend de la météo. Si le ciel est couvert, une présentation aura lieu dans la salle attenante.\n\nCette solution permet de conserver la rencontre même si les conditions extérieures sont défavorables.","question":"Que se passe-t-il en cas de nuages ?","explanation":"Le passage indique : « L'observation des étoiles dépend de la météo. Si le ciel est couvert, une présentation aura lieu dans la salle attenante. » Cela justifie la réponse : L'activité se poursuit à l'intérieur."},{"number":5,"points":9,"correct":"C","options":["Pour supprimer tous les résultats","Pour attendre un financement","Pour contrôler la fiabilité de l'instrument","Pour changer le sujet du projet"],"passage":"Je t'envoie mes mesures demain après avoir vérifié le thermomètre. Les valeurs de ce matin semblaient inhabituelles.\n\nJ'ai demandé à une collègue de refaire un relevé avec un autre appareil. Nous comparerons les deux séries avant de rédiger le compte rendu et de tirer une conclusion.","question":"Pourquoi l'envoi est-il différé ?","explanation":"Le passage indique : « Je t'envoie mes mesures demain après avoir vérifié le thermomètre. Les valeurs de ce matin semblaient inhabituelles. » Cela justifie la réponse : Pour contrôler la fiabilité de l'instrument."},{"number":6,"points":9,"correct":"C","options":["Une caméra professionnelle","Une antenne radio","Aucun télescope n'est exigé","Un grand télescope"],"passage":"Le club d'astronomie accueille les curieux sans télescope personnel. Des instruments seront installés par les bénévoles.\n\nLes bénévoles aideront chacun à regarder et répondront aux questions. Une carte du ciel sera distribuée pour retrouver ensuite quelques repères sans matériel complexe.","question":"Quel équipement personnel est obligatoire ?","explanation":"Le passage indique : « Le club d'astronomie accueille les curieux sans télescope personnel. Des instruments seront installés par les bénévoles. » Cela justifie la réponse : Aucun télescope n'est exigé."},{"number":7,"points":9,"correct":"A","options":["Une faible lumière extérieure","Un accès réservé aux vendeurs","Une exposition maximale au soleil","Une température tropicale"],"passage":"Notre groupe cherche un local sombre pour tester les lampes. Une grande fenêtre rendrait les comparaisons plus difficiles.\n\nIl nous faut surtout garder les mêmes conditions pendant les essais. Nous noterons chaque changement pour comprendre ce qui pourrait expliquer une différence entre deux résultats.","question":"Quelle caractéristique du local est recherchée ?","explanation":"Le passage indique : « Notre groupe cherche un local sombre pour tester les lampes. Une grande fenêtre rendrait les comparaisons plus difficiles. » Cela justifie la réponse : Une faible lumière extérieure."},{"number":8,"points":9,"correct":"A","options":["Aussi aux personnes sans formation scientifique","Uniquement aux chercheurs diplômés","Seulement aux vendeurs d'instruments","Aux participants refusant les explications"],"passage":"Bonjour, la conférence reste ouverte aux non-spécialistes. Le vocabulaire sera expliqué et un temps sera prévu pour les questions.\n\nLes personnes souhaitant approfondir recevront des références après la rencontre, sans devoir tout comprendre dès les premières minutes.","question":"À quel public s'adresse l'événement ?","explanation":"Le passage indique : « Bonjour, la conférence reste ouverte aux non-spécialistes. Le vocabulaire sera expliqué et un temps sera prévu pour les questions. » Cela justifie la réponse : Aussi aux personnes sans formation scientifique."},{"number":9,"points":9,"correct":"D","options":["La présence d'un animateur","L'observation des pièces","L'ouverture de l'atelier","La réparation de l'appareil"],"passage":"Apportez votre appareil cassé à l'atelier démontage. Nous étudierons ses composants, sans garantir sa remise en marche.\n\nLes objets dangereux ou trop volumineux seront refusés, et les propriétaires repartiront avec les pièces à la fin de la séance.","question":"Quel résultat n'est pas garanti ?","explanation":"Le passage indique : « Apportez votre appareil cassé à l'atelier démontage. Nous étudierons ses composants, sans garantir sa remise en marche. » Cela justifie la réponse : La réparation de l'appareil."},{"number":10,"points":9,"correct":"C","options":["Éviter toute répétition","Obtenir un résultat décidé d'avance","Rendre les conditions comparables","Augmenter la couleur des liquides"],"passage":"Nous répéterons l'expérience avec des récipients identiques. Les formes différentes utilisées hier empêchaient de comparer correctement.\n\nNous conserverons les autres paramètres pour mieux identifier l'effet observé. Le groupe préparera un tableau commun avant de recommencer les mesures dans les conditions prévues.","question":"Pourquoi changer les récipients ?","explanation":"Le passage indique : « Nous répéterons l'expérience avec des récipients identiques. Les formes différentes utilisées hier empêchaient de comparer correctement. » Cela justifie la réponse : Rendre les conditions comparables."},{"number":11,"points":15,"correct":"A","options":["L'heure de la mesure","Le lieu choisi","La longueur du bâton","Le nombre de saisons"],"passage":"Des collégiens mesurent l'ombre d'un bâton à plusieurs heures. Ils gardent le bâton au même endroit pour observer l'évolution au cours de la journée.\n\nIls notent chaque observation sur un dessin du sol, avec la date et l'état du ciel. Les journées couvertes donnent aussi lieu à une discussion sur ce qui reste visible. Leur professeur ne leur demande pas de retrouver un chiffre annoncé d'avance, mais de décrire une série cohérente. Les résultats seront comparés entre deux groupes pour repérer les difficultés de lecture. Les élèves expliqueront ensuite les limites de leur expérience, notamment ce qu'ils ne peuvent pas déduire d'une seule journée d'observation.","question":"Qu'est-ce qui varie dans leur protocole ?","explanation":"Le passage indique : « Des collégiens mesurent l'ombre d'un bâton à plusieurs heures. Ils gardent le bâton au même endroit pour observer l'évolution au cours de la journée. » Cela justifie la réponse : L'heure de la mesure."},{"number":12,"points":15,"correct":"B","options":["Dissimuler les méthodes employées","Rendre les tentatives infructueuses utiles à d'autres","Remplacer les expériences futures par des opinions","Prouver que toute recherche échoue"],"passage":"Une équipe publie aussi les essais qui n'ont pas confirmé son hypothèse. Ces résultats peuvent éviter à d'autres de répéter inutilement les mêmes démarches.\n\nLe compte rendu décrit les conditions et les vérifications réalisées avant l'arrêt de la tentative. Les auteurs souhaitent rendre ces informations compréhensibles, même lorsque le résultat ne se transforme pas en application immédiate. Une autre équipe pourra ainsi comparer ses propres méthodes et identifier une différence utile.","question":"Quel intérêt présente cette publication ?","explanation":"Le passage indique : « Une équipe publie aussi les essais qui n'ont pas confirmé son hypothèse. Ces résultats peuvent éviter à d'autres de répéter inutilement les mêmes démarches. » Cela justifie la réponse : Rendre les tentatives infructueuses utiles à d'autres."},{"number":13,"points":15,"correct":"D","options":["Elle fonctionne comme un volcan réel","Elle remplace toutes les observations","Elle permet de prévoir toute éruption","Elle simplifie la réalité"],"passage":"Un musée prête une maquette démontable de volcan. Les visiteurs découvrent une représentation simplifiée, pas une reproduction de tous les phénomènes réels.\n\nLes médiateurs montrent ce qui a été conservé et ce qui a été laissé de côté pour rendre l'ensemble lisible. Les visiteurs peuvent poser des questions sur la différence entre une représentation et une observation sur le terrain. Des photographies et des mesures complètent donc l'activité. Elles permettent de comprendre pourquoi plusieurs outils sont nécessaires pour étudier un phénomène dont les dimensions et les rythmes ne tiennent pas dans une salle.","question":"Quelle limite de la maquette est indiquée ?","explanation":"Le passage indique : « Un musée prête une maquette démontable de volcan. Les visiteurs découvrent une représentation simplifiée, pas une reproduction de tous les phénomènes réels. » Cela justifie la réponse : Elle simplifie la réalité."},{"number":14,"points":15,"correct":"C","options":["Rendre les capteurs invisibles aux oiseaux","Augmenter automatiquement les températures","Éviter une influence locale qui fausserait la comparaison","Accélérer la croissance des arbres"],"passage":"Des bénévoles relèvent la température de leur quartier. Les capteurs sont placés à l'ombre, loin des murs chauffés par le soleil.\n\nLes participants reçoivent une fiche d'installation et photographient l'emplacement choisi. Une équipe vérifiera quelques points avant d'utiliser les séries dans une carte commune. Les habitants peuvent aussi noter les changements survenus autour du capteur, comme un déplacement ou des travaux. Le projet souhaite multiplier les observations sans présenter tous les nombres recueillis comme directement comparables. Les consignes communes servent à distinguer une différence entre quartiers d'un effet produit par la manière de placer l'appareil.","question":"Pourquoi préciser leur emplacement ?","explanation":"Le passage indique : « Des bénévoles relèvent la température de leur quartier. Les capteurs sont placés à l'ombre, loin des murs chauffés par le soleil. » Cela justifie la réponse : Éviter une influence locale qui fausserait la comparaison."},{"number":15,"points":15,"correct":"D","options":["Le prix du verre","La vitesse de livraison du produit","La couleur des couvercles","La facilité d'utilisation pour divers profils"],"passage":"Une invention facilite l'ouverture des bocaux. Ses concepteurs invitent des utilisateurs aux forces différentes pour tester la poignée.\n\nLes volontaires essaient plusieurs positions et expliquent les moments où la prise leur semble inconfortable. Les concepteurs notent aussi les remarques des personnes qui comprennent moins vite la forme du dispositif. L'essai ne consiste pas à choisir l'utilisateur le plus habile, mais à voir si la poignée facilite réellement le geste pour des personnes différentes. Les prototypes seront modifiés avant une seconde séance. Le groupe veut éviter qu'un bon résultat obtenu par une seule personne serve de promesse générale au moment de présenter le produit.","question":"Quel critère veulent-ils examiner ?","explanation":"Le passage indique : « Une invention facilite l'ouverture des bocaux. Ses concepteurs invitent des utilisateurs aux forces différentes pour tester la poignée. » Cela justifie la réponse : La facilité d'utilisation pour divers profils."},{"number":16,"points":15,"correct":"C","options":["Éviter toute comparaison","Remplacer les images actuelles par des publicités","Observer des changements sur la durée","Garantir que rien ne change"],"passage":"Un observatoire diffuse des images en direct, mais archive aussi les séries anciennes. Les comparaisons dans le temps aident à repérer des évolutions lentes.\n\nLes responsables gardent les dates, les réglages et les informations sur les instruments utilisés. Les chercheurs qui consultent les archives peuvent ainsi apprécier les différences entre deux séries. L'observatoire souhaite que les anciennes données restent compréhensibles lorsque les appareils changent. Il ne conserve pas seulement de belles images, mais des éléments permettant de poser de nouvelles questions.","question":"À quoi servent les archives ?","explanation":"Le passage indique : « Un observatoire diffuse des images en direct, mais archive aussi les séries anciennes. Les comparaisons dans le temps aident à repérer des évolutions lentes. » Cela justifie la réponse : Observer des changements sur la durée."},{"number":17,"points":15,"correct":"D","options":["Le nombre d'affiches commerciales","Le nom du livreur","La forme de la facture","L'autonomie de la batterie"],"passage":"Un fabricant annonce une batterie plus légère. L'équipe de test mesure aussi sa durée de fonctionnement avant de juger le progrès.\n\nLes essais portent sur des usages comparables, avec les mêmes réglages. L'équipe indique les conditions retenues pour que les lecteurs puissent apprécier la portée du résultat. Elle examine aussi les situations où le gain de poids serait particulièrement utile. Un appareil destiné à rester posé ne présente pas les mêmes besoins qu'un équipement porté pendant plusieurs heures. Les résultats seront donc présentés avec plusieurs critères plutôt qu'une seule formule annonçant un progrès identique pour tous les acheteurs.","question":"Quelle information complémentaire est nécessaire ?","explanation":"Le passage indique : « Un fabricant annonce une batterie plus légère. L'équipe de test mesure aussi sa durée de fonctionnement avant de juger le progrès. » Cela justifie la réponse : L'autonomie de la batterie."},{"number":18,"points":15,"correct":"C","options":["Écarter tous les non-spécialistes","Interdire les désaccords","Mieux organiser la discussion","Fixer les réponses avant le débat"],"passage":"La médiathèque organise un débat avec une chercheuse. Les questions seront regroupées par thème pour éviter de répéter les mêmes échanges.\n\nLes participants peuvent envoyer une question auparavant ou la poser pendant le temps d'échange. L'animatrice expliquera pourquoi certaines demandes sont rapprochées et laissera la possibilité de signaler un point oublié. La bibliothèque souhaite conserver une discussion accessible malgré la diversité du public. La chercheuse pourra préciser ce qu'elle sait et ce qui dépasse son domaine de travail.","question":"Pourquoi regrouper les questions ?","explanation":"Le passage indique : « La médiathèque organise un débat avec une chercheuse. Les questions seront regroupées par thème pour éviter de répéter les mêmes échanges. » Cela justifie la réponse : Mieux organiser la discussion."},{"number":19,"points":15,"correct":"A","options":["Explorer le fonctionnement du dispositif","Éviter de modifier l'orientation","Ouvrir immédiatement un restaurant","Garantir une cuisson par tous les temps"],"passage":"Un club construit un four solaire. Le repas prévu reste simple : l'objectif est de comprendre les effets de l'orientation et de l'ensoleillement.\n\nLes participants compareront plusieurs positions et noteront le temps nécessaire dans les conditions du jour. Le responsable a prévu une solution pour le repas si le ciel se couvre durablement. Il veut éviter que cette contrainte empêche de poursuivre les observations. Le groupe discutera ensuite de ce que l'essai montre réellement et des situations où un tel appareil peut être utile.","question":"Quel est l'objectif principal ?","explanation":"Le passage indique : « Un club construit un four solaire. Le repas prévu reste simple : l'objectif est de comprendre les effets de l'orientation et de l'ensoleillement. » Cela justifie la réponse : Explorer le fonctionnement du dispositif."},{"number":20,"points":21,"correct":"B","options":["Les essais sur petites pièces sont toujours inutiles","Le changement d'échelle doit être vérifié","Les matériaux sont déjà interdits","Toute comparaison est impossible"],"passage":"Une étude compare deux matériaux sur de petites pièces. Ses auteurs demandent des essais supplémentaires avant de généraliser les résultats à de grandes constructions. Les spécialistes devront notamment examiner la résistance dans la durée et les contraintes de fabrication. Une petite pièce permet de contrôler facilement certaines conditions qui deviennent plus difficiles à maintenir ailleurs. Le laboratoire souhaite publier un résultat utile sans lui attribuer une portée que l'expérience n'a pas encore vérifiée. Les partenaires pourront ensuite choisir les essais nécessaires à leur propre projet.","question":"Quelle prudence expriment-ils ?","explanation":"Le passage indique : « Une étude compare deux matériaux sur de petites pièces. Ses auteurs demandent des essais supplémentaires avant de généraliser les résultats à de grandes constructions. » Cela justifie la réponse : Le changement d'échelle doit être vérifié."},{"number":21,"points":21,"correct":"C","options":["Éliminer les artisans du projet","Choisir uniquement la meilleure photographie","Croiser mesures techniques et expérience d'usage","Remplacer toute mesure par une anecdote"],"passage":"Un laboratoire échange avec des artisans sur les usages d'un nouvel outil. Les chercheurs disposent de mesures précises ; les professionnels signalent des contraintes rencontrées pendant une journée réelle. Un outil rapide sur une table d'essai peut être difficile à nettoyer, à ranger ou à utiliser avec des gants. Les artisans décrivent ces situations avec des exemples. L'équipe veut intégrer ces remarques pendant qu'il est encore possible de modifier le prototype. La consultation ne remplace pas les mesures ; elle aide à choisir celles qui correspondent aux difficultés réellement rencontrées.","question":"Quel est l'intérêt de l'échange ?","explanation":"Le passage indique : « Un laboratoire échange avec des artisans sur les usages d'un nouvel outil. Les chercheurs disposent de mesures précises ; les professionnels signalent des contraintes rencontrées pendant une journée réelle. » Cela justifie la réponse : Croiser mesures techniques et expérience d'usage."},{"number":22,"points":21,"correct":"B","options":["Un laboratoire et un musée","Un potentiel et un résultat déjà généralisable","Une expérience et une absence totale de résultat","Deux découvertes nécessairement opposées"],"passage":"Une annonce parle d'une découverte « prometteuse ». Le compte rendu précise qu'elle a été observée dans des conditions limitées. Les deux formulations ne sont pas contradictoires, mais elles n'autorisent pas la même attente. Les journalistes sont invités à expliquer la taille de l'essai et les étapes encore nécessaires. Les chercheurs ne souhaitent ni minimiser une piste intéressante, ni laisser croire qu'elle donne déjà une solution disponible pour tous.","question":"Que faut-il distinguer ?","explanation":"Le passage indique : « Une annonce parle d'une découverte « prometteuse ». Le compte rendu précise qu'elle a été observée dans des conditions limitées. Les deux formulations ne sont pas contradictoires, mais elles n'autorisent pas la même attente. » Cela justifie la réponse : Un potentiel et un résultat déjà généralisable."},{"number":23,"points":21,"correct":"A","options":["Relier les mesures aux situations vécues","Remplacer la carte par des votes","Annuler toutes les températures enregistrées","Garantir une météo uniforme"],"passage":"Une ville utilise des capteurs pour repérer les îlots de chaleur. Elle confronte les données aux témoignages des habitants, notamment pour identifier les lieux utilisés aux heures chaudes. Certains points sont très chauds mais peu fréquentés, tandis que d'autres accueillent de longues attentes sans ombre. Les responsables souhaitent distinguer ces situations avant de décider où intervenir. Les témoignages ne changent pas la température mesurée ; ils apportent une information sur son importance dans la vie quotidienne.","question":"Pourquoi ajouter ces témoignages ?","explanation":"Le passage indique : « Une ville utilise des capteurs pour repérer les îlots de chaleur. Elle confronte les données aux témoignages des habitants, notamment pour identifier les lieux utilisés aux heures chaudes. » Cela justifie la réponse : Relier les mesures aux situations vécues."},{"number":24,"points":21,"correct":"B","options":["L'absence de tout réglage","La vérification des mesures","La suppression des relevés","L'achat d'un appareil plus lourd"],"passage":"Un appareil de mesure devient moins cher. Les utilisateurs doivent toujours l'étalonner : une grande diffusion ne garantit pas que chaque instrument donne spontanément une valeur fiable. La notice fournit une procédure courte et un repère pour contrôler l'appareil. Les utilisateurs peuvent signaler une difficulté au distributeur ou à l'association qui organise les relevés. Un instrument accessible financièrement reste utile si les personnes savent aussi dans quelles conditions elles peuvent se fier aux valeurs qu'il affiche.","question":"Quelle exigence demeure ?","explanation":"Le passage indique : « Un appareil de mesure devient moins cher. Les utilisateurs doivent toujours l'étalonner : une grande diffusion ne garantit pas que chaque instrument donne spontanément une valeur fiable. » Cela justifie la réponse : La vérification des mesures."},{"number":25,"points":21,"correct":"D","options":["Parce que la durée de démontage mesure mieux la réparabilité que l'accès aux pièces réellement nécessaires.","Parce que les pièces vendues séparément rendent une opération de réparation plus coûteuse que le remplacement intégral.","Parce qu'un appareil facile à ouvrir peut être réparé à moindre coût même lorsque les éléments défectueux ne sont pas vendus à l'unité.","Parce que le diagnostic et l'accès à l'élément à remplacer conditionnent aussi la réparation effective."],"passage":"Un concours récompense une solution réparable avec des outils courants. Le jury regarde aussi les pièces détachées disponibles ; une conception démontable serait peu utile sans possibilité de remplacer les éléments. Les candidats présentent un exemple de démontage et expliquent les outils nécessaires. Le jury demande aussi comment un utilisateur pourra identifier la pièce défectueuse. Il souhaite distinguer une possibilité théorique d'ouverture et une réparation réellement réalisable. Un appareil s'ouvre en moins de cinq minutes, mais sa pièce la plus fragile n'est vendue qu'avec l'ensemble du mécanisme. Un autre demande un démontage plus long mais permet l'achat de l'élément seul. Le jury compare alors faisabilité matérielle et réparation accessible.","question":"Pourquoi la facilité de démontage ne suffit-elle pas à désigner le produit le plus réparable ?","explanation":"D exige l'identification de la panne et l'accès effectif à la pièce requise; l'exemple oppose un démontage rapide sans vente de l'élément seul à un démontage plus long avec pièce disponible. A réduit le critère à la durée; B suppose un surcoût non établi; C conclut qu'une ouverture facile suffit à rendre une réparation moins chère malgré l'indisponibilité de la pièce individuelle."},{"number":26,"points":21,"correct":"A","options":["Les hypothèses sont confrontées à partir d'observations communes et de nouveaux tests.","Les spécialistes doivent choisir l'explication la plus largement admise avant de recueillir de nouvelles mesures.","L'écart entre leurs hypothèses rend les relevés communs trop incertains pour être comparés efficacement.","Leur désaccord tient principalement à des méthodes différentes qu'ils n'ont pas encore cherché à harmoniser."],"passage":"Des scientifiques expliquent leur travail dans des ateliers publics. Ils présentent leurs désaccords sur certaines interprétations sans remettre en cause les observations communes. Les visiteurs découvrent des méthodes communes de vérification, mais aussi des questions qui restent ouvertes. Les intervenants expliquent comment ils comparent leurs interprétations et quelles observations pourraient les conduire à changer d'avis. Le programme veut donner une image plus précise du travail scientifique, sans le réduire à une collection de certitudes ni à une simple opposition d'opinions sans critères partagés. Deux spécialistes utilisent les mêmes mesures, mais l'un attribue l'écart à l'appareil et l'autre à une variation naturelle. Ils présentent un prochain relevé qui pourrait départager ces hypothèses plutôt que demander au public de choisir par préférence.","question":"Que révèle le désaccord présenté pendant l'atelier ?","explanation":"A montre que les hypothèses partagent des observations et peuvent être départagées par des tests. B demande une adhésion préalable, C nie la comparabilité, D attribue le désaccord à des méthodes divergentes alors que les mesures sont communes."},{"number":27,"points":21,"correct":"A","options":["Il aide à détecter les anomalies manquées par le logiciel avant le jugement humain.","L'examen des images non signalées confirme la fiabilité globale du tri tant qu'aucune anomalie n'a été signalée.","Le contrôle des images rejetées permet de réduire l'intervention des lecteurs humains après une première validation automatique.","Le contrôle sert surtout à estimer combien de temps le logiciel économise sur les images ordinaires sans anomalie."],"passage":"Un logiciel repère des anomalies dans des photographies. Les cas signalés sont ensuite examinés par une personne. L'outil accélère le tri, mais ne remplace pas la décision finale. Les personnes chargées de la lecture finale doivent comprendre les erreurs possibles et les limites des images utilisées. Le laboratoire conserve aussi des exemples où le logiciel n'a rien signalé, afin de vérifier ce qu'il pourrait manquer. Le logiciel détecte souvent de faibles contrastes mais manque parfois une anomalie à la périphérie. Le laboratoire vérifie des images signalées et non signalées, puis confie le jugement final à un lecteur formé.","question":"Quel rôle joue l'examen d'images que le logiciel n'a pas signalées ?","explanation":"A décrit la recherche d'anomalies manquées pour vérifier les faux négatifs. B prend l'absence d'alerte pour preuve, C réduit à tort la supervision, D limite l'évaluation à la vitesse."},{"number":28,"points":21,"correct":"C","options":["La différence d'appareil montre que le phénomène est indépendant des conditions de préparation des échantillons.","La variation des réglages rend la comparaison impossible tant que tous les instruments ne sont pas identiques.","Le résultat semble transférable sous certaines conditions de préparation qu'il faut expliciter.","Le résultat initial devrait être considéré comme invalide puisqu'il n'a pas été retrouvé à toutes les températures."],"passage":"Une équipe répète une expérience dans un second laboratoire. Les conditions sont décrites précisément afin de comprendre d'éventuelles différences. Les équipes gardent une trace des réglages et discutent des écarts avant de modifier leur protocole. Elles veulent distinguer un effet du matériel d'une différence liée à la préparation. Il reste essentiel pour savoir dans quelles conditions un résultat peut être utilisé par d'autres personnes et avec quel degré de confiance. Le second laboratoire retrouve l'effet avec un appareil différent, mais seulement lorsque les échantillons sont préparés à la même température que dans le premier. Les chercheurs enregistrent ce paramètre pour préciser la portée de l'observation.","question":"Quelle conclusion est justifiée par la reproduction partielle du résultat ?","explanation":"C identifie les conditions de préparation nécessaires à la reproduction. A néglige la température, B demande une identité matérielle non nécessaire, D rejette un résultat dont le domaine de validité est mieux précisé."},{"number":29,"points":21,"correct":"C","options":["Une démonstration techniquement réussie suffit pour prévoir l'adoption si le produit répond aux performances annoncées.","Les coûts d'entretien peuvent affecter l'adoption, mais les habitudes des utilisateurs se modifient automatiquement après l'achat.","L'adoption dépend aussi des coûts et des pratiques des utilisateurs concernés.","Les premières inventions avaient moins de qualités techniques, ce qui explique leur moindre diffusion malgré les démonstrations."],"passage":"Une exposition présente des inventions abandonnées. Certaines avaient de bonnes performances techniques, mais ne répondaient pas aux pratiques ou aux moyens des utilisateurs. Les visiteurs peuvent ainsi suivre une histoire moins simple qu'une opposition entre réussite et mauvaise invention. Le musée souhaite montrer que l'adoption d'un objet dépend de plusieurs acteurs et de contraintes concrètes, qui ne sont pas toujours visibles dans une démonstration technique réalisée devant un public enthousiaste. Une invention démontrée avec succès exigeait toutefois une maintenance chère et des gestes absents des habitudes du public visé. Une autre, moins spectaculaire, a été adoptée grâce à son intégration facile dans le travail courant.","question":"Que met en évidence la comparaison des deux inventions ?","explanation":"C associe l'adoption aux coûts et aux pratiques. A suppose un transfert automatique de performance à usage, B minimise la difficulté d'intégration, D attribue l'échec à une faible qualité technique non établie."},{"number":30,"points":26,"correct":"B","options":["Une moyenne plus élevée permettrait de distinguer directement les résultats dispersés sans consulter les notes individuelles.","Une moyenne identique peut masquer des distributions et des besoins différents.","Une distribution présentant des extrêmes donne nécessairement une moyenne trompeuse qu'il faudrait recalculer autrement.","Deux groupes ayant la même moyenne montrent des performances comparables dans presque toutes les catégories d'élèves."],"passage":"Un chiffre moyen résume une série de mesures, mais peut masquer des écarts importants. Une médiatrice montre deux ensembles ayant la même moyenne et des répartitions très différentes. L'indicateur reste correct ; sa lecture doit être complétée. Elle invite donc le public à regarder plusieurs valeurs et les écarts entre elles. Les participants apprennent à poser une question sur ce qu'un résumé laisse visible ou rend plus difficile à voir. Une classe et une autre obtiennent une note moyenne de 12; dans la première, presque tous se situent autour de 12, tandis que la seconde rassemble surtout des notes très faibles et très fortes. La moyenne ne change pas, mais les besoins d'accompagnement sont différents.","question":"Pourquoi le même chiffre moyen conduit-il ici à des interprétations distinctes ?","explanation":"B distingue moyenne et répartition des notes. A et D infèrent la dispersion d'un résumé insuffisant, C qualifie la moyenne d'erronée alors qu'elle peut être exacte."},{"number":31,"points":26,"correct":"B","options":["Les pannes apparues plus tard devraient invalider les mesures de performance réalisées sous l'assistance du concepteur.","Un fonctionnement ponctuel assisté ne permet pas, seul, d'établir la fiabilité dans les conditions ordinaires.","Le maintien d'une assistance technique pendant le pilote permettrait de prédire plus sûrement son usage quotidien sans suivi.","La démonstration ne doit être prise en compte que si les conditions du site pilote sont strictement identiques."],"passage":"Un prototype fonctionne en démonstration sous la surveillance de ses concepteurs. Pour apprécier son usage futur, il faut aussi observer l'entretien, les erreurs ordinaires et les contraintes des lieux d'installation. La réussite ponctuelle ne constitue pas encore un bilan d'utilisation. Le fabricant souhaite que les futurs utilisateurs puissent apprécier l'écart entre une possibilité technique montrée une fois et un service fiable dans leurs propres conditions de travail. En laboratoire, le concepteur corrige aussitôt chaque blocage. Sur le site pilote, les utilisateurs ne disposent pas de cette présence permanente et signalent des pannes après plusieurs jours. Une démonstration courte ne révèle pas les mêmes problèmes.","question":"Quelle limite d'évaluation illustre la différence entre la démonstration et le site pilote ?","explanation":"B constate qu'un essai ponctuel accompagné ne mesure pas la fiabilité durable. A invalide abusivement la performance instantanée, C continue de masquer les problèmes de maintenance, D impose des conditions identiques plutôt qu'une évaluation contextualisée."},{"number":32,"points":26,"correct":"B","options":["Les fiches de provenance suffisent à analyser de nouveaux phénomènes sans reprendre de mesures sur les spécimens.","Elles relient des observations nouvelles au contexte des prélèvements anciens.","La localisation initiale assure la validité d'hypothèses futures même lorsque leurs méthodes ont profondément changé.","Les informations anciennes restent plus fiables que les nouvelles analyses lorsqu'un instrument différent est employé."],"passage":"Les collections anciennes d'un musée peuvent servir à de nouvelles recherches. Des méthodes récentes révèlent des informations que les premiers collecteurs ne pouvaient pas observer. La conservation maintient ainsi des possibilités de questions futures, pas seulement le souvenir d'un savoir déjà établi. Les chercheurs peuvent revenir sur des spécimens avec des questions nouvelles. La valeur d'une collection dépend alors aussi des descriptions et des conditions de conservation qui permettent de comprendre ce qui a été recueilli à l'époque. Des échantillons anciens ont été conservés avec leurs lieux de prélèvement. Une nouvelle technique permet de mesurer aujourd'hui une propriété inconnue à l'époque; sans ces informations sur l'origine des échantillons, l'analyse aurait moins de portée.","question":"Pourquoi les informations de collecte participent-elles à la valeur scientifique des spécimens ?","explanation":"B montre que le contexte d'origine donne un sens aux mesures réalisées plus tard. A/C font des métadonnées une preuve suffisante, D les oppose aux méthodes récentes au lieu de les associer."},{"number":33,"points":26,"correct":"D","options":["La plage ajoutée évite de comparer les catégories, car le graphique décrit désormais une variation possible plutôt qu'une valeur.","La représentation d'une marge d'erreur réduit directement l'incertitude des mesures sur lesquelles le graphique repose.","Une seconde couche graphique rend les catégories plus comparables parce qu'elles disposent de davantage d'indicateurs visibles.","Elle montre une incertitude qui peut modifier la comparaison des estimations."],"passage":"Une représentation graphique peut simplifier un ensemble complexe sans le trahir. Le risque apparaît lorsqu'elle efface une limite essentielle, par exemple une incertitude sur une estimation. La clarté ne consiste donc pas toujours à retirer des informations, mais à rendre visibles celles qui changent l'interprétation. Le médiateur présente les choix de représentation et invite les lecteurs à comparer deux versions. Dans une première version, l'estimation est représentée par une barre unique; dans la seconde, une plage d'incertitude est ajoutée. Le public comprend alors que deux catégories présentées dans un ordre précis pourraient en réalité être très proches.","question":"En quoi la seconde représentation est-elle plus fidèle malgré un élément graphique supplémentaire ?","explanation":"D rend visible l'incertitude pouvant modifier l'interprétation du classement. A évite à tort la comparaison, B confond représentation et réduction de l'erreur, C attribue la justesse au nombre d'éléments."},{"number":34,"points":26,"correct":"B","options":["L'observation des utilisateurs risque de forcer l'abandon d'un prototype avant d'avoir validé toutes ses fonctions techniques.","Qu'une solution ingénieuse réponde à un problème mal défini avec les usagers.","Des préférences divergentes pourraient conduire le groupe à tester moins de prototypes que le programme le prévoyait.","Les participants pourraient adopter une solution fondée sur leurs habitudes plutôt que sur une innovation techniquement avancée."],"passage":"Un programme encourage les jeunes à inventer rapidement une solution. Les animateurs ajoutent ensuite une étape d'observation du problème avec les utilisateurs. Une réponse ingénieuse peut être mal orientée si la difficulté initiale a été définie sans ceux qui la rencontrent. Le centre souhaite préserver l'imagination des participants tout en l'orientant vers une difficulté qu'ils ont suffisamment comprise pour proposer une réponse réellement pertinente. Deux prototypes répondent parfaitement à la consigne écrite, mais les personnes censées s'en servir expliquent qu'elles rencontrent un problème différent. Les animateurs font reformuler le besoin avant de choisir lequel développer.","question":"Quel risque l'étape d'observation vise-t-elle à réduire ?","explanation":"B vise à éviter de résoudre avec efficacité un problème mal défini. A/C/D décrivent des risques d'organisation ou d'innovation qui ne sont pas la faiblesse constatée des deux prototypes."},{"number":35,"points":26,"correct":"A","options":["Elle rend visibles les conclusions révisées à partir de preuves nouvelles.","Elle démontre que les observations initiales étaient suffisantes, mais avaient été présentées dans une forme trop prudente.","Elle prouve que la première hypothèse reposait uniquement sur une erreur de mesure identifiable après publication.","Elle conserve le résultat initial comme référence, puis présente les données contraires comme une exception secondaire."],"passage":"Une publication scientifique accepte qu'une hypothèse soit corrigée à la lumière de nouveaux résultats. Ce changement n'est pas automatiquement une preuve d'incompétence initiale. Il peut manifester une démarche qui accepte de distinguer ce qui était plausible de ce que les observations permettent désormais d'affirmer. Ils souhaitent que le lecteur puisse suivre le raisonnement, plutôt que prendre la modification comme une simple contradiction sans explication. Une équipe avait défendu une explication raisonnable avec les mesures disponibles. Une nouvelle série plus précise la contredit; les auteurs publient ce qui change et distinguent l'ancienne incertitude de la conclusion désormais mieux étayée.","question":"Pourquoi la correction de l'hypothèse peut-elle renforcer la confiance dans la démarche ?","explanation":"A correspond à une révision motivée par des mesures nouvelles et expliquée au lecteur. B inverse l'apport des nouvelles données; C attribue l'hypothèse initiale à une erreur non démontrée; D minimise les preuves contradictoires."},{"number":36,"points":33,"correct":"D","options":["Financer les projets dont les méthodes sont solides sans demander de présenter leur progression durant les premières années.","Comparer seulement le potentiel d'application rapide des résultats, même lorsque les méthodes sont exploratoires.","Exiger une prévision des usages futurs, mais accepter un calendrier plus long pour les travaux fondamentaux.","Suivre les méthodes et résultats sans exiger d'application commerciale immédiatement prévisible."],"passage":"Une fondation souhaite ne financer que des recherches dont l'application serait immédiatement prévisible. Des chercheurs rappellent que certaines méthodes utiles aujourd'hui proviennent de travaux d'abord motivés par des questions fondamentales. Exiger d'avance un bénéfice précis peut écarter des explorations dont l'intérêt se révèle autrement ou plus tard. Les responsables de la fondation craignent de financer des travaux dont ils ne pourraient pas annoncer rapidement l'utilité au public. Les chercheurs proposent donc des comptes rendus qui rendent visible la progression des questions et des méthodes. Ils ne demandent pas de renoncer à tout bilan. Ils veulent seulement éviter qu'un calendrier trop court et une définition unique du bénéfice empêchent d'explorer des pistes importantes. La discussion porte ainsi sur les formes de responsabilité d'un projet, et sur la manière d'expliquer un travail dont les effets ne peuvent pas toujours être prévus avec précision au moment de son lancement. Une proposition de recherche fondamentale ne promet pas d'application dans les deux ans mais présente des méthodes reproductibles et des jalons mesurables. Le comité doit décider si cette forme de suivi peut satisfaire son exigence de responsabilité.","question":"Quelle solution correspond au compromis proposé par les chercheurs ?","explanation":"D retient des comptes rendus sur méthodes et questions sans exiger une application commerciale prévisible. A abandonne le suivi; B/C réintroduisent un critère d'usage prédéterminé au lieu d'évaluer la progression."},{"number":37,"points":33,"correct":"D","options":["Elle permet de prédire le prochain épisode en utilisant la zone commune aux deux hypothèses de pluie.","Elle indique que la route doit être fermée sans délibération dès lors que les deux cartes montrent un risque.","Elle montre que l'exposition de l'axe reste constante, mais ne dit rien de la vulnérabilité à protéger.","Elle identifie une vulnérabilité présente sous plusieurs hypothèses, sans transformer les cartes en certitudes."],"passage":"Une simulation aide une commune à anticiper les crues. Ses cartes dépendent d'hypothèses sur la pluie et l'état des sols. Les responsables les utilisent pour comparer des scénarios, sans les présenter comme une photographie certaine de l'avenir. La force de l'outil tient à l'explicitation des possibles, non à la disparition de l'incertitude. La commune publiera les hypothèses principales et présentera plusieurs situations aux habitants. Certaines cartes permettront d'examiner un épisode fréquent, d'autres un événement plus rare mais plus grave. Les responsables devront choisir des aménagements qui restent utiles malgré cette diversité. Ils souhaitent que l'outil aide à comprendre leurs décisions, sans lui attribuer la responsabilité de les prendre seul. Les personnes concernées pourront ainsi discuter des priorités et des limites du dispositif. Deux cartes reposent sur des pluies de fréquences différentes. La zone inondée varie fortement, mais une route figure dans les deux périmètres. Les élus envisagent de sécuriser d'abord cet axe sans affirmer qu'une carte prédit le prochain épisode.","question":"En quoi la comparaison de scénarios aide-t-elle la décision sur la route ?","explanation":"D tire des scénarios une vulnérabilité commune, sans confondre hypothèse et prévision. A prétend dater l'épisode; B retire aux élus le choix d'aménagement; C ignore la vulnérabilité précisément repérée."},{"number":38,"points":33,"correct":"D","options":["Il établit qu'une omission volontaire des auteurs initiaux a créé la différence entre les deux laboratoires.","Il rend la conclusion initiale inutile puisqu'une modification de préparation rapproche les résultats obtenus.","Il prouve que la comparaison entre laboratoires n'a d'intérêt que lorsque tous les instruments sont identiques.","Il révèle une condition expérimentale influente et précise quand le résultat publié peut être reproduit."],"passage":"Une équipe cherche à reproduire un résultat publié et obtient un écart. Avant d'accuser les premiers auteurs, elle examine les instruments, les matériaux et les conditions de l'essai. Un désaccord expérimental devient une source d'information lorsqu'on recherche ce qui le produit, plutôt que de le réduire immédiatement à une faute. Les deux laboratoires échangent leurs observations et préparent de nouveaux essais. Ils découvrent parfois qu'un détail jugé secondaire dans le premier compte rendu modifie le résultat. Cette découverte peut enrichir la compréhension du phénomène, même si elle complique l'annonce initiale. Les chercheurs souhaitent rendre ces étapes visibles pour éviter que toute différence soit interprétée comme un conflit personnel. La publication des méthodes devient alors aussi importante que celle de la conclusion. D'autres équipes pourront examiner les mêmes éléments, essayer des conditions différentes et préciser progressivement la portée de ce qui a été observé. Le groupe découvre que l'échantillon avait été séché plus longtemps dans le second laboratoire. Lorsqu'il harmonise ce détail, les résultats se rapprochent, sans rendre inutile la publication de l'écart initial.","question":"Quelle valeur scientifique conserve l'écart initial une fois le détail identifié ?","explanation":"D montre que l'écart révèle un facteur de préparation influent et précise les conditions de reproductibilité. A suppose une intention malhonnête; B efface à tort la découverte; C exige une identité instrumentale non soutenue."},{"number":39,"points":33,"correct":"A","options":["Maintenir une série commune aux sites et distinguer les mesures exploratoires adaptées à l'exposition locale, sans confondre leurs résultats.","Mesurer les sites selon les horaires jugés les plus représentatifs par chaque quartier, puis corriger les différences après la collecte.","Remplacer la série normalisée par les relevés au niveau des poussettes, puisque le pic découvert à l'arrêt confirme leur priorité scientifique.","Conserver les sites proposés par les habitants, mais ne publier que les écarts entre hauteurs, sans distinguer les périodes et méthodes d'acquisition."],"passage":"Des citoyens participent à une enquête sur la qualité de l'air. Les scientifiques les associent au choix des lieux, mais conservent un protocole commun de mesure. La participation n'exige pas l'abandon de la rigueur ; elle peut enrichir les questions posées tout en maintenant des conditions qui rendent les résultats comparables. Les habitants connaissent des endroits où les personnes attendent longtemps et des horaires où la circulation change. Ils apportent ces repères lors de la préparation des relevés. Les spécialistes expliquent ensuite les règles de placement et les vérifications nécessaires pour éviter des comparaisons trompeuses. Le groupe discutera les résultats ensemble, avec les circonstances de chaque mesure. Les participants ne deviennent pas interchangeables, mais leurs connaissances se complètent. Le projet souhaite ainsi produire des informations plus utiles au territoire, tout en permettant au public de comprendre comment un résultat est construit et quelles questions il laisse encore ouvertes. Les riverains signalent un arrêt d'autobus très fréquenté au moment où les voitures se concentrent. Les scientifiques retiennent le lieu, mais imposent la même hauteur de capteur et les mêmes périodes de mesure que pour les autres sites. Après une première campagne, le groupe découvre un pic de pollution à l'arrêt proposé par les riverains. Une association souhaite ajouter un capteur au niveau des poussettes et mesurer uniquement les heures de sortie d'école, alors que le protocole initial impose une hauteur commune et des créneaux identiques dans tous les lieux comparés. Les scientifiques proposent de conserver la série standardisée pour les comparaisons entre sites et d'effectuer, en complément clairement identifié, des relevés exploratoires à la hauteur suggérée. Ces relevés supplémentaires pourraient éclairer l'exposition des enfants, sans être directement mêlés à la série principale. Lors d'un essai, les deux hauteurs donnent effectivement des valeurs différentes au même arrêt. Le rapport précise donc à quelle méthode appartient chaque résultat et demande de nouveaux relevés avant de conclure sur la cause de l'écart. Les habitants participent au choix des questions complémentaires, mais les règles de la série commune ne changent pas au gré des sites.","question":"Quelle organisation des relevés permet de répondre à une question locale sans invalider la comparaison principale ?","explanation":"A conserve une mesure comparable dans tous les lieux et isole une exploration motivée par les habitants; les différences de hauteur observées ne peuvent être traitées comme des résultats directement interchangeables ou causalement expliqués. B fait varier les fenêtres d'observation selon le site; C supprime la série commune sur la base d'un pic; D mélangerait des méthodes ou perdrait les repères nécessaires à leur interprétation."}]}$paper_9$::jsonb),
('tcf-reading-10','tcf-reading-2026-11-close-reading-v4',$paper_10${"id":"tcf-reading-10","title":"TCF Reading · Test 10","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["Rencontrer tous les enseignants","Travailler dans la salle","Emprunter des livres","Inscrire une classe"],"passage":"La salle d'étude ouvre désormais le dimanche matin. Le prêt de documents reste fermé ce jour-là.\n\nLe personnel pourra orienter les lecteurs vers les rayons accessibles. Merci de respecter les espaces réservés au travail silencieux.","question":"Quel service est disponible dimanche ?","explanation":"Le passage indique : « La salle d'étude ouvre désormais le dimanche matin. Le prêt de documents reste fermé ce jour-là. » Cela justifie la réponse : Travailler dans la salle."},{"number":2,"points":3,"correct":"B","options":["Une personne déjà experte","Une personne débutante","Uniquement un diplômé","Un professeur seulement"],"passage":"Le cours d'initiation commence mercredi. Aucun niveau préalable n'est demandé ; le matériel sera prêté.\n\nUne première rencontre permettra de présenter les objectifs et l'organisation. Les candidats peuvent poser leurs questions avant de confirmer.","question":"Qui peut s'inscrire ?","explanation":"Le passage indique : « Le cours d'initiation commence mercredi. Aucun niveau préalable n'est demandé ; le matériel sera prêté. » Cela justifie la réponse : Une personne débutante."},{"number":3,"points":3,"correct":"C","options":["Dans une autre école","Uniquement par courrier","Au secrétariat mardi","À la bibliothèque dimanche"],"passage":"Les copies seront remises lundi en classe. Les élèves absents pourront les récupérer au secrétariat mardi.\n\nLe secrétariat demandera simplement le nom de l'élève et sa classe. Les documents ne seront pas laissés dans un lieu ouvert à tous.","question":"Où un élève absent pourra-t-il récupérer sa copie ?","explanation":"Le passage indique : « Les copies seront remises lundi en classe. Les élèves absents pourront les récupérer au secrétariat mardi. » Cela justifie la réponse : Au secrétariat mardi."},{"number":4,"points":3,"correct":"D","options":["Un cours obligatoire pour les parents","Un examen pour les enfants","Une sortie scolaire payante","Une garde pendant la réunion"],"passage":"La réunion des parents se déroulera sans les élèves. Un accueil gratuit des enfants est organisé dans la salle voisine.\n\nLe service est proposé pendant toute la durée des échanges. Merci de signaler le nombre d'enfants au moment de confirmer votre venue.","question":"Quel accompagnement est proposé ?","explanation":"Le passage indique : « La réunion des parents se déroulera sans les élèves. Un accueil gratuit des enfants est organisé dans la salle voisine. » Cela justifie la réponse : Une garde pendant la réunion."},{"number":5,"points":9,"correct":"C","options":["Un changement définitif de professeur","Une dispense de tous les cours","Les exercices qu'elle manquera","Un diplôme sans examen"],"passage":"Je suis inscrit au cours du soir, mais je travaillerai deux mercredis ce mois-ci. Pourrais-tu me transmettre les exercices de ces séances ?\n\nJe veux éviter de prendre du retard avant le prochain chapitre. Si certains points demandent une explication, je contacterai ensuite le formateur pour savoir comment les reprendre.","question":"Que demande cette personne ?","explanation":"Le passage indique : « Je suis inscrit au cours du soir, mais je travaillerai deux mercredis ce mois-ci. Pourrais-tu me transmettre les exercices de ces séances ? » Cela justifie la réponse : Les exercices qu'elle manquera."},{"number":6,"points":9,"correct":"A","options":["Un nombre minimal de confirmations","La réussite à un concours","Une expérience professionnelle précise","L'achat immédiat d'un manuel"],"passage":"Votre inscription est reçue. Le groupe n'ouvrira que si six personnes confirment ; nous vous informerons avant tout paiement.\n\nLe centre vous indiquera aussi les autres créneaux possibles. Si le groupe n'ouvre pas, vous pourrez choisir une autre formule ou renoncer sans frais.","question":"Quelle condition détermine l'ouverture ?","explanation":"Le passage indique : « Votre inscription est reçue. Le groupe n'ouvrira que si six personnes confirment ; nous vous informerons avant tout paiement. » Cela justifie la réponse : Un nombre minimal de confirmations."},{"number":7,"points":9,"correct":"D","options":["Être vendu en classe","Décorer définitivement l'école","Remplacer l'inscription","Soutenir une prise de parole"],"passage":"Apporte un objet de ton choix pour la séance de langue. Il servira de point de départ à une courte présentation orale.\n\nVous pourrez expliquer pourquoi vous l'avez choisi et raconter un souvenir qui lui est associé. Aucun objet coûteux ou particulièrement original n'est nécessaire pour participer à cet exercice.","question":"À quoi servira l'objet ?","explanation":"Le passage indique : « Apporte un objet de ton choix pour la séance de langue. Il servira de point de départ à une courte présentation orale. » Cela justifie la réponse : Soutenir une prise de parole."},{"number":8,"points":9,"correct":"D","options":["Un cours de dessin artistique uniquement","Un changement de lieu de travail","Une préparation à tous les examens","Un apprentissage lié à une tâche précise"],"passage":"Je souhaite apprendre à lire les plans de mon atelier, pas préparer un examen général. Peux-tu m'indiquer le module correspondant ?\n\nJ'utilise déjà ces documents au quotidien, mais certains symboles restent difficiles à interpréter.","question":"Quel besoin est exprimé ?","explanation":"Le passage indique : « Je souhaite apprendre à lire les plans de mon atelier, pas préparer un examen général. Peux-tu m'indiquer le module correspondant ? » Cela justifie la réponse : Un apprentissage lié à une tâche précise."},{"number":9,"points":9,"correct":"B","options":["Écarter les débutants","Partager une méthode sans l'imposer","Défendre une solution obligatoire","Comparer les notes publiquement"],"passage":"La bibliothèque organise un échange de méthodes de révision. Chaque participant peut présenter une pratique qui l'aide, sans prétendre qu'elle convient à tous.\n\nL'animateur aidera à comparer les pratiques et les situations dans lesquelles elles fonctionnent.","question":"Quelle attitude est attendue ?","explanation":"Le passage indique : « La bibliothèque organise un échange de méthodes de révision. Chaque participant peut présenter une pratique qui l'aide, sans prétendre qu'elle convient à tous. » Cela justifie la réponse : Partager une méthode sans l'imposer."},{"number":10,"points":9,"correct":"A","options":["En autonomie avec une aide possible","Sans aucun travail prévu","Avec un examen permanent","Uniquement en présence du directeur"],"passage":"Le stage d'été comprend des matinées encadrées et des après-midi de travail autonome. Un tuteur reste joignable pendant ces périodes.\n\nLes participants auront quelques exercices à terminer et pourront organiser leur temps. Une rencontre courte permettra de vérifier les difficultés avant de poursuivre la suite du programme.","question":"Comment sont organisés les après-midi ?","explanation":"Le passage indique : « Le stage d'été comprend des matinées encadrées et des après-midi de travail autonome. Un tuteur reste joignable pendant ces périodes. » Cela justifie la réponse : En autonomie avec une aide possible."},{"number":11,"points":15,"correct":"A","options":["Multiplier les moyens d'accès à la consigne","Imposer une seule méthode","Réserver l'audio aux enseignants","Supprimer la lecture pour tous"],"passage":"Une école propose une version audio des consignes. Le texte écrit demeure disponible ; les élèves peuvent choisir le support qui les aide.\n\nLes supports sont préparés avec le même contenu pour que personne ne reçoive une consigne différente par erreur. Les élèves peuvent réécouter un passage ou revenir au texte lorsqu'un mot leur échappe. L'équipe souhaite distinguer la compréhension de la tâche et les difficultés d'accès à son énoncé. Les enseignants observeront les usages avant de décider quels documents adapter ensuite. Ils ne présentent pas le choix du support comme une dispense d'apprendre à lire, mais comme une aide pour participer aux activités prévues.","question":"Quel principe est retenu ?","explanation":"Le passage indique : « Une école propose une version audio des consignes. Le texte écrit demeure disponible ; les élèves peuvent choisir le support qui les aide. » Cela justifie la réponse : Multiplier les moyens d'accès à la consigne."},{"number":12,"points":15,"correct":"C","options":["Éviter toute interaction","Supprimer les activités libres","Favoriser la participation de chacun","Classer définitivement les participants"],"passage":"Un atelier de conversation accueille des adultes de niveaux différents. Les activités alternent échanges libres et petits groupes pour que chacun puisse prendre la parole.\n\nLes personnes peuvent commencer par des échanges courts puis rejoindre une discussion plus longue. Les animateurs proposent des thèmes proches du quotidien et demandent aux habitués de laisser un temps de réponse. Le centre veut éviter qu'un niveau élevé chez quelques participants rende les autres invisibles.","question":"Pourquoi varier les groupes ?","explanation":"Le passage indique : « Un atelier de conversation accueille des adultes de niveaux différents. Les activités alternent échanges libres et petits groupes pour que chacun puisse prendre la parole. » Cela justifie la réponse : Favoriser la participation de chacun."},{"number":13,"points":15,"correct":"A","options":["Identifier le statut des informations","Écrire sans vérifier","Éliminer toutes les questions","Publier uniquement des certitudes personnelles"],"passage":"Des élèves rédigent un journal scientifique. Avant publication, ils doivent distinguer les faits vérifiés des hypothèses qu'ils souhaitent tester.\n\nLes groupes doivent indiquer d'où viennent leurs informations et conserver les documents consultés. Un enseignant les aide à voir quand une formulation affirme davantage que ce que la source permet. Les textes seront relus avant d'être montrés aux autres classes. Le projet souhaite donner une expérience concrète de publication, avec ses responsabilités. Les élèves pourront poser de nouvelles questions sans les présenter immédiatement comme des découvertes établies. Ils apprendront aussi à expliquer une incertitude plutôt qu'à la cacher pour rendre leur article plus impressionnant.","question":"Quel apprentissage est travaillé ?","explanation":"Le passage indique : « Des élèves rédigent un journal scientifique. Avant publication, ils doivent distinguer les faits vérifiés des hypothèses qu'ils souhaitent tester. » Cela justifie la réponse : Identifier le statut des informations."},{"number":14,"points":15,"correct":"C","options":["Les participants choisissent leur diplôme","Les examens sont tirés au sort","Les acquis initiaux sont pris en compte","Le tarif dépend de la taille des classes"],"passage":"Une formation professionnelle reconnaît certains acquis après entretien et exercice. Le parcours peut donc être plus court pour une personne déjà expérimentée.\n\nLes candidats apportent des exemples de tâches réalisées et décrivent les responsabilités qu'ils avaient réellement. L'exercice permet de vérifier certains points sans se fier uniquement au titre d'un ancien poste. Cette reconnaissance ne garantit pas une validation automatique : elle sert à rendre le parcours plus pertinent. Les participants savent ainsi pourquoi certaines séances leur sont proposées et pourquoi d'autres ne doivent pas nécessairement être suivies une seconde fois.","question":"Pourquoi la durée peut-elle varier ?","explanation":"Le passage indique : « Une formation professionnelle reconnaît certains acquis après entretien et exercice. Le parcours peut donc être plus court pour une personne déjà expérimentée. » Cela justifie la réponse : Les acquis initiaux sont pris en compte."},{"number":15,"points":15,"correct":"C","options":["Distribuer des notes secrètes","Éviter toute correction","Apprendre à partir des erreurs","Remplacer définitivement l'évaluation"],"passage":"Un enseignant autorise un premier essai non noté. Les élèves reçoivent un retour puis reprennent leur travail avant l'évaluation.\n\nLe retour porte sur des éléments précis du raisonnement et sur les moyens de progresser. Les élèves peuvent poser une question avant de reprendre le document. L'enseignant souhaite que la note finale ne soit pas la première information reçue sur la qualité de leur démarche. Il prévoit aussi un temps pour comparer les deux versions et identifier les changements utiles. Ce travail n'efface pas les exigences de l'évaluation ; il rend plus visible ce qui peut être appris entre une tentative initiale et une production plus aboutie.","question":"À quoi sert le premier essai ?","explanation":"Le passage indique : « Un enseignant autorise un premier essai non noté. Les élèves reçoivent un retour puis reprennent leur travail avant l'évaluation. » Cela justifie la réponse : Apprendre à partir des erreurs."},{"number":16,"points":15,"correct":"D","options":["Recopier une publicité sans commentaire","Évaluer le salaire des visiteurs","Donner uniquement une impression avant la visite","Confronter une représentation à l'expérience"],"passage":"La classe visite une entreprise après avoir préparé des questions. Le compte rendu devra comparer les attentes initiales et les observations réelles.\n\nCertains découvrent des tâches peu visibles pendant une simple présentation du métier. Les responsables de l'entreprise répondent aux questions, mais ne corrigent pas toutes les impressions à leur place. L'école souhaite que les jeunes apprennent à formuler un constat et à l'appuyer sur une situation concrète, plutôt qu'à reproduire uniquement les éléments les plus valorisants d'une brochure de recrutement ou d'une visite préparée pour eux.","question":"Quelle démarche est demandée ?","explanation":"Le passage indique : « La classe visite une entreprise après avoir préparé des questions. Le compte rendu devra comparer les attentes initiales et les observations réelles. » Cela justifie la réponse : Confronter une représentation à l'expérience."},{"number":17,"points":15,"correct":"A","options":["Une barrière matérielle à la formation","Le manque de places de parking","Le nombre de devoirs","La durée du trimestre"],"passage":"Un centre prête des calculatrices pour éviter que l'achat soit un obstacle à l'inscription. Les appareils doivent être rendus après le cours.\n\nLes étudiants peuvent poser des questions sans supposer qu'ils connaissent déjà le modèle. La formation ne veut pas évaluer une différence d'équipement familial à la place de la compétence travaillée. Les responsables suivront les demandes de prêt afin de prévoir un stock suffisant. Ils souhaitent que les personnes découvrent ce droit assez tôt pour ne pas abandonner une inscription simplement parce qu'elles pensent devoir acheter immédiatement du matériel supplémentaire.","question":"Quel problème cherche-t-on à réduire ?","explanation":"Le passage indique : « Un centre prête des calculatrices pour éviter que l'achat soit un obstacle à l'inscription. Les appareils doivent être rendus après le cours. » Cela justifie la réponse : Une barrière matérielle à la formation."},{"number":18,"points":15,"correct":"B","options":["La suppression de la cour","Différentes façons de vivre la pause","Une obligation de rester en classe","Un examen pendant la récréation"],"passage":"Une école aménage un espace calme accessible pendant les pauses. Il complète la cour active sans imposer le silence à tous les élèves.\n\nLes élèves ont participé au choix des sièges et des règles d'usage. Certaines personnes y lisent, d'autres préfèrent simplement s'asseoir quelques minutes. L'établissement souhaite reconnaître des besoins différents pendant le même temps de pause. Le bilan portera sur la manière dont les espaces se complètent, plutôt que sur une compétition entre ceux qui choisissent de jouer dehors et ceux qui recherchent un environnement plus calme.","question":"Quel choix est offert ?","explanation":"Le passage indique : « Une école aménage un espace calme accessible pendant les pauses. Il complète la cour active sans imposer le silence à tous les élèves. » Cela justifie la réponse : Différentes façons de vivre la pause."},{"number":19,"points":15,"correct":"A","options":["Vérifier le contexte de l'image","Se fier uniquement à sa première impression","Ignorer la date de publication","Compter les couleurs"],"passage":"Un groupe apprend à identifier les sources d'une photographie. Les participants recherchent sa date et son contexte avant d'interpréter ce qu'elle semble montrer.\n\nLes animateurs montrent comment une même image peut circuler avec des commentaires différents. Les participants essaient ensuite la démarche sur des exemples préparés pour l'atelier. Ils ne cherchent pas à démontrer que toute photographie serait fausse, mais à comprendre ce qui permet de lui attribuer un sens précis.","question":"Quelle précaution est enseignée ?","explanation":"Le passage indique : « Un groupe apprend à identifier les sources d'une photographie. Les participants recherchent sa date et son contexte avant d'interpréter ce qu'elle semble montrer. » Cela justifie la réponse : Vérifier le contexte de l'image."},{"number":20,"points":21,"correct":"D","options":["Éviter tout travail personnel","Obtenir immédiatement tous les diplômes","Interdire une poursuite d'études","Commencer progressivement sans perdre ses acquis"],"passage":"Des adultes souhaitent reprendre des études, mais hésitent à suivre un long programme. Le centre propose un premier module court, dont les acquis pourront être conservés s'ils continuent. Le centre précise les étapes suivantes et les conditions de reprise dès le début. Les personnes peuvent ainsi décider si elles souhaitent poursuivre après avoir découvert le rythme et le travail demandé. L'objectif est de proposer une première expérience suffisamment complète pour être utile, sans transformer une hésitation initiale en échec. Les acquis seront décrits dans un document conservé par l'apprenant.","question":"Que permet ce dispositif ?","explanation":"Le passage indique : « Des adultes souhaitent reprendre des études, mais hésitent à suivre un long programme. Le centre propose un premier module court, dont les acquis pourront être conservés s'ils continuent. » Cela justifie la réponse : Commencer progressivement sans perdre ses acquis."},{"number":21,"points":21,"correct":"D","options":["Toutes les questions sont inutiles","Les élèves comprennent toujours les consignes","La répétition prouve nécessairement un refus d'apprendre","La clarté de l'enseignement doit aussi être examinée"],"passage":"Une équipe enseignante analyse les questions posées après le cours. Des demandes répétées sur une consigne peuvent indiquer un problème d'explication, pas seulement un manque d'attention des élèves. Les formateurs regroupent les difficultés récurrentes et comparent la façon dont les consignes ont été présentées. Ils peuvent alors modifier un exemple ou prévoir une explication supplémentaire. Elle permet simplement de ne pas attribuer automatiquement une difficulté collective à des défauts individuels, alors qu'une même formulation a peut-être laissé plusieurs personnes dans l'incertitude.","question":"Quelle interprétation est ajoutée ?","explanation":"Le passage indique : « Une équipe enseignante analyse les questions posées après le cours. Des demandes répétées sur une consigne peuvent indiquer un problème d'explication, pas seulement un manque d'attention des élèves. » Cela justifie la réponse : La clarté de l'enseignement doit aussi être examinée."},{"number":22,"points":21,"correct":"D","options":["Isolement et contrôle permanent","Absence d'horaires et absence de contact","Cours uniquement en présence","Autonomie et accompagnement"],"passage":"Un cours en ligne reste consultable longtemps, mais prévoit des rendez-vous réguliers avec un tuteur. Les concepteurs veulent associer souplesse d'accès et soutien dans la durée. Les échanges avec le tuteur servent à préparer les étapes suivantes et à discuter des obstacles rencontrés. Les participants n'ont pas tous le même emploi du temps ni le même équipement. Le programme prévoit donc plusieurs possibilités de rendez-vous, sans laisser chacun seul face à une liste de vidéos.","question":"Quels éléments sont combinés ?","explanation":"Le passage indique : « Un cours en ligne reste consultable longtemps, mais prévoit des rendez-vous réguliers avec un tuteur. Les concepteurs veulent associer souplesse d'accès et soutien dans la durée. » Cela justifie la réponse : Autonomie et accompagnement."},{"number":23,"points":21,"correct":"C","options":["Imposer une langue unique au domicile","Classer les familles selon leurs revenus","Reconnaître des pratiques linguistiques diverses","Organiser un examen pour les parents"],"passage":"Une école invite les familles à expliquer les langues utilisées à la maison. Le projet ne mesure pas une maîtrise parfaite ; il rend visibles des ressources souvent absentes des échanges scolaires. Les enfants peuvent apporter une chanson, expliquer une expression ou raconter un usage quotidien. Les enseignants ne demandent pas aux parents de représenter toute une langue ou tout un pays. Ils souhaitent donner une place à des expériences présentes dans la classe, sans transformer l'activité en concours.","question":"Quel objectif est poursuivi ?","explanation":"Le passage indique : « Une école invite les familles à expliquer les langues utilisées à la maison. Le projet ne mesure pas une maîtrise parfaite ; il rend visibles des ressources souvent absentes des échanges scolaires. » Cela justifie la réponse : Reconnaître des pratiques linguistiques diverses."},{"number":24,"points":21,"correct":"D","options":["Éviter toute mise en pratique","Commencer par un classement des participants","Apprendre toutes les commandes sans usage","Partir d'un besoin pour introduire les notions"],"passage":"Un atelier de programmation commence par un problème concret, puis introduit les commandes nécessaires. Les participants comprennent ainsi à quoi sert l'outil avant d'en mémoriser la syntaxe. Les premiers essais peuvent être faits sans écrire toutes les lignes à partir de zéro. Les participants pourront modifier l'exemple et observer le résultat. Le centre souhaite que les nouvelles commandes deviennent des moyens d'agir et de comprendre, plutôt que des mots mémorisés sans lien avec un objectif identifiable.","question":"Quelle progression pédagogique est choisie ?","explanation":"Le passage indique : « Un atelier de programmation commence par un problème concret, puis introduit les commandes nécessaires. Les participants comprennent ainsi à quoi sert l'outil avant d'en mémoriser la syntaxe. » Cela justifie la réponse : Partir d'un besoin pour introduire les notions."},{"number":25,"points":21,"correct":"B","options":["Le tuteur fournit la réponse après une tentative de l'élève, même si le raisonnement reste incompris.","Le tuteur oriente le raisonnement et reconnaît les situations nécessitant l'aide du professeur.","Le tuteur organise la progression et attribue les notes finales en laissant les exercices au choix du camarade.","Le tuteur reprend les problèmes difficiles puis demande à l'élève de reproduire la méthode présentée."],"passage":"Une association propose un tutorat entre élèves. Les tuteurs apprennent à poser des questions plutôt qu'à fournir directement la réponse. Les élèves préparant une aide reçoivent quelques repères pour écouter et vérifier ce que leur camarade a déjà essayé. Ils doivent savoir quand demander l'intervention du professeur. Il donne à chacun un rôle précis et permet aussi de découvrir que comprendre un exercice et aider quelqu'un à le comprendre sont deux activités différentes. Un tuteur remarque une erreur de calcul, mais demande d'abord à son camarade quelle étape lui semble incertaine. Quand une notion n'est plus maîtrisée par aucun des deux, ils sollicitent l'enseignant.","question":"Quelle frontière distingue le tutorat décrit d'une substitution à l'enseignant ?","explanation":"B distingue l'aide au raisonnement d'un remplacement du professeur et reconnaît les limites du tuteur. A/D fournissent la solution à la place de l'apprenant, C attribue au tuteur une évaluation finale non prévue."},{"number":26,"points":21,"correct":"A","options":["Parce que le transfert dépend des acquis et des occasions de les utiliser.","Parce qu'une réaction favorable pendant le cours permet d'estimer les acquis mais non la fréquence de leur usage.","Parce que l'application des compétences se mesure surtout lorsque le nouveau poste ressemble au métier antérieur.","Parce que les participants ayant attendu plusieurs mois avant d'appliquer un savoir le perdent nécessairement."],"passage":"Le centre compare la satisfaction immédiate et l'utilisation réelle des compétences quelques mois plus tard. Un cours apprécié peut avoir peu d'effet si les participants n'ont pas l'occasion de pratiquer. Les anciens participants seront invités à décrire une situation où ils ont utilisé la formation et une autre où ils n'ont pas réussi à la mobiliser. Ils souhaitent distinguer un apprentissage réel, une appréciation favorable et les conditions nécessaires pour que ces acquis servent ensuite dans le travail ou dans les démarches prévues. Deux anciens élèves déclarent la même satisfaction. L'un utilise régulièrement la méthode apprise; l'autre travaille dans un service où il n'a pas accès au matériel nécessaire. Le bilan sépare acquis, occasion d'appliquer et ressenti.","question":"Pourquoi une satisfaction identique ne permet-elle pas de conclure au même effet de la formation ?","explanation":"A associe acquis et occasions réelles d'application. B confond satisfaction et compétence, C restreint sans preuve les situations de transfert, D suppose une perte automatique des connaissances."},{"number":27,"points":21,"correct":"C","options":["Sur la démarche adoptée par la majorité des camarades, puisque son utilisation répétée facilite la vérification.","Sur le nombre d'étapes requis, à condition que les deux procédures donnent des réponses correctes.","Sur les exigences du problème et les qualités respectives de chaque démarche correctement justifiée.","Sur la méthode présentée en premier par l'enseignant, dont les contraintes de calcul seraient normalement mieux connues."],"passage":"Un professeur montre deux solutions correctes à un problème. Les élèves doivent expliquer leurs différences plutôt que deviner laquelle l'enseignant préfère. Le professeur garde un rôle de vérification et ne présente pas toutes les propositions comme correctes par principe. Il veut que les élèves justifient leurs choix à partir du problème, au lieu de chercher seulement un indice sur la réponse qu'ils pensent attendue dans la classe. Une procédure est plus courte mais demande davantage de calcul mental; l'autre comporte davantage d'étapes et reste plus facile à vérifier. Les élèves doivent comparer ces propriétés en fonction du problème, sans qu'une seule méthode soit attendue.","question":"Sur quoi l'élève doit-il fonder le choix entre les deux solutions ?","explanation":"C demande de confronter les propriétés des deux méthodes au problème. A privilégie la popularité, B la brièveté sans contexte, D infère une préférence du professeur."},{"number":28,"points":21,"correct":"A","options":["Conserver des fonctions complémentaires et ajuster leur disponibilité en fonction des usages observés.","Conserver le même nombre de places de groupe, puis répondre aux demandes d'espace calme par un changement d'horaires.","Donner la priorité aux livres fragiles en limitant la durée des réservations de salles de travail collectif.","Accorder temporairement presque tout l'espace aux demandes de silence durant les examens, puis revenir au plan initial."],"passage":"Une université transforme une partie de sa bibliothèque en salles de groupe. Elle conserve des zones silencieuses après consultation des étudiants. Les étudiants ont expliqué à quels moments ils travaillent seuls, en groupe ou avec un document fragile. Elle souhaite éviter qu'un changement présenté comme moderne efface une fonction encore importante. Le bilan examinera la disponibilité réelle des espaces, notamment pendant les périodes où les demandes de travail individuel augmentent fortement. Pendant les examens, les salles de groupe sont pleines mais les demandes d'espaces silencieux doublent. La direction vérifie les besoins selon les périodes plutôt que d'évaluer l'aménagement sur une seule semaine.","question":"Quel principe devrait guider la répartition de l'espace de la bibliothèque ?","explanation":"A répartit les usages complémentaires selon la fréquentation constatée. B fige l'espace, C traite un autre usage comme solution globale, D fait presque disparaître les salles de groupe sans examen des besoins simultanés."},{"number":29,"points":21,"correct":"C","options":["Parce que l'assiduité devient l'indicateur de motivation principal lorsque les résultats pédagogiques restent satisfaisants.","Parce qu'un étudiant ayant de bons résultats devrait pouvoir compenser ses absences sans soutien logistique.","Parce que les absences observées correspondent ici à des contraintes d'accès malgré des acquis suffisants.","Parce que les contraintes de garde peuvent rendre les évaluations moins représentatives du niveau réellement acquis."],"passage":"Des participants abandonnent une formation malgré de bons résultats. Les entretiens révèlent des difficultés de garde et de transport. Le centre modifie ses aides plutôt que simplifier automatiquement les contenus. Les responsables ont contacté les personnes parties avant la fin pour comprendre leur expérience. Plusieurs souhaitaient continuer et savaient réaliser les exercices demandés. Le centre propose donc des solutions d'organisation et des relais locaux avant de revoir le niveau pédagogique. Un stagiaire réussit les évaluations mais manque trois cours faute de garde d'enfant. Le centre lui propose un soutien logistique plutôt qu'un cours simplifié; il vérifie ensuite si la présence reprend.","question":"Pourquoi le centre agit-il d'abord sur l'organisation de la formation ?","explanation":"C relie les absences à des obstacles d'accès malgré des acquis démontrés. A/B supposent un problème de volonté ou d'autonomie, D remet en cause des résultats qui sont décrits comme satisfaisants."},{"number":30,"points":26,"correct":"C","options":["Une procédure identique à appliquer à toute erreur afin de rendre les réponses plus homogènes.","La certitude de réussir à la tentative suivante, dès lors que l'élève identifie l'étape incorrecte.","Une compréhension exploitable de l'erreur et une possibilité d'ajuster la prochaine démarche.","Une manière de valoriser toute réponse pour maintenir l'envie de poursuivre sans modifier la démarche."],"passage":"Le droit à l'erreur est souvent invoqué en formation. Il suppose pourtant un retour permettant de comprendre et de reprendre. Sans cet accompagnement, répéter qu'on peut se tromper laisse l'apprenant face à une difficulté inchangée. Le formateur peut montrer comment analyser une tentative et préparer le prochain essai. La personne dispose alors d'éléments pour agir, au lieu d'être simplement rassurée sans savoir ce qu'elle pourrait modifier concrètement. Le retour doit rester précis et utilisable pour la prochaine tentative. Deux apprenants commettent la même erreur. Le premier reçoit seulement « ce n'est pas grave »; le second examine son étape fautive et essaie une autre démarche. Seul le second possède une indication pour la prochaine tentative.","question":"Qu'apporte le retour détaillé que la seule permission de se tromper ne fournit pas ?","explanation":"C ajoute une analyse permettant de corriger le raisonnement. A uniformise des erreurs différentes, B promet la réussite, D néglige l'ajustement concret."},{"number":31,"points":26,"correct":"B","options":["Que le suivi des réponses soit jugé moins précis lorsque l'élève explore de nouvelles méthodes de résolution.","Que l'adaptation au passé réduise les occasions de résoudre des problèmes nouveaux.","Que l'enseignant donne plus de poids aux erreurs passées qu'aux évaluations réalisées pendant les nouvelles tâches.","Que les exercices adaptés au niveau du moment retardent la vérification de compétences qui resteraient identiques."],"passage":"Un programme personnalise les exercices à partir des réponses précédentes. Les enseignants souhaitent garder une vue sur les choix du logiciel. Une adaptation automatique peut être utile tout en enfermant un élève dans des tâches trop semblables à celles qu'il a déjà réalisées. Les enseignants conservent donc des possibilités de changer la proposition ou d'introduire une tâche moins familière. Après plusieurs réponses faibles en géométrie, un élève reçoit presque exclusivement des exercices similaires. Il réussit ensuite mieux, mais n'a plus d'occasion d'appliquer les notions dans une situation nouvelle; le professeur introduit des tâches différentes.","question":"Quel risque la modification du parcours vise-t-elle à limiter ?","explanation":"B identifie une adaptation qui enferme l'élève dans des tâches similaires, limitant le transfert. A/C/D décrivent d'autres problèmes possibles mais pas le manque d'exposition à des contextes nouveaux observé."},{"number":32,"points":26,"correct":"B","options":["Parce que les élèves les plus avancés doivent rester responsables de toutes les étapes du projet commun.","Parce qu'un bon projet peut masquer une participation inégale des membres.","Parce que les rôles attribués au début suffisent à établir les compétences que chacun a réellement acquises.","Parce que la rotation des rôles peut rendre la qualité du travail moins stable d'une séance à la suivante."],"passage":"Une école développe des projets collectifs. Pour éviter que seuls les élèves déjà à l'aise prennent les décisions, les rôles tournent et les méthodes sont discutées. Travailler ensemble ne suffit pas spontanément à répartir les occasions d'apprendre. Chaque élève pourra expliquer sa contribution et les difficultés rencontrées dans le rôle occupé. Cette attention évite de considérer qu'un résultat collectif réussi prouve automatiquement que tous les membres ont eu les mêmes occasions de travailler. Le groupe rend un projet réussi, mais son porte-parole a dirigé tous les échanges et les autres n'ont jamais présenté de décision. La rotation donne à chacun une occasion identifiable de mener, vérifier ou expliquer.","question":"Pourquoi un résultat collectif satisfaisant ne suffit-il pas à évaluer l'apprentissage des membres ?","explanation":"B désigne le risque que le bon résultat masque l'inégalité de participation et des occasions d'apprentissage. A préconise de concentrer les tâches, C confond attribution initiale et contribution réelle, D suppose une instabilité des résultats due aux rotations que le passage ne constate pas."},{"number":33,"points":26,"correct":"C","options":["Considérer qu'une expérience répétée suffit pour prouver la compétence sans examen complémentaire de sa réalisation.","Privilégier le récit oral pour les compétences que le candidat ne parvient pas à documenter à l'écrit.","Assimiler une difficulté à décrire une expérience à une absence de savoir-faire pratique.","Adapter les modalités de présentation d'un acquis revient à réduire les exigences techniques du référentiel."],"passage":"Un adulte utilise efficacement un outil au travail mais peine à l'expliquer dans un dossier de formation. Son accompagnateur distingue la compétence pratique et la capacité à la décrire. L'une ne prouve pas automatiquement l'autre. Des exemples concrets et une observation peuvent compléter le dossier. Le centre souhaite éviter qu'une difficulté de rédaction masque un savoir réel, tout en aidant la personne à présenter ses acquis de manière compréhensible pour un évaluateur extérieur. Une candidate démontre oralement une procédure qu'elle applique chaque jour mais peine à en produire une description écrite. Le centre ajoute une observation guidée et une aide à la rédaction avant de statuer sur les compétences.","question":"Quel biais l'accompagnement cherche-t-il à éviter ?","explanation":"C évite de confondre difficulté d'expression écrite et absence de savoir-faire. A supprimerait la vérification pratique; B remplacerait un biais par un autre; D assimile à tort aménagement et baisse des exigences."},{"number":34,"points":26,"correct":"D","options":["L'ordre de publication des résultats et le moment auquel les établissements ont fermé leurs inscriptions.","Le montant des ressources consacrées à la préparation des examens dans chacun des établissements comparés.","La proportion d'étudiants satisfaits parmi ceux qui ont réellement présenté les épreuves finales.","Le périmètre des étudiants comptabilisés, notamment ceux partis avant l'examen."],"passage":"Un établissement publie son taux de réussite. Il précise aussi les caractéristiques des étudiants accueillis et les parcours interrompus. Sans ces informations, comparer deux taux pourrait confondre l'effet de l'enseignement avec les conditions de recrutement ou de vie des étudiants. Les responsables souhaitent une comparaison utile, sans transformer un indicateur simple en verdict sur toutes les dimensions d'un établissement. Deux écoles publient 85 % de réussite. Dans la première, le calcul exclut les nombreux étudiants partis avant l'examen; la seconde suit l'ensemble des inscrits. La comparaison brute négligerait cette différence de périmètre.","question":"Quelle information est indispensable pour interpréter les taux annoncés ?","explanation":"D exige de connaître le dénominateur et les abandons. A concerne les calendriers, B les moyens, C une satisfaction distincte; aucun ne résout la différence de périmètre des taux."},{"number":35,"points":26,"correct":"B","options":["En donnant plus d'indices lorsque les exercices deviennent familiers pour maintenir la sécurité des réponses.","En diminuant progressivement et en réapparaissant de façon ciblée lorsque la difficulté l'exige.","En conservant le même niveau d'aide pour rendre les performances comparables d'une séance à l'autre.","En retirant les aides après la première réussite, quitte à reprendre l'exercice si un problème nouveau apparaît."],"passage":"Un atelier vise l'autonomie. Les formateurs donnent progressivement moins d'indices, sans supprimer brutalement leur soutien. L'autonomie n'est pas supposée présente dès l'entrée : elle se construit dans une relation dont l'intensité évolue. Les apprenants sont invités à demander un appui lorsqu'une difficulté nouvelle apparaît. Le centre ne considère pas cette demande comme un échec de l'autonomie, mais comme une ressource possible pour continuer à progresser. La formatrice retire d'abord les exemples guidés, puis propose une situation moins familière. Si l'apprenant bloque, elle lui offre une question ciblée sans reprendre tout le raisonnement à sa place.","question":"Comment l'aide contribue-t-elle ici au développement de l'autonomie ?","explanation":"B décrit un étayage progressif et réajustable selon la difficulté. A augmente l'aide quand elle devrait diminuer; C la fige; D confond une première réussite et l'autonomie face à une situation nouvelle."},{"number":36,"points":33,"correct":"B","options":["Le nombre de tablettes distribuées et les compétences numériques déclarées, supposées directement comparables entre familles.","Le matériel distribué et les conditions réelles d'apprentissage à domicile.","La disponibilité d'un appareil à l'école et l'obligation de poursuivre toutes les tâches à domicile en ligne.","Le temps consacré aux devoirs et le niveau scolaire, considérés indépendamment de l'accès à la connexion."],"passage":"Une école distribue des tablettes à tous les élèves et constate des usages très différents. Certains disposent chez eux d'un espace calme et d'un adulte disponible ; d'autres partagent une connexion fragile. L'égalité d'équipement ne garantit pas l'égalité des conditions d'apprentissage. Certaines familles doivent attendre qu'un appareil soit libre pour terminer un devoir, tandis que d'autres peuvent reprendre les consignes à tout moment. L'école va donc proposer un accès encadré après les cours et des supports utilisables sans connexion permanente. Les enseignants examineront aussi la charge demandée à la maison. Le matériel distribué reste un progrès, mais ses effets dépendent des situations dans lesquelles il est utilisé. Le projet doit être évalué à partir de ces usages réels, pas seulement du nombre de tablettes remises lors d'une première journée de lancement. À équipement identique, un devoir vidéo se charge sans difficulté chez certains élèves, tandis que d'autres doivent attendre une connexion partagée. L'école ajoute une possibilité hors ligne plutôt que conclure à une égalité d'apprentissage.","question":"Quelle différence faut-il distinguer lorsqu'on évalue la distribution des tablettes ?","explanation":"B distingue l'égalité du matériel des conditions réelles de son usage, connexion et soutien. A/C assimilent équipement à apprentissage; D écarte précisément l'environnement matériel qui explique les différences."},{"number":37,"points":33,"correct":"A","options":["La flexibilité des règles de parcours et l'accès à l'accompagnement, en cohérence avec la promesse faite.","La durée totale du cursus, en maintenant les échéances communes pour préserver la comparabilité de l'évaluation.","La quantité d'exercices proposés en ligne, afin que les étudiants puissent apprendre seuls malgré les interruptions.","La difficulté des évaluations, adaptée aux rythmes individuels mais sans modifier la disponibilité des accompagnateurs."],"passage":"Une formation promet de respecter le rythme de chacun. Mais son calendrier final reste rigide, et les aides disparaissent après une courte période. Les participants qui ont besoin de plus de temps sont alors les premiers exclus. Une personnalisation annoncée doit être cohérente avec l'organisation qui encadre réellement les parcours. Les responsables avaient surtout décrit les possibilités offertes par les supports, sans regarder les délais ni la disponibilité des accompagnateurs. Les personnes intéressées pourront ainsi choisir en connaissant les limites du programme. Le centre souhaite conserver des objectifs communs sans prétendre qu'un outil flexible rend toutes les contraintes sans importance. Les résultats seront étudiés avec les abandons et les reprises, afin de vérifier si la nouvelle organisation aide effectivement ceux qui avaient du mal à suivre le rythme prévu. Une participante termine les exercices numériques à son rythme mais manque la date finale commune après une période de garde familiale. Les responsables envisagent des échéances de rattrapage et des aides prolongées.","question":"Que doit modifier le centre pour que la personnalisation soit autre chose qu'une propriété des supports ?","explanation":"A demande d'accorder délais de parcours et disponibilité d'aide avec la personnalisation annoncée. B/C/D changent durée, quantité ou niveau sans traiter ensemble les échéances rigides et le soutien limité."},{"number":38,"points":33,"correct":"B","options":["La capacité de suivre les étapes lorsque le chapitre et la formule pertinente sont indiqués à l'avance.","Le repérage des conditions dans lesquelles la méthode répond au problème posé.","La possibilité de reconnaître plusieurs formules d'un même chapitre avant de les appliquer successivement.","L'habitude de vérifier le résultat obtenu après avoir exécuté la méthode déjà désignée dans la consigne."],"passage":"Apprendre une méthode ne signifie pas toujours savoir quand l'utiliser. Des élèves réussissent un exercice familier, puis échouent lorsque le même problème apparaît dans une présentation différente. Le professeur multiplie les contextes et fait discuter les choix. La maîtrise implique aussi de reconnaître les situations auxquelles un savoir peut répondre. Les exercices proposés ensuite changent de présentation et mélangent plusieurs notions. Les élèves doivent expliquer pourquoi ils en choisissent une plutôt qu'une autre. Le professeur observe les hésitations, car elles peuvent révéler un repère mal compris malgré une procédure bien mémorisée. Il ne cherche pas à multiplier les pièges. Il veut rendre possible un passage des tâches familières à celles où il faut d'abord identifier le problème. Les retours aideront chacun à reconnaître des indices pertinents et à vérifier une démarche, plutôt qu'à reproduire automatiquement un geste appris dans un ordre toujours identique. Un élève applique une formule lorsque le chapitre est annoncé, mais choisit la mauvaise procédure lorsque plusieurs notions sont mélangées. Le professeur fait justifier les indices qui orientent vers une méthode.","question":"Quelle capacité manque à l'élève qui sait exécuter la formule dans un exercice familier ?","explanation":"B porte sur l'identification des indices qui rendent une méthode pertinente dans un contexte nouveau. A décrit la compétence déjà acquise; C reste à l'intérieur d'un chapitre désigné; D concerne le contrôle après sélection et non la sélection."},{"number":39,"points":33,"correct":"A","options":["L'expérience devient une ressource lorsqu'on peut expliciter ses conditions de validité et la réviser face à une contrainte nouvelle.","Une longue pratique antérieure garantit des méthodes plus sûres que l'application d'un critère appris seulement pendant la formation.","La correction d'un automatisme lors d'une seule mise en situation établit que le participant saura ensuite s'adapter dans tous les contextes.","Les différences de performance observées prouvent que les compétences anciennes doivent être écartées plutôt qu'analysées face aux règles nouvelles."],"passage":"Un centre valorise l'expérience de ses apprenants adultes. Il ne considère pourtant pas que cette expérience suffit à répondre à toute question. Les échanges mettent parfois en évidence des habitudes efficaces dans un contexte et inadaptées dans un autre. Reconnaître un parcours permet d'en faire une ressource d'analyse, sans le transformer en vérité intangible. Les apprenants apportent des exemples et discutent des conditions dans lesquelles leurs solutions ont fonctionné. Le formateur introduit d'autres situations pour faire apparaître les points communs et les différences. Certains participants découvrent qu'ils possèdent des ressources utiles sans avoir encore les mots pour les décrire. D'autres doivent modifier un automatisme longtemps efficace dans leur ancien contexte. Le cours ne demande donc ni d'oublier son parcours ni de s'y enfermer. Il propose de le travailler avec d'autres repères, afin de préparer des décisions plus adaptées aux situations nouvelles rencontrées pendant la formation ou ensuite. Un professionnel explique une pratique qui fonctionnait dans son ancien service; une nouvelle situation introduit une contrainte absente auparavant. Le groupe identifie ce qui reste transférable et ce qu'il faut modifier au lieu de rejeter ou d'appliquer sans examen l'expérience passée. Pour une évaluation, deux professionnels expérimentés résolvent un incident familier selon leur ancienne procédure. Dans le nouveau cadre, la même procédure impose désormais un délai de contrôle supplémentaire. L'un explique pourquoi son automatisme ancien doit être interrompu à cette étape; l'autre répète correctement le geste ancien, mais ne vérifie pas les nouvelles contraintes. Le formateur ne leur attribue pas des compétences générales différentes sur la seule base de cette observation. Il demande plutôt que chacun nomme ce qui reste pertinent, la condition nouvelle qui change le choix, puis un critère permettant de vérifier l'adaptation. Un troisième participant, moins expérimenté, réussit également en mobilisant ce critère après avoir écouté les deux raisonnements. Le centre précise qu'un bon parcours antérieur n'autorise pas à ignorer le contexte, et qu'une correction ponctuelle ne démontre pas, sans nouvel essai, une maîtrise transférable dans toute situation.","question":"Quelle conclusion pédagogique est la plus solidement appuyée par l'évaluation décrite ?","explanation":"A décrit la mise à l'épreuve des gestes antérieurs: reconnaître les repères transférables et identifier une condition nouvelle avant de modifier sa décision. B confond ancienneté et adéquation au contexte; C généralise une seule observation malgré la réserve du centre; D nie que les pratiques antérieures puissent rester des ressources d'analyse."}]}$paper_10$::jsonb),
('tcf-reading-11','tcf-reading-2026-11-close-reading-v4',$paper_11${"id":"tcf-reading-11","title":"TCF Reading · Test 11","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"C","options":["Des meubles démontés","Des aliments ouverts","Des couvertures propres","Des vêtements mouillés"],"passage":"La collecte de couvertures se termine samedi. Déposez uniquement des articles propres et secs ; les vêtements seront collectés le mois prochain.\n\nLes articles non adaptés ne doivent pas être laissés devant le local.","question":"Que peut-on donner cette semaine ?","explanation":"Le passage indique : « La collecte de couvertures se termine samedi. Déposez uniquement des articles propres et secs ; les vêtements seront collectés le mois prochain. » Cela justifie la réponse : Des couvertures propres."},{"number":2,"points":3,"correct":"D","options":["Tous les matins","Le dimanche soir","Le lundi seulement","Le jeudi"],"passage":"La permanence d'entraide reçoit sans rendez-vous le jeudi. Les autres jours, un appel préalable est nécessaire.\n\nMerci de prévoir un temps d'attente pendant les périodes de forte fréquentation.","question":"Quand peut-on venir directement ?","explanation":"Le passage indique : « La permanence d'entraide reçoit sans rendez-vous le jeudi. Les autres jours, un appel préalable est nécessaire. » Cela justifie la réponse : Le jeudi."},{"number":3,"points":3,"correct":"D","options":["Les musiciens du soir uniquement","Tous les convives","Les clients du marché","Les bénévoles chargés de l'installation"],"passage":"Les bénévoles du repas partagé se retrouveront à neuf heures pour installer les tables. Le public arrivera à midi.\n\nLes personnes inscrites pour une autre mission garderont leur horaire habituel de présence.","question":"Qui est attendu à neuf heures ?","explanation":"Le passage indique : « Les bénévoles du repas partagé se retrouveront à neuf heures pour installer les tables. Le public arrivera à midi. » Cela justifie la réponse : Les bénévoles chargés de l'installation."},{"number":4,"points":3,"correct":"A","options":["La confirmation d'inscription","Un billet de spectacle","Un relevé bancaire","Un diplôme scolaire"],"passage":"La distribution de cahiers est ouverte aux familles inscrites. Apportez votre confirmation, imprimée ou sur téléphone.\n\nLe personnel retrouvera ensuite votre dossier sans demander une nouvelle inscription. Une famille rencontrant une difficulté peut contacter l'accueil avant le jour prévu.","question":"Quel document faut-il présenter ?","explanation":"Le passage indique : « La distribution de cahiers est ouverte aux familles inscrites. Apportez votre confirmation, imprimée ou sur téléphone. » Cela justifie la réponse : La confirmation d'inscription."},{"number":5,"points":9,"correct":"C","options":["Un service de transport privé","Une absence d'activité","Une tâche sans port de charges lourdes","Un changement de tous les horaires"],"passage":"Je peux aider à trier les dons samedi, mais pas porter les cartons lourds. Peux-tu me prévoir une tâche à table ?\n\nJe suis disponible toute la matinée et peux aussi aider à vérifier les étiquettes. Ainsi, l'équipe pourra répartir les autres tâches entre les bénévoles disponibles.","question":"Quelle adaptation est demandée ?","explanation":"Le passage indique : « Je peux aider à trier les dons samedi, mais pas porter les cartons lourds. Peux-tu me prévoir une tâche à table ? » Cela justifie la réponse : Une tâche sans port de charges lourdes."},{"number":6,"points":9,"correct":"B","options":["Uniquement un comédien professionnel","Une personne intéressée par la lecture partagée","Une personne refusant de lire à voix haute","Un vendeur de livres seulement"],"passage":"Notre association cherche des personnes pour lire des histoires. Il suffit d'aimer partager des textes ; aucune expérience de spectacle n'est exigée.\n\nUne séance d'accueil permettra de découvrir les livres et de préparer une première lecture.","question":"Quel profil convient ?","explanation":"Le passage indique : « Notre association cherche des personnes pour lire des histoires. Il suffit d'aimer partager des textes ; aucune expérience de spectacle n'est exigée. » Cela justifie la réponse : Une personne intéressée par la lecture partagée."},{"number":7,"points":9,"correct":"C","options":["Annuler toutes les inscriptions","Calculer le prix des repas","Organiser les équipes de deux","Modifier le lieu du festival"],"passage":"Merci de confirmer votre disponibilité avant mardi. Nous devons constituer les binômes d'accompagnement, pas simplement compter les inscrits.\n\nUne absence peut être signalée sans devoir fournir de détail personnel au groupe. Il faut surtout que le responsable puisse rechercher un remplaçant assez tôt.","question":"Pourquoi la confirmation est-elle importante ?","explanation":"Le passage indique : « Merci de confirmer votre disponibilité avant mardi. Nous devons constituer les binômes d'accompagnement, pas simplement compter les inscrits. » Cela justifie la réponse : Organiser les équipes de deux."},{"number":8,"points":9,"correct":"C","options":["Remplacer les dons par un impôt","Réserver tous les articles aux touristes","Soutenir le fonctionnement solidaire","Supprimer les tarifs adaptés"],"passage":"La boutique solidaire vend aussi au grand public. Ces achats contribuent à financer les tarifs adaptés proposés à certaines familles.\n\nLe prix annoncé au public correspond aussi au travail de tri, d'entretien et d'accueil nécessaire au fonctionnement du lieu.","question":"Quel rôle jouent les achats ordinaires ?","explanation":"Le passage indique : « La boutique solidaire vend aussi au grand public. Ces achats contribuent à financer les tarifs adaptés proposés à certaines familles. » Cela justifie la réponse : Soutenir le fonctionnement solidaire."},{"number":9,"points":9,"correct":"A","options":["Une disponibilité moins fréquente mais fiable","Une participation sans calendrier","Un arrêt de toute aide","Une présence quotidienne"],"passage":"Je préfère m'engager une fois par mois régulièrement plutôt que promettre chaque semaine et annuler souvent.\n\nNous pourrons revoir le calendrier si mes disponibilités changent, plutôt que laisser l'équipe découvrir une absence le jour même.","question":"Quelle forme d'engagement est choisie ?","explanation":"Le passage indique : « Je préfère m'engager une fois par mois régulièrement plutôt que promettre chaque semaine et annuler souvent. » Cela justifie la réponse : Une disponibilité moins fréquente mais fiable."},{"number":10,"points":9,"correct":"C","options":["Attribuer un diplôme professionnel","Présenter les dossiers personnels au public","Préparer l'entrée dans l'activité","Sélectionner les donateurs les plus riches"],"passage":"L'équipe propose une séance d'accueil avant la première mission. Les nouveaux bénévoles y découvriront les règles de confidentialité.\n\nLes volontaires pourront poser leurs questions avant de s'engager. Les responsables présenteront aussi les limites des tâches et les situations qui demandent de contacter une personne compétente.","question":"À quoi sert cette séance ?","explanation":"Le passage indique : « L'équipe propose une séance d'accueil avant la première mission. Les nouveaux bénévoles y découvriront les règles de confidentialité. » Cela justifie la réponse : Préparer l'entrée dans l'activité."},{"number":11,"points":15,"correct":"C","options":["Seuls les professionnels peuvent participer","Le revenu détermine le nombre d'heures","Une même durée a la même valeur","Les outils sont vendus aux voisins"],"passage":"Une association échange des services entre habitants. Une heure de jardinage donne droit à une heure d'aide, quelle que soit la valeur marchande habituelle du métier.\n\nLes participants indiquent les services qu'ils peuvent proposer et les moments où ils sont disponibles. Un coordinateur facilite les premières rencontres sans promettre une réponse immédiate à chaque demande. Les échanges sont enregistrés dans un carnet commun pour que chacun sache ce qu'il a donné et reçu. Le groupe souhaite reconnaître des compétences diverses, y compris des gestes ordinaires parfois peu valorisés.","question":"Quel principe régit l'échange ?","explanation":"Le passage indique : « Une association échange des services entre habitants. Une heure de jardinage donne droit à une heure d'aide, quelle que soit la valeur marchande habituelle du métier. » Cela justifie la réponse : Une même durée a la même valeur."},{"number":12,"points":15,"correct":"D","options":["Remplacer les décisions des bénéficiaires","Éviter toute explication","Confisquer les documents personnels","Renforcer la compréhension des démarches"],"passage":"Le centre social aide à remplir des formulaires, mais demande aux personnes de rester présentes. Les animateurs expliquent les démarches plutôt que décider à leur place.\n\nLes animateurs montrent où trouver une information et demandent aux personnes de vérifier ce qui les concerne. L'aide peut prendre plus de temps qu'une saisie rapide effectuée sans explication. Le centre considère cependant que cette présence permet aussi de préparer une prochaine démarche.","question":"Quel objectif accompagne l'aide immédiate ?","explanation":"Le passage indique : « Le centre social aide à remplir des formulaires, mais demande aux personnes de rester présentes. Les animateurs expliquent les démarches plutôt que décider à leur place. » Cela justifie la réponse : Renforcer la compréhension des démarches."},{"number":13,"points":15,"correct":"D","options":["Supprimer les rencontres","Attirer des visiteurs payants","Empêcher toute coordination interne","Préserver la confidentialité"],"passage":"Une maraude adapte son parcours aux besoins signalés. Les bénévoles ne publient pas les lieux de rencontre pour protéger les personnes accompagnées.\n\nLes personnes choisissent ce qu'elles souhaitent dire et peuvent refuser une rencontre. L'équipe note seulement les informations nécessaires au suivi, dans un document non accessible au public. Les nouveaux volontaires reçoivent une présentation de ces règles avant leur première sortie. L'association souhaite favoriser un contact régulier sans transformer la situation d'une personne en contenu destiné à attirer de nouveaux donateurs. Les récits utilisés pour présenter le projet seront préparés séparément, avec un accord explicite des personnes concernées par la publication.","question":"Pourquoi limiter ces informations publiques ?","explanation":"Le passage indique : « Une maraude adapte son parcours aux besoins signalés. Les bénévoles ne publient pas les lieux de rencontre pour protéger les personnes accompagnées. » Cela justifie la réponse : Préserver la confidentialité."},{"number":14,"points":15,"correct":"A","options":["Une difficulté d'accès numérique","La durée des réparations","Le nombre de chaises","Le coût des outils professionnels"],"passage":"Un atelier de réparation réserve des places sans inscription en ligne. Les organisateurs veulent accueillir aussi ceux qui n'utilisent pas internet.\n\nUne partie des places reste réservée à un accueil sur place ou par téléphone. Les bénévoles expliquent ensuite comment préparer l'objet et quels renseignements apporter. Le service souhaite que la méthode d'inscription ne sélectionne pas à elle seule les participants. Les demandes seront suivies pour vérifier si ce choix touche réellement de nouvelles personnes. Il ne s'agit pas d'abandonner un outil pratique pour les habitués, mais de garder plusieurs voies possibles vers la même activité, dans des conditions clairement annoncées au public.","question":"Quelle barrière cherchent-ils à réduire ?","explanation":"Le passage indique : « Un atelier de réparation réserve des places sans inscription en ligne. Les organisateurs veulent accueillir aussi ceux qui n'utilisent pas internet. » Cela justifie la réponse : Une difficulté d'accès numérique."},{"number":15,"points":15,"correct":"B","options":["La publicité des dossiers","Le respect de la dignité","La sélection par la prise de parole","Le classement des difficultés"],"passage":"Une association fournit des repas sans demander aux personnes de raconter publiquement leur situation. L'accueil ne doit pas devenir une épreuve de justification devant les autres.\n\nLes bénéficiaires peuvent s'adresser discrètement à un responsable s'ils ont une demande particulière. Les bénévoles suivent une procédure commune pour éviter des pratiques très différentes selon la personne présente. L'association souhaite que la simplicité de l'accueil ne dépende pas d'une relation personnelle ou de la capacité à raconter une histoire convaincante. Elle vérifiera aussi les temps d'attente et l'organisation de la file.","question":"Quel principe est défendu ?","explanation":"Le passage indique : « Une association fournit des repas sans demander aux personnes de raconter publiquement leur situation. L'accueil ne doit pas devenir une épreuve de justification devant les autres. » Cela justifie la réponse : Le respect de la dignité."},{"number":16,"points":15,"correct":"A","options":["Clarifier les responsabilités lors du prêt","Garantir que rien ne s'abîmera jamais","Remplacer tous les échanges humains","Fixer un prix de vente obligatoire"],"passage":"Des voisins prêtent des objets grâce à un catalogue commun. Une fiche indique leur état au départ et au retour pour éviter les malentendus.\n\nL'emprunteur peut poser des questions avant de confirmer le prêt. Les organisateurs souhaitent préserver la confiance entre voisins sans attendre qu'un problème se transforme en accusation. Les règles précisent aussi ce qui se passe lorsqu'un objet s'abîme malgré une utilisation normale, afin de ne pas confondre tout incident avec une faute ou de promettre qu'un objet partagé restera toujours intact.","question":"À quoi sert cette fiche ?","explanation":"Le passage indique : « Des voisins prêtent des objets grâce à un catalogue commun. Une fiche indique leur état au départ et au retour pour éviter les malentendus. » Cela justifie la réponse : Clarifier les responsabilités lors du prêt."},{"number":17,"points":15,"correct":"D","options":["Les conversations sont interdites","Les visiteurs prescrivent des traitements","Les bénéficiaires doivent rester seuls","Les visites ne remplacent pas des soins"],"passage":"Une équipe organise des visites amicales. Les visiteurs ne réalisent pas de soins ; ils signalent les besoins particuliers au responsable compétent.\n\nLe programme prévoit surtout du temps pour discuter, lire ou faire une petite promenade lorsque cela convient. Les personnes accompagnées choisissent les activités et peuvent demander de reporter un rendez-vous. Le responsable distingue cette présence amicale des interventions nécessitant une formation ou une autorisation particulière. L'association préfère un cadre clair à une promesse d'aide illimitée, qui pourrait mettre en difficulté les visiteurs comme les personnes qu'ils viennent rencontrer.","question":"Quelle limite est posée ?","explanation":"Le passage indique : « Une équipe organise des visites amicales. Les visiteurs ne réalisent pas de soins ; ils signalent les besoins particuliers au responsable compétent. » Cela justifie la réponse : Les visites ne remplacent pas des soins."},{"number":18,"points":15,"correct":"A","options":["Élargir la participation aux échanges","Rendre les documents plus techniques","Réserver les décisions aux traducteurs","Supprimer les débats"],"passage":"Un collectif propose des réunions avec traduction dans plusieurs langues. Les comptes rendus restent courts pour que les informations circulent facilement.\n\nLes participants reçoivent les principaux documents avant la réunion et peuvent demander une précision pendant les échanges. Le comité souhaite que les personnes moins à l'aise dans une langue ne soient pas réduites à écouter sans intervenir. Les traducteurs ne prennent pas les décisions à leur place. Ils facilitent la compréhension de ce qui est proposé et des choix à effectuer.","question":"Quel objectif guide ces choix ?","explanation":"Le passage indique : « Un collectif propose des réunions avec traduction dans plusieurs langues. Les comptes rendus restent courts pour que les informations circulent facilement. » Cela justifie la réponse : Élargir la participation aux échanges."},{"number":19,"points":15,"correct":"B","options":["Éviter tout tri","Assurer la qualité des dons distribués","Réserver les jeux aux organisateurs","Augmenter leur prix de revente"],"passage":"Une collecte de jouets demande des jeux complets. Les pièces manquantes seront recherchées avant la distribution, afin d'offrir des objets réellement utilisables.\n\nLes bénévoles essaient les mécanismes et indiquent les limites lorsqu'un jeu ne peut pas être complété. Certains objets seront réparés avant d'être proposés, d'autres orientés vers une autre filière. Elle expliquera les critères de tri aux personnes qui apportent des jouets, afin de réduire les déplacements inutiles et de préparer les prochaines collectes dans de meilleures conditions.","question":"Pourquoi vérifier les jeux ?","explanation":"Le passage indique : « Une collecte de jouets demande des jeux complets. Les pièces manquantes seront recherchées avant la distribution, afin d'offrir des objets réellement utilisables. » Cela justifie la réponse : Assurer la qualité des dons distribués."},{"number":20,"points":21,"correct":"B","options":["Supprimer toute disponibilité bénévole","Prendre en compte des contraintes différentes","Fixer les horaires au hasard","Éviter de rencontrer les bénéficiaires"],"passage":"Une association consulte les bénéficiaires avant de choisir les horaires d'ouverture. Les créneaux pratiques pour les bénévoles ne sont pas toujours ceux qui conviennent aux personnes accueillies. Les personnes interrogées indiquent notamment les moments où elles peuvent se déplacer et les contraintes liées aux transports. L'association compare ces réponses avec les disponibilités de l'équipe avant de proposer un calendrier. Elle veut éviter qu'une permanence apparemment ouverte reste inaccessible à ceux qu'elle vise. Les horaires seront réexaminés après quelques semaines, en regardant les demandes non satisfaites autant que les présences effectivement enregistrées à l'accueil.","question":"Pourquoi cette consultation est-elle nécessaire ?","explanation":"Le passage indique : « Une association consulte les bénéficiaires avant de choisir les horaires d'ouverture. Les créneaux pratiques pour les bénévoles ne sont pas toujours ceux qui conviennent aux personnes accueillies. » Cela justifie la réponse : Prendre en compte des contraintes différentes."},{"number":21,"points":21,"correct":"D","options":["Les frais réels sont toujours nuls","Tous les déplacements sont des emplois","Les conducteurs paient les passagers","Rembourser une dépense n'est pas rémunérer un service"],"passage":"Un réseau de covoiturage solidaire rembourse les frais réels des conducteurs. Il ne cherche pas à leur procurer un revenu complémentaire. Les trajets et les dépenses doivent être notés selon les règles annoncées à l'inscription. L'association souhaite que les conducteurs n'avancent pas durablement des frais qu'ils ne peuvent pas supporter. Elle précise cependant que le dispositif reste différent d'une activité commerciale de transport. Les responsables vérifieront les documents sans demander aux bénéficiaires de négocier directement un prix à chaque sortie, afin de préserver un cadre compréhensible pour les deux parties.","question":"Quelle distinction est faite ?","explanation":"Le passage indique : « Un réseau de covoiturage solidaire rembourse les frais réels des conducteurs. Il ne cherche pas à leur procurer un revenu complémentaire. » Cela justifie la réponse : Rembourser une dépense n'est pas rémunérer un service."},{"number":22,"points":21,"correct":"B","options":["L'abandon du projet initial sans explication","La transparence envers les donateurs","Le refus de tout suivi","La recherche de nouveaux frais cachés"],"passage":"Une collecte financière réussit au-delà des prévisions. L'association publie l'utilisation du surplus au lieu de modifier discrètement l'objectif annoncé. Les responsables présentent les dépenses supplémentaires envisagées et expliquent leur lien avec le projet initial. Le comité souhaite que la réussite de la collecte ne rende pas son fonctionnement moins lisible. Une somme reçue au-delà de l'objectif reste une ressource à utiliser avec soin, selon des décisions identifiables, et non un montant dont l'emploi pourrait être laissé sans explication publique.","question":"Quel souci manifeste cette démarche ?","explanation":"Le passage indique : « Une collecte financière réussit au-delà des prévisions. L'association publie l'utilisation du surplus au lieu de modifier discrètement l'objectif annoncé. » Cela justifie la réponse : La transparence envers les donateurs."},{"number":23,"points":21,"correct":"C","options":["Éviter les intérêts personnels","Réserver le lieu aux nouveaux arrivants","Créer des relations qui dépassent le seul besoin d'aide","Transformer toutes les rencontres en démarches"],"passage":"Un café accueille des rencontres entre personnes arrivées récemment et habitants installés. Les échanges portent sur des centres d'intérêt partagés, pas uniquement sur les difficultés administratives. Des ateliers de musique, des promenades et des échanges de recettes servent de premiers points de rencontre. Les personnes peuvent venir sans devoir exposer immédiatement leur parcours. L'équipe veut que chacun puisse être reconnu pour ses intérêts et ses contributions, pas uniquement pour une difficulté. Les informations pratiques restent disponibles dans un autre cadre.","question":"Quel effet est recherché ?","explanation":"Le passage indique : « Un café accueille des rencontres entre personnes arrivées récemment et habitants installés. Les échanges portent sur des centres d'intérêt partagés, pas uniquement sur les difficultés administratives. » Cela justifie la réponse : Créer des relations qui dépassent le seul besoin d'aide."},{"number":24,"points":21,"correct":"A","options":["De l'aide pour intégrer les bénévoles","Une rémunération automatique de tous les volontaires","Un remplacement de leur activité par des annonces","Une suppression des missions"],"passage":"Une plateforme met en relation des bénévoles et des associations. Les petites structures souhaitent aussi un accompagnement, car publier une mission ne suffit pas à organiser l'accueil des volontaires. Les coordinateurs doivent présenter la mission, expliquer les limites et prévoir un interlocuteur pour le premier jour. Les structures peu nombreuses n'ont pas toujours le temps de préparer seules ces éléments. Elles demandent donc un soutien qui dépasse la simple visibilité de leur annonce.","question":"Quel besoin complémentaire expriment-elles ?","explanation":"Le passage indique : « Une plateforme met en relation des bénévoles et des associations. Les petites structures souhaitent aussi un accompagnement, car publier une mission ne suffit pas à organiser l'accueil des volontaires. » Cela justifie la réponse : De l'aide pour intégrer les bénévoles."},{"number":25,"points":21,"correct":"C","options":["La participation aux tâches d'accueil, qui serait surtout utile aux membres peu disponibles pour les travaux agricoles.","L'expérience des plantes, qui permet de mesurer plus précisément l'efficacité de chaque contribution au collectif.","La seule contribution physique, au détriment de la coordination et de l'accueil.","La capacité à travailler seul sur une parcelle, afin de réduire le besoin de coordination entre bénévoles."],"passage":"Un jardin collectif attribue des tâches adaptées aux capacités de chacun. L'association reconnaît aussi l'organisation et l'accueil comme des contributions, pas seulement le travail physique. Les membres discutent des tâches avant chaque période importante, puis peuvent changer de rôle. Certaines personnes connaissent les plantes, d'autres savent accueillir un nouveau voisin ou tenir le planning. L'association souhaite éviter qu'une même forme de contribution devienne la mesure unique de l'engagement. Un membre ne peut pas bêcher mais coordonne les plannings et aide à résoudre les conflits d'horaires; sans lui, les plantations seraient retardées. Les responsables comptabilisent aussi cette contribution quand ils répartissent les responsabilités.","question":"Quel critère d'engagement le jardin refuse-t-il de privilégier exclusivement ?","explanation":"C identifie la hiérarchie de tâches physiques que l'organisation refuse. A/B/D privilégient un type de capacité mais ne décrivent pas précisément l'exclusion du travail de planification mis en évidence."},{"number":26,"points":21,"correct":"B","options":["Elle confie aux personnes accueillies le choix du stock à commander pour la semaine selon leurs besoins exprimés.","Elle ouvre des choix informés dans la limite des stocks disponibles.","Elle étend la gamme de produits distribués sans modifier la manière dont les bénévoles orientent les décisions.","Elle facilite surtout les choix des personnes qui maîtrisent déjà la préparation des produits disponibles."],"passage":"Une banque alimentaire forme ses équipes à expliquer les choix disponibles. Les personnes accompagnées peuvent exprimer leurs préférences dans les limites du stock. Les bénévoles présentent les aliments et les conditions de conservation sans supposer que toutes les familles les utilisent de la même manière. L'équipe ne promet pas un choix sans limite, mais veut que les possibilités réelles soient expliquées et que les personnes ne soient pas simplement destinataires d'une décision prise sans elles. Le stock contient deux céréales que certaines familles ne savent pas préparer de la même façon. Une bénévole explique les usages et laisse la personne choisir, sans garantir que chaque produit sera toujours disponible.","question":"Que modifie cette pratique dans la relation d'aide ?","explanation":"B associe information et choix possible dans les limites du stock. A attribue aux bénéficiaires des commandes non prévues; C déplace le changement vers l'assortiment; D laisse les novices exclus contrairement à l'exemple."},{"number":27,"points":21,"correct":"D","options":["Elle permet aux fondateurs d'assurer seuls une continuité stable en confiant aux autres des tâches moins importantes.","Elle transforme les permanences en engagements spontanés, sans prévoir de relais lors des absences.","Elle rend les nouveaux bénévoles indépendants de toute formation supplémentaire après lecture des fiches.","Elle réduit la dépendance à quelques membres détenant les informations essentielles."],"passage":"Un groupe souhaite pérenniser ses actions après une urgence locale. Il organise un calendrier et répartit les responsabilités pour éviter que tout repose sur deux fondateurs. Les fondateurs préparent des fiches simples et accompagnent les nouveaux responsables lors des premières permanences. Ils souhaitent que l'information circule au lieu de rester dans quelques téléphones personnels. Les membres pourront signaler les tâches trop lourdes avant de se décourager. Lorsque l'un des fondateurs tombe malade, les nouvelles fiches permettent de maintenir les permanences avec une autre équipe. Les documents servent d'appui à une transmission effective, non de remplacement à tout accompagnement.","question":"Pourquoi la transmission des tâches est-elle centrale pour la pérennité du groupe ?","explanation":"D limite la dépendance à quelques membres. A conserve cette concentration; B supprime les remplacements nécessaires; C confond documentation et absence de tout accompagnement."},{"number":28,"points":21,"correct":"D","options":["Les récits permettent de calculer un impact identique pour toutes les interventions comptées dans la même catégorie.","Les témoignages rendent les totaux moins utiles lorsqu'ils donnent accès aux expériences détaillées de quelques personnes.","Le récit le plus significatif peut être retenu comme représentation du résultat typique du programme.","Éclairer des effets particuliers sans généraliser à tous les bénéficiaires."],"passage":"L'association ajoute des témoignages à son bilan chiffré. Une aide ponctuelle peut avoir un effet important que le seul nombre d'interventions ne décrit pas. Les récits sont recueillis avec l'accord des personnes et relus avant une éventuelle publication. Ils ne remplacent pas les données de suivi, mais aident à comprendre des effets que les tableaux résument mal. Le centre veut éviter de présenter chaque histoire comme représentative de toutes les situations. Le bilan compte dix interventions identiques, mais un témoignage décrit comment l'une d'elles a permis une reprise de démarches après des mois d'arrêt. L'association conserve le total et la description, sans généraliser ce résultat particulier à tous les cas.","question":"Que permet l'ajout de témoignages sans remplacer les chiffres ?","explanation":"D éclaire des effets situés sans généralisation à tous. A/C attribuent aux exemples une représentativité inexistante, B oppose à tort récit et bilan chiffré."},{"number":29,"points":21,"correct":"B","options":["La participation régulière aux activités constitue une condition pour bénéficier d'aides complémentaires plutôt que de l'accueil initial.","Recevoir une aide relève d'un droit d'accueil indépendant d'une éventuelle contribution volontaire.","Les bénéficiaires proposant d'aider à l'accueil peuvent être prioritaires lorsque les services manquent de places.","Une personne devenue bénévole cesse d'être éligible aux aides puisque ses besoins sont supposés avoir diminué."],"passage":"Un centre propose de participer à l'organisation aux personnes qui viennent y chercher une aide. Cette possibilité est facultative et n'est pas une condition pour être accueilli. Les bénéficiaires peuvent proposer une activité, aider à un rangement ou participer à une réunion lorsqu'ils le souhaitent. Ils veulent préserver un droit à l'accueil tout en reconnaissant que les personnes reçues peuvent aussi contribuer à la vie du lieu. Une personne ne souhaite pas participer aux réunions mais a besoin d'un colis alimentaire. Le centre confirme que son accès ne changera pas; une autre personne choisit d'aider ponctuellement à l'accueil.","question":"Quelle distinction protège la liberté des personnes accompagnées ?","explanation":"B affirme l'indépendance de l'aide et du bénévolat. A/C réintroduisent des conditions d'accès, D invente une perte de droits liée à la participation."},{"number":30,"points":26,"correct":"C","options":["Prolonger la période de mobilisation renforcée afin de profiter de l'expérience des bénévoles déjà très investis.","Confier durablement aux fondateurs les tâches les plus exigeantes et proposer les autres missions au reste du groupe.","Prévoir relais et limites pour maintenir l'engagement sans épuiser les bénévoles.","Privilégier des engagements très courts décidés au dernier moment pour respecter la liberté individuelle des bénévoles."],"passage":"L'engagement bénévole est parfois présenté comme un temps libre sans contraintes. Or une association doit aussi définir les limites des missions et reconnaître les indisponibilités. Une disponibilité généreuse mais sans cadre peut conduire à l'épuisement et compromettre la continuité de l'action. Les responsables prévoient des pauses, des relais et un interlocuteur en cas de difficulté. Ces règles ne diminuent pas la générosité du projet ; elles lui permettent de rester possible quand les premières semaines d'enthousiasme sont passées. Une bénévole assure trois permanences supplémentaires en période d'urgence puis demande un relais. L'association organise une rotation, car maintenir cette disponibilité exceptionnelle pendant toute l'année l'épuiserait.","question":"Quel principe soutient la continuité du bénévolat après la phase d'urgence ?","explanation":"C formalise des relais et des limites. A/B prolongent la surcharge sur quelques personnes, D supprime une prévisibilité nécessaire à la continuité."},{"number":31,"points":26,"correct":"A","options":["Les distributions répondent aux besoins actuels, tandis qu'une action plus lente vise des causes structurelles.","L'aide d'urgence fournit des observations mais ne peut pas être utilisée pour discuter des causes de logement.","L'amélioration du logement constitue une étape préalable à toute distribution, afin d'éviter la répétition des besoins.","La quantité de colis distribués donne directement la mesure des progrès accomplis dans les conditions d'habitat."],"passage":"Une aide rapide répond à une urgence. Elle ne modifie pas nécessairement les causes qui rendent cette aide indispensable. Un collectif maintient ses distributions tout en participant à un travail sur l'accès au logement. Les deux démarches répondent à des temporalités différentes. Ils souhaitent continuer à répondre aux besoins présents, tout en utilisant ce qu'ils observent pour participer à des changements qui pourraient réduire la nécessité de ces interventions à l'avenir. Les distributions de nourriture répondent aux besoins de cette semaine, tandis que les données recueillies sur les difficultés de logement sont transmises à un groupe de travail. Les organisateurs refusent de présenter l'une des démarches comme substitut de l'autre.","question":"Quel lien le collectif établit-il entre distribution et action sur le logement ?","explanation":"A articule aide immédiate et action plus lente sur les causes. B nie la possibilité de transmission d'information; C reporte l'urgence, D confond activité et changement structurel."},{"number":32,"points":26,"correct":"D","options":["Le comparer aux confirmations de créneau pour mesurer l'écart entre intérêt initial et disponibilité probable.","Le compléter avec les présences effectivement observées pendant la première semaine de mission.","Le prendre comme liste de contacts à relancer pour comprendre les contraintes de participation.","Le présenter comme un effectif disponible garanti pour couvrir les missions prévues."],"passage":"Le nombre de volontaires inscrits sur une plateforme augmente. Les associations observent pourtant des présences irrégulières. Pour apprécier les ressources réelles, elles distinguent une intention d'engagement et une participation effectivement organisée. Les responsables proposent un accueil et une confirmation concrète des créneaux. Le passage d'une candidature à une présence régulière demande une organisation, même lorsque les personnes déclarent sincèrement vouloir aider et disposent de compétences utiles à l'association. Cent profils sont créés en ligne, mais seuls trente volontaires confirment un créneau et dix se présentent la première semaine. L'association cherche à comprendre cette conversion sans supposer que les soixante-dix autres sont insincères.","question":"Quel usage du nombre d'inscriptions serait trompeur ?","explanation":"D est trompeur car cent profils ne garantissent ni confirmation ni présence. A/B/C sont des usages prudents qui distinguent les étapes de participation."},{"number":33,"points":26,"correct":"D","options":["Recueillir un accord général puis choisir les propositions que le budget rend effectivement applicables.","Présenter les contraintes financières après le vote et considérer les décisions finales comme automatiquement approuvées.","Mettre en avant les citations les plus fréquentes sans expliquer la manière dont les idées ont été examinées.","Expliquer comment les propositions ont influencé les décisions et pourquoi."],"passage":"Une organisation souhaite « donner la parole » à ses bénéficiaires. Elle doit aussi leur laisser un effet sur les décisions. Recueillir des avis sans expliquer ce qui en sera fait peut transformer la consultation en simple illustration d'un projet déjà arrêté. Cette réponse permet aux participants d'apprécier la portée de leur contribution et de comprendre les contraintes, au lieu de disparaître après la réunion. Après une réunion, les habitants proposent deux changements. L'organisation explique qu'elle adopte le premier et reporte le second pour des raisons de sécurité documentées. Cette réponse permet de comprendre la portée de la consultation.","question":"Quelle pratique rend la consultation plus qu'une collecte symbolique d'opinions ?","explanation":"D documente les suites données aux suggestions et les motifs. A/B n'expliquent pas le lien entre avis et arbitrages; C valorise des citations sans décision."},{"number":34,"points":26,"correct":"B","options":["Parce qu'un accueil soigné peut réduire l'importance des contraintes budgétaires des personnes aidées.","Parce qu'une présentation soignée peut respecter les clients et la mission solidaire.","Parce qu'une boutique agréable rend moins nécessaire l'accompagnement des clients dans leurs choix.","Parce que l'organisation ressemble davantage à un commerce ordinaire et peut donc adopter les mêmes objectifs de profit."],"passage":"Une boutique solidaire améliore sa présentation pour que les clients puissent choisir dans un lieu accueillant. Certains s'inquiètent qu'une belle vitrine fasse oublier la mission sociale. L'équipe répond que le respect des personnes peut aussi passer par la qualité ordinaire du service. Les clients peuvent consulter les prix et demander des informations sur les objets comme dans un autre commerce. La boutique présente les objets avec des prix lisibles et propose un conseil sans exiger que les clients expliquent leur situation. Les responsables estiment qu'une qualité d'accueil comparable à un commerce ordinaire peut faire partie du respect.","question":"Pourquoi une présentation soignée n'est-elle pas incompatible avec la mission sociale ?","explanation":"B considère la dignité de l'accueil comme compatible avec la mission sociale. A/C minimisent les besoins, D assimile apparence commerciale et finalité lucrative."},{"number":35,"points":26,"correct":"B","options":["À limiter les échanges informels aux membres les plus anciens afin de stabiliser les procédures communes.","À rendre l'organisation accessible aux nouveaux arrivants tout en conservant les relations d'entraide.","À maintenir la transmission dans les messages personnels tout en ajoutant un guide pour les nouveaux.","À fixer les consignes initiales de manière durable sans prévoir de nouvelles discussions sur leur évolution."],"passage":"Le développement d'un réseau d'entraide augmente les demandes adressées aux coordinateurs. Pour durer, le groupe formalise certaines règles sans supprimer les échanges informels. Il cherche à préserver la confiance tout en rendant l'organisation moins dépendante de relations personnelles fragiles. Les nouveaux membres sauront où chercher une information et à qui poser une question, même lorsque les personnes qui les ont accueillis sont absentes. Une nouvelle coordinatrice trouve les consignes écrites même lorsque son mentor est absent, mais continue d'échanger librement avec l'équipe. Le réseau souhaite réduire la fragilité de la transmission sans formaliser chaque conversation.","question":"À quoi sert la formalisation partielle des règles ?","explanation":"B combine une documentation accessible aux nouveaux avec les relations informelles. A restreint les échanges, C maintient la dépendance aux personnes, D exclut l'ajustement pourtant recherché."},{"number":36,"points":33,"correct":"A","options":["Parce que les effets sociaux et la capacité de participation constituent aussi des résultats pertinents.","Parce que l'absence d'emploi pendant le trimestre doit être compensée par des résultats de formation immédiats.","Parce que la fréquentation régulière d'un atelier établit à elle seule son effet sur l'autonomie économique.","Parce que des changements relationnels permettent de prévoir avec fiabilité de futurs contrats de travail."],"passage":"Un projet associe des personnes précaires à des ateliers culturels. Les organisateurs refusent de mesurer le résultat uniquement par un retour à l'emploi. Les relations, la confiance et la possibilité de participer à une vie commune ont une valeur propre. L'utilité sociale ne se réduit pas toujours à un indicateur économique immédiat. Les participants peuvent parler d'un changement dans leurs relations ou de la possibilité de sortir plus facilement de chez eux. Certains envisagent ensuite une formation ou un emploi, d'autres recherchent surtout un espace où ils se sentent reconnus. Le centre souhaite décrire ces trajectoires sans les classer selon une seule issue. Il discutera donc des critères avec les personnes concernées avant de rédiger son bilan. Le projet peut avoir plusieurs effets utiles, dont certains apparaissent lentement et restent difficiles à résumer dans un chiffre unique présenté à la fin de l'année. Un atelier n'aboutit à aucun contrat de travail pendant le trimestre, mais plusieurs personnes auparavant isolées participent désormais à des rencontres et prennent part à des décisions du quartier. Le centre veut rendre ce changement visible dans son bilan.","question":"Pourquoi l'absence de contrat de travail ne suffit-elle pas à qualifier cet atelier d'échec ?","explanation":"A reconnaît la participation sociale et la confiance comme résultats utiles en eux-mêmes. B/D réintroduisent une lecture essentiellement professionnelle; C prête à la seule fréquentation une portée causale non démontrée."},{"number":37,"points":33,"correct":"A","options":["L'exigence d'une activité durable se heurte à une visibilité des ressources trop courte pour l'organiser.","Une formation longue donne aux financeurs la possibilité de suspendre les ressources au moment des évaluations.","Un financement annuel réduit les coûts administratifs mais rend plus difficile l'examen régulier des résultats.","L'incertitude financière vient surtout d'un manque de planification interne que les responsables peuvent corriger seuls."],"passage":"Une association dépend d'un financement annuel renouvelable. Elle peut annoncer beaucoup d'activités, mais hésite à former durablement son équipe sans visibilité. Les financeurs demandent de la stabilité aux actions qu'ils soutiennent. Cette stabilité devient difficile lorsque les ressources permettant de la construire restent elles-mêmes incertaines. Les responsables cherchent un calendrier de financement qui permette d'anticiper les embauches et la formation. Ils expliquent que le temps passé à reconstruire sans cesse des dossiers réduit aussi celui disponible pour l'accueil. Les financeurs souhaitent garder la possibilité d'évaluer les actions et de réorienter les soutiens. Le débat porte donc sur des engagements assez stables pour rendre l'activité possible, sans supprimer l'examen de ses résultats. Les associations veulent que cette incertitude soit visible dans le bilan, plutôt que les interruptions soient interprétées uniquement comme un défaut d'organisation interne. Le financeur souhaite des équipes formées et régulières, mais annonce le renouvellement de sa subvention seulement quelques semaines avant chaque échéance. L'association hésite alors à embaucher pour les missions qui demandent un an de préparation.","question":"Quel problème de cohérence le calendrier de financement crée-t-il ?","explanation":"A décrit la contradiction entre demande de stabilité et ressources trop incertaines pour la préparer. B/C ne correspondent pas au problème exposé; D attribue à l'association seule un défaut lié au calendrier du financeur."},{"number":38,"points":33,"correct":"B","options":["Un nouveau support de communication exige d'informer les témoins, mais l'accord initial couvre toutes les campagnes similaires.","L'accord porte sur un usage précis, non sur toutes les diffusions futures.","La première diffusion autorise les campagnes suivantes dès lors que les propos cités ne sont pas modifiés.","Le consentement donné pendant l'accompagnement vaut aussi pour des usages institutionnels ultérieurs, sous réserve d'anonymat."],"passage":"Un collectif publie les récits de personnes accompagnées pour sensibiliser le public. Il leur propose de relire les textes et de retirer leur accord avant diffusion. Le fait qu'un témoignage serve une cause utile ne supprime pas les droits de la personne dont il raconte l'expérience. L'objectif collectif ne dispense pas de respecter une décision individuelle de ne pas s'exposer. L'association présente plusieurs moyens de contribuer à la sensibilisation, dont certains ne montrent aucun visage ni détail personnel. Elle accepte qu'une personne préfère ne pas participer, sans changer l'aide qu'elle reçoit. Les responsables souhaitent éviter qu'un accord donné dans une situation fragile devienne une obligation ressentie. Avant chaque nouvelle utilisation, le cadre sera expliqué dans une langue compréhensible. La communication pourra ainsi servir le projet tout en conservant une place à la décision de chacun, y compris lorsqu'une histoire particulièrement émouvante semblerait très efficace pour mobiliser de futurs soutiens. Une histoire publiée avec accord initial est ensuite demandée par une autre campagne. L'association sollicite une nouvelle autorisation, car la première personne n'avait accepté qu'une utilisation délimitée.","question":"Que signifie ici le respect du consentement lors d'une nouvelle campagne ?","explanation":"B limite l'accord à l'usage consenti et reconnaît la possibilité d'une nouvelle décision. A/C supposent une autorisation plus étendue que celle donnée; D lie à tort l'aide à des utilisations futures."},{"number":39,"points":33,"correct":"A","options":["Des moyens de départ comparables ne suffisent pas: la capacité des partenaires à assurer l'accueil doit être reconstruite selon chaque territoire.","Des activités initiales de même nombre prouvent que les deux territoires appliquent le modèle avec une efficacité comparable dans la durée.","La différence de continuité établit que les budgets locaux ne jouent aucun rôle dès que les bénévoles peuvent être mobilisés ponctuellement.","Une formule commune pourrait être maintenue sans adaptation si la seconde commune investissait davantage dans la promotion de ses permanences."],"passage":"Une initiative locale attire l'attention nationale. Ses responsables sont invités à reproduire partout le même modèle. Ils présentent les principes, mais soulignent les relations de confiance et les ressources particulières qui ont permis leur réussite. Transmettre une expérience ne signifie pas promettre qu'elle produira les mêmes effets sans adaptation. Ils proposent aux nouveaux groupes d'examiner les besoins, les partenaires et les disponibilités avant de reprendre les mêmes activités. Certaines règles pourront être conservées, tandis que d'autres devront changer selon les personnes accueillies. L'équipe souhaite rester utile sans transformer un succès local en formule universelle. Les échanges porteront aussi sur les difficultés rencontrées, pas seulement sur les résultats faciles à montrer. Cette démarche demande plus de temps qu'une copie rapide, mais permet de distinguer les principes transférables et les conditions particulières qui doivent être reconstruites dans le nouveau territoire. Dans une autre ville, l'association trouve des locaux comparables mais aucun partenaire capable d'assurer les permanences. Elle conserve le principe d'accueil libre et modifie le calendrier et les responsabilités au lieu de copier la formule initiale. Deux communes reprennent ensuite l'initiative en annonçant le même budget et des locaux semblables. Dans la première, une maison de quartier dispose déjà d'une équipe de médiateurs et d'accords avec les services sociaux; dans la seconde, les locaux restent souvent fermés faute de personnes pour recevoir les visiteurs. Les deux communes affichent pourtant un nombre d'activités comparable durant le premier mois, grâce à des bénévoles mobilisés exceptionnellement. Six mois plus tard, seule la première maintient des permanences régulières. L'équipe d'origine refuse de conclure que la seconde commune devrait simplement augmenter les dépenses de communication: elle propose d'identifier quels partenaires peuvent réellement assurer l'accueil et de modifier le calendrier en conséquence. Le rapport précise que la différence de continuité ne démontre pas, à elle seule, que chaque autre différence entre territoires est sans effet.","question":"Quelle leçon les deux implantations apportent-elles sur la transposition d'un modèle, sans généralisation abusive ?","explanation":"A tient compte de la similitude initiale des locaux et budgets, mais distingue la continuité assurée par des partenariats et des permanences effectives; le texte ne permet pas d'ériger ce facteur en cause exclusive. B confond activité du premier mois et pérennité; C exclut tous les autres facteurs sur une seule comparaison; D suppose qu'une communication accrue remplace l'organisation concrète de l'accueil."}]}$paper_11$::jsonb),
('tcf-reading-12','tcf-reading-2026-11-close-reading-v4',$paper_12${"id":"tcf-reading-12","title":"TCF Reading · Test 12","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"D","options":["Tous les champs privés","Le sentier des vergers","La cour de la ferme","Le chemin communal"],"passage":"Le sentier des vergers est fermé pendant la récolte. La promenade reste possible par le chemin communal.\n\nLes promeneurs sont invités à suivre les panneaux temporaires. La fermeture doit permettre le passage des équipes et du matériel sans gêne.","question":"Quel chemin reste accessible ?","explanation":"Le passage indique : « Le sentier des vergers est fermé pendant la récolte. La promenade reste possible par le chemin communal. » Cela justifie la réponse : Le chemin communal."},{"number":2,"points":3,"correct":"C","options":["Dormir dans l'étable","Visiter l'élevage","Acheter à la boutique","Participer aux naissances"],"passage":"La ferme ouvre sa boutique vendredi, mais les visites d'élevage reprendront seulement au printemps.\n\nL'équipe peut toutefois répondre aux questions sur les produits pendant les horaires de vente.","question":"Que peut-on faire vendredi ?","explanation":"Le passage indique : « La ferme ouvre sa boutique vendredi, mais les visites d'élevage reprendront seulement au printemps. » Cela justifie la réponse : Acheter à la boutique."},{"number":3,"points":3,"correct":"C","options":["Accompagner obligatoirement chaque visiteur","Courir librement dans les cultures","Rester attachés sur le chemin","Entrer dans tous les bâtiments"],"passage":"Les chiens sont acceptés sur le chemin s'ils restent en laisse. Ils ne doivent pas entrer dans les parcelles.\n\nCette consigne permet de maintenir l'accès public sans perturber le travail dans les champs voisins.","question":"Quelle règle concerne les chiens ?","explanation":"Le passage indique : « Les chiens sont acceptés sur le chemin s'ils restent en laisse. Ils ne doivent pas entrer dans les parcelles. » Cela justifie la réponse : Rester attachés sur le chemin."},{"number":4,"points":3,"correct":"A","options":["Dimanche pendant les horaires indiqués","Après seize heures dimanche","Tous les soirs","Uniquement en hiver"],"passage":"Le moulin reçoit les groupes sur réservation. Les visiteurs individuels peuvent venir dimanche entre dix et seize heures.\n\nLes groupes recevront une confirmation avec les conditions d'accueil. Les visites individuelles suivront le parcours ouvert et respecteront les espaces non accessibles au public.","question":"Quand une personne seule peut-elle venir sans réservation ?","explanation":"Le passage indique : « Le moulin reçoit les groupes sur réservation. Les visiteurs individuels peuvent venir dimanche entre dix et seize heures. » Cela justifie la réponse : Dimanche pendant les horaires indiqués."},{"number":5,"points":9,"correct":"A","options":["Protéger les jeunes plants du gel","Les laisser sans lumière pendant un mois","Les arroser avec de l'eau glacée","Les planter immédiatement dehors"],"passage":"Je te garderai les plants jusqu'à samedi. Mets-les à l'abri si le gel revient ; ils ne sont pas encore prêts pour la pleine terre.\n\nJe te préciserai quelles variétés supportent mieux le froid. Prévois quelques pots pour les garder temporairement près d'une fenêtre plutôt que les installer trop vite au jardin.","question":"Quelle précaution est conseillée ?","explanation":"Le passage indique : « Je te garderai les plants jusqu'à samedi. Mets-les à l'abri si le gel revient ; ils ne sont pas encore prêts pour la pleine terre. » Cela justifie la réponse : Protéger les jeunes plants du gel."},{"number":6,"points":9,"correct":"C","options":["Ils resteront obligatoirement au musée","Ils seront vendus aux visiteurs","Ils seront restitués après copie","Ils seront détruits après exposition"],"passage":"L'association recherche des photos anciennes du village. Les originaux seront numérisés puis rendus ; aucun don définitif n'est demandé.\n\nUne fiche permettra d'identifier les lieux et les personnes représentés lorsque ces informations sont connues. Les propriétaires pourront vérifier les légendes avant l'exposition.","question":"Que deviendront les documents prêtés ?","explanation":"Le passage indique : « L'association recherche des photos anciennes du village. Les originaux seront numérisés puis rendus ; aucun don définitif n'est demandé. » Cela justifie la réponse : Ils seront restitués après copie."},{"number":7,"points":9,"correct":"D","options":["Approcher seules les ruches","Renoncer à toute activité rurale","Apporter leur propre miel","Prévenir l'organisateur à l'avance"],"passage":"Nous visiterons les ruches avec un apiculteur. Les personnes sensibles aux piqûres doivent le signaler avant la sortie.\n\nUn équipement de protection sera présenté au groupe avant l'approche. Le responsable pourra proposer une autre manière de suivre l'activité si une situation demande davantage de précautions.","question":"Quelle démarche est demandée à certaines personnes ?","explanation":"Le passage indique : « Nous visiterons les ruches avec un apiculteur. Les personnes sensibles aux piqûres doivent le signaler avant la sortie. » Cela justifie la réponse : Prévenir l'organisateur à l'avance."},{"number":8,"points":9,"correct":"A","options":["Une récolte a subi un aléa météo","Tous les fruits ont été vendus à l'étranger","Les clients ont demandé uniquement des légumes","Le point de retrait est fermé"],"passage":"Le panier de cette semaine contient moins de fruits, mais davantage de légumes. La grêle a touché une partie du verger.\n\nLes quantités seront expliquées au point de retrait. Les producteurs vous remercient pour votre compréhension.","question":"Pourquoi le contenu change-t-il ?","explanation":"Le passage indique : « Le panier de cette semaine contient moins de fruits, mais davantage de légumes. La grêle a touché une partie du verger. » Cela justifie la réponse : Une récolte a subi un aléa météo."},{"number":9,"points":9,"correct":"B","options":["Des sandales de ville","Des chaussures adaptées à la boue","Des patins","Un masque de plongée"],"passage":"Apportez des bottes pour la visite : le chemin près des pâtures est boueux, même lorsque la cour semble sèche.\n\nNous marcherons aussi sur une partie du terrain pour découvrir les activités du jour.","question":"Quel équipement est recommandé ?","explanation":"Le passage indique : « Apportez des bottes pour la visite : le chemin près des pâtures est boueux, même lorsque la cour semble sèche. » Cela justifie la réponse : Des chaussures adaptées à la boue."},{"number":10,"points":9,"correct":"B","options":["Éviter toute rencontre","Limiter la fatigue liée à la chaleur","Terminer une livraison nocturne","Profiter d'une température plus élevée"],"passage":"Je préfère venir aider au désherbage tôt le matin. Ensuite, la chaleur rend le travail plus fatigant.\n\nJe pourrai ensuite aider à ranger le matériel avant de repartir. Cette organisation me permettra de travailler tranquillement sans devoir interrompre longtemps l'activité aux heures les plus difficiles.","question":"Pourquoi choisir cet horaire ?","explanation":"Le passage indique : « Je préfère venir aider au désherbage tôt le matin. Ensuite, la chaleur rend le travail plus fatigant. » Cela justifie la réponse : Limiter la fatigue liée à la chaleur."},{"number":11,"points":15,"correct":"B","options":["La suppression des plantes aquatiques","La préservation d'habitats particuliers","L'uniformité esthétique","La création d'un parking"],"passage":"Une commune conserve de petites mares malgré leur aspect parfois désordonné. Elles accueillent des espèces qui ne vivent pas dans les bassins décoratifs.\n\nLes agents ont prévu un entretien différent des abords, afin de ne pas retirer toute la végétation pendant une période sensible. Des panneaux expliqueront ce choix aux passants. La commune souhaite éviter que la présence de plantes irrégulières ou d'eau trouble soit automatiquement interprétée comme un abandon. Les habitants pourront alors découvrir les fonctions de ces lieux modestes, dont l'intérêt ne se voit pas toujours dans un paysage aménagé uniquement pour paraître propre sur une photographie.","question":"Quel intérêt est souligné ?","explanation":"Le passage indique : « Une commune conserve de petites mares malgré leur aspect parfois désordonné. Elles accueillent des espèces qui ne vivent pas dans les bassins décoratifs. » Cela justifie la réponse : La préservation d'habitats particuliers."},{"number":12,"points":15,"correct":"C","options":["Transformer les prairies en routes","Récolter le lait sans déplacement","Laisser les prairies se renouveler","Éviter toute alimentation des animaux"],"passage":"Un éleveur déplace ses animaux entre plusieurs parcelles. Les périodes de repos permettent à l'herbe de repousser.\n\nIl observe la végétation et les traces de passage avant de décider du prochain déplacement. L'exploitant ne présente pas la rotation comme un calendrier indépendant de la météo : elle demande un suivi, afin que l'organisation protège les ressources dont les animaux auront besoin pendant le reste de la saison.","question":"À quoi sert la rotation ?","explanation":"Le passage indique : « Un éleveur déplace ses animaux entre plusieurs parcelles. Les périodes de repos permettent à l'herbe de repousser. » Cela justifie la réponse : Laisser les prairies se renouveler."},{"number":13,"points":15,"correct":"B","options":["Le prix des clôtures","La présence de fleurs","La couleur des maisons","Le nombre de voitures"],"passage":"Des habitants relèvent la présence d'insectes sur une haie. Ils observent aussi les fleurs disponibles pour relier les visites aux ressources du lieu.\n\nLes bénévoles utilisent une fiche commune et choisissent plusieurs moments d'observation pour ne pas retenir seulement une visite exceptionnelle. Les espèces difficiles à identifier seront examinées avec une association. Le groupe souhaite apprendre à relier les présences aux conditions du lieu, sans conclure à partir d'une photographie isolée. Les habitants pourront ainsi comprendre pourquoi deux observations différentes ne signifient pas automatiquement qu'une plante attire toujours davantage d'insectes qu'une autre dans toutes les situations.","question":"Quelle information complète le comptage ?","explanation":"Le passage indique : « Des habitants relèvent la présence d'insectes sur une haie. Ils observent aussi les fleurs disponibles pour relier les visites aux ressources du lieu. » Cela justifie la réponse : La présence de fleurs."},{"number":14,"points":15,"correct":"D","options":["Supprimer toutes les ventes fraîches","Travailler uniquement un mois par an","Acheter exclusivement des produits importés","Réduire les variations saisonnières de revenus"],"passage":"Une ferme vend des produits transformés sur place pour mieux répartir ses revenus dans l'année. Les ateliers occupent notamment les périodes où les ventes fraîches diminuent.\n\nLes préparations sont choisies selon les produits disponibles et les équipements que la ferme peut utiliser correctement. Les clients peuvent acheter sur place ou lors de quelques marchés. L'exploitant suit le temps consacré à cette activité, car transformer demande aussi de nouvelles compétences et une organisation précise. Il ne suffit pas de conserver un produit pour garantir sa vente.","question":"Quel objectif économique est poursuivi ?","explanation":"Le passage indique : « Une ferme vend des produits transformés sur place pour mieux répartir ses revenus dans l'année. Les ateliers occupent notamment les périodes où les ventes fraîches diminuent. » Cela justifie la réponse : Réduire les variations saisonnières de revenus."},{"number":15,"points":15,"correct":"C","options":["Éviter toute observation","Appliquer une règle identique à toutes les graines","Distinguer les conditions de culture","Mesurer seulement le prix des sachets"],"passage":"Une classe découvre les semences avant le potager. Les élèves comparent leur taille et leurs besoins plutôt que planter tout au même moment.\n\nLes groupes peuvent comparer leurs observations avant d'intervenir. Les animateurs souhaitent éviter que l'activité soit réduite à enfouir des graines puis attendre un résultat identique. Certaines demandes d'eau, de lumière ou de température doivent être anticipées. À la fin de la saison, les élèves raconteront aussi les essais qui n'ont pas fonctionné, afin de comprendre ce qu'ils ont appris sans mesurer la réussite uniquement au nombre de légumes récoltés dans leur petite parcelle.","question":"Quel apprentissage est visé ?","explanation":"Le passage indique : « Une classe découvre les semences avant le potager. Les élèves comparent leur taille et leurs besoins plutôt que planter tout au même moment. » Cela justifie la réponse : Distinguer les conditions de culture."},{"number":16,"points":15,"correct":"C","options":["Remplacer les pierres par du plastique","Empêcher tous les passages d'eau","Conserver plusieurs fonctions du muret","Rendre le sol totalement étanche"],"passage":"Des bénévoles restaurent un muret sans ciment. Ils apprennent une technique locale qui permet l'écoulement de l'eau et offre des refuges à de petits animaux.\n\nLes participants observent les pierres disponibles avant de commencer et choisissent leur position avec l'aide d'un artisan. Ils ne cherchent pas à reproduire un décor sans comprendre sa construction. Le chantier permettra aussi de discuter des réparations anciennes et des gestes d'entretien. Le village souhaite conserver un savoir utile en donnant aux bénévoles l'occasion de pratiquer, plutôt qu'en montrant seulement un mur terminé.","question":"Quel avantage est indiqué ?","explanation":"Le passage indique : « Des bénévoles restaurent un muret sans ciment. Ils apprennent une technique locale qui permet l'écoulement de l'eau et offre des refuges à de petits animaux. » Cela justifie la réponse : Conserver plusieurs fonctions du muret."},{"number":17,"points":15,"correct":"B","options":["Récolter dans toutes les parcelles","Préserver les cultures pendant la récolte","Choisir gratuitement tout le stock","Entrer sans consigne"],"passage":"Un producteur ouvre une journée d'autocueillette. Les visiteurs paient les fruits récoltés et doivent respecter les rangs indiqués pour ne pas abîmer les plants.\n\nLes rangs ouverts sont marqués et les quantités pesées à la sortie. L'équipe explique quels fruits peuvent être cueillis et comment éviter de casser les branches. Les visiteurs sont invités à demander conseil plutôt qu'à déplacer les repères eux-mêmes. La ferme souhaite proposer une rencontre agréable avec la production, sans oublier que les plantes doivent continuer à donner après leur passage.","question":"Quelle responsabilité accompagne l'activité ?","explanation":"Le passage indique : « Un producteur ouvre une journée d'autocueillette. Les visiteurs paient les fruits récoltés et doivent respecter les rangs indiqués pour ne pas abîmer les plants. » Cela justifie la réponse : Préserver les cultures pendant la récolte."},{"number":18,"points":15,"correct":"D","options":["Une fermeture des commerces","Une hausse obligatoire des achats","Une suppression des relations de voisinage","Un accès plus autonome au marché"],"passage":"Un marché rural ajoute un arrêt de navette. Les personnes sans voiture peuvent désormais y venir, sans dépendre d'un voisin disponible.\n\nLes horaires ont été construits autour des jours de marché, avec un temps suffisant pour faire les achats sans courir. Une information sera distribuée aux habitants qui ne consultent pas les annonces en ligne. Les responsables regarderont si les correspondances et l'emplacement de l'arrêt conviennent réellement. Ils ne souhaitent pas présenter la création de la ligne comme une réponse achevée avant de connaître l'expérience des premiers usagers.","question":"Quel effet est attendu ?","explanation":"Le passage indique : « Un marché rural ajoute un arrêt de navette. Les personnes sans voiture peuvent désormais y venir, sans dépendre d'un voisin disponible. » Cela justifie la réponse : Un accès plus autonome au marché."},{"number":19,"points":15,"correct":"C","options":["Refuser toute comparaison annuelle","Ignorer les dates de floraison","Croiser les observations avant de conclure","Considérer un seul événement comme suffisant"],"passage":"Une association surveille les floraisons chaque année. Une floraison plus précoce sera interprétée avec d'autres observations, pas comme la preuve isolée d'une tendance générale.\n\nLe groupe utilise plusieurs points fixes et conserve les relevés même lorsqu'aucun changement remarquable n'est visible. Les participants peuvent noter les conditions du moment et demander une vérification de leur identification. L'association souhaite construire une série utile, pas seulement recueillir des annonces de phénomènes inhabituels. Les visiteurs découvriront les résultats avec ces limites.","question":"Quelle prudence est exprimée ?","explanation":"Le passage indique : « Une association surveille les floraisons chaque année. Une floraison plus précoce sera interprétée avec d'autres observations, pas comme la preuve isolée d'une tendance générale. » Cela justifie la réponse : Croiser les observations avant de conclure."},{"number":20,"points":21,"correct":"A","options":["Donner de la stabilité avec un suivi","Exiger des résultats immédiats identiques","Réserver les terres aux exploitants déjà installés","Offrir un accès sans aucune règle"],"passage":"Une commune loue des terres à de nouveaux agriculteurs. Le bail laisse du temps pour développer une activité, mais prévoit un suivi des pratiques et des engagements pris. Les candidats présentent leur projet et les moyens dont ils disposent pour le mettre en place. Le service souhaite leur donner le temps d'apprendre le terrain et de préparer leurs débouchés. Les rencontres de suivi permettront d'identifier les difficultés, sans modifier les règles à chaque imprévu. La commune veut une activité viable et cohérente avec les objectifs annoncés, plutôt qu'une installation rapide qui disparaîtrait après une première saison difficile.","question":"Quel équilibre est recherché ?","explanation":"Le passage indique : « Une commune loue des terres à de nouveaux agriculteurs. Le bail laisse du temps pour développer une activité, mais prévoit un suivi des pratiques et des engagements pris. » Cela justifie la réponse : Donner de la stabilité avec un suivi."},{"number":21,"points":21,"correct":"A","options":["Plusieurs changements ont eu lieu simultanément","Les habitants ignorent le lieu de la ferme","Les mesures n'ont jamais été réalisées","Aucun oiseau n'a été observé"],"passage":"Le retour de certains oiseaux près d'une ferme encourage ses habitants. Ils ne l'attribuent pas à une seule mesure : haies, mares et changements de pratiques ont été mis en place ensemble. Les habitants ont participé à plusieurs actions et les changements ne peuvent pas être isolés facilement dans leurs souvenirs. Une association propose de garder des repères communs pour les prochaines années. Les observations resteront utiles, même sans permettre d'affirmer qu'un geste unique explique tout.","question":"Pourquoi rester prudent sur la cause ?","explanation":"Le passage indique : « Le retour de certains oiseaux près d'une ferme encourage ses habitants. Ils ne l'attribuent pas à une seule mesure : haies, mares et changements de pratiques ont été mis en place ensemble. » Cela justifie la réponse : Plusieurs changements ont eu lieu simultanément."},{"number":22,"points":21,"correct":"A","options":["Préserver tout en adaptant à un nouvel usage","Conserver uniquement le nom de la ferme","Reconstruire une copie sans utiliser le bâtiment","Interdire toute activité nouvelle"],"passage":"Un village transforme un ancien bâtiment agricole en atelier partagé. Il conserve la charpente, mais adapte l'accès aux normes actuelles. La conservation ne signifie pas l'absence de modification. Les futurs utilisateurs ont expliqué les espaces nécessaires au rangement, aux machines et à la circulation. Certains éléments seront protégés ou déplacés pour permettre ces activités. Le comité souhaite que les visiteurs puissent encore comprendre l'histoire du bâtiment. Il refuse cependant de confondre respect du lieu et impossibilité d'y travailler autrement.","question":"Quelle démarche est décrite ?","explanation":"Le passage indique : « Un village transforme un ancien bâtiment agricole en atelier partagé. Il conserve la charpente, mais adapte l'accès aux normes actuelles. La conservation ne signifie pas l'absence de modification. » Cela justifie la réponse : Préserver tout en adaptant à un nouvel usage."},{"number":23,"points":21,"correct":"B","options":["Une disparition des responsabilités","Une coordination entre producteurs","L'arrêt de toute production","L'obligation de vendre les mêmes produits"],"passage":"Des agriculteurs proposent une vente collective. Chacun gagne du temps de commercialisation, mais doit accepter des règles communes de présence et de présentation des produits. Les produits de chacun sont identifiés et les ventes suivies dans un document partagé. Les décisions importantes seront discutées avant d'être appliquées. Les agriculteurs veulent que la boutique reste compatible avec leurs périodes de travail sur les terres. Ils devront parfois échanger une permanence ou réduire une présence annoncée.","question":"Quelle contrepartie accompagne le gain de temps ?","explanation":"Le passage indique : « Des agriculteurs proposent une vente collective. Chacun gagne du temps de commercialisation, mais doit accepter des règles communes de présence et de présentation des produits. » Cela justifie la réponse : Une coordination entre producteurs."},{"number":24,"points":21,"correct":"D","options":["Remplacer les fermes par des cartes postales","Ignorer toute intervention humaine","Évaluer uniquement les couleurs","Comprendre les activités qui le façonnent"],"passage":"Un parcours explique les paysages avec les témoignages de travailleurs agricoles. Les champs sont présentés comme des espaces de production et de décisions, pas seulement comme un décor. Les témoins racontent les rythmes de l'année et les raisons de certaines transformations visibles depuis le chemin. Les visiteurs pourront comparer ces récits avec des cartes. Les organisateurs ne demandent pas aux habitants de présenter une campagne idéale ni de justifier chaque choix devant le public.","question":"Quelle lecture du paysage est proposée ?","explanation":"Le passage indique : « Un parcours explique les paysages avec les témoignages de travailleurs agricoles. Les champs sont présentés comme des espaces de production et de décisions, pas seulement comme un décor. » Cela justifie la réponse : Comprendre les activités qui le façonnent."},{"number":25,"points":21,"correct":"D","options":["Parce que les volumes récoltés déterminent exclusivement l'emplacement des futurs bureaux.","Parce que l'agrandissement est rentable dès que les entrepôts sont vides hors saison.","Parce que des périodes de pointe prouvent que le partage des locaux est impossible en toute circonstance.","Parce qu'une capacité inutilisée sur l'année peut masquer des pointes simultanées où aucun espace n'est disponible."],"passage":"Une coopérative hésite entre agrandir son entrepôt et mieux partager les capacités existantes. Elle réalise d'abord un état des lieux des périodes d'utilisation avant d'investir. Le groupe relève les volumes, les moments de pointe et les marges disponibles dans les bâtiments voisins. Certains espaces semblent vides une partie de l'année, mais leur usage reste important pendant une courte période. La coopérative veut donc regarder l'ensemble du calendrier avant de conclure à une capacité inutile ou insuffisante. Le relevé montre que deux entrepôts ont chacun 30 % de places libres en moyenne, mais qu'ils atteignent leur capacité maximale pendant les mêmes trois semaines de récolte. La coopérative examine si les volumes peuvent être décalés avant de conclure que ces places suffisent.","question":"Pourquoi un taux moyen d'occupation ne permet-il pas à lui seul de décider l'investissement ?","explanation":"Les pics coïncident malgré la vacance moyenne, donc D. C/B/A surinterprètent ou changent de sujet."},{"number":26,"points":21,"correct":"A","options":["Une organisation des soins et des relais doit prolonger l'enthousiasme et les gestes initiaux.","Les tâches d'entretien peuvent être fixées sans tenir compte des absences prévues.","La présence d'un premier jardinier suffira dès lors que les plants ont survécu à leur première saison.","Le nombre de fruits récoltés l'année de plantation permet d'éviter toute répartition ultérieure des tâches."],"passage":"Des habitants veulent planter des arbres fruitiers communs. L'association prévoit aussi qui taillera, arrosera et récoltera. La plantation n'est que le début de l'engagement. Les habitants préparent un calendrier et identifient les personnes pouvant transmettre les gestes nécessaires aux nouveaux participants. Des périodes d'absence doivent aussi être prévues. Le projet ne veut pas dépendre d'un seul jardinier enthousiaste qui s'occuperait de tout sans relais. Les décisions porteront donc sur les plantations et sur les conditions qui permettront de les garder en bon état. Les premières plantations ont bien repris, mais les arbres taillés par une seule personne ont été négligés durant ses vacances. Le groupe répartit désormais les savoir-faire et les remplacements dans un calendrier accessible.","question":"Quelle condition distingue la réussite initiale d'une plantation de sa pérennité ?","explanation":"La plantation n'est qu'un début; les relais et l'entretien assurent la durée. A. Les autres ignorent les absences et soins."},{"number":27,"points":21,"correct":"D","options":["Elle signifie que les photographies d'autres saisons ne concernent pas le même fonctionnement.","Elle suffit à mesurer la totalité des espèces présentes si la visite est assez longue.","Elle prouve que le site ne participe plus à aucun cycle écologique pendant le reste de l'année.","Elle donne un état ponctuel qui ne permet pas de juger les fonctions saisonnières de la zone."],"passage":"Une zone humide est parfois vide d'eau en été. Des visiteurs la jugent inutile, mais les gestionnaires expliquent que ses cycles saisonniers font partie de son fonctionnement. Les gestionnaires montreront des photographies prises à différents moments et expliqueront les espèces qui utilisent le lieu. Certaines fonctions sont moins faciles à observer pendant une visite courte. Le programme souhaite donner ces repères sans prétendre qu'un état unique serait le bon toute l'année. En été sec, certaines plantes ont disparu en surface; les observations de printemps montrent pourtant que la zone retient temporairement l'eau et accueille d'autres espèces. Le guide demande d'interpréter le lieu sur plusieurs saisons.","question":"Pourquoi l'observation d'une parcelle sèche en août serait-elle insuffisante ?","explanation":"La zone a des fonctions variables dans l'année. D. C/B/A extrapolent depuis un instant unique."},{"number":28,"points":21,"correct":"B","options":["Écarter toute production rentable pour éliminer définitivement les incertitudes de vente.","Répartir l'exposition économique entre plusieurs activités malgré un coût initial d'adaptation.","Maximiser le rendement immédiat des nouvelles cultures avant d'évaluer leurs débouchés.","Remplacer une dépendance à un acheteur par une dépendance encore plus forte à un seul marché."],"passage":"Un agriculteur réduit une culture très rentable pour diversifier ses productions. Il accepte un gain immédiat moins élevé afin de moins dépendre d'un seul débouché. Il étudie d'autres ventes possibles et réserve du temps pour apprendre les nouvelles cultures. Cette évolution comporte elle aussi des difficultés, qu'il ne veut pas cacher dans son bilan. L'exploitant cherche une organisation moins fragile lorsqu'un prix baisse ou qu'un acheteur se retire. Le prix de sa culture principale avait fortement chuté alors que les deux autres débouchés restaient stables. L'agriculteur accepte les coûts d'apprentissage de nouvelles cultures pour diminuer la part de revenu liée à ce seul marché.","question":"Quel raisonnement justifie l'abandon d'une part de rentabilité à court terme ?","explanation":"La diversification sert à réduire le risque de concentration. B. C/D/A contredisent la logique ou promettent une sécurité absolue."},{"number":29,"points":21,"correct":"D","options":["Une succession d'activités nouvelles indépendantes des traditions déjà pratiquées dans le village.","Un calendrier nouveau qui efface les activités héritées pour faciliter l'arrivée de bénévoles.","Une fête réservée aux personnes connaissant les usages, avec une consultation organisée après l'événement.","Une tradition maintenue mais ouverte à la contribution des nouveaux habitants."],"passage":"Une fête de village donne une place aux nouveaux habitants dans son organisation. Les traditions restent présentes, mais des activités supplémentaires sont proposées après discussion. Les nouveaux bénévoles peuvent participer aux réunions et proposer un rôle correspondant à leurs disponibilités. Les organisateurs souhaitent transmettre les habitudes sans demander de les connaître toutes avant de venir. Le programme final garde des repères familiers et introduit quelques essais. Une activité ancienne est maintenue, mais le parcours de la fête est modifié à la suggestion de nouveaux arrivants pour inclure des habitants jusque-là peu présents. Les anciens bénévoles expliquent les repères historiques sans imposer de les connaître.","question":"Quelle forme de continuité le nouveau programme cherche-t-il à construire ?","explanation":"Le projet maintient des éléments et accepte des modifications discutées. D. B/C/A suppriment cette articulation."},{"number":30,"points":26,"correct":"C","options":["Parce que toutes les campagnes sont désormais définies principalement par leur distance à la ville.","Parce que le monde rural ne subit plus aucun changement depuis l'arrivée des nouveaux métiers.","Parce que services et relations urbaines créent des besoins différents selon les villages.","Parce que la présence d'agriculture empêche d'analyser les autres formes d'activité."],"passage":"L'image d'une campagne immobile masque les transformations des métiers, des techniques et des relations entre habitants. Un chercheur observe ces changements sans en déduire que tous les villages suivent la même trajectoire. La ruralité ne décrit pas une situation unique. Il compare notamment l'accès aux services, les activités et les relations avec les villes proches. Ces éléments aident à comprendre pourquoi une mesure utile dans un village ne produit pas automatiquement le même effet dans tous les autres. Deux villages voisins connaissent des trajectoires opposées: l'un accueille des télétravailleurs grâce au train, l'autre perd une ligne de bus et des services. Une aide identique ne leur donnerait pas les mêmes possibilités.","question":"Pourquoi le chercheur refuse-t-il une mesure rurale universelle ?","explanation":"Les territoires connaissent des changements non uniformes. C; B/A/D simplifient précisément ce que l'enquête distingue."},{"number":31,"points":26,"correct":"C","options":["Elle pénalise les sites qui photographient davantage les opérations de plantation.","Elle tient trop compte du besoin d'arrosage et pas assez du nombre de personnes présentes.","Elle confond l'action initiale financée avec la persistance réelle de ses résultats au fil des saisons.","Elle suppose que des pertes constatées deux ans plus tard prouvent la mauvaise qualité de chaque plant."],"passage":"Une aide agricole dépend du nombre d'arbres plantés. Certains bénéficiaires demandent qu'un suivi de leur survie soit également financé. Compter les plantations sans regarder leur avenir risque de récompenser un geste ponctuel plutôt qu'un effet durable sur le paysage. Elles demandent des moyens pour agir après la photographie du jour de plantation, lorsque la réussite dépend encore de gestes moins visibles mais réguliers. Sur cent jeunes arbres photographiés le jour de la plantation, soixante restent vivants deux ans après dans une commune et quatre-vingt-dix dans l'autre. Le nombre initial identique ne mesure pas l'effet durable recherché.","question":"Quelle limite présente une aide indexée seulement sur le nombre d'arbres mis en terre ?","explanation":"La survie diffère malgré des plantations identiques. C distingue activité et effet; les autres attribuent des causes non établies."},{"number":32,"points":26,"correct":"A","options":["L'origine effective des produits et l'organisation de leur acheminement, indépendamment du nombre d'intermédiaires.","La durée de la relation commerciale, qui garantit l'absence de transports entre régions.","Le nombre de clients de chaque producteur, qui permet de calculer automatiquement la distance des livraisons.","La proportion de ventes faites sans intermédiaire, qui prouve à elle seule la proximité géographique."],"passage":"Un circuit court réduit le nombre d'intermédiaires, mais ne dit pas à lui seul quelle distance parcourt le produit. Un achat direct très éloigné peut demander davantage de transport qu'un produit distribué localement par plusieurs acteurs. Les consommateurs peuvent donc demander où le produit a été fabriqué et comment il est acheminé. Une information claire permettra de comparer les offres sans attribuer à un seul terme des garanties qu'il ne donne pas forcément. Un producteur livre directement ses paniers à 300 kilomètres, tandis qu'un grossiste distribue des pommes provenant de fermes à 20 kilomètres. Le nombre d'acteurs et la distance évoluent donc séparément.","question":"Quel indicateur faudrait-il ajouter à la mention « circuit court » pour comparer les deux offres ?","explanation":"Le circuit court décrit les intermédiaires, non le kilométrage. A demande les données pertinentes; D/C/B produisent des équivalences fausses."},{"number":33,"points":26,"correct":"B","options":["Ils conservent toujours la mesure numérique, les signes du terrain étant purement subjectifs.","Ils confrontent les conditions de mesure aux observations faites sur le terrain.","Ils suivent l'observation traditionnelle sans examiner la profondeur à laquelle la sonde mesure.","Ils additionnent mécaniquement les deux indications, même si elles concernent des lieux distincts."],"passage":"Des pratiques agricoles se transmettent par l'observation de signes locaux : état du sol, végétation, humidité. Un nouvel outil apporte d'autres données. Les utilisateurs les plus expérimentés ne choisissent pas forcément entre les deux ; ils cherchent comment les confronter utilement. Les producteurs discutent les cas où les deux sources se complètent et ceux où elles semblent se contredire. Une sonde indique un sol encore humide, mais un agriculteur observe une croûte superficielle sur une parcelle voisine. Le groupe vérifie la profondeur et la localisation des mesures avant de choisir l'arrosage.","question":"Comment les producteurs traitent-ils des indications apparemment divergentes ?","explanation":"Le croisement exige de comprendre contexte et limites des sources. B; les autres privilégient ou combinent les indications sans contrôle."},{"number":34,"points":26,"correct":"B","options":["Un déplacement de toutes les exploitations pour garantir aux promeneurs des voies sans véhicules.","Une cohabitation organisée selon les périodes et les contraintes des usages déjà présents.","Une promenade accessible en toutes circonstances, même lorsqu'elle empêche les travaux agricoles nécessaires.","Une priorité systématique aux engins quel que soit l'horaire, sans information donnée aux visiteurs."],"passage":"Une commune aménage des chemins pour les visiteurs, mais les engins agricoles doivent continuer à circuler. Les règles élaborées avec les usagers tiennent compte des périodes de travail. Ouvrir un espace ne signifie pas effacer les activités qui y existaient déjà. Le projet veut rendre les rencontres possibles tout en expliquant pourquoi certaines contraintes ne peuvent pas être décidées uniquement selon le confort des visiteurs. La promenade est très fréquentée en juillet, période où les engins ont aussi besoin d'un passage large pour la récolte. Le comité propose des horaires de circulation affichés plutôt qu'un accès permanent privilégiant une seule activité.","question":"Quel arbitrage les règles d'accès cherchent-elles à rendre possible ?","explanation":"Le partage doit tenir compte des périodes agricoles et des visiteurs. B. C/D/A excluent une partie des usages."},{"number":35,"points":26,"correct":"A","options":["Elle relie les gestes observés aux décisions et aux contraintes qui expliquent la production réelle.","Elle permet aux élèves de comparer les méthodes de travail sans examiner leurs effets sur la production.","Elle rend les visites plus authentiques en montrant exclusivement les imprévus au lieu des pratiques ordinaires.","Elle confirme que les gestes observés ont des conséquences constantes indépendamment des conditions de travail."],"passage":"Des fermes accueillent des classes pour montrer la production alimentaire. Les visites les plus riches ne se limitent pas à une démonstration agréable : elles expliquent aussi les choix difficiles et les incertitudes du métier. Comprendre une activité demande parfois de dépasser son image rassurante. Les responsables souhaitent qu'ils comprennent les liens entre une décision et ses conséquences, au lieu de repartir avec une image agréable mais incomplète d'une journée de travail. Une classe assiste à la traite puis découvre pourquoi la ferme adapte ses pratiques en période de sécheresse. Les élèves posent des questions sur les choix et leurs conséquences au lieu de ne retenir que la démonstration.","question":"Pourquoi la présentation des difficultés professionnelles approfondit-elle la visite ?","explanation":"A relie gestes, choix et contraintes. B sépare artificiellement décisions et conséquences; C remplace une présentation partielle par une autre; D efface les aléas que l'équipe veut faire comprendre."},{"number":36,"points":33,"correct":"A","options":["Préserver des qualités paysagères tout en adaptant certains usages du territoire.","La conservation des formes bâties est prioritaire lorsque les usages anciens restent économiquement viables.","Les adaptations contemporaines doivent être déterminées surtout par les besoins immédiats sans relever les traces du passé.","Une rénovation préserve l'aspect d'un lieu seulement si son usage actuel demeure identique à l'ancien."],"passage":"Un projet propose de protéger un paysage en interdisant toute transformation. Les habitants rappellent que ce paysage résulte lui-même de pratiques successives. Ils souhaitent préserver des qualités sans figer les conditions de vie. La conservation d'un territoire habité doit composer avec les besoins de ceux qui continuent à le faire vivre. Certains bâtiments nécessitent de nouvelles fonctions pour rester entretenus, et les exploitants doivent parfois changer leur organisation. Les habitants souhaitent distinguer ces besoins de transformations qui effaceraient sans raison les qualités du lieu. La discussion devra donc examiner des cas concrets et leurs effets. Une règle générale apparemment protectrice peut devenir difficile à vivre si elle traite toute modification comme une dégradation. Les responsables du projet proposent des visites communes pour comprendre les usages présents, les héritages à maintenir et les possibilités d'adaptation compatibles avec la vie du village. Une ancienne grange, remarquable dans le paysage, risque de tomber en ruine sans nouvelle utilisation. Les habitants proposent de conserver son volume extérieur tout en y installant une activité compatible avec les besoins actuels.","question":"Quelle conception de la protection patrimoniale sous-tend cette proposition ?","explanation":"A propose de conserver des qualités tout en adaptant certains usages. B subordonne la préservation à la rentabilité, ce que le cas n'énonce pas; C néglige le patrimoine; D impose un maintien des fonctions refusé par le projet."},{"number":37,"points":33,"correct":"D","options":["Il remplacerait une mesure de production par une mesure de surface, sans inclure les services rendus au territoire.","Il donnerait une image des revenus agricoles mais laisserait inconnues les quantités réellement commercialisées.","Il montrerait une différence de rendement que la contribution des haies suffirait à annuler.","Il négligerait des contributions environnementales et collectives qui ne se reflètent pas directement dans le rendement."],"passage":"Une exploitation est souvent évaluée par son rendement sur une seule culture. Pourtant, elle entretient aussi des haies, partage du matériel et contribue à l'emploi local. Ces fonctions ne justifient pas d'ignorer le rendement, mais elles élargissent les questions à poser. Une performance devient différente selon les dimensions que l'on accepte de compter. Les responsables souhaitent notamment rendre visibles des tâches qui n'apparaissent pas directement dans les volumes vendus. Les comparaisons devront donc préciser ce qu'elles retiennent et les limites du résultat. Une ferme peut présenter des forces et des difficultés différentes selon le domaine observé. Le bilan devient plus utile lorsqu'il aide à discuter ces écarts, plutôt que lorsqu'il transforme un seul chiffre en classement complet de toutes les activités et de leurs effets sur le territoire. Une ferme vend moins de tonnes que sa voisine mais entretient des haies et partage des équipements avec plusieurs exploitations. Le bilan sépare donc production, contribution environnementale et services au territoire.","question":"Pourquoi un classement fondé sur le seul volume vendu serait-il incomplet ?","explanation":"D indique les fonctions écologiques et collectives absentes du seul volume vendu. A reste un indicateur partiel; B confond tonnes et revenus; C suppose une compensation non chiffrée."},{"number":38,"points":33,"correct":"D","options":["Les tâches de distribution deviennent secondaires lorsque les clients passent directement leurs commandes au producteur.","Le lien direct devient plus rentable quand les fonctions commerciales sont confiées exclusivement à chaque exploitation.","Le nombre d'intermédiaires révèle mieux la charge de travail que le temps consacré aux commandes et aux retraits.","Les fonctions demeurent et doivent être assumées ou réparties, même si le circuit commercial change."],"passage":"La vente directe est parfois présentée comme une relation spontanée entre producteur et consommateur. Elle demande pourtant du temps pour accueillir, expliquer et organiser les commandes. Un producteur peut bien cultiver sans souhaiter assurer seul cette activité supplémentaire. Réduire les intermédiaires ne fait pas disparaître les fonctions qu'ils prenaient en charge. Les clients doivent pouvoir connaître les horaires, réserver, obtenir une réponse et récupérer leur commande dans de bonnes conditions. Ces tâches peuvent être partagées ou confiées à un partenaire sans effacer le lien recherché avec les producteurs. Le débat ne porte donc pas seulement sur le nombre d'acteurs entre le champ et le panier. Il concerne aussi la manière dont le travail est réparti et reconnu. Les exploitants souhaitent comparer les solutions avec leur charge réelle, afin qu'une formule présentée comme plus simple pour l'acheteur ne rende pas leur propre activité plus difficile à maintenir. Un producteur augmente ses ventes directes mais passe chaque semaine davantage d'heures à répondre aux messages et à coordonner les retraits. Une solution collective lui permettrait de déléguer ces tâches sans ajouter un intermédiaire inutile au sens du projet.","question":"Que signifie la réduction du nombre d'intermédiaires pour l'organisation du travail ?","explanation":"D rappelle que la suppression d'intermédiaires n'efface pas les fonctions commerciales. A minimise les tâches, B impose leur prise en charge individuelle, C confond structure du circuit et charge effective."},{"number":39,"points":33,"correct":"B","options":["La progression du nombre total de ménages atteste que l'objectif de maintien est atteint, même si les parcours résidentiels individuels ne sont pas suivis.","Le léger gain global doit être rapproché des départs de familles installées et des difficultés de logement, sans prétendre attribuer chaque départ au programme.","Les recettes accrues des commerces suffisent à mesurer la capacité des ménages antérieurs à rester, puisque l'activité locale leur bénéficie indirectement.","La hausse des trajets domicile-travail démontre que toutes les familles parties ont quitté le village uniquement en raison des nouveaux loyers."],"passage":"Un village développe son attractivité pour retenir des habitants. Des services nouveaux apparaissent, mais le prix des logements augmente. Les familles que le projet voulait initialement maintenir peuvent alors rencontrer davantage de difficultés. L'attractivité n'est pas automatiquement synonyme d'accessibilité pour les habitants déjà présents. Les élus doivent donc suivre les coûts du logement en même temps que les arrivées et les recettes nouvelles. Les habitants demandent des possibilités de rester près de leur travail et de leurs proches. Plusieurs solutions seront étudiées, dont des logements accessibles et un maintien de certains services ordinaires. Le programme ne sera pas jugé uniquement à partir d'une image plus attractive ou d'une hausse des visites. Il faudra aussi regarder qui peut encore vivre sur place et dans quelles conditions, afin de comprendre à qui profite réellement le changement annoncé pour l'ensemble du village. Le nouveau café attire des visiteurs et des ménages aisés, mais une famille du village doit quitter son logement après une forte hausse de loyer. Le conseil suit désormais les prix et les départs autant que l'ouverture de services. Pour dresser son bilan, le conseil distingue désormais les nouvelles inscriptions à l'école, les départs de familles déjà installées et les changements de propriétaires. Sur deux ans, le nombre total de ménages augmente légèrement, mais six familles présentes avant le programme sont parties après une hausse de loyer. Trois logements quittés sont occupés par de nouveaux ménages. Le café et les commerces ont gagné des clients, tandis que les salariés aux revenus modestes parcourent en moyenne davantage de kilomètres pour rejoindre leur emploi dans le village. Les élus notent que les dossiers de départ ne permettent pas tous de prouver que le loyer est l'unique motif; certains mentionnent aussi des mutations professionnelles. Le tableau présenté au public sépare donc le solde global de population, la stabilité des habitants antérieurs et les conditions de logement. Les promoteurs du projet souhaitent publier seulement la progression du nombre de ménages, que les associations locales jugent insuffisante.","question":"Quel bilan permet d'apprécier le maintien des habitants sans confondre hausse globale et stabilité des résidents antérieurs ?","explanation":"B met en regard le solde légèrement positif avec les départs de six familles antérieures, les loyers et l'éloignement des salariés, tout en respectant la pluralité des motifs de départ mentionnés dans les dossiers. A confond nombre total et maintien de la population initiale; C infère une capacité résidentielle à partir des recettes commerciales; D transforme un indicateur collectif et des motifs multiples en cause exclusive pour tous les départs."}]}$paper_12$::jsonb),
('tcf-reading-13','tcf-reading-2026-11-close-reading-v4',$paper_13${"id":"tcf-reading-13","title":"TCF Reading · Test 13","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"A","options":["L'impression à l'accueil","L'accès à tous les ordinateurs","Le cours dans la salle fermée","Le prêt d'une imprimante personnelle"],"passage":"La salle informatique sera fermée pour mise à jour mardi matin. L'accueil pourra toujours imprimer vos documents.\n\nLes agents retrouveront le service habituel après les vérifications. Merci de ne pas essayer d'entrer dans la salle pendant l'intervention.","question":"Quel service sera maintenu ?","explanation":"Le passage indique : « La salle informatique sera fermée pour mise à jour mardi matin. L'accueil pourra toujours imprimer vos documents. » Cela justifie la réponse : L'impression à l'accueil."},{"number":2,"points":3,"correct":"B","options":["Publier ses identifiants","Joindre l'assistance par son canal connu","Donner son mot de passe","Rappeler le numéro fourni sans vérification"],"passage":"Votre mot de passe ne vous sera jamais demandé par téléphone. En cas d'appel suspect, contactez directement l'assistance habituelle.\n\nLe numéro figure sur vos documents de service.","question":"Que faut-il faire après un appel suspect ?","explanation":"Le passage indique : « Votre mot de passe ne vous sera jamais demandé par téléphone. En cas d'appel suspect, contactez directement l'assistance habituelle. » Cela justifie la réponse : Joindre l'assistance par son canal connu."},{"number":3,"points":3,"correct":"C","options":["Supprimer la batterie","Acheter un nouveau téléphone","Recharger l'appareil","Imprimer toutes les photos"],"passage":"L'atelier photo accepte les téléphones anciens. Chargez votre batterie avant de venir ; les prises disponibles sont limitées.\n\nLes participants pourront venir avec un modèle qu'ils utilisent déjà au quotidien, sans devoir en acheter un autre.","question":"Quelle préparation est demandée ?","explanation":"Le passage indique : « L'atelier photo accepte les téléphones anciens. Chargez votre batterie avant de venir ; les prises disponibles sont limitées. » Cela justifie la réponse : Recharger l'appareil."},{"number":4,"points":3,"correct":"A","options":["Envoyer","Enregistrer provisoirement","Agrandir le texte","Fermer la fenêtre"],"passage":"Le formulaire peut être enregistré puis repris plus tard. Le bouton « Envoyer » termine la démarche.\n\nUn message confirme ensuite la réception. Avant cette dernière étape, vous pouvez encore relire et corriger les informations saisies dans votre dossier personnel.","question":"Quel bouton finalise le dossier ?","explanation":"Le passage indique : « Le formulaire peut être enregistré puis repris plus tard. Le bouton « Envoyer » termine la démarche. » Cela justifie la réponse : Envoyer."},{"number":5,"points":9,"correct":"D","options":["Empêcher toute modification","Réduire le nombre de participants","Remplacer les fichiers par des appels","Limiter la confusion entre les versions"],"passage":"Je t'enverrai les fichiers par le dossier partagé. Évite les pièces jointes : nous risquerions de travailler sur des versions différentes.\n\nJ'ai préparé des noms de documents simples pour retrouver rapidement le travail de chacun. Nous pourrons discuter des modifications dans la note commune sans multiplier les copies.","question":"Pourquoi utiliser un dossier commun ?","explanation":"Le passage indique : « Je t'enverrai les fichiers par le dossier partagé. Évite les pièces jointes : nous risquerions de travailler sur des versions différentes. » Cela justifie la réponse : Limiter la confusion entre les versions."},{"number":6,"points":9,"correct":"B","options":["Le partage de tous les mots de passe","La non-conservation des codes par l'accompagnateur","L'envoi des codes aux autres participants","La publication des comptes créés"],"passage":"La permanence numérique accompagne les démarches, mais ne conserve pas vos codes. Vous devrez les saisir vous-même.\n\nLe bénévole peut expliquer où trouver une information, mais les données restent sous votre responsabilité. Merci de fermer votre session après la démarche.","question":"Quelle règle protège l'utilisateur ?","explanation":"Le passage indique : « La permanence numérique accompagne les démarches, mais ne conserve pas vos codes. Vous devrez les saisir vous-même. » Cela justifie la réponse : La non-conservation des codes par l'accompagnateur."},{"number":7,"points":9,"correct":"B","options":["Abandonner tout appel","Prolonger l'usage du téléphone","Vendre la batterie neuve","Acheter immédiatement un modèle récent"],"passage":"Mon téléphone fonctionne encore. Je préfère changer sa batterie plutôt que remplacer tout l'appareil.\n\nLe réparateur a vérifié que cette intervention est possible sur mon modèle. Je conserverai aussi mes photos avant de lui laisser l'appareil, par précaution. Je demanderai aussi combien de temps cela prendra.","question":"Quelle décision est prise ?","explanation":"Le passage indique : « Mon téléphone fonctionne encore. Je préfère changer sa batterie plutôt que remplacer tout l'appareil. » Cela justifie la réponse : Prolonger l'usage du téléphone."},{"number":8,"points":9,"correct":"D","options":["Un nouvel ordinateur gratuit","Un examen en salle obligatoire","Une vidéo sans son uniquement","Un texte de la séance"],"passage":"Pour suivre le cours à distance, un casque est conseillé, pas obligatoire. Une transcription écrite sera disponible après la séance.\n\nLes personnes souhaitant revoir un passage pourront le retrouver après la rencontre.","question":"Quel autre support est prévu ?","explanation":"Le passage indique : « Pour suivre le cours à distance, un casque est conseillé, pas obligatoire. Une transcription écrite sera disponible après la séance. » Cela justifie la réponse : Un texte de la séance."},{"number":9,"points":9,"correct":"B","options":["Travailler uniquement la nuit","Mieux maîtriser les interruptions","Supprimer définitivement sa messagerie","Empêcher tous ses proches d'écrire"],"passage":"J'ai désactivé les notifications pendant mes révisions. Je regarderai les messages à des moments choisis.\n\nJe répondrai aux demandes importantes après ma séance de travail. Si une urgence se présente, mes proches savent comment me joindre autrement que par une succession de notifications.","question":"Quel objectif poursuit cette personne ?","explanation":"Le passage indique : « J'ai désactivé les notifications pendant mes révisions. Je regarderai les messages à des moments choisis. » Cela justifie la réponse : Mieux maîtriser les interruptions."},{"number":10,"points":9,"correct":"B","options":["Un appareil acheté neuf","La tablette et son chargeur","Uniquement la housse","Un abonnement téléphonique"],"passage":"Le club prête des tablettes pour le week-end. Elles doivent être rapportées lundi avec leur chargeur.\n\nUne fiche indiquera les précautions et les accessoires remis au départ. Les emprunteurs devront signaler un problème avant de repartir avec le matériel pour un nouveau prêt.","question":"Que faut-il restituer ?","explanation":"Le passage indique : « Le club prête des tablettes pour le week-end. Elles doivent être rapportées lundi avec leur chargeur. » Cela justifie la réponse : La tablette et son chargeur."},{"number":11,"points":15,"correct":"D","options":["Acheter du stockage supplémentaire","Effacer tous les dossiers","Créer des programmes complexes","Acquérir un repère de base"],"passage":"Une association propose une initiation au rangement des fichiers. Les participants apprennent d'abord à retrouver un document avant d'utiliser des fonctions plus avancées.\n\nLe formateur utilise des exemples courants et laisse les personnes choisir un classement qu'elles comprennent. Il montre aussi comment éviter des noms trop semblables et comment reconnaître plusieurs versions d'un même fichier. Les participants essaient ensuite de retrouver un document après avoir fermé le dossier. L'objectif est de vérifier qu'ils possèdent un repère utilisable seuls, pas seulement qu'ils réussissent à suivre une démonstration. Les questions permettront de préparer les séances suivantes selon les usages réellement rencontrés dans leur quotidien personnel ou professionnel.","question":"Quelle priorité est donnée ?","explanation":"Le passage indique : « Une association propose une initiation au rangement des fichiers. Les participants apprennent d'abord à retrouver un document avant d'utiliser des fonctions plus avancées. » Cela justifie la réponse : Acquérir un repère de base."},{"number":12,"points":15,"correct":"A","options":["Si l'accès demandé correspond au service","Si tous les contacts utilisent l'application","Si le logo est suffisamment coloré","Si le téléphone est assez grand"],"passage":"Une application demande l'accès aux contacts pour afficher la météo. Une animatrice explique que cette autorisation n'est pas nécessaire à la fonction annoncée.\n\nLes participants comparent plusieurs exemples pour éviter de penser qu'une application doit toujours recevoir tous les accès proposés. Le but n'est pas de refuser automatiquement chaque service, mais de comprendre la relation entre une fonction et les informations demandées.","question":"Quelle question faut-il se poser ?","explanation":"Le passage indique : « Une application demande l'accès aux contacts pour afficher la météo. Une animatrice explique que cette autorisation n'est pas nécessaire à la fonction annoncée. » Cela justifie la réponse : Si l'accès demandé correspond au service."},{"number":13,"points":15,"correct":"A","options":["Maintenir plusieurs voies d'accès au service","Supprimer les formulaires","Réserver les appels aux informaticiens","Obliger chacun à acheter un ordinateur"],"passage":"Un service municipal conserve un accueil téléphonique en parallèle du portail en ligne. Il ne souhaite pas que l'absence d'équipement empêche une démarche.\n\nLes usagers peuvent consulter les mêmes informations essentielles quel que soit le canal choisi. Le personnel est formé pour expliquer les différences de procédure sans renvoyer systématiquement les personnes vers un ordinateur. Le service souhaite conserver la simplicité du portail pour ceux qui l'utilisent, tout en regardant ce qui reste possible pour les autres. Les responsables suivront les temps d'attente, car une alternative annoncée mais difficile à joindre ne constitue pas nécessairement un accès réel.","question":"Quel objectif est poursuivi ?","explanation":"Le passage indique : « Un service municipal conserve un accueil téléphonique en parallèle du portail en ligne. Il ne souhaite pas que l'absence d'équipement empêche une démarche. » Cela justifie la réponse : Maintenir plusieurs voies d'accès au service."},{"number":14,"points":15,"correct":"D","options":["Rendre les photos publiques","Augmenter automatiquement la qualité des images","Supprimer le besoin de classement","Limiter les conséquences de la perte de l'appareil"],"passage":"Un atelier montre comment sauvegarder ses photos sur un second support. Une copie située seulement sur le téléphone disparaîtrait avec lui en cas de perte.\n\nLes animateurs distinguent une sauvegarde et une simple copie restée dans le même appareil. Les participants apprennent aussi à vérifier qu'ils peuvent ouvrir les documents sur le second support. Le cours ne promet pas qu'une opération unique protégera définitivement tous les fichiers. Il propose une organisation régulière, adaptée au volume et à l'importance des données. Chacun prépare un premier essai avec des images fictives avant de choisir ses propres documents.","question":"À quoi sert la seconde copie ?","explanation":"Le passage indique : « Un atelier montre comment sauvegarder ses photos sur un second support. Une copie située seulement sur le téléphone disparaîtrait avec lui en cas de perte. » Cela justifie la réponse : Limiter les conséquences de la perte de l'appareil."},{"number":15,"points":15,"correct":"C","options":["Le nombre de fenêtres de la salle","Le prix du papier","Le rythme de l'interaction","La couleur du bâtiment"],"passage":"Des habitants testent une nouvelle borne. Ils signalent que les boutons sont lisibles mais que le temps laissé pour répondre est trop court.\n\nCertains habitants ont besoin de relire une consigne ou d'obtenir une explication avant d'appuyer. Les concepteurs avaient surtout testé la borne avec des personnes connaissant déjà les démarches. Ils vont donc revoir le délai et permettre de demander plus de temps. Les essais suivants comprendront des profils différents. L'équipe souhaite distinguer une difficulté liée au contenu et une difficulté produite par le rythme imposé à l'écran.","question":"Quel aspect doit être amélioré ?","explanation":"Le passage indique : « Des habitants testent une nouvelle borne. Ils signalent que les boutons sont lisibles mais que le temps laissé pour répondre est trop court. » Cela justifie la réponse : Le rythme de l'interaction."},{"number":16,"points":15,"correct":"C","options":["Le livre reste acquis pour toujours","L'emprunteur doit imprimer chaque page","Le droit de lecture est temporaire","Le prêt n'a aucune durée"],"passage":"Une bibliothèque prête des livres numériques. Le prêt s'arrête automatiquement à la date prévue ; le document ne devient pas un achat définitif.\n\nLa bibliothèque explique les possibilités de renouvellement et les conditions de téléchargement. Les lecteurs peuvent demander une démonstration s'ils découvrent le service. Les fichiers empruntés ne doivent pas être confondus avec ceux qu'ils ont achetés ailleurs. Les responsables souhaitent que chacun comprenne les droits annoncés avant de commencer un livre, notamment pendant un voyage.","question":"Quelle distinction est précisée ?","explanation":"Le passage indique : « Une bibliothèque prête des livres numériques. Le prêt s'arrête automatiquement à la date prévue ; le document ne devient pas un achat définitif. » Cela justifie la réponse : Le droit de lecture est temporaire."},{"number":17,"points":15,"correct":"C","options":["La couleur du câble","Le nombre de publicités","La possibilité de changer d'outil plus tard","La taille du logo"],"passage":"Une équipe choisit un outil de messagerie après un essai commun. Elle évalue aussi la facilité de quitter le service et d'exporter les données.\n\nLes salariés comparent les formats obtenus et regardent si les conversations utiles restent compréhensibles hors de l'outil. Ils souhaitent éviter une dépendance découverte uniquement au moment du départ. Cette vérification ne signifie pas que le groupe prévoit déjà d'abandonner le service. Elle sert à conserver une marge de décision si les besoins, les tarifs ou les règles changent.","question":"Quel critère dépasse l'usage immédiat ?","explanation":"Le passage indique : « Une équipe choisit un outil de messagerie après un essai commun. Elle évalue aussi la facilité de quitter le service et d'exporter les données. » Cela justifie la réponse : La possibilité de changer d'outil plus tard."},{"number":18,"points":15,"correct":"C","options":["Faire confiance à toute copie visuelle","Télécharger tous les fichiers proposés","Vérifier l'adresse plutôt que le seul aspect","Ignorer les informations du navigateur"],"passage":"Un atelier apprend à repérer l'adresse exacte d'un site. Une page qui ressemble à un service connu peut être hébergée ailleurs.\n\nLes participants observent des exemples fictifs où un détail du nom change alors que le logo paraît familier. Ils apprennent à retrouver le service par un moyen connu plutôt qu'à suivre immédiatement un lien reçu. Le formateur souhaite ralentir le geste lorsque la demande semble inhabituelle. Il ne promet pas une méthode qui remplacerait toute vérification future.","question":"Quelle précaution est enseignée ?","explanation":"Le passage indique : « Un atelier apprend à repérer l'adresse exacte d'un site. Une page qui ressemble à un service connu peut être hébergée ailleurs. » Cela justifie la réponse : Vérifier l'adresse plutôt que le seul aspect."},{"number":19,"points":15,"correct":"D","options":["La publication est obligatoire après réception","Les familles ne peuvent jamais regarder les photos","Toute image de groupe doit être vendue","Recevoir une image ne suffit pas à autoriser sa diffusion"],"passage":"Une école demande aux familles de ne pas diffuser les images de groupe sans vérifier les autorisations. Une photo reçue ne donne pas automatiquement le droit de la publier.\n\nLes organisateurs recueilleront les choix avant le prochain événement et indiqueront quelles images peuvent être utilisées sur les supports du groupe. Les familles pourront poser une question sans devoir se justifier devant tout le monde. L'école veut éviter qu'une habitude de partage transforme un souvenir reçu en autorisation supposée générale.","question":"Quelle limite est rappelée ?","explanation":"Le passage indique : « Une école demande aux familles de ne pas diffuser les images de groupe sans vérifier les autorisations. Une photo reçue ne donne pas automatiquement le droit de la publier. » Cela justifie la réponse : Recevoir une image ne suffit pas à autoriser sa diffusion."},{"number":20,"points":21,"correct":"A","options":["Pour améliorer la conception du service","Pour supprimer automatiquement les dossiers","Pour éviter toute correction","Pour classer publiquement les usagers"],"passage":"Une administration simplifie ses formulaires numériques avec les usagers. Les erreurs fréquentes servent à identifier des consignes peu claires, et pas seulement à constater l'inattention des personnes. Les agents relisent les demandes avec des personnes connaissant peu la procédure. Ils observent où les utilisateurs hésitent et quels mots produisent des interprétations différentes. Le service souhaite garder les informations nécessaires, mais les présenter au moment où elles sont utiles. Les modifications seront testées sur de nouveaux exemples avant d'être généralisées. Un formulaire plus court ne sera pas automatiquement meilleur si les étapes supprimées empêchent encore de comprendre ce qui est demandé.","question":"Comment les erreurs sont-elles utilisées ?","explanation":"Le passage indique : « Une administration simplifie ses formulaires numériques avec les usagers. Les erreurs fréquentes servent à identifier des consignes peu claires, et pas seulement à constater l'inattention des personnes. » Cela justifie la réponse : Pour améliorer la conception du service."},{"number":21,"points":21,"correct":"D","options":["L'impossibilité d'écrire sans internet","Le manque de papier","La disparition obligatoire du fichier","La réunion de modifications concurrentes"],"passage":"Un logiciel permet de travailler sans connexion puis de synchroniser les documents. L'équipe vérifie les conflits de versions lorsque deux personnes ont modifié le même fichier hors ligne. Les documents gardent une trace des changements et les auteurs peuvent expliquer ce qu'ils souhaitaient modifier. Elle veut savoir comment réagir lorsque la réunion automatique des modifications produit un résultat ambigu. Les personnes ne seront pas invitées à considérer tout fichier final comme correct simplement parce qu'une synchronisation s'est terminée sans afficher de message d'erreur.","question":"Quel problème doit être géré ?","explanation":"Le passage indique : « Un logiciel permet de travailler sans connexion puis de synchroniser les documents. L'équipe vérifie les conflits de versions lorsque deux personnes ont modifié le même fichier hors ligne. » Cela justifie la réponse : La réunion de modifications concurrentes."},{"number":22,"points":21,"correct":"B","options":["Le classement chronologique des dates","La concentration de l'attention sur quelques avis","L'apparition de nouveaux commentaires","La possibilité de lire les avis récents"],"passage":"Une plateforme affiche les avis dans l'ordre de publication plutôt que selon leur popularité. Elle souhaite éviter que les premiers avis très appréciés occupent durablement toute la visibilité. Les lecteurs pourront toujours rechercher un ancien avis ou examiner les réponses reçues. Le changement ne garantit pas que toutes les contributions seront lues autant, mais modifie ce qui apparaît en premier. La plateforme souhaite expliquer cette règle pour que le classement ne soit pas interprété comme une mesure neutre de qualité.","question":"Quel effet cherche-t-elle à limiter ?","explanation":"Le passage indique : « Une plateforme affiche les avis dans l'ordre de publication plutôt que selon leur popularité. Elle souhaite éviter que les premiers avis très appréciés occupent durablement toute la visibilité. » Cela justifie la réponse : La concentration de l'attention sur quelques avis."},{"number":23,"points":21,"correct":"A","options":["Conserver ses documents avant de partir","Transférer les fichiers sans accord à la publicité","Interdire la suppression du compte","Rester abonné sans le savoir"],"passage":"Un service propose de supprimer un compte tout en permettant de récupérer ses documents auparavant. Cette étape évite de confondre départ du service et perte souhaitée de tous les fichiers. La procédure indique les formats disponibles et demande de vérifier les copies avant la fermeture définitive. Les utilisateurs disposent d'un délai pour poser une question. Le service souhaite que le départ reste compréhensible, sans confondre fidélisation et difficulté à récupérer son travail.","question":"Quelle possibilité est offerte ?","explanation":"Le passage indique : « Un service propose de supprimer un compte tout en permettant de récupérer ses documents auparavant. Cette étape évite de confondre départ du service et perte souhaitée de tous les fichiers. » Cela justifie la réponse : Conserver ses documents avant de partir."},{"number":24,"points":21,"correct":"B","options":["Remplacer tous les échanges par le silence","Choisir le moyen de communication selon l'usage","Éviter toute trace écrite","Imposer une caméra permanente"],"passage":"Une entreprise réduit le nombre de réunions vidéo, mais conserve des échanges audio et des notes partagées. Le but est d'adapter le support au besoin, pas d'interdire la communication à distance. Les équipes précisent ce qui demande un échange immédiat et ce qui peut être lu plus tard. Elles souhaitent éviter qu'un changement d'outil augmente simplement le nombre de messages ou d'interruptions. Le bilan regardera donc l'organisation complète du travail.","question":"Quel principe guide le changement ?","explanation":"Le passage indique : « Une entreprise réduit le nombre de réunions vidéo, mais conserve des échanges audio et des notes partagées. Le but est d'adapter le support au besoin, pas d'interdire la communication à distance. » Cela justifie la réponse : Choisir le moyen de communication selon l'usage."},{"number":25,"points":21,"correct":"B","options":["Elle établit que les comptes personnels sont inutiles pour chaque exercice avancé.","Elle permet de comprendre l'usage avant de décider quelles données transmettre.","Elle supprime définitivement le besoin d'expliquer la collecte de données du service.","Elle garantit qu'aucune information n'est recueillie lors d'une utilisation ultérieure."],"passage":"Des formateurs utilisent des exercices sans compte personnel pour les premières séances. Les apprenants peuvent découvrir les fonctions avant de transmettre des informations les concernant. Les personnes peuvent décider à partir d'une expérience concrète, plutôt que remplir immédiatement une longue série de champs. Le centre veut que la découverte d'un outil ne soit pas conditionnée à une transmission de données dont l'utilité reste encore difficile à comprendre pour un débutant. À la troisième séance, certains choisissent d'ouvrir un compte après avoir essayé l'outil; d'autres préfèrent encore un exercice anonyme. Le formateur explique quelles fonctionnalités exigent réellement des informations personnelles.","question":"Pourquoi l'inscription différée renforce-t-elle la qualité du choix de l'apprenant ?","explanation":"L'apprenant comprend avant de décider d'inscrire ses données. B. D/C/A généralisent au-delà du choix progressif."},{"number":26,"points":21,"correct":"D","options":["La présentation des critères interdit à l'utilisateur de choisir un trajet plus lent.","La destination est choisie automatiquement dès que la durée de trajet est calculée.","Le trajet recommandé devient adapté à tous les usagers lorsqu'ils connaissent les critères.","Un critère de trajet optimisé peut ignorer une contrainte personnelle décisive."],"passage":"Une application propose une recommandation automatique de trajet. Elle affiche aussi les critères retenus pour que l'utilisateur comprenne pourquoi un parcours est privilégié. L'utilisateur peut alors décider si le gain de temps annoncé correspond à sa situation. Il peut choisir un trajet différent lorsqu'un critère non retenu lui paraît plus important. Des retours permettront d'améliorer les informations et d'identifier les contraintes fréquentes que le service n'avait pas encore correctement prises en compte dans ses premières propositions. Le trajet le plus rapide proposé comporte des escaliers, alors que l'usager transporte une poussette. En lisant les critères, il comprend pourquoi cette option a été proposée et privilégie une autre route.","question":"Quelle limite l'explication des critères permet-elle de gérer ?","explanation":"Un trajet rapide peut ne pas convenir aux contraintes non intégrées. D. B/C/A décrivent des comportements absents."},{"number":27,"points":21,"correct":"D","options":["Demander aux jeunes d'abandonner toutes les pratiques en ligne avant d'apprendre à les vérifier.","Remplacer les exemples concrets par des règles générales imposées sans échange avec les participants.","Faire traiter chaque expérience comme une infraction, même lorsqu'elle sert de point de départ à une discussion.","Permettre une analyse collective des risques et des ressources d'aide à partir de situations effectivement rencontrées."],"passage":"Une médiathèque accueille des adolescents pour discuter de leurs pratiques en ligne. Les animateurs partent de situations concrètes plutôt que d'un discours présentant tous les usages comme dangereux. Les participants parlent de leurs habitudes, mais aussi des moments où ils ont besoin d'aide ou de recul. Les questions seront reprises lors d'une séance suivante avec les familles intéressées, dans un cadre respectant les choix de chacun. Un jeune explique avoir partagé une image sans vérifier son origine; les autres discutent de moyens de contrôle sans réduire la séance à la recherche d'un coupable. Les familles reçoivent ensuite des pistes adaptées.","question":"Quel bénéfice l'approche fondée sur des exemples vécus cherche-t-elle à produire ?","explanation":"Les usages sont examinés avec les jeunes et les points de soutien identifiés. D. C/A/B ferment la discussion que le programme organise."},{"number":28,"points":21,"correct":"C","options":["Les essais menés avec un lecteur d'écran rendent inutiles les vérifications auprès des autres visiteurs.","Une amélioration de l'accessibilité profite nécessairement à tous dans exactement les mêmes proportions.","Certaines modifications facilitent plusieurs parcours, sans prouver qu'elles résolvent toutes les situations d'accès.","Les difficultés spécifiques disparaissent dès que les menus sont plus explicites."],"passage":"Un site simplifie ses menus après des tests avec des lecteurs d'écran. Les améliorations facilitent aussi la navigation de nombreux autres visiteurs. Les menus deviennent plus prévisibles et les formulaires plus explicites. Certains visiteurs sans outil particulier disent aussi trouver plus rapidement la bonne page. Elle observe leurs effets sur des parcours variés, tout en continuant à vérifier les besoins spécifiques qui ne seraient pas résolus par une modification générale de la présentation. Des essais montrent que les intitulés de boutons devenus plus explicites aident un utilisateur de lecteur d'écran et une personne sans handicap qui découvre le site. Les besoins plus spécifiques font toutefois l'objet de tests distincts.","question":"Quelle conclusion est justifiée par ces deux observations ?","explanation":"Les bénéfices sont transversaux mais non exhaustifs. C conserve les deux nuances; B/D sur-généralisent, A écarte le suivi."},{"number":29,"points":21,"correct":"C","options":["La limitation du nombre de fonctions rend impossible une approche autonome du numérique.","La découverte de fonctions secondaires n'a d'intérêt que si les participants maîtrisent déjà toute l'interface.","Une tâche concrète rend les gestes compréhensibles et révèle les difficultés rencontrées.","Une démarche réelle prouve que les participants n'auront plus besoin d'aide lors des tâches suivantes."],"passage":"Une association organise des ateliers en petits groupes. Les questions techniques y sont liées à une tâche réelle, comme retrouver un justificatif, afin d'éviter des manipulations sans objectif compréhensible. Les participants peuvent expliquer les étapes qu'ils comprennent et celles où ils ont besoin d'un soutien. Les formateurs évitent de multiplier les fonctions avant que la première démarche soit maîtrisée. Pour apprendre à joindre un justificatif, les participants accomplissent leur propre démarche guidée. Le formateur note où chacun se bloque, puis introduit la fonction suivante lorsqu'elle devient nécessaire.","question":"Pourquoi le formateur ne commence-t-il pas par présenter toutes les fonctionnalités ?","explanation":"Le contexte réel donne sens aux gestes et ordonne les apprentissages. C; les autres imposent des conditions ou des conclusions absolues."},{"number":30,"points":26,"correct":"A","options":["La diffusion imprévue due à un réglage initial souvent laissé inchangé.","La possibilité pour des utilisateurs de choisir volontairement un partage plus large.","La confusion entre les données nécessaires au service et l'ensemble des informations du compte.","L'absence de tout contrôle ultérieur lorsque le réglage a été sélectionné à l'inscription."],"passage":"Les réglages par défaut influencent les pratiques, car de nombreux utilisateurs ne les modifient pas. Un service choisit donc un partage limité au départ. La possibilité d'élargir ensuite l'accès demeure, mais elle résulte d'une décision explicite. Les explications montrent comment élargir l'accès si une personne le souhaite. Le service veut que cette décision soit compréhensible et réversible, plutôt qu'un changement que l'utilisateur découvrirait après la diffusion de ses informations à un public inattendu. Lors d'un essai, peu d'utilisateurs changent le réglage initial. Ceux qui souhaitent rendre un dossier public disposent néanmoins d'une option clairement expliquée qu'ils peuvent annuler ensuite.","question":"Quel risque le réglage de confidentialité limité par défaut cherche-t-il à réduire ?","explanation":"Les valeurs par défaut influencent les choix réels; limiter l'exposition protège les inattentifs sans supprimer le choix. A."},{"number":31,"points":26,"correct":"C","options":["Elle retire des fonctions peu fréquentes pour accélérer les opérations ordinaires.","Elle place toutes les fonctions sur la page principale afin d'éviter tout apprentissage des menus.","Elle facilite les actions courantes sans supprimer les fonctions avancées.","Elle limite le service aux utilisateurs novices en supprimant les besoins spécialisés."],"passage":"Une interface peut afficher beaucoup de fonctions et paraître complète. Si les actions courantes sont difficiles à trouver, cette richesse devient un obstacle. Les concepteurs retirent des éléments de l'écran principal sans supprimer les fonctions avancées accessibles ailleurs. Ils souhaitent réduire le temps de recherche, sans décider que les fonctions moins fréquentes ne servent plus à personne ou doivent disparaître du service. Un bouton fréquemment utilisé passe sur l'écran d'accueil, tandis qu'une option experte rejoint un sous-menu clairement identifié. Le nombre total d'actions disponibles reste identique.","question":"Comment l'équipe distingue-t-elle simplification de l'écran et appauvrissement du service ?","explanation":"L'architecture change, non les capacités. C. A/B/D confondent visibilité et disponibilité."},{"number":32,"points":26,"correct":"B","options":["Un format récent élimine le besoin de conserver des informations sur l'origine.","Des fichiers intacts peuvent devenir illisibles ou perdre leur contexte.","La numérisation initiale suffit à rendre tout document pérenne sans suivi technique.","Le nombre de copies garantit la possibilité de comprendre la provenance des documents."],"passage":"Une organisation numérise ses archives. Elle doit aussi conserver des descriptions, des formats lisibles et des copies fiables. Transformer un document en fichier ne suffit pas à garantir qu'il pourra être retrouvé et compris dix ans plus tard. Les archivistes contrôlent donc régulièrement les supports et les informations associées. Ils prévoient aussi les changements de format, afin qu'un fichier conservé matériellement ne devienne pas un document impossible à lire ou à interpréter plus tard. Deux fichiers ont des copies intactes dix ans après numérisation. L'un conserve la description de son origine et se lit avec un format maintenu; l'autre a perdu ces informations et ne s'ouvre plus avec les logiciels récents.","question":"Quelle distinction illustrent les deux fichiers conservés ?","explanation":"Un fichier intact peut être illisible ou sans contexte. B. D/C/A attribuent trop au stockage ou au format."},{"number":33,"points":26,"correct":"D","options":["Parce que l'étude de sous-groupes supprime la nécessité d'examiner les exemples initiaux.","Parce que toute différence de performance démontre une intention de discriminer un groupe.","Parce que le nombre de demandes traitées rend inutile la comparaison des erreurs entre catégories.","Parce qu'un niveau moyen élevé peut masquer des erreurs concentrées sur certains profils de demandes."],"passage":"Un outil automatisé classe les demandes selon les exemples utilisés pour le préparer. Si ces exemples représentent mal certaines situations, l'efficacité moyenne peut masquer des erreurs répétées pour un groupe. Une évaluation doit donc regarder la répartition des erreurs, pas seulement leur total. Ils pourront alors préparer des tests complémentaires, plutôt que publier seulement un taux global encourageant qui laisserait certains problèmes durablement invisibles. Le système affiche 92 % de réponses correctes au total, mais seulement 60 % pour des demandes rédigées dans un format minoritaire. L'équipe vérifie désormais les résultats pour chaque type de cas.","question":"Pourquoi le taux global ne suffit-il pas à juger le dispositif ?","explanation":"L'écart montre une performance inégale dissimulée par la moyenne. D. B/A/C ne sont pas justifiés."},{"number":34,"points":26,"correct":"A","options":["Elles distinguent l'envoi d'un message d'une attente de disponibilité immédiate, afin de protéger les limites personnelles.","Elles font dépendre la qualité du travail du nombre de réponses envoyées en dehors des heures habituelles.","Elles garantissent que les mêmes horaires de connexion soient imposés à tous les salariés.","Elles permettent de supprimer les messages écrits au profit des seuls échanges en direct."],"passage":"Le travail à distance permet une présence géographique plus souple, mais peut rendre les limites horaires moins visibles. Une équipe définit des temps sans attente de réponse. La souplesse ne signifie pas une disponibilité permanente ; elle demande aussi des règles partagées de déconnexion. Les salariés peuvent ainsi organiser leur journée sans devoir interpréter chaque silence comme un refus de travailler ou chaque message tardif comme une demande immédiate. Un salarié envoie un document tard le soir sans attendre de réponse; un collègue, ignorant cette convention, se croit tenu de répondre. L'équipe inscrit les règles d'urgence et les plages sans réponse attendue.","question":"Pourquoi les règles partagées sont-elles nécessaires malgré la souplesse du télétravail ?","explanation":"Les conventions explicites évitent l'obligation implicite de répondre. A. C/D/B suppriment la flexibilité."},{"number":35,"points":26,"correct":"C","options":["Reproduire les étapes de l'ancienne interface puis rechercher les boutons déplacés sans consulter les consignes.","Attendre les consignes du formateur avant toute navigation pour éviter les erreurs liées aux mises à jour.","Savoir chercher une information pertinente, tester une procédure et contrôler sa validité.","Connaître plusieurs emplacements possibles pour chaque fonction sans vérifier leur fonctionnement après le changement."],"passage":"Une formation numérique promet l'autonomie après quelques séances. Les outils changent pourtant rapidement. Les formateurs privilégient donc des repères pour chercher de l'aide, comprendre une consigne et vérifier une information, plutôt qu'une liste de gestes liée à un seul écran. Les personnes pourront réutiliser ces repères lorsqu'une fonction change de place. Le centre veut transmettre une manière de chercher et de vérifier, sans promettre qu'un seul cours rendrait toutes les interfaces futures immédiatement familières et faciles. Une application change l'ordre de ses menus après une mise à jour. Un ancien apprenant retrouve pourtant la procédure en lisant l'aide, en vérifiant les étapes et en contrôlant le résultat.","question":"Quel apprentissage permet de continuer après ce changement ?","explanation":"C correspond à des repères transférables pour rechercher, tester et contrôler. A/D restent centrées sur la mémorisation d'emplacements; B crée une dépendance à l'accompagnateur."},{"number":36,"points":33,"correct":"C","options":["Parce qu'un objectif de consultation longue produit un classement comparable à celui qui privilégie la diversité.","Parce que les données initiales doivent être modifiées dès que la plateforme choisit une autre priorité de classement.","Parce que les priorités du classement influencent les résultats affichés.","Parce que la neutralité dépend principalement du nombre de recommandations affichées et non de leur ordre."],"passage":"Une plateforme présente ses recommandations comme neutres parce qu'elles sont calculées. Pourtant, elle doit choisir ce qu'elle optimise : durée de consultation, diversité ou satisfaction déclarée. Ces objectifs peuvent conduire à des sélections différentes. Un calcul n'efface pas les choix inscrits dans les critères qui le guident. Une recommandation peut être très efficace pour garder un utilisateur longtemps sur un site, sans lui faire découvrir des sources différentes. Une autre peut lui proposer plus de variété, mais demander davantage d'effort au début. Le service doit donc expliquer ses priorités et observer leurs conséquences. Les responsables souhaitent que le public puisse discuter ces choix, plutôt que considérer la formule comme une simple description du monde. La technique apporte des moyens de calcul, mais elle ne décide pas seule de la valeur que l'on attribue à chacun des résultats recherchés. Lors d'un essai, privilégier la durée de consultation fait monter les recommandations de contenus polarisants; privilégier la variété modifie le classement sans changer les données de départ. L'équipe publie les critères de chaque version.","question":"Pourquoi le même jeu de données ne garantit-il pas un classement neutre ?","explanation":"C montre qu'une règle d'optimisation incorpore une priorité qui façonne le classement. A nie l'écart observé, B suppose une modification des données absente, D attribue la neutralité au volume affiché."},{"number":37,"points":33,"correct":"A","options":["Le travail d'assistance déplacé vers les partenaires et l'achèvement réel des démarches par les usagers.","Le nombre de dossiers commencés, même lorsque certaines personnes ne peuvent pas les terminer sans aide.","La réduction des dépenses administratives, indépendamment du temps de soutien requis par les associations.","L'économie de temps enregistrée au guichet, sans considérer les démarches déplacées vers les autres acteurs."],"passage":"Une administration remplace un guichet par une démarche en ligne. Le nombre de dossiers déposés augmente, mais les personnes en difficulté se déplacent désormais vers les associations pour obtenir de l'aide. Une simplification pour le service peut déplacer le travail d'accompagnement vers d'autres acteurs plutôt que le faire disparaître. Les bénévoles expliquent qu'ils doivent apprendre les nouvelles interfaces et accompagner des cas parfois complexes. Cette activité ne figure pas toujours dans les économies annoncées par le service public. Les responsables vont rencontrer les associations pour préciser les difficultés et garder une possibilité d'accueil direct. Ils souhaitent mesurer les démarches menées jusqu'au bout, pas seulement les formulaires commencés. Le bilan devra donc inclure les personnes qui n'ont pas réussi seules et les ressources nécessaires pour les aider, afin de comprendre si le nouveau fonctionnement simplifie réellement l'accès pour l'ensemble du public. Le service annonce un gain de dix minutes par dossier, mais une association consacre désormais vingt minutes à accompagner certaines personnes sur la nouvelle interface. Ces heures ne figurent pas dans le bilan administratif initial.","question":"Quelle information faut-il intégrer pour apprécier le gain de la dématérialisation ?","explanation":"A intègre les tâches transférées et les démarches réellement terminées. B confond commencement et aboutissement; C/D excluent le coût d'assistance observé."},{"number":38,"points":33,"correct":"D","options":["Une information détaillée permet d'accepter plus facilement, même si le refus reste accessible après plusieurs étapes.","Une option de refus demeure suffisamment claire lorsque son emplacement est décrit au bas du formulaire.","La rapidité du consentement révèle une préférence stable, sauf si l'utilisateur choisit de revenir sur sa décision.","Une option juridiquement présente peut être difficile à exercer lorsque sa présentation oriente le choix."],"passage":"Un service demande le consentement avant d'utiliser des données, puis présente un formulaire très long dont le refus est difficile à trouver. Le choix existe juridiquement à l'écran, mais l'organisation de la page peut orienter fortement la décision. La présence d'une option ne suffit pas à garantir qu'elle soit aussi facile à comprendre et à exercer que les autres. Les utilisateurs peuvent accepter rapidement pour terminer une tâche urgente, même s'ils auraient préféré limiter l'utilisation de leurs informations. Une association propose donc des choix présentés avec la même lisibilité et un résumé des effets principaux. Les responsables souhaitent conserver les explications détaillées pour ceux qui en ont besoin, sans rendre le refus plus compliqué que l'accord. Les essais seront menés avec des personnes découvrant le service. Deux écrans offrent « Accepter » en gros bouton et « Refuser » derrière plusieurs liens. Lors d'un test, des participants qui souhaitaient limiter leurs données acceptent par impatience; le service rééquilibre la visibilité.","question":"Quelle faiblesse du recueil de consentement ce test met-il en évidence ?","explanation":"D souligne que l'asymétrie de présentation limite le choix réel malgré la présence juridique d'une option. A/B justifient une difficulté d'accès au refus; C attribue trop de sens aux acceptations précipitées."},{"number":39,"points":33,"correct":"A","options":["La reprise des opérations et le rapprochement des résultats après redémarrage, car une procédure de secours ne garantit pas à elle seule la fiabilité finale.","Le temps minimal d'interruption rapporté dans chaque service, puisque les deux équipes ont continué leur travail manuel sans attendre la remise en route du logiciel et ont donc assuré les opérations attendues.","La proportion d'opérations réalisées sans logiciel, qui démontre directement que les paramètres informatiques ont été correctement restaurés après la panne.","La satisfaction du client après rétablissement du service, même lorsque l'équipe n'a pas contrôlé le résultat de ses calculs intermédiaires."],"passage":"Un logiciel rend une tâche plus rapide. Les professionnels conservent néanmoins un moyen de travailler en cas de panne et des connaissances pour contrôler les résultats. Ils ne rejettent pas l'automatisation ; ils évitent qu'une commodité se transforme en dépendance sans recours. La maîtrise d'un outil comprend aussi la possibilité de vérifier et de s'en passer temporairement. Des exercices permettent de repérer un résultat inhabituel et de reprendre une tâche avec un autre moyen. Les nouveaux collègues reçoivent ces repères lors de leur arrivée, pour éviter qu'ils disparaissent avec les personnes les plus expérimentées. L'organisation souhaite profiter du gain de temps sans perdre la compréhension de ce qui est réalisé. Le bilan portera donc sur la vitesse, mais aussi sur la capacité à expliquer les décisions et à continuer lors d'un incident. Lors d'une panne, l'équipe exécute une procédure manuelle déjà exercée. À la reprise du logiciel, elle compare les résultats et détecte une anomalie issue d'un paramètre mal réglé. Un audit compare ensuite deux incidents. Lors du premier, l'équipe applique une procédure manuelle et continue le service, mais conserve un ancien paramètre dans le logiciel lors de sa remise en route. Un contrôle croisé découvre l'erreur avant l'envoi des résultats aux clients. Lors du second, la procédure de secours permet également de poursuivre les opérations, mais aucun rapprochement n'est effectué à la reprise; une anomalie de calcul n'est identifiée que par un client plusieurs jours plus tard. Les deux équipes disposent donc d'une capacité minimale de continuité en cas de panne, sans posséder le même niveau de vérification après le redémarrage. Le responsable estime qu'un tableau indiquant seulement les minutes d'interruption masquerait cette différence. Il veut suivre séparément la capacité à terminer les tâches, à expliciter les résultats produits et à détecter les anomalies après rétablissement du système.","question":"Quel indicateur distingue le mieux une simple continuité de service d'une maîtrise vérifiable du processus automatisé ?","explanation":"A associe continuité et vérification indépendante des calculs, illustrée par la détection préventive dans le premier incident et tardive dans le second. B ne mesure que l'interruption; C infère un réglage exact à partir de la part de travail manuel; D confond satisfaction et contrôle effectif de la fiabilité des résultats."}]}$paper_13$::jsonb),
('tcf-reading-14','tcf-reading-2026-11-close-reading-v4',$paper_14${"id":"tcf-reading-14","title":"TCF Reading · Test 14","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["Vendredi soir obligatoirement","Le mois suivant","Jamais","Avant son envoi"],"passage":"Le journal du quartier recevra vos annonces jusqu'au vendredi midi. Les textes arrivés ensuite paraîtront le mois suivant.\n\nUn message confirmera la réception des annonces retenues. Merci d'indiquer une date et un contact pour permettre aux lecteurs de demander des renseignements.","question":"Quand une annonce tardive sera-t-elle publiée ?","explanation":"Le passage indique : « Le journal du quartier recevra vos annonces jusqu'au vendredi midi. Les textes arrivés ensuite paraîtront le mois suivant. » Cela justifie la réponse : Le mois suivant."},{"number":2,"points":3,"correct":"D","options":["L'accès est réservé aux journalistes","Les lecteurs doivent apporter un article","La réunion est payante","La capacité est limitée"],"passage":"La conférence de rédaction est ouverte aux lecteurs mercredi. Merci de réserver une place ; la salle est petite.\n\nLes personnes inscrites recevront les horaires et le lieu d'accueil.","question":"Pourquoi faut-il réserver ?","explanation":"Le passage indique : « La conférence de rédaction est ouverte aux lecteurs mercredi. Merci de réserver une place ; la salle est petite. » Cela justifie la réponse : La capacité est limitée."},{"number":3,"points":3,"correct":"D","options":["Une attribution à un autre photographe","Toute publicité commerciale","Une vente sans accord","Un travail scolaire"],"passage":"Les photos de l'exposition peuvent être utilisées pour un travail scolaire en citant leur auteur. L'usage commercial nécessite un accord séparé.\n\nLes conditions sont indiquées sur le site avec les noms des photographes.","question":"Quel usage est autorisé sous condition de citation ?","explanation":"Le passage indique : « Les photos de l'exposition peuvent être utilisées pour un travail scolaire en citant leur auteur. L'usage commercial nécessite un accord séparé. » Cela justifie la réponse : Un travail scolaire."},{"number":4,"points":3,"correct":"A","options":["À la mairie","Au guichet de la piscine seulement","Dans chaque train","Uniquement dans les boîtes aux lettres"],"passage":"Le bulletin ne sera pas distribué dans les boîtes aux lettres cette semaine. Il reste disponible à la mairie.\n\nLa rédaction publiera aussi une version numérique pour les lecteurs qui ne peuvent pas se déplacer.","question":"Où peut-on le consulter ?","explanation":"Le passage indique : « Le bulletin ne sera pas distribué dans les boîtes aux lettres cette semaine. Il reste disponible à la mairie. » Cela justifie la réponse : À la mairie."},{"number":5,"points":9,"correct":"C","options":["La taille du fichier uniquement","Le nombre de photos du pont","La date de l'information","Le nom de tous les lecteurs"],"passage":"Je t'ai transmis un article ancien par erreur. Vérifie la date avant de partager l'annonce de fermeture du pont.\n\nLe nouveau texte de la mairie indique que la circulation a déjà repris. Je préfère te prévenir avant que tu organises un autre trajet à partir de mon premier envoi.","question":"Quelle vérification est demandée ?","explanation":"Le passage indique : « Je t'ai transmis un article ancien par erreur. Vérifie la date avant de partager l'annonce de fermeture du pont. » Cela justifie la réponse : La date de l'information."},{"number":6,"points":9,"correct":"D","options":["Une publication automatique intégrale","Un vote sur son identité","Une diffusion sans contact préalable","Une confirmation avec le témoin"],"passage":"Notre podcast accueille des témoignages courts. Nous vous rappellerons avant diffusion pour confirmer les passages retenus.\n\nLes enregistrements seront montés pour rendre les échanges plus faciles à suivre. Vous pourrez poser vos questions sur ce fonctionnement avant de confirmer votre participation au programme.","question":"Quelle étape est prévue ?","explanation":"Le passage indique : « Notre podcast accueille des témoignages courts. Nous vous rappellerons avant diffusion pour confirmer les passages retenus. » Cela justifie la réponse : Une confirmation avec le témoin."},{"number":7,"points":9,"correct":"B","options":["Une annonce uniquement promotionnelle","Un portrait comportant des questions critiques","Un catalogue de prix sans entretien","Un texte rédigé par tous les clients"],"passage":"J'aimerais interviewer un artisan, pas réaliser une publicité. Je lui demanderai aussi quelles difficultés il rencontre.\n\nJe préparerai des questions sur ses choix, ses outils et l'organisation de ses journées. Le lecteur doit pouvoir comprendre son activité, pas seulement connaître les produits qu'il souhaite vendre.","question":"Quel type de contenu est recherché ?","explanation":"Le passage indique : « J'aimerais interviewer un artisan, pas réaliser une publicité. Je lui demanderai aussi quelles difficultés il rencontre. » Cela justifie la réponse : Un portrait comportant des questions critiques."},{"number":8,"points":9,"correct":"B","options":["Supprimer les annonces de service","Rendre les informations urgentes plus visibles","Augmenter le nombre d'alertes sans distinction","Interdire toute discussion"],"passage":"Le groupe de discussion réserve les messages urgents aux informations de service. Les débats généraux se tiennent dans un autre espace.\n\nLes membres pourront continuer à discuter sans rendre difficile la recherche d'une annonce importante au milieu des réactions.","question":"Pourquoi séparer les espaces ?","explanation":"Le passage indique : « Le groupe de discussion réserve les messages urgents aux informations de service. Les débats généraux se tiennent dans un autre espace. » Cela justifie la réponse : Rendre les informations urgentes plus visibles."},{"number":9,"points":9,"correct":"A","options":["Le nom de l'association","Le sujet complet de l'article","Toutes les citations","La date de l'entretien"],"passage":"Merci de corriger le nom de mon association dans l'article. Les propos cités sont exacts ; seule cette mention pose problème.\n\nUne note courte permettra aux lecteurs de retrouver le bon organisme sans modifier le sens de l'entretien.","question":"Quelle correction est demandée ?","explanation":"Le passage indique : « Merci de corriger le nom de mon association dans l'article. Les propos cités sont exacts ; seule cette mention pose problème. » Cela justifie la réponse : Le nom de l'association."},{"number":10,"points":9,"correct":"B","options":["Seuls les élus peuvent témoigner","Un témoignage représente d'abord une expérience individuelle","Chaque récit décrit nécessairement toute la population","Les souvenirs doivent tous être identiques"],"passage":"Nous préparons une émission sur les souvenirs du quartier. Les participants peuvent raconter une expérience personnelle sans prétendre parler pour tous les habitants.\n\nLes personnes pourront aussi préférer un texte ou une photographie à un enregistrement de leur voix pendant la rencontre.","question":"Quelle limite est reconnue ?","explanation":"Le passage indique : « Nous préparons une émission sur les souvenirs du quartier. Les participants peuvent raconter une expérience personnelle sans prétendre parler pour tous les habitants. » Cela justifie la réponse : Un témoignage représente d'abord une expérience individuelle."},{"number":11,"points":15,"correct":"C","options":["Éviter toute lecture critique","Prouver que toute analyse est impossible","Permettre de vérifier le point de départ","Remplacer l'enquête par un titre"],"passage":"Un journaliste publie le document à l'origine de son enquête. Les lecteurs peuvent ainsi distinguer la source et l'analyse qu'il en propose.\n\nLe document est accompagné de sa date et d'une indication sur la manière dont il a été obtenu. Les journalistes expliquent les passages qui leur paraissent importants et les limites de ce qu'ils peuvent en déduire. Les lecteurs peuvent ainsi examiner le raisonnement sans devoir accepter une conclusion sur la seule réputation du média. La rédaction souhaite rendre le travail plus lisible, pas prétendre qu'une source brute supprimerait tout besoin d'analyse ou donnerait automatiquement une interprétation identique à toutes les personnes qui la consultent.","question":"Quel intérêt présente cette publication ?","explanation":"Le passage indique : « Un journaliste publie le document à l'origine de son enquête. Les lecteurs peuvent ainsi distinguer la source et l'analyse qu'il en propose. » Cela justifie la réponse : Permettre de vérifier le point de départ."},{"number":12,"points":15,"correct":"B","options":["Le nom du fabricant du papier","Le moment de la prise de vue","Le prix de l'appareil","La largeur du cadre"],"passage":"Une photographie montre une rue vide à l'aube. Utilisée pour illustrer l'activité de toute la journée, elle peut donner une impression trompeuse.\n\nLa légende devrait préciser les conditions et éviter de présenter ce moment comme représentatif de toutes les heures. Des observations complémentaires pourraient montrer les variations de fréquentation. Les élèves de l'atelier comparent plusieurs usages de la même image et discutent des impressions produites.","question":"Quelle information manque pour l'interpréter ?","explanation":"Le passage indique : « Une photographie montre une rue vide à l'aube. Utilisée pour illustrer l'activité de toute la journée, elle peut donner une impression trompeuse. » Cela justifie la réponse : Le moment de la prise de vue."},{"number":13,"points":15,"correct":"A","options":["Éviter une confusion temporelle","Augmenter le volume sonore","Interdire la rediffusion","Cacher l'origine du programme"],"passage":"Une radio locale rediffuse une émission en signalant clairement sa date initiale. Les informations pratiques anciennes ne doivent pas être prises pour des annonces actuelles.\n\nLe présentateur rappelle également le contexte avant les passages consacrés aux services du quotidien. Certaines questions restent intéressantes longtemps, mais des horaires ou des procédures peuvent avoir changé depuis l'entretien. Elle souhaite conserver la valeur des archives sans encourager des démarches à partir d'une information devenue ancienne. Les auditeurs pourront retrouver la version d'origine, avec les précisions permettant de la distinguer d'une annonce nouvelle destinée au public de cette semaine.","question":"Pourquoi afficher cette date ?","explanation":"Le passage indique : « Une radio locale rediffuse une émission en signalant clairement sa date initiale. Les informations pratiques anciennes ne doivent pas être prises pour des annonces actuelles. » Cela justifie la réponse : Éviter une confusion temporelle."},{"number":14,"points":15,"correct":"D","options":["Désigner un titre sans lire","Éviter toute comparaison","Mémoriser tous les titres","Identifier un choix de présentation"],"passage":"Un atelier compare deux titres portant sur le même rapport. Les participants repèrent les aspects sélectionnés et ceux qui ne sont pas mentionnés.\n\nLes groupes lisent ensuite les extraits correspondants pour voir ce que chaque titre permet réellement d'affirmer. Un titre peut être exact tout en donnant la priorité à un aspect particulier. Les animateurs souhaitent que les lecteurs apprennent à reconnaître ce travail de sélection, sans conclure que toutes les formulations sont nécessairement trompeuses. Les participants proposeront une autre version et expliqueront leur choix.","question":"Quelle compétence est travaillée ?","explanation":"Le passage indique : « Un atelier compare deux titres portant sur le même rapport. Les participants repèrent les aspects sélectionnés et ceux qui ne sont pas mentionnés. » Cela justifie la réponse : Identifier un choix de présentation."},{"number":15,"points":15,"correct":"C","options":["La taille des bureaux","Le poids du papier","La nature des textes publiés","La profession de tous les abonnés"],"passage":"Une rédaction distingue les tribunes d'opinion des enquêtes d'information. Les rubriques ne demandent pas au lecteur la même manière d'évaluer les arguments.\n\nLes tribunes peuvent défendre une position et doivent être lues comme des arguments signés. La rédaction précise cependant que la séparation des rubriques ne dispense pas de vérifier une affirmation lorsqu'elle apparaît dans un texte d'opinion. Le journal souhaite rendre sa présentation plus claire, sans créer une catégorie dans laquelle les auteurs pourraient affirmer n'importe quoi en se contentant de rappeler que le texte exprime leur point de vue personnel.","question":"Quelle distinction est rendue visible ?","explanation":"Le passage indique : « Une rédaction distingue les tribunes d'opinion des enquêtes d'information. Les rubriques ne demandent pas au lecteur la même manière d'évaluer les arguments. » Cela justifie la réponse : La nature des textes publiés."},{"number":16,"points":15,"correct":"A","options":["La transparence sur les rectifications","L'effacement de toute responsabilité","La suppression de toutes les archives","L'interdiction de signaler une erreur"],"passage":"Le journal rectifie un chiffre et explique l'erreur dans une note. Il conserve une trace de la correction au lieu de modifier silencieusement l'article.\n\nLa note indique ce qui a changé et pourquoi l'équipe a retenu la nouvelle valeur. Les lecteurs peuvent ainsi comprendre si la correction modifie ou non la conclusion générale. La rédaction ne souhaite pas garder une donnée fausse simplement pour ne pas attirer l'attention sur l'incident. Elle veut aussi éviter qu'une modification invisible empêche de suivre le parcours d'une information déjà citée ailleurs.","question":"Quel principe applique-t-il ?","explanation":"Le passage indique : « Le journal rectifie un chiffre et explique l'erreur dans une note. Il conserve une trace de la correction au lieu de modifier silencieusement l'article. » Cela justifie la réponse : La transparence sur les rectifications."},{"number":17,"points":15,"correct":"C","options":["Le refus de consulter les habitants","Le remplacement du projet par une rumeur","Le recueil de points de vue indépendants de l'annonce","La copie exacte de la publicité"],"passage":"Un communiqué annonce un projet municipal. Avant de le reprendre, une journaliste interroge aussi les personnes concernées par ses effets.\n\nLa journaliste recueille les réactions des riverains et consulte des documents sur des réalisations comparables. Elle veut distinguer les intentions et les effets encore à vérifier. Les responsables du projet pourront répondre aux questions, mais leur présentation ne sera pas traitée comme un bilan déjà établi. Le journal souhaite que les lecteurs comprennent ce qui est annoncé et ce qui reste incertain.","question":"Quelle démarche complète le communiqué ?","explanation":"Le passage indique : « Un communiqué annonce un projet municipal. Avant de le reprendre, une journaliste interroge aussi les personnes concernées par ses effets. » Cela justifie la réponse : Le recueil de points de vue indépendants de l'annonce."},{"number":18,"points":15,"correct":"D","options":["La longueur du titre","Le prix de l'abonnement","La couleur du graphique","La taille du groupe interrogé"],"passage":"Un média publie des statistiques accompagnées du nombre de répondants. Un résultat fondé sur un petit groupe demande davantage de prudence dans sa généralisation.\n\nLe média précise aussi comment les personnes ont été choisies et dans quelles conditions elles ont répondu. Les journalistes souhaitent éviter qu'un pourcentage donne une impression de précision supérieure à celle des données. Le chiffre peut rester utile pour décrire les répondants, sans représenter automatiquement une population plus vaste. Les lecteurs pourront consulter les limites annoncées et comparer avec d'autres travaux.","question":"Quelle information aide à juger la portée du résultat ?","explanation":"Le passage indique : « Un média publie des statistiques accompagnées du nombre de répondants. Un résultat fondé sur un petit groupe demande davantage de prudence dans sa généralisation. » Cela justifie la réponse : La taille du groupe interrogé."},{"number":19,"points":15,"correct":"C","options":["Une experte ne peut avoir aucune préférence","Le métier suffit à valider toute opinion","Toutes ses opinions n'ont pas le même fondement d'expertise","Les connaissances interdisent les questions"],"passage":"Une émission invite une experte sur son domaine de recherche. Le présentateur distingue ses connaissances professionnelles de ses préférences personnelles.\n\nL'invitée peut indiquer les résultats qu'elle connaît et préciser les questions qui dépassent son travail. Le présentateur souhaite éviter de transformer une qualité professionnelle réelle en autorité générale sur tous les sujets. Les auditeurs recevront des références pour approfondir les éléments scientifiques abordés. Les préférences exprimées seront présentées comme telles, afin que chacun puisse apprécier leur statut.","question":"Pourquoi cette distinction importe-t-elle ?","explanation":"Le passage indique : « Une émission invite une experte sur son domaine de recherche. Le présentateur distingue ses connaissances professionnelles de ses préférences personnelles. » Cela justifie la réponse : Toutes ses opinions n'ont pas le même fondement d'expertise."},{"number":20,"points":21,"correct":"D","options":["Réserver l'article aux spécialistes","Remplacer toutes les preuves par des slogans","Supprimer les informations importantes","Rendre le texte accessible sans effacer ses fondements"],"passage":"Un journal souhaite élargir son lectorat. Il réduit les termes techniques, mais conserve les sources et les explications nécessaires. Simplifier la langue ne signifie pas supprimer ce qui permet de comprendre le raisonnement. Des lecteurs ont participé à la relecture des premiers essais. Ils ont signalé les mots qui gênaient la compréhension et les endroits où une explication manquait. Les journalistes ont ensuite réorganisé certains passages sans retirer les éléments qui permettent de contrôler les affirmations. Le journal souhaite une lecture plus fluide, pas une conclusion qu'il faudrait accepter sans comprendre comment elle a été construite.","question":"Quel équilibre cherche-t-il ?","explanation":"Le passage indique : « Un journal souhaite élargir son lectorat. Il réduit les termes techniques, mais conserve les sources et les explications nécessaires. Simplifier la langue ne signifie pas supprimer ce qui permet de comprendre le raisonnement. » Cela justifie la réponse : Rendre le texte accessible sans effacer ses fondements."},{"number":21,"points":21,"correct":"C","options":["Éviter d'identifier les sujets","Remplacer les informations par des adhésions","Permettre au lecteur d'apprécier leur position","Garantir que toute critique sera supprimée"],"passage":"Des habitants lancent une lettre locale parce que certaines initiatives ne sont jamais couvertes. Ils prévoient toutefois de mentionner leurs liens avec les associations présentées. La lettre indiquera qui a proposé le sujet et si un membre de la rédaction participe à l'activité présentée. Les lecteurs pourront demander d'autres points de vue. Le groupe souhaite conserver sa connaissance du quartier, tout en rendant visibles les relations qui peuvent influencer ses choix. Il ne prétend pas remplacer cette proximité par une absence de position impossible à garantir.","question":"Pourquoi annoncer ces liens ?","explanation":"Le passage indique : « Des habitants lancent une lettre locale parce que certaines initiatives ne sont jamais couvertes. Ils prévoient toutefois de mentionner leurs liens avec les associations présentées. » Cela justifie la réponse : Permettre au lecteur d'apprécier leur position."},{"number":22,"points":21,"correct":"D","options":["Supprimer les vérifications","Remplacer tous les journalistes","Décider du résultat avant l'enquête","Contribuer aux questions à examiner"],"passage":"Une rédaction organise ses reportages selon les questions du public, mais garde la décision sur les vérifications et les sources. La participation des lecteurs nourrit l'enquête sans en fixer d'avance la conclusion. Les journalistes regroupent les propositions, vérifient ce qui peut être étudié et expliquent les sujets qu'ils ne pourront pas traiter immédiatement. Certains lecteurs apportent des documents ou des observations utiles. La rédaction conserve toutefois la responsabilité de confronter ces éléments à d'autres sources.","question":"Quelle place est donnée aux lecteurs ?","explanation":"Le passage indique : « Une rédaction organise ses reportages selon les questions du public, mais garde la décision sur les vérifications et les sources. La participation des lecteurs nourrit l'enquête sans en fixer d'avance la conclusion. » Cela justifie la réponse : Contribuer aux questions à examiner."},{"number":23,"points":21,"correct":"A","options":["Un contexte ajouté de manière erronée","Une image entièrement inventée nécessairement","Une absence de toute scène visible","Une qualité technique trop faible uniquement"],"passage":"Une vidéo très partagée montre une scène réelle, mais le commentaire affirme qu'elle se déroule dans une autre ville. La fausseté ne se trouve pas dans l'image elle-même, mais dans son attribution. Les participants apprennent donc à rechercher l'origine de la vidéo et les publications antérieures. Ils comparent les détails visibles avec les lieux annoncés. Un document réel peut être utilisé pour soutenir une affirmation fausse si le contexte ajouté ne correspond pas à ce qui a été filmé.","question":"Quel problème est identifié ?","explanation":"Le passage indique : « Une vidéo très partagée montre une scène réelle, mais le commentaire affirme qu'elle se déroule dans une autre ville. La fausseté ne se trouve pas dans l'image elle-même, mais dans son attribution. » Cela justifie la réponse : Un contexte ajouté de manière erronée."},{"number":24,"points":21,"correct":"D","options":["Une identité connue doit toujours être publiée","La protection d'une source interdit tout entretien","L'anonymat impose de ne rien vérifier","Anonymat public et absence de vérification ne se confondent pas"],"passage":"Un média refuse de citer une personne de manière anonyme sans en connaître l'identité. Il peut protéger son nom publiquement tout en vérifiant qui fournit l'information. La rédaction évalue les raisons de la protection et cherche des confirmations indépendantes. Elle explique aux lecteurs la portée de ce choix sans révéler les informations permettant d'identifier la personne. L'objectif est de rendre possible un témoignage utile, tout en gardant une exigence de fiabilité.","question":"Quelle différence est faite ?","explanation":"Le passage indique : « Un média refuse de citer une personne de manière anonyme sans en connaître l'identité. Il peut protéger son nom publiquement tout en vérifiant qui fournit l'information. » Cela justifie la réponse : Anonymat public et absence de vérification ne se confondent pas."},{"number":25,"points":21,"correct":"A","options":["Parce que le nombre de partages renseigne sur l'attention, non la fiabilité.","Parce que la fréquence des partages révèle directement la méthode employée par l'auteur.","Parce qu'un contenu largement partagé ne peut être fondé sur une étude consultable.","Parce qu'un message vérifiable circule nécessairement moins vite qu'une information sans source."],"passage":"Un atelier explique qu'un nombre de partages mesure une circulation, pas une exactitude. Une information fausse peut être très visible, et une enquête fiable peu connue. Les participants comparent la circulation de plusieurs messages et cherchent les documents sur lesquels ils s'appuient. Certains contenus attirent surtout parce qu'ils surprennent ou confirment une opinion. Le groupe souhaite distinguer ces raisons de partage du travail nécessaire pour établir un fait. Deux articles circulent largement. Le premier cite une étude dont la méthode peut être consultée; le second reprend une rumeur sans document vérifiable. Le nombre de partages est proche, mais les fondements diffèrent.","question":"Pourquoi l'égalité de diffusion des deux messages ne permet-elle pas de conclure à leur fiabilité comparable ?","explanation":"La circulation et la vérification sont deux critères distincts. A. D/C/B infèrent un lien non établi."},{"number":26,"points":21,"correct":"C","options":["Écarter toutes ses observations car il ne contient pas de données suffisantes pour une moyenne nationale.","Le traiter comme un échantillon représentatif puisque les journalistes ont détaillé les circonstances.","Le traiter comme un cas détaillé sans lui attribuer une portée statistique nationale.","En déduire la part nationale des familles rencontrant le même problème à partir de l'année suivie."],"passage":"Un reportage suit une seule famille pendant une année. Il rend son expérience précise, mais les auteurs ne prétendent pas que toutes les familles vivent la même situation. Les journalistes montrent les choix quotidiens, les hésitations et les changements observés pendant le suivi. Ils présentent aussi les circonstances de cette rencontre, afin de ne pas donner l'illusion d'une famille choisie comme résumé de toute la société. Le reportage peut ainsi rendre sensible une expérience précise. Le reportage montre comment cette famille a modifié son budget après un déménagement. Les journalistes précisent que le récit ne permet pas d'estimer combien de familles vivent une situation similaire.","question":"Quelle utilisation de ce reportage est défendable ?","explanation":"L'étude détaillée d'un cas n'est ni une statistique représentative ni inutile. C. D/B généralisent; A rejette à tort sa valeur descriptive."},{"number":27,"points":21,"correct":"B","options":["Ne retenir que les conclusions les plus populaires afin de représenter l'opinion du public.","Hiérarchiser les affirmations selon l'état des preuves, tout en expliquant les désaccords encore ouverts.","Présenter la controverse comme un choix personnel entre deux convictions impossibles à vérifier.","Accorder un temps strictement identique aux intervenants, quelle que soit la qualité des références."],"passage":"Une émission débat d'un désaccord scientifique. Le producteur distingue une controverse entre spécialistes et une affirmation isolée sans preuve. Donner un temps égal à toute affirmation ne produirait pas forcément une représentation équilibrée des connaissances. Les organisateurs consultent donc des travaux de référence et demandent aux invités de préciser leurs arguments. Ils ne souhaitent pas éliminer le désaccord, mais rendre visible ce qui le soutient. L'un des invités défend une hypothèse appuyée par plusieurs études; un autre avance une objection récente encore peu examinée. Le producteur prévoit de présenter les deux sans laisser croire qu'elles ont le même degré de confirmation.","question":"Quel principe évite une fausse équivalence entre les positions ?","explanation":"La place d'un argument doit refléter ses fondements. B. D/C/A ignorent le degré d'appui scientifique."},{"number":28,"points":21,"correct":"C","options":["Il permet à la rédaction de retirer les sources pour alléger la lecture des non-spécialistes.","Il distingue les lecteurs qui disposent de peu de temps de ceux qui sont autorisés à examiner les sources.","Il offre un premier niveau de compréhension tout en maintenant l'accès aux preuves et aux nuances.","Il donne un aperçu suffisant pour affirmer connaître les limites et tous les documents du dossier."],"passage":"Un journal ajoute un résumé au début de ses enquêtes longues. Les lecteurs pressés disposent d'un repère, tandis que les détails restent consultables. La rédaction veut permettre une entrée plus facile dans un sujet complexe. Elle observera aussi si les lecteurs retrouvent les explications dont ils ont besoin. Une lecture rapide reste possible, mais elle ne doit pas être présentée comme nécessairement équivalente à l'examen complet du dossier et de ses limites. Certains lecteurs utilisent le résumé pour décider d'ouvrir le dossier complet, tandis que d'autres ne lisent que l'essentiel. La rédaction indique les limites de l'enquête dans le dossier et évite d'effacer cette possibilité d'approfondissement.","question":"Quelle fonction le résumé remplit-il sans se substituer à l'enquête ?","explanation":"Le résumé facilite l'entrée tout en laissant les détails disponibles. C. D/A/B déforment les degrés de lecture."},{"number":29,"points":21,"correct":"A","options":["Pour expliquer les arbitrages et les options écartées dans la décision.","Pour remplacer le procès-verbal par une liste de désaccords sans résultats.","Pour montrer que les membres absents approuvaient nécessairement les options finalement retenues.","Pour prouver que toutes les propositions étaient équivalentes avant le vote."],"passage":"Une association explique ses décisions dans un bulletin. Elle mentionne aussi les propositions non retenues et leurs raisons, afin que le compte rendu ne paraisse pas présenter un accord unanime fictif. Les membres absents peuvent ainsi comprendre pourquoi une décision a été prise et quelles difficultés ont été discutées. Le bulletin distingue les points d'accord et ceux qui restent ouverts. Le bulletin explique qu'une proposition de financement a été écartée non parce qu'elle manquait de soutien, mais parce qu'une condition juridique empêchait son application. Les membres absents peuvent comprendre la décision malgré ce désaccord.","question":"Pourquoi rendre compte des propositions rejetées ?","explanation":"Les raisons des refus rendent la décision transparente, A. D/B/C effacent les justifications ou inventent un accord."},{"number":30,"points":26,"correct":"D","options":["Vérifier uniquement que la citation provient du même intervenant et de la même date.","Déterminer si la courte citation est plus facile à mémoriser que l'explication longue.","Compter le nombre de mots communs entre le message viral et l'entretien original.","Comparer la formulation complète et les conditions qui déterminent le sens de la conclusion."],"passage":"Une phrase exacte peut devenir trompeuse lorsqu'elle est séparée de la condition qui la limitait. Un atelier demande donc de retrouver le passage complet avant de discuter une citation très courte. Vérifier les mots ne suffit pas toujours à vérifier le sens attribué. Les animateurs proposent des citations dont les mots sont authentiques mais le sens incomplet. Les participants peuvent alors examiner ce qui change lorsque l'on retrouve la question posée et la suite de la réponse. Une chercheuse déclare: « Cette mesure ne réduit pas le risque dans tous les cas. » Le titre d'un message viral ne retient que « Cette mesure réduit le risque » et supprime la négation de portée et la condition.","question":"Quelle vérification manque au lecteur qui confirme seulement que certains mots figurent dans l'entretien ?","explanation":"L'omission altère la portée du propos. D exige de retrouver les restrictions; C/A/B ne vérifient pas le sens."},{"number":31,"points":26,"correct":"A","options":["Elle publie les faits vérifiés et reporte ceux encore incertains.","Elle retarde toutes les nouvelles, y compris celles déjà vérifiées, jusqu'au lendemain.","Elle publie l'annonce incertaine en laissant aux lecteurs le soin d'en vérifier la source.","Elle refuse de corriger une information publiée avant la vérification complète."],"passage":"La rapidité est devenue un argument des médias. Une rédaction choisit pourtant de retarder une annonce lorsqu'une vérification essentielle manque. Elle ne renonce pas à informer, mais considère que publier avant de savoir peut créer une erreur difficile à corriger ensuite. Elle souhaite conserver une information utile au public, sans transformer le délai de vérification en silence total ni l'urgence de publier en excuse pour affirmer sans preuve. Une information urgente semble plausible mais dépend d'un document que la rédaction n'a pas pu confirmer. Elle publie ce qu'elle a vérifié et réserve l'annonce contestée pour un point ultérieur.","question":"Comment la rédaction concilie-t-elle rapidité et responsabilité ?","explanation":"Elle informe dans la limite de ce qui est confirmé, A. B/C/D ne respectent pas le compromis décrit."},{"number":32,"points":26,"correct":"A","options":["Les valeurs ne changent pas avec l'échelle, mais l'impression de grandeur dépend de la représentation.","La différence numérique est déterminée par la hauteur visuelle des colonnes.","La seconde échelle prouve que la hausse observée est sans conséquence dans tous les contextes.","Le premier est nécessairement faux puisque les axes ne commencent pas tous à zéro."],"passage":"Un graphique commence son axe vertical au-dessus de zéro. Ce choix peut rendre une variation plus visible. Il n'est pas forcément illégitime, mais doit être compris : une impression de rupture spectaculaire peut venir en partie de l'échelle choisie. Les lecteurs peuvent comparer plusieurs échelles à partir des mêmes valeurs. Le cours veut rendre ces choix compréhensibles plutôt que demander de se fier uniquement à l'impression immédiate produite par la hauteur de deux colonnes. Les valeurs passent de 98 à 100. Sur un axe commençant à 97, les colonnes semblent différer énormément; sur un axe commençant à zéro, leur différence paraît modeste. Les nombres eux-mêmes restent identiques.","question":"Quelle distinction permet de lire correctement les deux graphiques ?","explanation":"L'échelle modifie le rendu sans changer les données. A. D/B/C surinterprètent l'aspect visuel."},{"number":33,"points":26,"correct":"C","options":["Elles prouvent qu'une relation ancienne avec un élu rend chaque article favorable à cet élu.","Elles obligent les journalistes à rompre toutes leurs relations locales pour préserver l'indépendance.","Elles permettent de contrôler les informations malgré la proximité des sources.","Elles rendent inutile toute critique, puisque les informations ont été obtenues par un contact régulier."],"passage":"Un journal local entretient des relations régulières avec les acteurs qu'il couvre. Cette proximité facilite l'accès aux informations, mais peut rendre une critique délicate. L'équipe formalise ses règles pour préserver une indépendance qui ne dépend pas de l'absence totale de contacts. Le journal souhaite que la confiance se construise sur des pratiques visibles, pas seulement sur l'affirmation générale de son indépendance dans une présentation officielle. Une journaliste connaît depuis longtemps les responsables municipaux, ce qui facilite les entretiens. Pour examiner un contrat contesté, elle conserve les documents et les critères de vérification accessibles à ses collègues.","question":"Pourquoi les règles éditoriales explicites comptent-elles dans un contexte de proximité ?","explanation":"La proximité peut aider l'accès tout en créant un risque; des règles vérifiables protègent le jugement. C. B/A/D exagèrent ou nient ce risque."},{"number":34,"points":26,"correct":"B","options":["Une correction doit nécessairement remplacer toutes les archives, même lorsqu'elles documentent le changement.","La correction reste peu utile si les lecteurs initiaux ne la voient pas.","Le public n'accorde jamais d'attention à une information rectifiée dans le même média.","La correction devient moins vraie lorsqu'elle circule après l'article auquel elle répond."],"passage":"Une correction atteint souvent moins de lecteurs que le message initial. Des journalistes réfléchissent donc à la manière de la diffuser auprès du même public. Reconnaître l'erreur constitue une étape ; réparer son effet demande aussi de regarder sa circulation. Elle vérifiera la visibilité du correctif, plutôt que considérer le travail terminé dès qu'une note exacte a été placée dans une rubrique peu consultée. Un correctif discret est publié en fin de journée, mais l'article erroné continue de circuler sous forme de captures d'écran. La rédaction cherche à signaler la correction aux lecteurs exposés au message initial.","question":"Pourquoi publier une note exacte sur une page peu consultée ne règle-t-il pas entièrement l'erreur ?","explanation":"La réparation dépend de la diffusion auprès du public déjà exposé. B; A/D/C sont des affirmations non étayées."},{"number":35,"points":26,"correct":"C","options":["Le témoignage situe la tendance sur le terrain et permet d'en déduire combien de résidents vivent la même situation.","La carte établit le phénomène général tandis que le témoignage en confirme directement l'ampleur dans le quartier.","Les chiffres situent une tendance et le témoignage illustre un effet particulier.","La carte et le récit donnent deux estimations quantitatives de la même tendance qui peuvent être additionnées."],"passage":"Une enquête associe cartes, témoignages et documents. Aucun support n'épuise le sujet : les chiffres situent une tendance, tandis qu'un récit montre ses conséquences dans une vie. Leur combinaison devient utile si le lecteur comprend ce que chaque élément permet réellement d'affirmer. Le lecteur peut ainsi comprendre comment les éléments se complètent, sans attribuer à une histoire singulière la représentativité d'une enquête ni aux nombres la précision d'un récit individuel. Une carte signale une hausse de fréquentation, tandis qu'un habitant raconte comment cette évolution affecte son trajet. Le journaliste précise qu'un seul témoignage ne mesure pas la proportion d'habitants touchés.","question":"Quelle lecture combine correctement les deux sources ?","explanation":"C distingue la portée de la carte et celle du témoignage individuel. A et B infèrent une représentativité non mesurée par le récit; D traite un récit qualitatif comme une seconde estimation numérique."},{"number":36,"points":33,"correct":"B","options":["L'obligation d'obtenir davantage de documents de référence avant d'inviter des personnes non représentées.","La confusion entre visibilité médiatique et pertinence des personnes touchées par la décision.","La tendance à sélectionner les groupes qui comptent le plus de membres, sans examiner leur rapport au problème.","La difficulté de comparer les expériences des participants lorsque chacun intervient dans un cadre médiatique différent."],"passage":"Une rédaction veut représenter équitablement un débat. Elle invite les acteurs les plus visibles, puis découvre que certains habitants directement concernés ne disposent d'aucun porte-parole organisé. La visibilité publique n'est pas une mesure suffisante de l'importance d'un point de vue dans une situation. Les journalistes vont rechercher ces personnes avec des relais locaux et proposer plusieurs façons de répondre. Certaines ne souhaitent pas intervenir sur un plateau mais peuvent expliquer leur expérience dans un autre cadre. La rédaction veut éviter que son calendrier et ses habitudes de contact ne déterminent seuls les voix entendues. Les acteurs déjà présents ne seront pas écartés pour autant. Le dossier sera construit à partir des intérêts en jeu et des personnes concernées, plutôt qu'à partir d'une liste de porte-parole faciles à joindre et habitués à parler dans les médias. Les invités habituels sont facilement joignables, mais les travailleurs concernés par le nouveau règlement n'ont pas d'organisation qui les représente. Le journal prévoit des entretiens hors studio pour entendre leurs expériences.","question":"Quel biais de sélection la rédaction tente-t-elle de corriger ?","explanation":"B désigne le biais de visibilité médiatique, qui écarte des personnes directement touchées. A confond vérification et sélection; C remplace visibilité par taille des groupes; D évoque une question de comparaison, non l'absence de voix."},{"number":37,"points":33,"correct":"B","options":["Une sélection de sujet ne peut être jugée rigoureuse que si la rédaction ne rend pas publics ses critères.","Discuter des priorités éditoriales sans réduire les faits à des opinions.","La transparence des priorités éditoriales rend secondaires les preuves citées pour établir les faits.","L'existence de sources vérifiables garantit que la sélection des sujets ne reflète aucune priorité éditoriale."],"passage":"Un média explique ses choix de sujets. Certains lecteurs y voient un aveu de subjectivité qui invaliderait toute information. La rédaction répond que sélectionner est inévitable, mais que les critères peuvent être discutés et les faits vérifiés. Reconnaître un point de vue de travail ne revient pas à déclarer que toutes les affirmations se valent. Elle présente les critères qui l'ont conduite à suivre un événement et les moyens utilisés pour vérifier les informations. Les lecteurs peuvent contester ces choix ou proposer des sujets absents. La rédaction souhaite conserver cette discussion sans confondre critique des priorités et rejet de toute possibilité d'établir des faits. Certaines questions restent ouvertes, d'autres peuvent recevoir des réponses mieux appuyées que de simples impressions. Les sources restent consultables. Le média explique pourquoi il suit un conflit local et met à disposition les documents qu'il cite. Des lecteurs peuvent discuter du choix du sujet, tout en vérifiant séparément si un fait précis est étayé.","question":"Quel rapport la rédaction établit-elle entre sélection éditoriale et vérification ?","explanation":"B sépare la discussion des priorités et la vérification des faits. A et D attribuent à la sélection des propriétés infondées; C rend les preuves secondaires alors qu'elles sont maintenues."},{"number":38,"points":33,"correct":"A","options":["Elle présentait comme générale une offre dont des conditions déterminent la possibilité d'en bénéficier.","Elle transformait une condition administrative secondaire en une restriction décisive dont le public ne pouvait comprendre l'origine.","Elle risquait de décourager les lecteurs en donnant trop de place à des critères géographiques clairement définis.","Elle présentait une offre trop limitée alors que les possibilités d'inscription étaient plus larges que prévu."],"passage":"Une campagne de communication cherche un message très simple. Les responsables retirent successivement les réserves jusqu'à produire une promesse plus forte que le projet réel. La clarté devient trompeuse lorsqu'elle efface précisément les conditions qui déterminent la validité de ce qu'elle annonce. L'équipe compare la formule finale aux engagements réellement possibles et réintroduit les limites importantes. Elle veut garder un message lisible, mais aussi permettre au destinataire de savoir si l'offre correspond à sa situation. Des exemples courts peuvent parfois être plus utiles qu'une promesse très large suivie d'une longue liste de réserves difficiles à trouver. Le projet sera donc présenté avec ses conditions principales au même endroit. La communication ne remplace pas la réalisation, mais elle influence les attentes à partir desquelles les personnes jugeront ensuite ce qui a effectivement été fait. Le message publicitaire initial annonce « disponible pour tous ». Le service est en réalité réservé aux résidents de trois communes à certaines dates. L'équipe réintroduit ces conditions à proximité de l'annonce.","question":"Quelle erreur la version initiale du message risquait-elle de produire ?","explanation":"A constate qu'une promesse générale omettait des critères d'accès essentiels. B minimise faussement ces critères, C suppose qu'ils étaient détaillés, D inverse l'écart entre annonce et offre réelle."},{"number":39,"points":33,"correct":"B","options":["Les réactions initiales sont un indicateur de valeur éditoriale fiable, mais elles doivent être ajustées au nombre de consultations différées.","L'intérêt durable peut échapper au classement initial, sans que ces observations prouvent l'effet qu'aurait eu un autre algorithme sur l'audience.","Les partages tardifs démontrent que l'algorithme a volontairement réduit la visibilité de la seconde enquête, malgré un intérêt du public supérieur.","Les lectures achevées établissent que les utilisateurs préfèrent toujours les textes complexes aux contenus qui reçoivent des réactions immédiates."],"passage":"Les plateformes recommandent souvent des contenus suscitant une réaction rapide. Une enquête complexe demande au contraire du temps avant de produire une conclusion. Évaluer tous les contenus par la réaction immédiate risque de défavoriser des formes d'information dont l'intérêt apparaît au cours d'une lecture attentive. Le média expérimente des présentations qui aident à entrer dans ces sujets sans les réduire à une formule provocante. Il observe aussi les lectures achevées et les retours plus tardifs. Les responsables souhaitent éviter qu'un travail utile mais lent à produire une réaction soit systématiquement moins visible. Ils ne demandent pas d'ignorer l'intérêt du public. Ils cherchent d'autres manières de le comprendre, en tenant compte du temps nécessaire pour découvrir une question complexe. Les choix de recommandation doivent ainsi être discutés avec les effets qu'ils produisent sur les informations accessibles, pas seulement avec le nombre de clics obtenus dans les premières secondes. Une enquête soigneusement vérifiée reçoit peu de clics le premier jour mais est largement lue et discutée les semaines suivantes. Les responsables envisagent un indicateur de lecture achevée et des retours différés. Le média suit ensuite deux enquêtes comparables publiées à un mois d'intervalle. La première reçoit beaucoup de réactions dans les deux premières heures, puis presque aucune lecture menée jusqu'au bout. La seconde reçoit peu de réactions initiales, mais ses lectures achevées progressent pendant trois semaines et plusieurs associations la citent lors de réunions publiques. Les responsables observent aussi que certaines visites tardives proviennent de partages entre lecteurs et non des recommandations automatiques. Ils ne disposent pas d'une expérience où le même article aurait été recommandé selon deux règles différentes. Ils évitent donc de présenter la seconde enquête comme la preuve qu'un autre algorithme augmenterait nécessairement son audience. Ils veulent plutôt savoir si l'indicateur retenu pour classer les articles capture la forme d'attention qu'ils cherchent à favoriser, au lieu de confondre toute consultation tardive avec une réaction immédiate manquée.","question":"Que montre le rapprochement des deux enquêtes, et quelle conclusion serait excessive ?","explanation":"B combine deux constats séparés: les réactions immédiates ne rendent pas compte des lectures achevées et des citations ultérieures, et l'absence d'essai contrôlé interdit d'affirmer quel aurait été l'effet d'un autre classement. A maintient la fiabilité de l'indicateur initial non établie; C attribue intention et causalité à l'algorithme sans preuve; D généralise une comparaison de deux enquêtes à une préférence universelle."}]}$paper_14$::jsonb),
('tcf-reading-15','tcf-reading-2026-11-close-reading-v4',$paper_15${"id":"tcf-reading-15","title":"TCF Reading · Test 15","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"D","options":["Un remboursement sans ticket","Un échange sans limite de temps","Une reprise par n'importe quel magasin","Un échange sous conditions"],"passage":"Les articles soldés peuvent être échangés pendant quinze jours avec le ticket. Cette offre ne prévoit pas de remboursement.\n\nL'article doit être rapporté dans son état d'origine. Le personnel vérifiera les conditions indiquées sur le document remis au moment de l'achat.","question":"Quelle possibilité est annoncée ?","explanation":"Le passage indique : « Les articles soldés peuvent être échangés pendant quinze jours avec le ticket. Cette offre ne prévoit pas de remboursement. » Cela justifie la réponse : Un échange sous conditions."},{"number":2,"points":3,"correct":"A","options":["Le prix doit être recalculé","Le devis initial s'applique toujours","Le service devient gratuit","Le délai disparaît"],"passage":"Le devis reste valable trente jours. Toute modification de la demande donnera lieu à un nouveau calcul.\n\nLe client recevra les nouvelles conditions avant toute intervention.","question":"Que se passe-t-il si la demande change ?","explanation":"Le passage indique : « Le devis reste valable trente jours. Toute modification de la demande donnera lieu à un nouveau calcul. » Cela justifie la réponse : Le prix doit être recalculé."},{"number":3,"points":3,"correct":"D","options":["Chez un commerçant voisin","À la caisse principale obligatoirement","Dans l'atelier fermé","À l'arrière du magasin"],"passage":"Le retrait des commandes se fait derrière le magasin. L'accueil principal reste réservé aux achats sur place.\n\nUn panneau indiquera l'accès depuis le parking. Présentez la confirmation reçue pour que l'équipe retrouve les articles déjà préparés à votre nom.","question":"Où retirer une commande ?","explanation":"Le passage indique : « Le retrait des commandes se fait derrière le magasin. L'accueil principal reste réservé aux achats sur place. » Cela justifie la réponse : À l'arrière du magasin."},{"number":4,"points":3,"correct":"C","options":["Remplacer lui-même toutes les pièces","Envoyer une publicité","Accepter ou refuser le devis","Venir chercher une commande déjà achevée"],"passage":"La réparation est suspendue en attendant votre accord sur le devis. Aucune pièce supplémentaire ne sera commandée avant votre réponse.\n\nLe réparateur vous indiquera ensuite le délai, selon votre choix et la disponibilité des pièces.","question":"Quelle action est attendue du client ?","explanation":"Le passage indique : « La réparation est suspendue en attendant votre accord sur le devis. Aucune pièce supplémentaire ne sera commandée avant votre réponse. » Cela justifie la réponse : Accepter ou refuser le devis."},{"number":5,"points":9,"correct":"B","options":["Payer nécessairement le moins cher sur douze mois","Limiter la durée d'engagement","Obtenir un contrat définitif","Éviter toute facture"],"passage":"J'ai choisi l'abonnement mensuel, même s'il coûte plus cher sur un an. Je ne sais pas encore combien de temps j'utiliserai le service.\n\nJe pourrai passer à une formule plus longue lorsque mon emploi du temps sera stabilisé. Pour le moment, je préfère garder la possibilité d'arrêter sans payer toute une année.","question":"Pourquoi ce choix est-il fait ?","explanation":"Le passage indique : « J'ai choisi l'abonnement mensuel, même s'il coûte plus cher sur un an. Je ne sais pas encore combien de temps j'utiliserai le service. » Cela justifie la réponse : Limiter la durée d'engagement."},{"number":6,"points":9,"correct":"B","options":["Une livraison gratuite à l'étranger","Un délai de retrait prolongé","Une annulation automatique","Un achat supplémentaire obligatoire"],"passage":"Votre colis est arrivé dans un autre point de retrait. Vous disposez de deux jours supplémentaires pour le récupérer.\n\nLe message précise l'adresse et les nouveaux horaires. Merci de vérifier ces informations avant de vous déplacer au lieu que vous utilisez habituellement.","question":"Quelle adaptation est proposée ?","explanation":"Le passage indique : « Votre colis est arrivé dans un autre point de retrait. Vous disposez de deux jours supplémentaires pour le récupérer. » Cela justifie la réponse : Un délai de retrait prolongé."},{"number":7,"points":9,"correct":"A","options":["L'ensemble des frais liés au contrat","Le nombre de publicités","La couleur du matériel","Le prix du premier mois uniquement"],"passage":"Je veux comparer le coût total, pas seulement la première mensualité. Peux-tu vérifier les frais d'installation et de résiliation ?\n\nUne petite différence annoncée peut devenir importante sur plusieurs mois. J'aimerais donc noter les conditions dans le même tableau avant de comparer les deux offres proposées.","question":"Quelle information est recherchée ?","explanation":"Le passage indique : « Je veux comparer le coût total, pas seulement la première mensualité. Peux-tu vérifier les frais d'installation et de résiliation ? » Cela justifie la réponse : L'ensemble des frais liés au contrat."},{"number":8,"points":9,"correct":"C","options":["Venir sans signaler son besoin","Attendre la fin de la réparation","Demander le prêt dès le dépôt","Acheter un appareil neuf obligatoirement"],"passage":"La boutique prête un appareil pendant certaines réparations. Signalez ce besoin lors du dépôt ; le stock est limité.\n\nLe prêt ne sera pas automatiquement possible pour chaque modèle ou à toutes les périodes de l'année.","question":"Que doit faire le client intéressé ?","explanation":"Le passage indique : « La boutique prête un appareil pendant certaines réparations. Signalez ce besoin lors du dépôt ; le stock est limité. » Cela justifie la réponse : Demander le prêt dès le dépôt."},{"number":9,"points":9,"correct":"D","options":["Commander trois tailles","Produire sans connaître les dimensions","Attendre le retour de tous les clients","Mesurer avant fabrication"],"passage":"Merci de ne pas commander deux tailles pour notre atelier de fabrication sur mesure. Nous pouvons organiser une prise de mesures avant de lancer la production.\n\nUn conseiller vous expliquera les étapes et les délais.","question":"Quelle solution évite les commandes multiples ?","explanation":"Le passage indique : « Merci de ne pas commander deux tailles pour notre atelier de fabrication sur mesure. Nous pouvons organiser une prise de mesures avant de lancer la production. » Cela justifie la réponse : Mesurer avant fabrication."},{"number":10,"points":9,"correct":"C","options":["Une suppression de la main-d'œuvre","Une hausse automatique","Une présentation plus détaillée","Une réduction des fournitures"],"passage":"La facture distingue maintenant les fournitures et la main-d'œuvre. Le montant total ne change pas.\n\nLes clients pourront poser une question sur chaque rubrique. Le service souhaite rendre le document plus facile à comprendre sans modifier les conditions du travail déjà convenu.","question":"Quel changement est annoncé ?","explanation":"Le passage indique : « La facture distingue maintenant les fournitures et la main-d'œuvre. Le montant total ne change pas. » Cela justifie la réponse : Une présentation plus détaillée."},{"number":11,"points":15,"correct":"A","options":["L'historique des réparations effectuées","La liste des anciens utilisateurs","Une promesse de fonctionnement éternel","Le prix de tous les objets neufs"],"passage":"Une coopérative répare les objets avant de les revendre. Les clients reçoivent une description des interventions réalisées.\n\nLes intervenants indiquent les pièces remplacées et les limites éventuelles du matériel. L'acheteur peut ainsi demander une précision avant de décider. La coopérative veut distinguer une remise en état vérifiée d'un objet simplement présenté comme une bonne affaire. Les bénévoles gardent une trace des contrôles et expliquent les conditions du service après la vente. Ils ne promettent pas qu'un produit d'occasion sera identique à un appareil neuf, mais souhaitent que la comparaison repose sur des informations suffisamment claires pour les personnes intéressées.","question":"Quelle information accompagne la vente ?","explanation":"Le passage indique : « Une coopérative répare les objets avant de les revendre. Les clients reçoivent une description des interventions réalisées. » Cela justifie la réponse : L'historique des réparations effectuées."},{"number":12,"points":15,"correct":"B","options":["Comparer uniquement les couleurs","Faciliter une comparaison homogène","Éviter de montrer les prix","Garantir que la plus grosse bouteille coûte moins cher"],"passage":"Un magasin affiche le prix à l'unité et au litre. Cela permet de comparer des bouteilles de contenances différentes.\n\nLe personnel peut montrer où lire cette indication sur les étiquettes. Le magasin utilise la même base pour éviter que les clients comparent seulement le prix placé en grands caractères. Le format le plus économique dépend aussi de la quantité réellement utilisée. Une grande bouteille n'est donc pas présentée comme toujours préférable.","question":"Quel objectif poursuit cet affichage ?","explanation":"Le passage indique : « Un magasin affiche le prix à l'unité et au litre. Cela permet de comparer des bouteilles de contenances différentes. » Cela justifie la réponse : Faciliter une comparaison homogène."},{"number":13,"points":15,"correct":"D","options":["L'association signe tous les contrats","Tous les fournisseurs sont exclus","Le consommateur doit changer d'offre","La décision reste au consommateur"],"passage":"Une association aide à lire les contrats, sans choisir un fournisseur à la place du consommateur.\n\nLes conseillers expliquent les termes et aident à repérer les frais annoncés. Ils peuvent aussi proposer une liste de questions à adresser au fournisseur. Le service ne connaît pas forcément tous les besoins personnels et ne transforme pas son accompagnement en vente d'une offre particulière. Les personnes restent libres de poursuivre leur comparaison après la rencontre. L'association souhaite surtout que la signature corresponde à une décision comprise, plutôt qu'à un accord donné rapidement parce que le document semblait trop complexe pour être examiné ou discuté avant l'engagement.","question":"Quelle est la limite de l'accompagnement ?","explanation":"Le passage indique : « Une association aide à lire les contrats, sans choisir un fournisseur à la place du consommateur. » Cela justifie la réponse : La décision reste au consommateur."},{"number":14,"points":15,"correct":"B","options":["L'autorisation du client n'a aucun rôle","Tout n'est pas inclus dans le forfait","Le forfait interdit les interventions","Chaque réparation est nécessairement gratuite"],"passage":"Une entreprise vend un service d'entretien annuel. Les interventions supplémentaires sont facturées séparément et doivent être autorisées.\n\nLes clients recevront une fiche avec les opérations habituelles comprises dans l'abonnement. Une intervention inhabituelle fera l'objet d'une proposition précisant le travail et son montant. L'entreprise veut éviter une confusion entre un service régulier et une prise en charge illimitée de tout incident. Le bilan de l'année indiquera aussi les demandes les plus fréquentes, afin de voir si la formule correspond bien aux usages réels ou si elle doit être revue pour rester compréhensible et utile.","question":"Quelle information est importante ?","explanation":"Le passage indique : « Une entreprise vend un service d'entretien annuel. Les interventions supplémentaires sont facturées séparément et doivent être autorisées. » Cela justifie la réponse : Tout n'est pas inclus dans le forfait."},{"number":15,"points":15,"correct":"C","options":["Supprimer toutes les réservations","Acheter une machine pour chaque heure","Mieux utiliser un équipement commun","Réduire les compétences nécessaires"],"passage":"Un atelier partage une machine coûteuse entre plusieurs professionnels. Les horaires sont coordonnés pour réduire les temps inutilisés.\n\nLes utilisateurs réservent des plages et signalent leurs besoins avant les périodes les plus chargées. Le collectif souhaite éviter qu'une machine accessible en principe soit presque toujours indisponible au moment où chacun en a besoin. Les horaires seront donc réexaminés après les premiers mois. Le projet ne consiste pas seulement à répartir un prix d'achat, mais à organiser un équipement capable de servir correctement plusieurs activités dans la durée, avec des responsabilités connues de toutes les personnes concernées.","question":"Quel avantage économique est recherché ?","explanation":"Le passage indique : « Un atelier partage une machine coûteuse entre plusieurs professionnels. Les horaires sont coordonnés pour réduire les temps inutilisés. » Cela justifie la réponse : Mieux utiliser un équipement commun."},{"number":16,"points":15,"correct":"A","options":["Un nettoyage inclus","Un achat définitif","La possibilité de découper le vêtement","Une fabrication sur mesure automatique"],"passage":"Une boutique propose la location d'une tenue de cérémonie. Le nettoyage est compris, mais les retouches personnelles sont interdites.\n\nLe personnel vérifie l'état du vêtement au départ et au retour avec le client. Il explique les précautions et les accessoires fournis. Une demande particulière doit être discutée avant la réservation, car le même article sera ensuite porté par d'autres personnes. La boutique souhaite offrir une solution ponctuelle sans laisser croire qu'une location donne tous les droits d'un achat.","question":"Que peut attendre le client ?","explanation":"Le passage indique : « Une boutique propose la location d'une tenue de cérémonie. Le nettoyage est compris, mais les retouches personnelles sont interdites. » Cela justifie la réponse : Un nettoyage inclus."},{"number":17,"points":15,"correct":"A","options":["Identifier la cause avant d'engager une dépense","Changer immédiatement tout l'appareil","Vendre uniquement du matériel neuf","Garantir une panne précise sans examen"],"passage":"Un réparateur refuse un remplacement coûteux avant d'avoir vérifié une panne simple. Il explique les étapes du diagnostic.\n\nIl décrit les observations nécessaires et indique le coût du premier examen. Les clients peuvent ensuite décider s'ils souhaitent poursuivre. Le professionnel veut éviter qu'une solution techniquement possible soit choisie avant que son utilité soit appréciée. Certains défauts demandent une intervention importante, d'autres une vérification plus simple. Le service conserve une trace des échanges pour que les opérations réalisées correspondent à ce qui a été expliqué.","question":"Quelle démarche adopte-t-il ?","explanation":"Le passage indique : « Un réparateur refuse un remplacement coûteux avant d'avoir vérifié une panne simple. Il explique les étapes du diagnostic. » Cela justifie la réponse : Identifier la cause avant d'engager une dépense."},{"number":18,"points":15,"correct":"D","options":["Garantir l'absence de toute facture","Payer un service déjà terminé uniquement","Supprimer le montant final","Financer une partie de la préparation"],"passage":"Une entreprise demande un acompte pour acheter les matériaux. Le solde sera payé après la livraison convenue.\n\nLe document précise le calendrier, les matériaux concernés et les étapes qui restent à réaliser. L'entreprise souhaite expliquer pourquoi une somme est demandée alors que l'objet n'a pas encore été livré. Les conditions d'une modification ou d'un abandon seront indiquées avant le versement, afin que les personnes sachent quels engagements elles prennent et quelles questions poser si la préparation ne peut pas avancer comme prévu.","question":"À quoi sert l'acompte ?","explanation":"Le passage indique : « Une entreprise demande un acompte pour acheter les matériaux. Le solde sera payé après la livraison convenue. » Cela justifie la réponse : Financer une partie de la préparation."},{"number":19,"points":15,"correct":"A","options":["Le contrôle ne garantit pas tous les aspects techniques","Aucune observation n'est réalisée","Les objets sont tous neufs","Le prix assure automatiquement la sécurité"],"passage":"Le marché d'occasion organise un contrôle visuel des objets électriques. Les organisateurs précisent qu'il ne remplace pas une vérification technique complète.\n\nLes bénévoles regardent les signes de dommage visibles et les informations présentes sur l'appareil. Ils orientent les cas douteux vers un professionnel et refusent de promettre une sécurité complète sur cette seule base. Le marché souhaite réduire les risques sans transformer une inspection rapide en certification. Les acheteurs sont invités à demander les limites du contrôle et à vérifier l'adaptation de l'objet à leur usage.","question":"Quelle limite est reconnue ?","explanation":"Le passage indique : « Le marché d'occasion organise un contrôle visuel des objets électriques. Les organisateurs précisent qu'il ne remplace pas une vérification technique complète. » Cela justifie la réponse : Le contrôle ne garantit pas tous les aspects techniques."},{"number":20,"points":21,"correct":"A","options":["L'adéquation entre quantité achetée et besoin","La musique diffusée","Le nombre de caisses du magasin","La taille de l'affiche"],"passage":"Une promotion propose un prix bas pour trois articles. Un conseiller rappelle que l'économie n'existe que si l'acheteur utilise réellement ces quantités. Une personne vivant seule pourra préférer un article à l'unité, même si le prix annoncé pour un lot semble plus avantageux. Le conseiller propose de comparer le montant total et la consommation prévue. Il souhaite éviter que le mot promotion suffise à faire acheter une quantité sans rapport avec les habitudes. Les dates et les possibilités de conservation restent des informations utiles pour apprécier la proposition dans chaque foyer.","question":"Quelle condition faut-il examiner ?","explanation":"Le passage indique : « Une promotion propose un prix bas pour trois articles. Un conseiller rappelle que l'économie n'existe que si l'acheteur utilise réellement ces quantités. » Cela justifie la réponse : L'adéquation entre quantité achetée et besoin."},{"number":21,"points":21,"correct":"B","options":["Un retrait obligatoire à l'usine","Moins de rapidité contre une meilleure organisation","Une suppression de tous les délais","Une livraison immédiate garantie partout"],"passage":"Une entreprise baisse ses coûts de livraison en regroupant les commandes. Elle annonce des délais moins rapides mais plus prévisibles. L'entreprise explique pourquoi elle ne promet plus un départ immédiat après chaque commande. Les économies réalisées seront suivies avec les retards et les difficultés de regroupement. Le service veut éviter qu'un gain pour sa propre organisation se traduise par une attente mal expliquée ou par une obligation pour les clients de rester disponibles sans connaître un créneau de réception.","question":"Quel compromis est proposé ?","explanation":"Le passage indique : « Une entreprise baisse ses coûts de livraison en regroupant les commandes. Elle annonce des délais moins rapides mais plus prévisibles. » Cela justifie la réponse : Moins de rapidité contre une meilleure organisation."},{"number":22,"points":21,"correct":"C","options":["Vendre tous les objets au même prix","Abandonner son propre atelier","Participer à la tenue de la boutique","Refuser les nouveaux clients"],"passage":"Des artisans créent une boutique collective. Les ventes soutiennent chacun, mais la permanence est partagée selon un calendrier commun. Les membres s'engagent sur des créneaux compatibles avec leur travail de production. Une personne de remplacement pourra être prévue lorsque plusieurs marchés ont lieu le même jour. Les résultats seront discutés à partir des ventes et du temps réellement consacré au lieu, afin de savoir si la coopération apporte un avantage soutenable à chacun plutôt qu'un surcroît de tâches mal réparti.","question":"Quelle obligation accompagne cette organisation ?","explanation":"Le passage indique : « Des artisans créent une boutique collective. Les ventes soutiennent chacun, mais la permanence est partagée selon un calendrier commun. » Cela justifie la réponse : Participer à la tenue de la boutique."},{"number":23,"points":21,"correct":"C","options":["Le nombre de slogans","La date des publicités","La possibilité d'entretenir le produit","Le volume de l'emballage seulement"],"passage":"Un client compare deux produits de prix proches. Celui dont les pièces sont disponibles longtemps pourrait coûter moins cher à l'usage, même si l'achat initial est légèrement supérieur. Le client se renseigne sur les références et les délais de commande. Il cherche aussi à savoir si l'appareil peut être ouvert avec un outillage courant. Les documents disponibles lui permettront de comparer des situations possibles, sans garantir à l'avance qu'aucune panne ne surviendra. Son choix repose sur plusieurs dépenses probables au cours du temps.","question":"Quel critère complète le prix d'achat ?","explanation":"Le passage indique : « Un client compare deux produits de prix proches. Celui dont les pièces sont disponibles longtemps pourrait coûter moins cher à l'usage, même si l'achat initial est légèrement supérieur. » Cela justifie la réponse : La possibilité d'entretenir le produit."},{"number":24,"points":21,"correct":"D","options":["Interdire la monnaie habituelle","Supprimer les prix","Obliger tous les magasins à participer","Soutenir certains échanges de proximité"],"passage":"Une commune teste une monnaie locale auprès de commerces volontaires. L'objectif est de favoriser les échanges dans le réseau, pas de remplacer tous les moyens de paiement. Les participants reçoivent une information sur les lieux acceptant le dispositif et les modalités de fonctionnement. Les organisateurs veulent observer les achats effectivement réalisés dans le réseau, sans confondre inscriptions et échanges. Les commerçants restent libres de participer selon les règles annoncées.","question":"Quelle ambition est précisée ?","explanation":"Le passage indique : « Une commune teste une monnaie locale auprès de commerces volontaires. L'objectif est de favoriser les échanges dans le réseau, pas de remplacer tous les moyens de paiement. » Cela justifie la réponse : Soutenir certains échanges de proximité."},{"number":25,"points":21,"correct":"C","options":["Toute annulation produit exactement la même perte quel que soit le moment où elle intervient.","Le paiement d'une pénalité garantit qu'un nouveau client reprendra automatiquement la place libre.","Le créneau annulé trop tard risque de rester inutilisé malgré une demande.","La pénalité remplace l'obligation de communiquer les conditions avant la réservation."],"passage":"Un service de réservation facture une annulation tardive. Il explique cette règle avant paiement, car le créneau ne peut pas toujours être attribué à un autre client. Les clients peuvent annuler sans frais jusqu'à une limite clairement annoncée. Au-delà, le prestataire examine les conditions prévues au contrat. Il souhaite éviter que plusieurs rendez-vous restent inutilisés alors que d'autres personnes attendent une place. Les responsables vérifieront cependant que la règle est visible et comprise avant la confirmation. Deux clients annulent à 24 heures d'intervalle; seul le premier reste dans le délai gratuit, car la place du second n'a plus pu être proposée à temps. Le service affiche la limite lors du choix du créneau.","question":"Quelle justification de la facturation tardive ressort de la règle ?","explanation":"La limite vise le risque de perte d'un créneau non réattribué. C; A/D/B généralisent ou inversent les conditions."},{"number":26,"points":21,"correct":"C","options":["Elle oblige les clients à reconnaître que chaque poste de coût a augmenté dans la même proportion.","Elle remplace toute possibilité de comparaison puisque les dépenses ont été détaillées.","Elle rend les motifs évaluables sans imposer aux clients l'acceptation de la décision tarifaire.","Elle élimine la hausse dès lors que les raisons sont comprises par les acheteurs."],"passage":"Une entreprise annonce une hausse de prix et décrit les coûts concernés. Certains clients restent mécontents, mais peuvent comparer les raisons données plutôt que découvrir un montant sans explication. Les explications distinguent les éléments durables des variations temporaires. Le commerce ne demande pas aux clients d'accepter toute décision parce qu'un motif est présenté. Il souhaite leur donner des repères pour juger si l'offre reste adaptée à leur budget et à leurs besoins. Le fournisseur détaille une hausse liée au transport et une autre à un matériau devenu plus cher. Un client accepte la première justification mais envisage une offre concurrente; le commerçant ne considère pas cette décision comme une erreur.","question":"Quel rôle l'explication des coûts joue-t-elle dans la relation commerciale ?","explanation":"Les motifs donnent des repères sans garantie de satisfaction ou d'adhésion. C. A/D/B imposent des conséquences non dites."},{"number":27,"points":21,"correct":"D","options":["L'absence de tout client ayant récemment acheté un produit malgré le grand nombre d'avis.","L'écart entre le nombre de produits disponibles et celui des notes recueillies.","Le manque de précisions sur les avis les plus tranchés, qui devraient être exclus des résultats.","Le surpoids des clients particulièrement satisfaits ou mécontents parmi les réponses spontanées."],"passage":"Une étude de satisfaction reçoit surtout les réponses des clients très contents ou très déçus. Le commerce ajoute des entretiens courts avec des acheteurs ordinaires. Les enquêteurs demandent aux personnes comment s'est déroulé un achat récent, sans les choisir uniquement à partir d'une note déjà publiée. Le commerce souhaite conserver les critiques et les compliments, mais savoir aussi comment ils se répartissent parmi les clients. Sur cent achats, une poignée de clients laisse des avis extrêmes. Les enquêteurs contactent également des personnes qui n'ont publié aucune note afin de mieux comprendre les expériences moins visibles.","question":"Quel défaut d'échantillonnage l'enquête complémentaire cherche-t-elle à corriger ?","explanation":"Les réponses spontanées sont polarisées; D précise le biais. C/A/B ne représentent pas la situation."},{"number":28,"points":21,"correct":"B","options":["Les annonceurs rémunèrent nécessairement chaque utilisateur en fonction du nombre de messages vus.","L'absence de paiement direct peut correspondre à un financement par l'attention commercialisée aux annonceurs.","L'offre sans abonnement ne donne lieu à aucun échange économique puisqu'elle n'est pas facturée.","L'abonnement finance toute prestation numérique tandis qu'une publicité ne peut financer des fonctions."],"passage":"Une offre gratuite est financée par la publicité. Les utilisateurs ne paient pas directement, mais leur attention intéresse les annonceurs. Il ne souhaite pas que l'absence de paiement direct soit comprise comme l'absence de tout échange économique. Les utilisateurs pourront ainsi apprécier ce qui finance les fonctions proposées, au lieu de devoir déduire le fonctionnement de la seule mention gratuite placée en tête de la présentation commerciale du produit. Deux offres proposent la même fonctionnalité. La première demande un abonnement; la seconde affiche des annonces et mesure l'exposition publicitaire des utilisateurs. Le mot « gratuit » décrit uniquement l'absence de prix payé directement.","question":"Quelle différence doit comprendre l'utilisateur lorsqu'il compare ces deux offres ?","explanation":"Le service est payé par la publicité et l'attention; B. C/A/D lui attribuent des impossibilités ou paiements erronés."},{"number":29,"points":21,"correct":"C","options":["Remplacer les engagements de livraison par une présentation plus séduisante des produits en vitrine.","Rendre impossibles les demandes particulières des clients afin de maintenir un catalogue fixe.","Limiter l'assortiment pour rendre plus fiables les disponibilités annoncées.","Augmenter le nombre d'articles présentés sans vérifier la capacité des fournisseurs à livrer."],"passage":"Un commerçant préfère une petite gamme suivie à un choix très vaste souvent indisponible. Il veut rendre plus fiables les promesses de stock. Les fournisseurs connaissent mieux les quantités et les dates auxquelles le magasin s'engage. Les clients peuvent demander un article particulier, mais la boutique préfère annoncer un délai réaliste plutôt qu'une disponibilité supposée immédiate. Le responsable suivra les commandes non satisfaites pour ajuster la gamme. Sur une ancienne gamme de cinquante produits, douze manquent souvent. La boutique limite désormais son assortiment à trente références pour lesquelles les livraisons sont suivies; les commandes spéciales restent possibles avec un délai annoncé.","question":"Quel arbitrage commercial guide la réduction de l'assortiment ?","explanation":"Le magasin sacrifie la largeur affichée pour la disponibilité crédible. C. D/B/A ignorent stock et délais."},{"number":30,"points":26,"correct":"B","options":["Prendre la dépense maximale imaginable pour chaque produit comme coût certain de tous les clients.","Estimer les dépenses cumulées dans un scénario d'usage explicite, plutôt que s'arrêter au prix initial.","Comparer la durée de garantie sans intégrer la fréquence des consommables utilisés.","Comparer les prix affichés à l'achat, puis attribuer les différences futures à la seule marque."],"passage":"Le coût d'un produit comprend parfois des dépenses reportées : consommables, entretien et remplacement d'accessoires. Un prix de départ attractif ne suffit donc pas à juger une offre. Comparer suppose de définir une durée et des usages vraisemblables. Les utilisateurs peuvent ainsi comparer les offres sur une base plus cohérente. Une estimation restera cependant liée aux hypothèses retenues, qu'il faut rendre lisibles plutôt que présenter comme des dépenses futures certaines pour chaque personne. Un appareil peu cher exige des consommables fréquents, tandis qu'un autre plus coûteux initialement demande peu d'entretien. Le meilleur choix varie selon l'intensité et la durée d'utilisation prévues.","question":"Quel calcul permet une comparaison pertinente des deux appareils ?","explanation":"Le coût total dépend de l'horizon et des usages. B; D/C négligent les coûts, A traite une hypothèse extrême comme certitude."},{"number":31,"points":26,"correct":"B","options":["Il indique que les demandes deviennent moins complexes et nécessitent moins de vérifications.","Il améliore la vitesse d'un échange tout en pouvant dégrader la résolution durable des problèmes.","Il prouve que les salariés ne consacrent plus aucun temps à expliquer leurs réponses.","Il établit que le nombre de clients servis diminue, quelle que soit la fréquence des rappels."],"passage":"Une entreprise mesure le service client par la durée moyenne des appels. Les employés raccourcissent les échanges, mais les mêmes personnes rappellent davantage. L'amélioration apparente d'un indicateur peut donc masquer une résolution moins efficace des problèmes. L'entreprise ajoute donc le nombre de demandes résolues sans rappel à son suivi. Elle souhaite que les salariés puissent prendre le temps utile, sans confondre rapidité de l'échange et qualité du résultat obtenu pour le client. La durée moyenne passe de six à quatre minutes, mais la part des problèmes réglés au premier appel baisse et les rappels doublent. Le directeur ajoute un suivi de résolution sur plusieurs jours.","question":"Pourquoi le raccourcissement des appels peut-il tromper sur le progrès du service ?","explanation":"Les appels courts cachent parfois des dossiers non résolus. B; A/C/D ne suivent pas des données."},{"number":32,"points":26,"correct":"C","options":["La promesse d'une rémunération satisfaisante quel que soit le niveau de production.","La présentation d'un logo reconnaissable, sans information sur les paiements réels.","Les mécanismes du prix peuvent être examinés plutôt qu'un slogan.","La fréquence de répétition du mot « équitable » dans les publicités adressées aux clients."],"passage":"Un magasin affirme pratiquer des prix équitables. Pour rendre l'engagement compréhensible, il explique la répartition du prix entre production, transport et distribution. Une formule valorisante devient plus informative lorsqu'elle renvoie à des éléments que l'on peut examiner. Le magasin mettra ces informations à jour lorsque ses conditions d'achat changent. Il souhaite que les clients puissent poser des questions précises, au lieu de devoir accepter une formule générale qui paraît positive sans expliquer ce qu'elle garantit réellement. Deux magasins revendiquent une rémunération équitable des producteurs. L'un publie des parts de prix et leur évolution, tandis que l'autre ne communique qu'un slogan. Le premier laisse au client des éléments pour vérifier la portée de sa promesse.","question":"Quelle propriété distingue l'engagement le plus vérifiable ?","explanation":"Les éléments chiffrés et mis à jour permettent une vérification. C; D/B/A n'apportent pas les preuves décrites."},{"number":33,"points":26,"correct":"D","options":["Le service ne présente d'intérêt que si tous les utilisateurs habitent exactement à la même distance.","La durée de vie du matériel ne joue aucun rôle lorsque plusieurs personnes peuvent emprunter le même objet.","Un équipement partagé est nécessairement plus polluant dès que les membres effectuent des trajets.","La réduction effective des achats et les coûts de transport ou d'entretien doivent être comparés dans l'usage réel."],"passage":"Un service de location réduit l'achat individuel d'équipements rarement utilisés. Son intérêt dépend toutefois de la durée de vie du matériel et des déplacements nécessaires. Le partage constitue une possibilité d'économie, pas une garantie indépendante de son organisation. Les responsables regardent les prêts achevés, les réparations et les trajets nécessaires. Cette observation permet de distinguer une intention de partage et une organisation qui remplace effectivement des achats individuels dans les conditions ordinaires d'utilisation. Un outil partagé remplace plusieurs achats individuels, mais son transport augmente après l'ouverture de nouveaux points de retrait. L'association mesure les trajets, la durée de vie et le nombre d'achats effectivement évités.","question":"Pourquoi le seul nombre d'adhérents au service ne démontre-t-il pas un bénéfice matériel ?","explanation":"L'effet dépend de remplacements réels et des ressources mobilisées, D. C/B/A abusent des généralisations."},{"number":34,"points":26,"correct":"A","options":["Elle déplace certains achats vers les promotions au lieu d'en créer.","Elle empêche les clients de reconnaître les prochaines campagnes de réduction.","Elle augmente les ventes hors promotion dans la même proportion que les achats réduits.","Elle transforme les achats immédiats en achats récurrents indépendants de tout prix."],"passage":"Une boutique veut fidéliser ses clients par des réductions fréquentes. Certains attendent alors systématiquement la prochaine promotion. Le mécanisme qui devait stimuler l'achat immédiat transforme la perception du prix habituel et peut ralentir les ventes entre deux offres. Elle veut savoir si les offres augmentent réellement les achats ou les déplacent, et comprendre les attentes qu'elles installent chez les clients lorsqu'ils reviennent hors promotion. Les ventes grimpent pendant les semaines de promotion, mais restent faibles entre deux réductions. Les clients interrogés expliquent avoir reporté un achat qu'ils envisageaient au prix habituel.","question":"Quel effet non prévu l'opération commerciale semble-t-elle produire ?","explanation":"Les clients attendent le prochain rabais; A distingue déplacement et création de demande. C/D/B ne cadrent pas."},{"number":35,"points":26,"correct":"B","options":["Une procédure uniforme qui évite aux conseillers d'examiner les situations lorsque le document contractuel existe.","Expliquer les clauses et orienter les cas particuliers vers un spécialiste.","La possibilité pour chaque conseiller de modifier les clauses afin d'adapter rapidement le contrat au client.","Une réponse identique formulée dans un langage plus simple, même lorsque la clause ne décrit pas le cas."],"passage":"Un contrat standard facilite la vente rapide. Mais lorsqu'une situation particulière apparaît, le client doit pouvoir comprendre ses options. Une entreprise forme donc ses équipes à expliquer les clauses plutôt qu'à renvoyer systématiquement vers un document difficile à lire. Les conseillers disposent d'exemples et peuvent reconnaître les cas qui demandent un avis spécialisé. L'entreprise souhaite conserver une procédure commune sans traiter toutes les questions comme si la lecture du même paragraphe apportait nécessairement une réponse suffisante. Un client rencontre une clause particulière sur le remboursement. Le conseiller présente les règles communes puis l'oriente vers un spécialiste lorsque le contrat ne couvre pas clairement son cas.","question":"Que doit permettre une bonne application d'un contrat standard ?","explanation":"B combine explication et orientation d'un cas particulier vers un spécialiste. A/D répètent une réponse standard insuffisante, C accorde au conseiller un pouvoir de modification non prévu."},{"number":36,"points":33,"correct":"D","options":["Les fournisseurs ayant déjà vendu davantage reçoivent un classement supérieur, ce qui reflète seulement leur qualité initiale.","Le classement est fondé sur les commandes passées, sans modifier les choix que feront les nouveaux clients.","La mise en avant des offres récentes suffit à effacer la différence de réputation accumulée par les anciens.","L'ordre d'exposition influence les achats futurs, qui alimentent ensuite le critère de popularité."],"passage":"Une plateforme classe les offres selon leur popularité. Les nouveaux fournisseurs, encore peu visibles, ont alors moins de chances d'obtenir les achats qui amélioreraient leur classement. Un indicateur censé refléter le succès peut aussi contribuer à reproduire l'avantage de ceux qui sont déjà installés. Les clients voient surtout les offres déjà achetées par d'autres et hésitent à essayer celles qui n'ont pas encore reçu d'avis. La plateforme étudie des moyens de présenter de nouveaux fournisseurs sans prétendre qu'ils auraient déjà la même expérience. Elle devra aussi expliquer les critères utilisés, afin que le classement ne paraisse pas une simple photographie indépendante des règles du site. Les responsables veulent distinguer la popularité observée et les effets produits par leur propre présentation. Cette distinction devient importante lorsqu'un outil d'information influence directement les possibilités de vendre et de se faire connaître. Le classement met en avant les offres ayant déjà reçu de nombreuses commandes. Les nouveaux vendeurs sont moins consultés et accumulent donc plus lentement les données qui feraient progresser leur position.","question":"Pourquoi la popularité affichée n'est-elle pas indépendante de l'algorithme ?","explanation":"D montre la boucle entre classement, visibilité et ventes futures. A présente le volume comme qualité, B nie l'effet d'exposition, C attribue une garantie excessive au changement de présentation."},{"number":37,"points":33,"correct":"D","options":["Mesurer d'abord le délai de livraison, puis traiter les reprises comme un coût extérieur au service étudié.","Rétablir les vérifications supprimées afin de retrouver les anciens délais sans analyser le motif des retours.","Suivre le nombre de contrôles retirés comme indicateur principal, même lorsque des erreurs restent non résolues.","Compter toutes les étapes, y compris les reprises causées par les erreurs."],"passage":"Une entreprise revendique un service rapide en supprimant certaines étapes de contrôle. Les délais diminuent, mais les retours augmentent. Elle doit comparer le gain initial au travail supplémentaire causé par les erreurs. L'efficacité ne se mesure pas toujours au temps économisé à une seule étape du parcours. Les équipes doivent alors rouvrir les dossiers, répondre aux clients et organiser des échanges. Ces tâches mobilisent parfois davantage de moyens que les vérifications supprimées au départ. Les responsables vont comparer plusieurs organisations sur une durée suffisante. Ils ne souhaitent pas revenir automatiquement à chaque ancienne étape, mais identifier celles qui évitent un travail plus lourd ensuite. Le résultat sera décrit avec les retards et les erreurs, pas uniquement avec le délai initial. Dans le nouveau parcours, chaque dossier est traité deux minutes plus vite avant livraison, mais les reprises liées aux erreurs ajoutent trois minutes par dossier en moyenne. Le gain local devient une perte globale.","question":"Quel calcul de performance respecte cette observation ?","explanation":"D additionne temps initial et travail de reprise pour évaluer le processus. A/C omettent les corrections, B rétablit toutes les anciennes étapes sans examen de leur utilité."},{"number":38,"points":33,"correct":"B","options":["La disponibilité des accessoires influence la solidité matérielle sans intervenir dans la décision d'acheter un autre modèle.","Les campagnes de renouvellement influencent la conservation effective d'un objet pourtant utilisable.","La résistance des composants détermine presque toute la durée d'usage, les campagnes ayant un effet secondaire.","L'apparition de versions nouvelles indique qu'un appareil ancien n'a plus les fonctionnalités nécessaires aux utilisateurs."],"passage":"Un consommateur choisit un article durable pour limiter ses achats. Les campagnes du fabricant l'encouragent néanmoins à le remplacer souvent pour suivre de nouvelles versions. La durée de vie technique d'un produit ne garantit pas sa durée réelle d'usage si les pratiques commerciales poussent à son renouvellement. Les associations demandent des informations sur les réparations et les mises à jour permettant de continuer à utiliser l'appareil. Certains clients choisiraient de le garder plus longtemps s'ils savaient comment traiter une panne ou conserver les fonctions nécessaires. Le fabricant devra donc regarder ses services et ses messages commerciaux, pas seulement les caractéristiques du modèle neuf. Une promesse de durabilité peut perdre une partie de son sens lorsque toute l'organisation pousse à renouveler rapidement les achats. Les utilisateurs pourront comparer ces dimensions avant de juger si l'engagement annoncé correspond réellement à leurs possibilités d'usage dans le temps. Une machine fonctionne encore bien après dix ans, mais une nouvelle version est annoncée chaque année et ses accessoires ne sont plus mis à jour. Le propriétaire la remplace malgré sa durabilité matérielle.","question":"Quel écart l'exemple met-il en lumière ?","explanation":"B distingue capacité technique de durer et conservation effective influencée par campagnes et accessoires. A/C minimisent ces influences, D infère une obsolescence fonctionnelle sans preuve."},{"number":39,"points":33,"correct":"A","options":["Varier les horaires a révélé des usages absents du premier atelier, mais leur fréquence dans l'ensemble des clients reste à vérifier.","Les participants du soir forment une population suffisamment représentative pour définir seuls les étapes du parcours de l'ensemble des futurs utilisateurs, dès lors que leurs ateliers ont mis en lumière des besoins différents.","La différence entre ateliers démontre que seuls les usagers du soir ont besoin d'enregistrer une procédure avant de la terminer.","La fonction de sauvegarde devient superflue dès que les participants du jour connaissent les étapes à effectuer sans aide extérieure."],"passage":"Une entreprise associe des clients à la conception d'un service. Les participants les plus disponibles ne représentent pas tous les futurs usagers. L'équipe cherche donc d'autres retours avant de stabiliser le projet. La participation fournit des informations précieuses sans supprimer la question de ceux qui n'ont pas pu participer. Elle organise des essais courts à plusieurs horaires et propose des échanges à distance pour ceux qui ne peuvent pas venir. Les personnes rencontrées ne deviennent pas pour autant un portrait exact de tous les clients. Elles apportent d'autres difficultés et d'autres façons d'utiliser le service. Les concepteurs souhaitent comparer ces retours avant de choisir des règles durables. Le travail participatif reste utile, mais doit être décrit avec ses conditions et ses limites. Un groupe enthousiaste peut aider à améliorer un projet sans suffire à garantir qu'il conviendra ensuite aux publics qui n'étaient pas présents lors de sa préparation. Les premiers ateliers sont fréquentés surtout par des personnes libres en journée. Des essais le soir révèlent d'autres besoins, notamment la possibilité d'effectuer une démarche en plusieurs fois. Une seconde phase associe des participants de jour et du soir aux mêmes tâches d'essai. Plusieurs personnes du soir signalent qu'elles interrompent une procédure en cours de route, alors que les premiers ateliers avaient surtout évalué les étapes réalisables d'une seule traite. Le nouveau dispositif recueille des journaux d'usage sur une semaine: quelques participants de jour connaissent eux aussi ces interruptions, mais leur fréquence est supérieure chez ceux qui ne peuvent se libérer qu'après le travail. Le service ajoute une fonction de sauvegarde provisoire. Le comité précise qu'il n'a pas recruté un échantillon représentatif de tous les clients et que les horaires d'atelier ne sont qu'un indice imparfait des conditions de vie. Il refuse d'en déduire que tous les usagers du soir ont les mêmes besoins ou que tous les usagers de jour réalisent les tâches sans interruption.","question":"Quelle conclusion peut guider la conception sans transformer un échantillon de volontaires en portrait de toute la clientèle ?","explanation":"A s'appuie sur les journaux d'usage et les besoins révélés par des recrutements différents, tout en respectant l'absence de représentativité déclarée. B prend les volontaires pour un échantillon général; C exclut à tort les interruptions observées aussi le jour; D ne tient pas compte des interruptions possibles indépendamment de la connaissance de la procédure."}]}$paper_15$::jsonb),
('tcf-reading-16','tcf-reading-2026-11-close-reading-v4',$paper_16${"id":"tcf-reading-16","title":"TCF Reading · Test 16","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"D","options":["La tour","La salle haute","Le toit","La cour"],"passage":"La tour se visite uniquement l'après-midi cette semaine. La cour reste accessible dès neuf heures.\n\nUn panneau rappellera les créneaux de visite à l'entrée. Les billets peuvent être retirés à l'accueil pendant les horaires habituels.","question":"Quel espace ouvre le matin ?","explanation":"Le passage indique : « La tour se visite uniquement l'après-midi cette semaine. La cour reste accessible dès neuf heures. » Cela justifie la réponse : La cour."},{"number":2,"points":3,"correct":"C","options":["La pièce d'identité","Le billet de visite","Les sacs","Les lunettes"],"passage":"La visite des archives exige une pièce d'identité. Les sacs seront déposés dans les casiers avant l'entrée.\n\nLe personnel indiquera les règles de manipulation des documents.","question":"Que faut-il laisser au vestiaire ?","explanation":"Le passage indique : « La visite des archives exige une pièce d'identité. Les sacs seront déposés dans les casiers avant l'entrée. » Cela justifie la réponse : Les sacs."},{"number":3,"points":3,"correct":"D","options":["Le passage fermé","Le sommet des remparts","La sortie sans panneau","La porte sud"],"passage":"Le passage sous les remparts est fermé pour travaux. Suivez les panneaux bleus vers la porte sud.\n\nLa déviation ajoute quelques minutes de marche. Les agents demandent de ne pas déplacer les barrières, même lorsque le chantier semble inoccupé.","question":"Quelle direction faut-il prendre ?","explanation":"Le passage indique : « Le passage sous les remparts est fermé pour travaux. Suivez les panneaux bleus vers la porte sud. » Cela justifie la réponse : La porte sud."},{"number":4,"points":3,"correct":"B","options":["L'accès à toutes les rues","La visite accompagnée","La lecture des panneaux","L'entrée libre à l'exposition"],"passage":"L'exposition de maquettes est gratuite samedi. Les visites guidées restent sur réservation.\n\nLe personnel pourra expliquer les horaires et les places encore disponibles. Une entrée gratuite ne garantit pas automatiquement une place dans un groupe déjà complet.","question":"Quel service exige toujours une réservation ?","explanation":"Le passage indique : « L'exposition de maquettes est gratuite samedi. Les visites guidées restent sur réservation. » Cela justifie la réponse : La visite accompagnée."},{"number":5,"points":9,"correct":"D","options":["Acheter une usine","Revoir uniquement le château","Éviter toute activité culturelle","Découvrir une histoire moins familière"],"passage":"J'ai choisi la visite du quartier industriel. Nous connaissons déjà le château et je voudrais découvrir un autre aspect de la ville.\n\nLe guide parlera aussi des habitants qui travaillaient dans les anciens ateliers. Nous pourrons comparer ce parcours avec les visites habituelles, sans chercher uniquement les monuments les plus connus.","question":"Pourquoi choisir cette visite ?","explanation":"Le passage indique : « J'ai choisi la visite du quartier industriel. Nous connaissons déjà le château et je voudrais découvrir un autre aspect de la ville. » Cela justifie la réponse : Découvrir une histoire moins familière."},{"number":6,"points":9,"correct":"B","options":["Prouver la propriété d'un bâtiment","Observer les transformations du quartier","Remplacer la carte de transport","Décorer uniquement la salle d'accueil"],"passage":"Apportez une photo ancienne de votre rue, si vous en avez une. Nous la comparerons aux lieux actuels pendant la promenade.\n\nLes images seront observées avec leur date, lorsque celle-ci est connue. Vous pourrez repartir avec les originaux après leur numérisation pour le groupe.","question":"À quoi servira la photo ?","explanation":"Le passage indique : « Apportez une photo ancienne de votre rue, si vous en avez une. Nous la comparerons aux lieux actuels pendant la promenade. » Cela justifie la réponse : Observer les transformations du quartier."},{"number":7,"points":9,"correct":"A","options":["Le projet présenté","Le numéro de téléphone uniquement","L'horaire initial","La date de publication du bulletin"],"passage":"La réunion sur la place rénovée est avancée d'une heure. Le plan présenté ne change pas ; seule l'heure a été modifiée.\n\nLes participants recevront une confirmation et pourront préparer leurs questions. Les responsables souhaitent garder le même temps d'échange malgré ce changement d'organisation.","question":"Quel élément est conservé ?","explanation":"Le passage indique : « La réunion sur la place rénovée est avancée d'une heure. Le plan présenté ne change pas ; seule l'heure a été modifiée. » Cela justifie la réponse : Le projet présenté."},{"number":8,"points":9,"correct":"C","options":["Le retirer dans la boutique voisine","Acheter une place assise spéciale","Le demander à l'accueil","Attendre la fin du parcours"],"passage":"Le musée prête des sièges pliants pour suivre la visite. Demandez-les à l'accueil avant le départ du groupe.\n\nLes sièges doivent être rapportés avant de quitter le musée. Le personnel expliquera les endroits où ils peuvent être utilisés sans gêner les passages.","question":"Comment obtenir ce matériel ?","explanation":"Le passage indique : « Le musée prête des sièges pliants pour suivre la visite. Demandez-les à l'accueil avant le départ du groupe. » Cela justifie la réponse : Le demander à l'accueil."},{"number":9,"points":9,"correct":"D","options":["Exposer un travail déjà terminé","Gagner un prix dès la première séance","Éviter toute pratique","Se former sans compétition"],"passage":"Je participerai à l'atelier de photographie plutôt qu'au concours. Je veux apprendre sans avoir à présenter immédiatement un résultat.\n\nL'animateur présentera plusieurs techniques et laissera chacun essayer à son rythme. Je pourrai ensuite décider si je souhaite montrer des images lors d'une prochaine rencontre.","question":"Quel besoin guide ce choix ?","explanation":"Le passage indique : « Je participerai à l'atelier de photographie plutôt qu'au concours. Je veux apprendre sans avoir à présenter immédiatement un résultat. » Cela justifie la réponse : Se former sans compétition."},{"number":10,"points":9,"correct":"A","options":["Une personne ayant un souvenir à raconter","Uniquement un propriétaire d'archives papier","Un vendeur de matériel audio","Seulement un historien diplômé"],"passage":"Notre collecte de souvenirs accepte aussi des récits enregistrés. Il n'est pas nécessaire de posséder un document écrit.\n\nUne permanence permettra de choisir la forme de la contribution et de vérifier les informations associées. Les personnes restent libres de ne pas publier certains détails trop personnels.","question":"Qui peut contribuer ?","explanation":"Le passage indique : « Notre collecte de souvenirs accepte aussi des récits enregistrés. Il n'est pas nécessaire de posséder un document écrit. » Cela justifie la réponse : Une personne ayant un souvenir à raconter."},{"number":11,"points":15,"correct":"B","options":["Une fermeture au public","Un nouvel usage respectant des éléments du bâtiment","Une démolition complète","Un retour obligatoire au commerce d'origine"],"passage":"Une ancienne halle devient une bibliothèque. Les grandes ouvertures sont conservées, tandis que l'intérieur est adapté aux collections et aux lecteurs.\n\nLes architectes ont prévu des espaces calmes et des tables de groupe, tout en gardant visible le volume de la halle. Les futurs lecteurs pourront visiter un secteur témoin avant l'ouverture complète. La ville souhaite éviter qu'une conservation purement décorative laisse le bâtiment inutilisé. Elle explique donc les choix techniques et les contraintes du nouvel accueil. Les éléments anciens ne seront pas tous maintenus au même endroit, mais ceux qui racontent le mieux le fonctionnement du lieu feront l'objet d'une présentation accessible au public.","question":"Quel type de transformation est réalisé ?","explanation":"Le passage indique : « Une ancienne halle devient une bibliothèque. Les grandes ouvertures sont conservées, tandis que l'intérieur est adapté aux collections et aux lecteurs. » Cela justifie la réponse : Un nouvel usage respectant des éléments du bâtiment."},{"number":12,"points":15,"correct":"C","options":["La taille des dossiers municipaux","Les horaires des magasins uniquement","La mémoire des pratiques locales","Le prix des panneaux routiers"],"passage":"Des habitants identifient les noms anciens des rues sur un plan. Le projet recueille aussi les usages populaires qui n'apparaissent pas dans les archives administratives.\n\nLes témoins indiquent où ils ont entendu un nom et à quelle période il était utilisé. Les animateurs rapprochent ces récits des plans conservés, sans effacer les différences. Le projet ne cherche pas à remplacer les noms actuels par une version unique supposée authentique.","question":"Quelle information complète les sources officielles ?","explanation":"Le passage indique : « Des habitants identifient les noms anciens des rues sur un plan. Le projet recueille aussi les usages populaires qui n'apparaissent pas dans les archives administratives. » Cela justifie la réponse : La mémoire des pratiques locales."},{"number":13,"points":15,"correct":"A","options":["La compatibilité avec les matériaux existants","La dureté maximale à tout prix","La rapidité de la publicité","La couleur de l'emballage"],"passage":"Un chantier restaure les joints d'un pont avec un matériau compatible avec la pierre. Un produit plus dur pourrait provoquer des dégradations au lieu de protéger l'ensemble.\n\nUne partie du chantier servira de test pour observer le résultat. Le responsable souhaite éviter qu'un produit paraissant plus solide soit considéré comme automatiquement meilleur. Les propriétés doivent être appréciées ensemble, avec les contraintes du bâtiment. Des informations seront proposées aux riverains, afin qu'ils comprennent pourquoi les travaux ne consistent pas simplement à remplacer un ancien matériau par le plus récent ou le plus résistant disponible chez un fournisseur.","question":"Quel critère guide le choix ?","explanation":"Le passage indique : « Un chantier restaure les joints d'un pont avec un matériau compatible avec la pierre. Un produit plus dur pourrait provoquer des dégradations au lieu de protéger l'ensemble. » Cela justifie la réponse : La compatibilité avec les matériaux existants."},{"number":14,"points":15,"correct":"D","options":["Éteindre tous les services publics","Augmenter la puissance partout","Rendre les monuments invisibles en journée","Maintenir la visibilité avec moins d'éclairage"],"passage":"Une ville éclaire moins fortement ses monuments la nuit. Les visiteurs peuvent encore les voir, mais la consommation et la gêne lumineuse diminuent.\n\nLes techniciens ont réalisé plusieurs essais et recueilli les remarques sur les principaux points de vue. Les riverains peuvent encore se repérer dans les rues, tandis que les projecteurs décoratifs fonctionnent moins longtemps. Le service distingue donc les besoins de circulation et la mise en scène des façades. Il ne veut pas présenter tous les éclairages comme également nécessaires ou également inutiles.","question":"Quel compromis est recherché ?","explanation":"Le passage indique : « Une ville éclaire moins fortement ses monuments la nuit. Les visiteurs peuvent encore les voir, mais la consommation et la gêne lumineuse diminuent. » Cela justifie la réponse : Maintenir la visibilité avec moins d'éclairage."},{"number":15,"points":15,"correct":"B","options":["Uniquement des conseils de jardinage","Une compréhension de l'histoire du lieu","Une interdiction de marcher","Le programme des trains actuels"],"passage":"Une ancienne voie d'eau est remise en valeur comme promenade. Des panneaux expliquent son rôle dans le transport des marchandises, pas seulement ses qualités paysagères.\n\nDes photographies montrent les chargements, les chemins utilisés et les bâtiments liés à cette activité. Les promeneurs peuvent comparer ces repères avec ce qui reste visible aujourd'hui. Le projet veut éviter qu'un aménagement agréable efface entièrement le sens du site. Les informations ne demanderont pas aux visiteurs de suivre un cours complet, mais leur donneront des éléments pour comprendre pourquoi la voie existe et comment elle participait à la vie locale.","question":"Que souhaite transmettre l'aménagement ?","explanation":"Le passage indique : « Une ancienne voie d'eau est remise en valeur comme promenade. Des panneaux expliquent son rôle dans le transport des marchandises, pas seulement ses qualités paysagères. » Cela justifie la réponse : Une compréhension de l'histoire du lieu."},{"number":16,"points":15,"correct":"C","options":["Le stock de produits à vendre","Les plans des parkings actuels","La mémoire du travail vécu","Les tarifs des visites"],"passage":"Un atelier recueille les souvenirs d'ouvriers d'une usine fermée. Les organisateurs veulent conserver l'expérience des personnes, au-delà des machines déjà exposées.\n\nLes personnes décrivent des horaires, des gestes et des relations que les objets seuls ne permettent pas de connaître. Les récits sont datés et préparés avec les participants, afin d'éviter une image uniforme de toutes les périodes. Le musée souhaite conserver les désaccords et les changements importants lorsqu'ils aident à comprendre l'activité. Il ne présente pas un souvenir individuel comme le résumé de toute l'usine.","question":"Quel aspect du patrimoine est complété ?","explanation":"Le passage indique : « Un atelier recueille les souvenirs d'ouvriers d'une usine fermée. Les organisateurs veulent conserver l'expérience des personnes, au-delà des machines déjà exposées. » Cela justifie la réponse : La mémoire du travail vécu."},{"number":17,"points":15,"correct":"B","options":["Démolition et publicité","Accessibilité et préservation","Stationnement et circulation rapide","Fermeture et abandon"],"passage":"Un immeuble ancien accueille un ascenseur dans une extension discrète. L'objectif est de permettre l'accès tout en limitant les transformations des espaces historiques.\n\nLe parcours d'entrée et les passages entre les salles ont été examinés avec plusieurs usagers. Les spécialistes souhaitent éviter une solution annoncée comme accessible mais difficile à utiliser au quotidien. Le projet ne demande pas de choisir entre l'accueil actuel et la valeur du bâtiment : il cherche une intervention qui réponde réellement aux besoins en limitant les effets sur ce qui doit être préservé pour les visiteurs et les habitants des prochaines années.","question":"Quels besoins sont associés ?","explanation":"Le passage indique : « Un immeuble ancien accueille un ascenseur dans une extension discrète. L'objectif est de permettre l'accès tout en limitant les transformations des espaces historiques. » Cela justifie la réponse : Accessibilité et préservation."},{"number":18,"points":15,"correct":"A","options":["Vérifier la fonction de la fontaine","Boire à toutes les fontaines décoratives","Ignorer les indications","Se fier uniquement à la forme"],"passage":"Une carte présente les fontaines de la ville et indique celles qui délivrent de l'eau potable. Les visiteurs ne doivent pas déduire cette possibilité de leur seule apparence.\n\nCertains bassins ont seulement une fonction décorative, tandis que d'autres sont entretenus pour cet usage précis. Les agents mettront la carte à jour si une installation doit être temporairement arrêtée. Les visiteurs pourront retrouver les indications sur place et signaler un problème. Le service souhaite que l'information reste simple sans encourager une déduction fondée sur le seul aspect de la pierre ou sur la présence d'un robinet.","question":"Quelle précaution est demandée ?","explanation":"Le passage indique : « Une carte présente les fontaines de la ville et indique celles qui délivrent de l'eau potable. Les visiteurs ne doivent pas déduire cette possibilité de leur seule apparence. » Cela justifie la réponse : Vérifier la fonction de la fontaine."},{"number":19,"points":15,"correct":"A","options":["Des constructions récentes méritent aussi d'être comprises","Les quartiers modernes sont tous identiques","Les promenades doivent éviter les habitants","Seuls les châteaux ont une histoire"],"passage":"Une association propose des balades dans les quartiers récents. Elle estime que le patrimoine urbain ne se limite pas aux centres très anciens.\n\nLes guides présentent les choix de construction, les espaces partagés et les transformations demandées par les résidents. Ils recueillent aussi les souvenirs de personnes arrivées lors des premières années. L'association ne prétend pas que chaque bâtiment doit devenir un monument protégé. Elle souhaite ouvrir un regard sur des lieux souvent considérés comme ordinaires et sans histoire.","question":"Quelle idée défend-elle ?","explanation":"Le passage indique : « Une association propose des balades dans les quartiers récents. Elle estime que le patrimoine urbain ne se limite pas aux centres très anciens. » Cela justifie la réponse : Des constructions récentes méritent aussi d'être comprises."},{"number":20,"points":21,"correct":"C","options":["Confirmer automatiquement le premier plan","Éviter toute consultation","Observer les usages avant de fixer l'aménagement","Réduire le nombre d'arbres sans raison"],"passage":"Une ville transforme une place après une phase d'essai. Les bancs provisoires ont révélé que certains emplacements étaient trop exposés au soleil. Le plan définitif est modifié en conséquence. Les usagers ont pu déplacer les sièges et noter les heures où ils évitaient certains secteurs. Les agents ont également observé les trajets des livraisons et des personnes se déplaçant lentement. Ces retours ont révélé des contraintes absentes des premières images du projet. La ville souhaite que la phase provisoire serve à apprendre quelque chose, et pas seulement à faire accepter un plan déjà arrêté sans possibilité de modification.","question":"À quoi a servi l'essai ?","explanation":"Le passage indique : « Une ville transforme une place après une phase d'essai. Les bancs provisoires ont révélé que certains emplacements étaient trop exposés au soleil. Le plan définitif est modifié en conséquence. » Cela justifie la réponse : Observer les usages avant de fixer l'aménagement."},{"number":21,"points":21,"correct":"A","options":["Inclure des acteurs longtemps peu visibles","Remplacer l'histoire par une liste de prix","Présenter uniquement les visiteurs actuels","Supprimer toute information sur le palais"],"passage":"Un musée raconte l'histoire d'un palais en mentionnant aussi les personnes qui l'entretenaient. Le récit ne se limite plus à ses propriétaires célèbres. Les commissaires souhaitent éviter qu'un grand bâtiment soit raconté uniquement par la vie de quelques figures connues. Les visiteurs pourront relier les pièces à des usages précis et découvrir les tâches nécessaires à leur entretien. Le musée garde les récits célèbres, mais les replace dans une organisation plus large dont dépendait le fonctionnement quotidien du palais.","question":"Quelle évolution du regard est proposée ?","explanation":"Le passage indique : « Un musée raconte l'histoire d'un palais en mentionnant aussi les personnes qui l'entretenaient. Le récit ne se limite plus à ses propriétaires célèbres. » Cela justifie la réponse : Inclure des acteurs longtemps peu visibles."},{"number":22,"points":21,"correct":"B","options":["Éviter de mentionner son origine","Préserver le sens de l'objet conservé","Augmenter automatiquement sa valeur","Garantir la réouverture du commerce"],"passage":"Une commune garde une ancienne enseigne après la fermeture du commerce. Elle la documente pour qu'elle reste compréhensible aux générations qui n'ont pas connu la boutique. La notice indiquera le type d'activité, sa période et les sources utilisées pour la décrire. Les habitants pourront apporter une précision lors d'une rencontre. Le service ne cherche pas à promettre le retour d'un commerce disparu, mais à garder des repères dans une rue qui change.","question":"Pourquoi ajouter des informations ?","explanation":"Le passage indique : « Une commune garde une ancienne enseigne après la fermeture du commerce. Elle la documente pour qu'elle reste compréhensible aux générations qui n'ont pas connu la boutique. » Cela justifie la réponse : Préserver le sens de l'objet conservé."},{"number":23,"points":21,"correct":"D","options":["Réserver la place aux voitures","Interdire toute présence humaine","Accepter toute nuisance","Organiser les usages plutôt que les supprimer"],"passage":"Des riverains acceptent des événements sur une place historique, mais demandent des horaires et une gestion du bruit. Leur proposition ne vise pas à transformer le lieu en espace sans vie. Ils proposent des jours et des limites discutés avec les organisateurs. Les associations pourront continuer à préparer des fêtes, mais devront prévoir le rangement et l'accès aux logements. Le comité veut éviter un débat réduit à accepter toute activité ou à réclamer le silence permanent.","question":"Quelle position adoptent-ils ?","explanation":"Le passage indique : « Des riverains acceptent des événements sur une place historique, mais demandent des horaires et une gestion du bruit. Leur proposition ne vise pas à transformer le lieu en espace sans vie. » Cela justifie la réponse : Organiser les usages plutôt que les supprimer."},{"number":24,"points":21,"correct":"B","options":["Transformer tous les quais en exposition","Permettre aux usagers de se repérer","Limiter l'accès aux historiens","Supprimer les horaires"],"passage":"La rénovation d'une gare conserve des éléments anciens et améliore l'orientation. Les panneaux patrimoniaux sont placés sans masquer les informations nécessaires aux voyageurs. Les premiers voyageurs essaieront le parcours avec leurs bagages et pourront signaler les points difficiles à comprendre. Les panneaux historiques resteront consultables dans des zones où l'on peut s'arrêter sans bloquer les passages. Le projet souhaite rendre l'histoire visible, sans demander à un usager pressé de traverser une exposition pour trouver sa correspondance.","question":"Quelle priorité pratique demeure ?","explanation":"Le passage indique : « La rénovation d'une gare conserve des éléments anciens et améliore l'orientation. Les panneaux patrimoniaux sont placés sans masquer les informations nécessaires aux voyageurs. » Cela justifie la réponse : Permettre aux usagers de se repérer."},{"number":25,"points":21,"correct":"A","options":["On confondrait une proposition documentée avec une réalisation que les autres sources contredisent.","On attribuerait à la photographie la date de conception du projet.","On supposerait que tout jardin de 1905 était prévu dès la date du plan.","On traiterait le plan comme inutile pour comprendre les débats de l'époque."],"passage":"Une archive montre un projet jamais construit. Les médiateurs le présentent comme une intention de l'époque, pas comme la preuve d'un état ancien de la ville. La notice expliquera qui avait préparé le plan, dans quelles circonstances et pourquoi il n'a pas été réalisé. Le musée souhaite que les archives servent à comprendre des intentions et des débats, sans transformer toute représentation ancienne en preuve de ce qui a réellement existé sur le terrain. Un plan daté de 1890 propose une gare sur la place; des photographies de 1905 montrent que l'emplacement est resté un jardin. La notice présente les deux documents pour distinguer le souhait des décideurs du résultat observé.","question":"Quelle erreur ferait-on en utilisant le plan de 1890 comme preuve de l'existence de la gare ?","explanation":"Le plan atteste une intention, la photographie un état réalisé différent. A. B/C/D ne décrivent pas la confusion."},{"number":26,"points":21,"correct":"B","options":["Sélectionner la finition la moins visible en conditions sèches, indépendamment de ses usages réels.","Comparer intégration esthétique, sécurité et entretien, sans réduire le projet à l'apparence initiale.","Privilégier l'apparence immédiatement, puis reporter l'examen de l'usure après la pose définitive.","Retenir le revêtement le plus ancien disponible, même lorsque ses qualités d'adhérence sont inconnues."],"passage":"Une rue reçoit des revêtements moins glissants à proximité d'un monument. L'équipe cherche une solution visuellement discrète, mais refuse que l'apparence rende le passage dangereux. Les essais seront menés avec des personnes utilisant des aides à la marche et avec le service chargé de l'entretien. Les spécialistes devront tenir compte de la pluie et de l'usure, pas seulement de l'aspect le jour de la pose. La commune veut une solution qui reste praticable et lisible, tout en respectant l'ensemble architectural. Une première dalle semble parfaitement adaptée au style de la place, mais devient très glissante sous la pluie. Une seconde est légèrement plus visible tout en restant sûre après usure; l'équipe consulte les utilisateurs.","question":"Quel choix correspond au raisonnement de la commune ?","explanation":"Les essais portent sur style, pluie, usure et accessibilité. B; les autres privilégient un seul critère."},{"number":27,"points":21,"correct":"A","options":["L'accueil peut sécuriser les visites sans transformer les pièces patrimoniales essentielles.","La transformation garantit que les ateliers ne nécessiteront plus aucune surveillance.","L'aménagement permet de reconstituer la décoration d'origine dans l'ensemble des pièces restantes.","L'ouverture au public impose de remplacer tous les espaces de travail par des salles de repos."],"passage":"Une maison d'artiste conserve plusieurs pièces intactes et transforme une autre en espace d'accueil. Le projet distingue les besoins de présentation des conditions nécessaires à la visite. L'équipe prépare les flux de visiteurs, les possibilités de repos et les conditions de surveillance des œuvres. Elle souhaite éviter qu'une ouverture trop fragile oblige ensuite à fermer des salles ou à interrompre les visites. La maison manque d'espace pour les files d'attente; convertir une pièce secondaire permet de contrôler l'accès tout en gardant les ateliers intacts. L'équipe cherche à éviter une fréquentation qu'elle ne pourrait surveiller.","question":"Pourquoi transformer une pièce plutôt que conserver tout le bâtiment dans le même état ?","explanation":"La pièce d'accueil soutient les visites tout en préservant les lieux essentiels. A; C/B/D ajoutent des conséquences inexistantes."},{"number":28,"points":21,"correct":"A","options":["Parce que le symbole choisi doit rester identifiable sans confusion pour les secours.","Parce que la commission doit choisir uniquement les propositions issues des services techniques.","Parce que les noms historiques sont exclus des lieux où circulent les services d'urgence.","Parce que des habitants déjà consultés ne peuvent participer à la discussion d'une variante."],"passage":"Des habitants participent au choix de nouveaux noms de rues. Une commission vérifie les propositions pour éviter les doublons qui compliqueraient l'orientation et les secours. Les services vérifient aussi la lisibilité sur les plans et la prononciation possible lors d'un appel. Les propositions historiques ou culturelles seront examinées avec ces contraintes. La commission souhaite que le choix reste compréhensible, plutôt que donner l'impression de rejeter une contribution sans raison. Un nom proposé honore une personnalité locale mais ressemble à celui d'une avenue voisine. Les services craignent des confusions lors d'appels aux secours et présentent une variante aux habitants.","question":"Pourquoi la commission ne retient-elle pas automatiquement le nom populaire ?","explanation":"La commission croise valeur historique et sécurité pratique. A; B/C/D imposent des exclusions absentes."},{"number":29,"points":21,"correct":"C","options":["Une réparation récente efface nécessairement les marques des interventions précédentes.","La présence d'un matériau ancien prouve que le bâtiment n'a subi aucune adaptation ultérieure.","Les matériaux et retouches peuvent témoigner de plusieurs époques d'entretien dans le même élément.","Toute différence de couleur démontre qu'une reconstruction intégrale a eu lieu."],"passage":"Une visite montre des traces de réparations successives sur un bâtiment. Elles témoignent de son histoire matérielle plutôt que d'un état originel resté inchangé. Les médiateurs montrent les différences de matière et expliquent les circonstances connues de chaque réparation. Ils ne cherchent pas à cacher toutes les interventions pour présenter un bâtiment resté inchangé. Le public pourra comprendre comment le lieu a été entretenu, abîmé et adapté selon les périodes. Sur une façade, une pierre ancienne porte des traces d'une restauration du XXe siècle. L'équipe indique les deux périodes plutôt que de présenter l'élément comme entièrement original ou entièrement récent.","question":"Quelle interprétation des traces rend le mieux compte de l'histoire matérielle ?","explanation":"La façade conserve plusieurs couches d'interventions. C. Les autres imposent une lecture binaire ou absolue."},{"number":30,"points":26,"correct":"D","options":["Limiter les transformations aux bâtiments qui n'ont plus aucun usage quotidien.","Supprimer le classement patrimonial pour permettre n'importe quelle intervention.","Conserver toute règle existante même lorsque son effet exclut une partie des usagers.","Concilier préservation du patrimoine et accès réel par une intervention adaptée."],"passage":"La protection d'un centre ancien peut rendre certaines adaptations plus difficiles. Un urbaniste propose de discuter les effets concrets des règles : préserver des qualités ne suppose pas de refuser toute évolution des usages. Les personnes chargées du projet consulteront les usagers et les spécialistes avant de définir les interventions. Elles souhaitent distinguer une transformation nécessaire et une modification qui ne répondrait à aucun besoin clairement expliqué dans le dossier. Un escalier classé est difficile à utiliser pour certains habitants. Le projet étudie une rampe réversible qui laisse les éléments d'origine lisibles sans empêcher l'accès aux activités du lieu.","question":"Quel critère guide ici le traitement d'une adaptation nécessaire ?","explanation":"La rampe réversible vise conservation et usage. D. C/B/A suppriment une dimension du compromis."},{"number":31,"points":26,"correct":"D","options":["Elle prouve que l'usage de l'objet n'a jamais varié selon les personnes et les époques.","Elle remplace les sources historiques puisque le mouvement est désormais visible dans le musée.","Elle rend inutiles les descriptions des matériaux, les gestes suffisant à expliquer l'histoire.","Elle peut éclairer l'usage pratique de l'objet sans prétendre reproduire exactement toutes les expériences anciennes."],"passage":"Un objet quotidien devient une pièce de musée. Sa conservation change le regard porté sur lui, mais peut aussi l'éloigner des gestes qui expliquaient son usage. Les médiateurs ajoutent des démonstrations pour rendre cette dimension perceptible. La démonstration sera présentée comme une interprétation appuyée sur des sources. Elle donnera des repères sur les gestes et les matières, sans faire croire que l'expérience d'un ancien utilisateur peut être entièrement reproduite dans une salle actuelle. La présentation d'un outil agricole ancien comprend une démonstration à partir de descriptions et d'images historiques. Le guide précise que le geste reconstitué peut différer de celui de certains utilisateurs passés.","question":"Quelle valeur et quelle limite la démonstration doit-elle conserver ?","explanation":"La démonstration est une interprétation fondée sur des sources avec limites. D. B/A/C lui attribuent trop."},{"number":32,"points":26,"correct":"C","options":["Le besoin d'éviter tout point de vue déjà diffusé sur les réseaux sociaux.","La présence d'un point de vue connu qui rend nécessairement toute visite inutile.","L'image célèbre risque de résumer abusivement un lieu aux multiples histoires.","L'impossibilité de photographier un monument après avoir consulté son histoire."],"passage":"Les touristes photographient un monument depuis un même point, devenu célèbre en ligne. Le gestionnaire ouvre un second parcours pour montrer des aspects moins connus. Il ne conteste pas la première vue, mais veut éviter qu'elle résume toute l'expérience du lieu. Les nouveaux parcours expliquent d'autres usages et des points de vue complémentaires. Les visiteurs resteront libres de regarder l'image connue, mais disposeront de moyens pour ne pas réduire le site à ce seul cadrage déjà rencontré ailleurs. Le nouveau circuit montre des traces d'un autre usage du monument et explique pourquoi la photographie célèbre ne fait apparaître qu'une façade. Les visiteurs peuvent choisir les deux itinéraires.","question":"Quel défaut du parcours unique le second itinéraire cherche-t-il à limiter ?","explanation":"Le nouvel itinéraire enrichit le regard sans interdire la vue célèbre; C. B/D/A surinterprètent."},{"number":33,"points":26,"correct":"D","options":["Les marques d'usage suffisent à garantir la stabilité structurelle de l'édifice.","Une trace ancienne rend impossible toute intervention sur un autre élément du lavoir.","Le remplacement intégral de la pierre supprimerait nécessairement toute connaissance historique du quartier.","Certaines marques documentent les usages, contrairement aux dégâts menaçant la conservation."],"passage":"Une ville restaure un ancien lavoir tout en conservant les marques d'usure. Les pierres abîmées ne sont pas toutes remplacées : certaines portent les traces des gestes répétés. La valeur historique ne se réduit pas à une apparence parfaitement neuve. Le choix de garder une marque n'est donc pas une absence d'intervention, mais une décision à expliquer dans l'ensemble du travail de restauration. Les artisans conservent un creux dans la pierre du lavoir, formé par des années de frottement, tout en réparant une fissure qui menaçait la stabilité. La décision sépare traces d'usage et désordres techniques.","question":"Pourquoi conserver une marque d'usure plutôt que restaurer toute la pierre à neuf ?","explanation":"La trace raconte les gestes, la fissure menace le bâtiment. D distingue les valeurs; B/A/C généralisent."},{"number":34,"points":26,"correct":"D","options":["La fonction réelle du lieu peut être déduite du seul plan dès lors que sa date est connue.","Les témoignages ne peuvent aider à comprendre les transformations puisqu'ils restent subjectifs.","Le plan devient faux dès que l'usage réel diffère de l'intention politique initiale.","Il faut distinguer les intentions de conception des pratiques constatées pour comprendre l'histoire de l'espace."],"passage":"Une exposition sur l'urbanisme confronte plans officiels et récits de résidents. Les premiers montrent des intentions et des règles ; les seconds révèlent des usages parfois différents. Comprendre la ville suppose de regarder ce qui a été prévu et ce qui a été vécu. L'exposition ne cherche pas un gagnant entre ces sources, mais ce que leur rapprochement rend visible sur la construction et l'évolution des espaces urbains. Un plan municipal prévoit une grande place publique, tandis que des récits décrivent son emploi comme parking pendant des années. Les deux sources éclairent des étapes différentes de la vie du lieu.","question":"Que révèle l'écart entre le plan et les récits ?","explanation":"Les plans sont des intentions, les récits les usages. D les rapproche sans en annuler un."},{"number":35,"points":26,"correct":"B","options":["Parce que les matériaux anciens perdent leur intérêt lorsque les travaux de mise aux normes sont importants.","Parce que les travaux nécessaires conditionnent la pertinence d'un réemploi.","Parce que la réutilisation d'un bâtiment suppose de conserver à l'identique les fonctions prévues à sa construction.","Parce que la valeur historique garantit une meilleure adéquation aux besoins futurs que la transformation du bâtiment."],"passage":"La réutilisation d'un bâtiment semble éviter une construction neuve. Son intérêt doit néanmoins être étudié avec les adaptations nécessaires et les besoins futurs. Conserver à tout prix une structure très inadaptée peut déplacer les coûts plutôt que résoudre le problème d'usage. Les études compareront les possibilités avant de choisir. Elles éviteront de considérer la seule présence d'un ancien bâtiment comme une réponse suffisante, sans examiner les travaux qu'il demande pour accueillir correctement les activités prévues. La transformation d'un entrepôt ancien en école demande des travaux d'isolation très lourds, alors qu'un autre bâtiment proche pourrait être réutilisé avec moins de modifications. Le conseil compare les coûts et l'usage futur.","question":"Pourquoi la réutilisation de n'importe quel bâtiment n'est-elle pas automatiquement optimale ?","explanation":"B fait dépendre l'intérêt du réemploi des adaptations nécessaires et de l'usage prévu. A généralise leur effet négatif, C impose un maintien des fonctions, D déduit une utilité pratique de la seule valeur historique."},{"number":36,"points":33,"correct":"C","options":["Il privilégie les témoignages des habitants anciens comme version de référence, puis invite les nouveaux à les illustrer.","Il rassemble les souvenirs selon une chronologie commune pour atténuer les différences entre les personnes.","Il recueille plusieurs expériences situées et les met en relation, sans condition d'ancienneté pour contribuer.","Il traite les usages récents du quartier comme une mémoire indépendante de l'histoire partagée documentée."],"passage":"Un quartier souhaite valoriser son histoire. Les habitants les plus anciens possèdent beaucoup de souvenirs, mais les nouveaux arrivants contribuent aussi à la vie actuelle du lieu. Le projet accueille les deux perspectives. Le patrimoine partagé peut se construire à partir d'héritages différents sans exiger une ancienneté identique pour participer. Les personnes arrivées récemment découvrent les récits anciens et peuvent apporter leurs propres repères. Le comité souhaite que la transmission crée des rencontres plutôt qu'un examen implicite de la légitimité à parler du quartier. Les archives restent importantes, mais ne résument pas toute la vie du lieu. Les prochaines activités associeront donc plusieurs générations et périodes d'installation. Cette ouverture permettra de discuter ce que les habitants partagent et ce qu'ils découvrent différemment, sans exiger qu'ils possèdent les mêmes souvenirs ou qu'un seul groupe définisse définitivement le sens de l'espace commun. Lors d'un atelier, une habitante arrivée récemment raconte un usage actuel de la place, tandis qu'un ancien résident présente une photographie du même lieu trente ans plus tôt. Le comité expose les deux sans assimiler leurs expériences.","question":"Comment le projet construit-il une mémoire commune sans effacer les différences ?","explanation":"C met en relation souvenirs anciens et usages nouveaux sans condition d'ancienneté. A hiérarchise les voix, B cherche à gommer les écarts, D sépare les récits plutôt que de les confronter."},{"number":37,"points":33,"correct":"A","options":["Une restitution visuelle peut transmettre une image sans constituer la continuité intégrale des éléments historiques.","La ressemblance de la façade permet de traiter les fonctions et les matériaux reconstruits comme ceux d'origine.","La valeur historique d'une reconstruction tient uniquement à son authenticité matérielle, sans apport visuel possible.","La date des photographies suffit à justifier l'emploi des matériaux récents comme s'ils avaient été conservés."],"passage":"La reconstruction d'une façade disparue peut redonner une image familière à une place. Elle ne restitue pourtant ni tous les matériaux ni toutes les fonctions du bâtiment d'origine. Une ressemblance visuelle doit être distinguée d'une continuité historique complète. Les notices expliqueront la date et les matériaux de la nouvelle intervention. Les visiteurs pourront ainsi apprécier le travail sans le confondre avec un élément resté en place depuis l'origine. Les responsables souhaitent éviter aussi bien la promesse d'un retour complet dans le passé que le refus de reconnaître tout intérêt à la reconstruction. Celle-ci peut modifier une place et transmettre des repères, mais son statut doit rester lisible. Le débat gagnera en précision si chacun sait ce qui a été conservé, ce qui a été étudié et ce qui a été recréé aujourd'hui. La façade reconstruite ressemble à des photographies du XIXe siècle, mais la structure, les matériaux et les fonctions intérieures datent de la restauration récente. La notice distingue les éléments d'origine des ajouts.","question":"Quelle précision doit accompagner la reconstruction pour éviter un malentendu historique ?","explanation":"A distingue restitution visuelle et continuité matérielle et fonctionnelle. B/D effacent cette distinction, C nie l'intérêt documentaire et urbain d'une reconstruction."},{"number":38,"points":33,"correct":"C","options":["Le nombre de photographies partagées chaque année, qui indique indirectement l'emploi conservé dans les ateliers.","L'évolution du prix des souvenirs, considérée comme indice de maintien des services destinés aux habitants.","La stabilité des logements, ateliers et commerces nécessaires aux habitants.","Le total des labels accordés à la région, qui permettrait d'inférer la stabilité des logements du quartier."],"passage":"Une ville veut attirer des visiteurs grâce à un label patrimonial. Certains ateliers et logements risquent de devenir des hébergements touristiques. Le conseil débat donc d'outils pour conserver des fonctions ordinaires. Valoriser un lieu peut fragiliser ce qui le rend habitable si l'attractivité devient son seul objectif. Les élus étudient notamment la place des commerces utiles au quotidien et les possibilités pour les salariés de se loger. Les associations rappellent qu'une rue attractive pour une visite courte peut devenir difficile à vivre si les fonctions ordinaires disparaissent. Le programme cherchera donc des indicateurs qui ne se limitent pas aux entrées dans les monuments. Il devra aussi regarder la stabilité des habitants et l'accès aux services. Le patrimoine est ici lié à une vie présente, dont l'affaiblissement pourrait finir par réduire la diversité et l'intérêt du quartier que l'on souhaite précisément mettre en valeur. Après l'obtention du label, les visiteurs augmentent mais deux ateliers ferment pour devenir des locations de courte durée. La commune suit désormais le maintien des fonctions quotidiennes parallèlement aux entrées touristiques.","question":"Quel indice compléterait utilement les chiffres de fréquentation patrimoniale ?","explanation":"C suit la continuité des fonctions locales, logements et ateliers, que les visites patrimoniales ne mesurent pas. A/B/D substituent des indicateurs touristiques à la vie quotidienne."},{"number":39,"points":33,"correct":"C","options":["Remplacer sans trace les anciennes catégories dans l'index, mais conserver les originaux uniquement dans les copies téléchargeables aux chercheurs spécialisés.","Afficher les anciens intitulés sans commentaire pour préserver une recherche neutre, en réservant les notes aux documents ouverts après sélection.","Maintenir les termes historiques identifiables et recherchables, tout en signalant les notes de contexte dès l'affichage des résultats.","Masquer les expressions contestées dans tous les résultats publics, puis les restituer seulement si un lecteur démontre leur valeur historique."],"passage":"Des archives numérisées rendent une collection plus largement consultable. Pourtant, certaines descriptions reflètent d'anciennes catégories contestées. L'équipe conserve la trace historique tout en ajoutant des explications. Faciliter l'accès à une source ne dispense pas d'aider à comprendre les conditions dans lesquelles elle a été produite. Les utilisateurs pourront voir le vocabulaire d'origine tout en disposant d'une note sur son contexte et sur les limites qu'il comporte aujourd'hui. Les archivistes ne veulent ni corriger silencieusement le passé ni laisser les descriptions anciennes fonctionner comme des catégories naturelles. Ils rendront leurs interventions identifiables pour permettre la recherche. Les documents restent des sources à examiner, pas des récits automatiquement fiables parce qu'ils sont anciens ou désormais disponibles sur un écran. La numérisation élargit les possibilités de consultation, mais elle augmente aussi l'importance des repères qui accompagnent leur lecture par un public nouveau. Une fiche ancienne emploie une catégorie aujourd'hui contestée. La base conserve le texte original dans un champ identifié et lui ajoute une note récente expliquant son contexte et ses limites. Les archivistes examinent ensuite deux modes de recherche. Dans le premier, une requête utilisant le terme ancien retrouve les fiches, mais les résultats affichent aussi une note indiquant sa provenance et les catégories auxquelles il renvoyait à l'époque. Dans le second, le terme a été remplacé dans les métadonnées sans conserver de lien visible vers la formulation d'origine; certains documents deviennent difficiles à retrouver pour les chercheurs qui étudient précisément l'histoire de ce vocabulaire. Un groupe d'usagers relève toutefois que l'affichage du mot ancien sans contexte dans les aperçus peut encore laisser croire qu'il s'agit d'une catégorie actuelle. L'équipe décide donc de signaler la médiation éditoriale jusque dans les listes de résultats, sans supprimer le champ d'origine. Elle précise que cette solution ne garantit pas que tous les lecteurs interpréteront correctement les archives.","question":"Quelle décision concilie le mieux la traçabilité scientifique et le risque de naturaliser une catégorie ancienne ?","explanation":"C concilie une source historique visible et recherchable avec un avertissement contextuel également visible dans les résultats. A efface la trace dans les métadonnées, limitant la recherche; B laisse les aperçus hors contexte; D établit un filtre d'accès non prévu qui empêche une consultation historique normale. Le texte ne prétend pas que la note élimine toute mauvaise interprétation."}]}$paper_16$::jsonb),
('tcf-reading-17','tcf-reading-2026-11-close-reading-v4',$paper_17${"id":"tcf-reading-17","title":"TCF Reading · Test 17","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["Dans chaque salle d'activité","Dans l'espace près de l'entrée","Sur l'escalier","Dans la cuisine"],"passage":"L'accueil parents-enfants ouvre à neuf heures trente. Les poussettes doivent rester dans l'espace prévu près de l'entrée.\n\nL'équipe vous indiquera ensuite la salle de jeux. Merci de libérer le passage pour les autres familles.","question":"Où déposer les poussettes ?","explanation":"Le passage indique : « L'accueil parents-enfants ouvre à neuf heures trente. Les poussettes doivent rester dans l'espace prévu près de l'entrée. » Cela justifie la réponse : Dans l'espace près de l'entrée."},{"number":2,"points":3,"correct":"C","options":["Ils doivent tous payer une seconde fois","Le groupe change de destination obligatoirement","Leur inscription est conservée","La sortie est annulée définitivement"],"passage":"La sortie intergénérationnelle est reportée à jeudi. Les inscriptions déjà confirmées restent valables.\n\nLe lieu de rendez-vous reste le même. Merci de prévenir les personnes qui vous accompagnent.","question":"Que doivent savoir les inscrits ?","explanation":"Le passage indique : « La sortie intergénérationnelle est reportée à jeudi. Les inscriptions déjà confirmées restent valables. » Cela justifie la réponse : Leur inscription est conservée."},{"number":3,"points":3,"correct":"C","options":["Seulement les enfants majeurs","Uniquement une famille au complet","Un parent non accompagné","Les professionnels exclusivement"],"passage":"La permanence familiale reçoit aussi sans enfant. Un parent peut venir seul poser ses questions.\n\nLes échanges sont gratuits et confidentiels. Aucune inscription préalable n'est demandée pour cette première rencontre.","question":"Qui peut être accueilli ?","explanation":"Le passage indique : « La permanence familiale reçoit aussi sans enfant. Un parent peut venir seul poser ses questions. » Cela justifie la réponse : Un parent non accompagné."},{"number":4,"points":3,"correct":"D","options":["Un gâteau chacun","Des boissons sucrées","Un repas complet","Aucun plat n'est obligatoire"],"passage":"Le goûter partagé ne demande aucune préparation maison. Des fruits et de l'eau sont déjà prévus.\n\nVous pouvez simplement venir avec votre famille. Merci de signaler les allergies lors de votre inscription à l'accueil.","question":"Que doivent nécessairement préparer les participants ?","explanation":"Le passage indique : « Le goûter partagé ne demande aucune préparation maison. Des fruits et de l'eau sont déjà prévus. » Cela justifie la réponse : Aucun plat n'est obligatoire."},{"number":5,"points":9,"correct":"A","options":["Une heure de fin à respecter","Un changement d'école","Une obligation de rester jusqu'au soir","Un refus de toute garde"],"passage":"Je garderai les enfants mardi, mais peux-tu les récupérer à dix-sept heures ? Mon rendez-vous suivant ne peut pas être déplacé.\n\nJe préparerai leurs affaires avant ton arrivée et laisserai les manteaux près de la porte. Préviens-moi si tu as besoin de l'adresse exacte.","question":"Quelle contrainte est exprimée ?","explanation":"Le passage indique : « Je garderai les enfants mardi, mais peux-tu les récupérer à dix-sept heures ? Mon rendez-vous suivant ne peut pas être déplacé. » Cela justifie la réponse : Une heure de fin à respecter."},{"number":6,"points":9,"correct":"C","options":["Respecter le lieu de départ","Prendre connaissance de l'horaire","Être accompagné d'un enfant","Participer à la promenade"],"passage":"Notre groupe de marche accueille aussi les grands-parents sans petits-enfants. Le thème rapproche les générations sans imposer de venir en famille.\n\nLe départ se fait devant le centre social. Le parcours est court et comprend une pause sur la place du village.","question":"Quelle condition n'est pas exigée ?","explanation":"Le passage indique : « Notre groupe de marche accueille aussi les grands-parents sans petits-enfants. Le thème rapproche les générations sans imposer de venir en famille. » Cela justifie la réponse : Être accompagné d'un enfant."},{"number":7,"points":9,"correct":"D","options":["Les horaires de la cuisine","Uniquement les prix des ingrédients","Le nom des magasins","Les gestes et conseils associés à la recette"],"passage":"J'aimerais enregistrer les recettes de grand-mère avec ses explications. La liste des ingrédients seule ne raconte pas ses astuces.\n\nJe pourrais ensuite partager ces souvenirs avec mes cousins qui habitent loin. Veux-tu lui demander si elle accepte que nous venions dimanche avec un microphone ?","question":"Quel aspect veut-on conserver ?","explanation":"Le passage indique : « J'aimerais enregistrer les recettes de grand-mère avec ses explications. La liste des ingrédients seule ne raconte pas ses astuces. » Cela justifie la réponse : Les gestes et conseils associés à la recette."},{"number":8,"points":9,"correct":"B","options":["Imposer un jeu unique à toutes les familles","Aider à choisir un jeu partagé","Remplacer les parents pendant une semaine","Vendre tous les jouets neufs"],"passage":"La ludothèque prête des jeux de plusieurs âges. L'équipe peut conseiller un jeu utilisable par des enfants de niveaux différents.\n\nLe prêt dure trois semaines. Pensez à vérifier le contenu de la boîte avant de la rapporter à l'accueil.","question":"Quel service est proposé ?","explanation":"Le passage indique : « La ludothèque prête des jeux de plusieurs âges. L'équipe peut conseiller un jeu utilisable par des enfants de niveaux différents. » Cela justifie la réponse : Aider à choisir un jeu partagé."},{"number":9,"points":9,"correct":"C","options":["Une dispense de recevoir les informations","Une suppression de la réunion","Un autre accès aux informations et aux échanges","Un changement de tous les participants"],"passage":"Je ne pourrai pas venir à la réunion en soirée. Existe-t-il un compte rendu ou un autre moment d'échange ?\n\nJe souhaite comprendre les décisions prises et donner mon avis sur la prochaine sortie. Tu peux me répondre par message.","question":"Que demande cette personne ?","explanation":"Le passage indique : « Je ne pourrai pas venir à la réunion en soirée. Existe-t-il un compte rendu ou un autre moment d'échange ? » Cela justifie la réponse : Un autre accès aux informations et aux échanges."},{"number":10,"points":9,"correct":"B","options":["Publier automatiquement chaque visage","Vérifier les autorisations de diffusion","Vendre les photos aux invités","Éviter toute prise de vue privée nécessairement"],"passage":"Merci de demander l'accord des familles avant de diffuser les photos de la fête. La présence à l'événement n'autorise pas toute publication.\n\nCertaines familles acceptent les images dans l'album privé du groupe mais pas sur un site accessible à tous. Vérifiez chaque autorisation.","question":"Quelle règle est rappelée ?","explanation":"Le passage indique : « Merci de demander l'accord des familles avant de diffuser les photos de la fête. La présence à l'événement n'autorise pas toute publication. » Cela justifie la réponse : Vérifier les autorisations de diffusion."},{"number":11,"points":15,"correct":"B","options":["Le statut professionnel des parents","La diversité des contributions possibles","Une hiérarchie fixe par génération","La force physique uniquement"],"passage":"Un centre organise des ateliers où enfants et adultes construisent ensemble. Les tâches sont réparties selon les envies et les capacités, pas seulement selon l'âge.\n\nPour fabriquer une petite étagère, une personne peut mesurer, une autre tenir les pièces et une troisième préparer la peinture. Les animateurs présentent les outils et vérifient leur maniement avant chaque étape. Les rôles peuvent changer pendant la séance afin que chacun découvre plusieurs gestes. Les réalisations seront emportées par les participants après le séchage. Le centre demande simplement de porter des vêtements qui ne craignent pas les taches et de prévenir en cas de besoin particulier.","question":"Quel principe guide la répartition ?","explanation":"Le passage indique : « Un centre organise des ateliers où enfants et adultes construisent ensemble. Les tâches sont réparties selon les envies et les capacités, pas seulement selon l'âge. » Cela justifie la réponse : La diversité des contributions possibles."},{"number":12,"points":15,"correct":"C","options":["Des meubles définitifs pour chaque maison","Un transport scolaire permanent","Des équipements temporaires","Des réparations industrielles"],"passage":"Des habitants proposent une bibliothèque de poussettes et de sièges. Le prêt limite l'achat d'objets utilisés pendant de courtes périodes.\n\nLes objets sont nettoyés et vérifiés entre deux prêts. Les familles réservent le matériel dont elles ont besoin pour une visite ou une période de croissance. Une fiche indique les conditions de retour et la disponibilité des équipements. Les réservations seront confirmées par un bénévole avant chaque retrait.","question":"Quel besoin ce service vise-t-il ?","explanation":"Le passage indique : « Des habitants proposent une bibliothèque de poussettes et de sièges. Le prêt limite l'achat d'objets utilisés pendant de courtes périodes. » Cela justifie la réponse : Des équipements temporaires."},{"number":13,"points":15,"correct":"D","options":["Appliquer un questionnaire sans discussion","Présenter des informations personnelles obligatoires","Évaluer les autres familles publiquement","Définir les sujets utiles à partir de leurs besoins"],"passage":"Une association accueille les nouveaux parents sans programme imposé. Les échanges partent des questions du groupe, tout en respectant la confidentialité.\n\nLes rencontres se déroulent dans une salle où chacun peut parler ou simplement écouter. L'animatrice commence par rappeler que les situations sont différentes et qu'aucun témoignage ne sera transmis à l'extérieur. Certains participants évoquent les nuits difficiles, d'autres les démarches à réaliser après une naissance. Une information professionnelle peut être proposée lorsque le groupe le souhaite. Les coordonnées des services compétents restent disponibles à la fin de la séance, sans obligation de poursuivre un accompagnement.","question":"Quelle place est donnée aux participants ?","explanation":"Le passage indique : « Une association accueille les nouveaux parents sans programme imposé. Les échanges partent des questions du groupe, tout en respectant la confidentialité. » Cela justifie la réponse : Définir les sujets utiles à partir de leurs besoins."},{"number":14,"points":15,"correct":"B","options":["Accueillir des jeunes visiteurs","Réduire les personnes âgées à leurs souvenirs","Permettre des intérêts communs","Choisir des sujets actuels"],"passage":"Une maison de retraite invite des lycéens à un atelier radio. Chacun choisit son sujet ; les résidents ne sont pas limités au récit du passé.\n\nLes participants préparent les questions, enregistrent les voix et choisissent les sons qui accompagneront l'émission. Une résidente souhaite parler de musique actuelle tandis qu'un élève s'intéresse aux transformations de son quartier. Le journaliste qui les accompagne explique comment vérifier une information et demander l'autorisation de diffuser une voix. L'émission finale sera écoutée ensemble avant publication. Cette étape permettra à chacun de commenter le montage et de préciser un propos qui aurait été mal compris.","question":"Quelle idée est évitée ?","explanation":"Le passage indique : « Une maison de retraite invite des lycéens à un atelier radio. Chacun choisit son sujet ; les résidents ne sont pas limités au récit du passé. » Cela justifie la réponse : Réduire les personnes âgées à leurs souvenirs."},{"number":15,"points":15,"correct":"A","options":["La participation avec un accompagnateur non apparenté","La garde anonyme des enfants","La suppression des inscriptions","L'absence de tout adulte responsable"],"passage":"Un club ouvre des activités familiales sans exiger un lien de parenté entre accompagnateurs et enfants. Les adultes responsables sont identifiés à l'inscription.\n\nUne tante, un voisin ou un ami peut ainsi accompagner un enfant avec l'autorisation nécessaire. Les organisateurs souhaitent accueillir les différents réseaux de soutien qui existent autour des jeunes. Ils demandent les coordonnées des responsables pour pouvoir les joindre pendant la séance. Les activités sont présentées à l'avance afin de choisir celles qui conviennent aux capacités du groupe. Le mot familial décrit ici une façon de participer ensemble, sans imposer un modèle unique de composition du foyer.","question":"Quelle souplesse est prévue ?","explanation":"Le passage indique : « Un club ouvre des activités familiales sans exiger un lien de parenté entre accompagnateurs et enfants. Les adultes responsables sont identifiés à l'inscription. » Cela justifie la réponse : La participation avec un accompagnateur non apparenté."},{"number":16,"points":15,"correct":"C","options":["Supprimer les documents individuels","Confier toutes les décisions au groupe","Partager sans effacer toute confidentialité","Rendre tous les dossiers publics"],"passage":"Un atelier aide les familles à organiser des documents communs. Il distingue les pièces utiles à partager et les informations personnelles à conserver séparément.\n\nLes participants classent notamment les contrats, les contacts utiles et les consignes concernant les personnes à prévenir. L'animatrice rappelle qu'une organisation pratique ne donne pas automatiquement le droit de consulter tous les dossiers d'un proche. Chaque personne décide des accès qu'elle souhaite autoriser. Une liste indique où se trouvent les documents sans nécessairement en reproduire le contenu.","question":"Quel apprentissage est proposé ?","explanation":"Le passage indique : « Un atelier aide les familles à organiser des documents communs. Il distingue les pièces utiles à partager et les informations personnelles à conserver séparément. » Cela justifie la réponse : Partager sans effacer toute confidentialité."},{"number":17,"points":15,"correct":"B","options":["La présence des nouveaux habitants","L'incompatibilité de certains horaires","Le nombre de salles seulement","Le manque de sujets à discuter"],"passage":"Une commune propose des réunions en journée et en soirée. Elle souhaite toucher des familles ayant des horaires de travail différents.\n\nLes premières rencontres avaient lieu à une heure qui convenait surtout aux personnes déjà présentes dans les associations. Les agents ont demandé aux absents quels moments seraient possibles pour eux. Une synthèse commune circulera après chaque séance pour que les échanges ne se divisent pas en deux groupes sans lien. Les familles pourront aussi envoyer une remarque écrite. Le conseil municipal comparera les propositions avant d'arrêter le calendrier du trimestre suivant.","question":"Quel obstacle cherche-t-elle à réduire ?","explanation":"Le passage indique : « Une commune propose des réunions en journée et en soirée. Elle souhaite toucher des familles ayant des horaires de travail différents. » Cela justifie la réponse : L'incompatibilité de certains horaires."},{"number":18,"points":15,"correct":"A","options":["Le refus ponctuel reste possible","Le calendrier est fixé pour dix ans","Une absence entraîne une exclusion automatique","Toute demande doit être acceptée"],"passage":"Des voisins échangent des heures de garde selon un calendrier. Chacun peut refuser un créneau sans perdre définitivement l'accès au réseau.\n\nLe règlement prévoit une confirmation écrite pour chaque garde et un échange préalable entre les adultes concernés. Les disponibilités sont mises à jour chaque semaine afin d'éviter les malentendus. Un membre peut être très présent pendant les vacances puis beaucoup moins disponible au moment d'un changement professionnel. Le réseau cherche à reconnaître ces variations plutôt qu'à imposer une contribution identique chaque mois.","question":"Quelle règle protège la souplesse du dispositif ?","explanation":"Le passage indique : « Des voisins échangent des heures de garde selon un calendrier. Chacun peut refuser un créneau sans perdre définitivement l'accès au réseau. » Cela justifie la réponse : Le refus ponctuel reste possible."},{"number":19,"points":15,"correct":"A","options":["Partager un moment autour de la lecture","Préparer un concours obligatoire","Mesurer la vitesse de lecture uniquement","Classer les familles"],"passage":"Un programme de lecture associe un adulte et un enfant autour d'un livre choisi ensemble. L'objectif est le plaisir de l'échange, pas une note scolaire.\n\nLes bénévoles proposent plusieurs albums, mais le duo peut aussi apporter un ouvrage déjà aimé. On peut s'arrêter sur une image, revenir à une page ou raconter un souvenir évoqué par l'histoire. Les organisateurs espèrent que cette liberté aidera les participants à prendre confiance et à retrouver, plus tard, le chemin de la bibliothèque.","question":"Quelle finalité est privilégiée ?","explanation":"Le passage indique : « Un programme de lecture associe un adulte et un enfant autour d'un livre choisi ensemble. L'objectif est le plaisir de l'échange, pas une note scolaire. » Cela justifie la réponse : Partager un moment autour de la lecture."},{"number":20,"points":21,"correct":"D","options":["Obligation de participer chaque soir","Séparation complète de toutes les générations","Suppression de tous les espaces privés","Rencontres possibles et respect de l'intimité"],"passage":"Une résidence intergénérationnelle prévoit des espaces communs, mais aussi des logements privés. Les relations ne doivent pas devenir une présence collective permanente imposée. Les habitants définissent ensemble les horaires des repas partagés et les modalités de réservation de la salle. Chacun conserve la possibilité de dîner chez soi ou de recevoir ses proches sans participer à l'activité annoncée. Une personne référente intervient en cas de désaccord sur le bruit ou l'entretien. Le projet repose ainsi sur des occasions régulières de se croiser et sur des limites claires qui permettent de choisir son degré de participation.","question":"Quel équilibre est recherché ?","explanation":"Le passage indique : « Une résidence intergénérationnelle prévoit des espaces communs, mais aussi des logements privés. Les relations ne doivent pas devenir une présence collective permanente imposée. » Cela justifie la réponse : Rencontres possibles et respect de l'intimité."},{"number":21,"points":21,"correct":"A","options":["Une difficulté d'accès au lieu","Une absence certaine d'intérêt","Un prix obligatoirement trop élevé","Un manque de jeux dans chaque foyer"],"passage":"Un centre reçoit de moins en moins de familles malgré des activités appréciées. Les entretiens montrent que le trajet en bus a été compliqué par une nouvelle correspondance. Le questionnaire de satisfaction avait été distribué uniquement aux personnes encore présentes. Il ne permettait donc pas de comprendre pourquoi les autres avaient cessé de venir. L'équipe a rappelé plusieurs anciens participants avec leur accord. Ceux-ci ont expliqué que le nouvel itinéraire rendait le retour difficile à l'heure du repas.","question":"Quelle cause possible est identifiée ?","explanation":"Le passage indique : « Un centre reçoit de moins en moins de familles malgré des activités appréciées. Les entretiens montrent que le trajet en bus a été compliqué par une nouvelle correspondance. » Cela justifie la réponse : Une difficulté d'accès au lieu."},{"number":22,"points":21,"correct":"C","options":["Un centre commercial obligatoire","Une salle sans possibilité de discussion","Un espace de sociabilité accessible","Une compétition permanente"],"passage":"Des adolescents participent à la conception d'un espace de quartier. Ils demandent un lieu où se rencontrer sans devoir consommer, pas seulement des équipements sportifs. Lors des premières réunions, les adultes avaient surtout discuté du choix des terrains et du matériel. Les jeunes ont décrit leurs habitudes après les cours et leurs difficultés à rester ensemble lorsqu'il pleut. Son fonctionnement sera discuté avec les riverains, afin que les règles répondent aux usages réels et aux contraintes du voisinage.","question":"Quel besoin expriment-ils ?","explanation":"Le passage indique : « Des adolescents participent à la conception d'un espace de quartier. Ils demandent un lieu où se rencontrer sans devoir consommer, pas seulement des équipements sportifs. » Cela justifie la réponse : Un espace de sociabilité accessible."},{"number":23,"points":21,"correct":"A","options":["Le travail d'organisation","La surface des logements uniquement","Le nombre de meubles","Les achats de loisirs"],"passage":"Une enquête sur les aidants mesure les tâches visibles, puis ajoute le temps consacré à organiser et anticiper. Cette charge moins matérielle était peu décrite dans les premiers résultats. Prendre les rendez-vous, vérifier les renouvellements de documents ou prévoir un remplacement mobilise l'attention même lorsqu'aucun soin n'est réalisé. Plusieurs personnes expliquent qu'elles doivent rester joignables pendant leur travail. La nouvelle enquête demande donc aussi qui coordonne les interventions et avec quelle fréquence.","question":"Quel aspect est mieux pris en compte ?","explanation":"Le passage indique : « Une enquête sur les aidants mesure les tâches visibles, puis ajoute le temps consacré à organiser et anticiper. Cette charge moins matérielle était peu décrite dans les premiers résultats. » Cela justifie la réponse : Le travail d'organisation."},{"number":24,"points":21,"correct":"A","options":["Adapter les échanges aux situations particulières","Éviter tous les témoignages","Imposer une méthode unique","Considérer les contraintes comme identiques"],"passage":"Un atelier réunit des personnes qui accompagnent un proche. Les animateurs rappellent que les solutions d'une famille ne conviennent pas automatiquement à toutes les autres. Les horaires professionnels, la distance entre les logements ou l'état de santé du proche modifient ce qui est réalisable. Une proposition peut être discutée comme une piste à adapter, sans devenir une consigne. Les échanges permettent aussi d'identifier les questions qui nécessitent un avis spécialisé.","question":"Quelle prudence est recommandée ?","explanation":"Le passage indique : « Un atelier réunit des personnes qui accompagnent un proche. Les animateurs rappellent que les solutions d'une famille ne conviennent pas automatiquement à toutes les autres. » Cela justifie la réponse : Adapter les échanges aux situations particulières."},{"number":25,"points":21,"correct":"D","options":["L'augmentation automatique de la fréquentation de toutes les autres aires du quartier.","La disparition des besoins d'accueil des familles fréquentant le parc.","La réduction systématique de la durée de présence des accompagnateurs.","La possibilité d'une présence prolongée et d'échanges entre adultes autour des jeux."],"passage":"Un quartier installe des bancs près de l'aire de jeux. Les adultes peuvent rester confortablement, ce qui facilite aussi la venue des grands-parents et les échanges entre accompagnateurs. Auparavant, plusieurs accompagnateurs partaient rapidement faute de pouvoir s'asseoir. Les nouveaux équipements sont placés à distance raisonnable des jeux, avec une vue dégagée. Elle observera les usages au cours des prochaines semaines avant de décider si d'autres installations sont nécessaires pour rendre le lieu plus accueillant. Les bancs sont surtout utilisés par des adultes accompagnant des enfants, mais certains voisins y restent même après les jeux pour discuter. La commune mesure donc aussi la durée des visites et les rencontres.","question":"Quel effet du mobilier serait sous-estimé par un comptage limité aux enfants jouant ?","explanation":"Les bancs servent au confort et aux liens des accompagnateurs. D; les autres effets ne sont pas établis."},{"number":26,"points":21,"correct":"D","options":["L'illustration est utile uniquement si elle élimine toutes les consignes écrites du dossier.","Les personnes maîtrisant la langue du service n'ont jamais besoin d'aide pour une inscription.","Les exemples fictifs remplacent la nécessité de fournir des renseignements dans les dossiers réels.","La traduction d'un terme doit s'accompagner d'étapes permettant d'agir."],"passage":"Une association propose des conseils aux parents en plusieurs langues. Elle utilise aussi des exemples concrets plutôt que traduire uniquement des termes administratifs difficiles. Une demande d'inscription est ainsi présentée à partir d'un dossier fictif, étape par étape. Les personnes peuvent poser leurs questions oralement et repartir avec un résumé illustré. Les intervenants vérifient que les informations essentielles ont été comprises sans demander aux participants de raconter leur situation devant tout le groupe. Lors d'un essai, les parents comprennent la traduction littérale d'un mot administratif sans savoir quelle pièce joindre. Un dossier fictif et un exemple illustré clarifient l'étape attendue.","question":"Pourquoi la traduction seule ne suffit-elle pas toujours à rendre le service accessible ?","explanation":"La compréhension opérationnelle exige des étapes concrètes, D. C/B/A exagèrent ou restreignent l'outil."},{"number":27,"points":21,"correct":"C","options":["L'impossibilité d'organiser des échanges avec des proches à horaires fixés à l'avance.","L'absence de toute envie de communiquer chez les personnes qui demandent une première aide.","Un accompagnement pratique pour rendre le matériel réellement utilisable.","La nécessité d'acquérir davantage d'appareils avant toute communication vidéo."],"passage":"Des résidents souhaitent un téléphone collectif pour les appels vidéo. L'équipe organise des créneaux accompagnés, car la présence du matériel ne suffit pas à garantir son utilisation. Une première séance permet de régler le volume, de comprendre l'image et d'apprendre à terminer un appel. Les proches reçoivent aussi les horaires auxquels ils peuvent contacter la résidence. Le personnel vérifie que chacun souhaite participer avant d'organiser une conversation. Après la mise à disposition du téléphone, plusieurs résidents attendent le personnel pour régler le son ou lancer l'appel. Les séances accompagnées leur permettent progressivement de choisir eux-mêmes les créneaux.","question":"De quoi les résidents ont-ils encore besoin pour utiliser eux-mêmes le téléphone collectif ?","explanation":"C désigne l'accompagnement concret pour régler le son, lancer l'appel et ensuite choisir un créneau. A invente une impossibilité de programmer des échanges; B transforme un besoin d'aide en absence d'envie; D prescrit d'autres appareils alors que celui disponible peut être utilisé après accompagnement."},{"number":28,"points":21,"correct":"A","options":["Elle révèle des difficultés de visibilité particulières à la hauteur des enfants.","Elle permet de choisir les aménagements définitifs sans consultation des services ou des familles.","Elle remplace les données techniques puisque l'expérience vécue suffit à déterminer les travaux.","Elle établit que chaque danger perçu par un élève correspond à un accident certain."],"passage":"Une commune associe les enfants à l'évaluation des trajets scolaires. Leur taille et leur expérience font apparaître des obstacles peu visibles pour les adultes. Ils photographient les endroits où leur vue est cachée par un véhicule ou un panneau. Les agents comparent ensuite ces observations avec les mesures de circulation. Cette démarche complète l'expertise technique sans demander aux élèves de décider seuls des travaux. Les premières propositions seront présentées aux familles et testées sur un trajet avant un éventuel élargissement. À hauteur d'adulte, une voiture garée ne masque pas le passage; à hauteur d'enfant, elle cache l'arrivée des véhicules. Les observations des élèves sont confrontées aux relevés de circulation.","question":"Quel intérêt possède l'observation faite à hauteur d'enfant ?","explanation":"La perspective physique des élèves ajoute une donnée d'usage. A; C/D/B surinterprètent."},{"number":29,"points":21,"correct":"B","options":["Séparer les séances par tranche d'âge pour éviter que les expériences ne se contredisent.","Attribuer les rôles selon les savoirs à partager, non selon l'âge.","Confier systématiquement le numérique aux jeunes et les objets matériels aux générations âgées.","Garder les aînés comme enseignants afin de transmettre des pratiques anciennes aux plus jeunes."],"passage":"Un groupe organise un échange de savoirs entre générations. Les jeunes ne sont pas toujours les élèves : ils présentent aussi des pratiques que les plus âgés souhaitent découvrir. Une personne âgée peut vouloir découvrir un logiciel et un adolescent apprendre à entretenir une plante. Les organisateurs constituent les petits groupes selon ces envies, plutôt qu'en distribuant les rôles à partir des dates de naissance. Dans le même atelier, une adolescente explique un réglage numérique et un retraité montre une technique de jardinage. Lors de la séance suivante, leurs rôles changent encore selon les sujets.","question":"Quel principe d'organisation rend cette transmission réellement réciproque ?","explanation":"Les rôles dépendent des savoirs et envies, non des générations. B. D/C/A réintroduisent des stéréotypes."},{"number":30,"points":26,"correct":"C","options":["La solidarité privée doit remplacer la totalité de l'aide publique dès qu'un parent existe.","Les familles qui vivent loin souhaitent nécessairement participer moins aux décisions.","Temps, distance et ressources font varier les possibilités d'aide familiale.","La présence de proches suffit à prouver que les besoins d'accompagnement diminuent."],"passage":"La solidarité familiale est parfois supposée disponible sans limite. Elle dépend pourtant du temps, de la proximité et des ressources de chacun. Un service public qui compte uniquement sur elle risque de traiter différemment des personnes ayant les mêmes besoins mais des entourages très différents. Deux voisins âgés, par exemple, peuvent avoir des enfants qui habitent à des distances très différentes. Demander le même soutien à leurs familles ne crée pas les mêmes possibilités concrètes. Deux personnes âgées ont les mêmes besoins d'aide. L'une peut compter sur des proches vivant à quelques rues, l'autre sur un fils vivant loin avec des contraintes professionnelles. Un service identique fondé sur la famille leur offrirait des soutiens très différents.","question":"Pourquoi l'administration ne peut-elle pas déduire une capacité de soutien identique des liens familiaux ?","explanation":"Les configurations familiales modifient la possibilité concrète d'aider. C; D/B/A ignorent les contraintes."},{"number":31,"points":26,"correct":"D","options":["Le nombre d'enfants par classe, sans rapport avec l'inscription proposée.","La présence des animateurs, dont la profession déterminait l'accessibilité du programme.","Le prix des activités, qui n'était pas décrit comme obstacle dans cette situation.","Les conditions pratiques supposées par l'organisation, malgré un intitulé inclusif."],"passage":"Une activité dite familiale peut sembler ouverte à tous. Si elle suppose deux adultes disponibles le samedi et une voiture, certaines familles restent à l'écart. Les conditions concrètes de participation comptent autant que le nom accueillant donné au programme. Les organisateurs proposent désormais une inscription individuelle et indiquent les transports possibles. Ils vérifient aussi si le matériel peut être prêté. Une activité annoncée « pour toutes les familles » demande une voiture et deux adultes disponibles le samedi. Après avoir proposé un accès par transport et une participation individuelle, les organisateurs accueillent de nouveaux foyers.","question":"Quel aspect de l'annonce pouvait masquer une exclusion ?","explanation":"Des présupposés de transport et de disponibilité excluent malgré le titre. D. Les autres paramètres ne sont pas appuyés."},{"number":32,"points":26,"correct":"D","options":["La différence de détail prouve que l'un des deux n'était pas présent pendant l'événement.","Les deux souvenirs doivent être identiques s'ils concernent la même date familiale.","Le souvenir de l'aîné est nécessairement exact parce qu'il avait davantage de responsabilités.","Des expériences différentes peuvent produire des souvenirs divergents sans mensonge."],"passage":"La mémoire familiale se construit avec des récits qui évoluent selon ceux qui les racontent. Des versions différentes ne signifient pas nécessairement qu'une personne cherche à tromper. Elles peuvent refléter des positions, des âges et des expériences distincts dans un même événement. Lors d'un atelier, plusieurs membres d'une famille décrivent ainsi une même fête avec des détails différents. L'animatrice conserve les deux témoignages et précise les circonstances dans lesquelles ils ont été recueillis. Deux frères se souviennent différemment d'un déménagement: l'un avait six ans, l'autre dix-sept et organisait le trajet. L'atelier relève leur âge et leur rôle avant de rapprocher les deux récits.","question":"Quelle conclusion sur ces témoignages serait la plus prudente ?","explanation":"Les positions vécues diffèrent, sans preuve de mensonge. D; C/B/A concluent trop vite."},{"number":33,"points":26,"correct":"B","options":["La prise de décision définitive à l'ouverture du dossier, sans nouvelles consultations.","Réviser l'aide selon l'évolution des besoins observés et exprimés.","L'attribution d'un soutien croissant automatiquement à chaque personne, indépendamment de son évolution.","La fixation d'un volume d'aide identique pour éviter toute différence entre les personnes."],"passage":"Un service souhaite soutenir les aidants sans décider à leur place. Il propose des temps de relais et demande régulièrement si les besoins ont changé. L'accompagnement ne consiste pas à fixer une fois pour toutes une solution supposée convenir à toute la durée de la situation. Une aide adaptée à une courte convalescence peut devenir insuffisante lorsque la dépendance s'installe. Un aidant bénéficie d'abord d'un relais deux heures par semaine; après une aggravation, cet horaire devient insuffisant. L'équipe revoit le soutien après échange plutôt que reconduire automatiquement l'ancien accord.","question":"Quelle qualité du suivi répond à l'évolution de la situation ?","explanation":"Le suivi est réévaluable et dialogué. B; D/A/C supposent une uniformité ou automatisme absent."},{"number":34,"points":26,"correct":"C","options":["Que les expériences diffèrent selon les parcours personnels.","Que les ateliers de jardinage exigent une qualification professionnelle.","Que les préférences découlent directement de l'âge des participants.","Que le programme puisse évoluer à partir des discussions des participants."],"passage":"Un projet rapproche des générations par des activités communes. Les organisateurs évitent de supposer d'avance que les jeunes veulent uniquement du numérique et les anciens uniquement raconter le passé. Les centres d'intérêt réels émergent des rencontres. Les premières séances laissent une place à la discussion et aux propositions spontanées. Un atelier peut ainsi réunir des amateurs de jardinage de plusieurs âges. Les premières propositions viennent de participants de plusieurs âges souhaitant tous jardiner. Les organisateurs renoncent donc au programme prévu qui séparait jeux numériques et récits anciens.","question":"Quelle hypothèse initiale le groupe doit-il abandonner ?","explanation":"Des intérêts réels traversent les âges, C. Les autres hypothèses ne sont pas celles critiquées."},{"number":35,"points":26,"correct":"B","options":["Les écarts entre quartiers, même lorsque les ménages interrogés présentent des réponses familiales cohérentes.","Des besoins contradictoires entre personnes d'un même ménage malgré une adresse commune.","Le nombre de questionnaires reçus par quartier, qui doit rester indépendant de la taille des ménages.","La localisation de chaque répondant, qui serait différente pour les personnes vivant à la même adresse."],"passage":"Une consultation compte une réponse par foyer. Des participants soulignent que cette unité peut masquer les besoins différents des personnes qui y vivent. Un avis commun est utile pour certaines questions, mais ne remplace pas toujours l'écoute individuelle. Un adolescent peut demander un espace calme tandis qu'un adulte souhaite surtout un accès plus facile au stationnement. Le questionnaire distingue les avis individuels et les réponses communes. Dans une consultation sur les transports, la mère et son adolescent vivent dans le même foyer mais utilisent des trajets différents. Une réponse unique risque de faire disparaître l'un de ces besoins.","question":"Quelle information une réponse par foyer peut-elle masquer ?","explanation":"B indique que des personnes partageant une adresse peuvent avoir des besoins opposés. A déplace le problème entre quartiers, C concerne le volume de réponses, D invente des localisations différentes au sein d'un foyer."},{"number":36,"points":33,"correct":"D","options":["Le sentiment des résidents de pouvoir choisir les occasions de rencontre, même lorsqu'ils n'y participent pas.","La diversité des activités proposées, dont certaines correspondent aux intérêts exprimés par les habitants.","La qualité des liens décrits par les résidents lors d'entretiens sur leurs relations quotidiennes.","Compter les présences sans tenir compte des liens ni du consentement."],"passage":"Une résidence promet de lutter contre la solitude en rapprochant des générations. Elle découvre que la proximité physique facilite certaines rencontres sans garantir la confiance. Des activités choisies et un respect du refus sont nécessaires. Créer les conditions d'une relation ne revient pas à pouvoir l'imposer. Lors des premières semaines, plusieurs habitants se sont sentis obligés d'assister à chaque repas annoncé, de peur de paraître peu sociables. L'équipe a donc précisé que les invitations pouvaient être refusées sans justification. Elle propose aussi des rencontres en petits groupes autour d'intérêts choisis, plutôt qu'un programme collectif quotidien. Les nouveaux arrivants disposent d'un interlocuteur pour poser leurs questions, mais restent libres d'organiser leurs journées. L'évaluation portera sur la qualité des liens décrits par les résidents et sur leur sentiment de pouvoir choisir, pas uniquement sur le nombre de personnes réunies dans la salle commune. Les résidents d'un immeuble partagent une salle commune, mais seuls ceux qui choisissent des activités à leur goût développent des liens. Ceux qui déclinent les rencontres restent pleinement membres du lieu.","question":"Quel résultat serait trompeur pour mesurer la lutte contre la solitude ?","explanation":"D serait trompeur parce que la coprésence ne garantit pas de lien librement choisi. A/B/C apportent justement des éléments sur le choix, les possibilités et les relations vécues."},{"number":37,"points":33,"correct":"D","options":["Inciter des personnes âgées à découvrir une activité sans expliquer les capacités différentes nécessaires à sa pratique.","Présenter des parcours variés au risque de diminuer la cohérence du message publicitaire sur l'âge.","Valoriser des liens discrets au détriment des grands-parents ayant des pratiques plus visibles et sportives.","Faire d'un portrait valorisant une attente uniforme qui invisibilise des situations moins spectaculaires."],"passage":"Une campagne valorise les grands-parents très actifs, toujours disponibles et connectés. Des associations apprécient cette image positive, mais craignent qu'elle devienne une norme excluant les personnes fatiguées ou moins équipées. Combattre un stéréotype ne devrait pas consister à le remplacer par une exigence de performance identique pour tous. Les témoignages retenus montrent surtout des voyages, des activités sportives et des services rendus aux enfants. Ils rendent moins visibles les relations fondées sur une présence discrète, un appel régulier ou un souvenir partagé. Les associations proposent d'élargir la campagne à ces expériences, sans présenter les limitations physiques comme un échec personnel. Une image valorisante peut ouvrir des possibilités, à condition de laisser une place à la diversité des situations et au droit de ne pas correspondre au portrait le plus spectaculaire. Une affiche montre uniquement des grands-parents sportifs et parfaitement connectés. Des personnes fatiguées y voient une nouvelle manière d'être jugées insuffisantes malgré leur engagement familial.","question":"Quel effet indésirable d'une représentation positive les associations redoutent-elles ?","explanation":"D signale le risque de transformer une image positive en norme de performance uniforme. A limite l'enjeu à une activité, B réduit la diversité à un problème de campagne, C suppose un remplacement du stéréotype par son inverse."},{"number":38,"points":33,"correct":"A","options":["Prendre l'absence en journée pour un manque d'intérêt.","Donner trop de poids à une contribution écrite lorsqu'elle complète des observations menées pendant les réunions.","Traiter les réponses à distance comme plus représentatives que celles recueillies auprès de parents présents.","Retenir seulement les avis formulés dans les réunions malgré la création de nouveaux canaux de participation."],"passage":"Des parents sont invités à participer aux activités de l'école. Les personnes disponibles en journée deviennent les interlocuteurs les plus visibles. L'équipe organise d'autres moyens de contribution pour entendre aussi celles qui ne peuvent pas venir. La disponibilité ne doit pas être confondue avec l'intérêt porté à la scolarité. Un questionnaire accessible par téléphone et des entretiens à des horaires variés complètent désormais les réunions habituelles. Des familles peuvent aussi apporter une contribution à distance, par exemple en proposant une lecture ou en commentant une information envoyée par l'équipe. Les enseignants veillent à ne pas réserver les décisions importantes aux échanges informels de fin de matinée. Ils résument les propositions et expliquent les suites qui leur sont données. Cette organisation permet de distinguer les obstacles pratiques d'une absence de volonté, tout en maintenant des occasions de rencontre pour les personnes qui peuvent se déplacer. Une mère souhaite s'impliquer mais travaille durant les réunions. Grâce à un entretien du soir, elle propose un changement finalement retenu. Le projet n'aurait pas recueilli cet avis avec ses seuls horaires habituels.","question":"Quelle erreur d'évaluation les nouveaux canaux de participation cherchent-ils à prévenir ?","explanation":"A nomme l'erreur d'interprétation de l'absence pendant les horaires de travail. B/C concernent des hiérarchies de contributions non décrites; D reprend un ancien biais, mais le problème précisément mesuré est l'inférence de désintérêt."},{"number":39,"points":33,"correct":"B","options":["Les échanges ont échoué à produire un soutien significatif parce qu'ils n'ont pas créé directement des places de remplacement institutionnelles, même si les informations utiles ont davantage circulé entre les personnes participant aux ateliers.","Les échanges peuvent améliorer l'orientation et les arrangements ponctuels, mais leur activité ne démontre pas que le manque de service institutionnel est comblé.","Le nombre de conseils échangés permet de mesurer l'accès réel à une relève professionnelle, dès lors que les demandes sont transmises anonymement.","Les arrangements avec les proches dispensent les organismes compétents de répondre à la pénurie de personnel déjà signalée par les participants."],"passage":"Un atelier réunit des aidants pour partager des pratiques. Les animateurs veillent à ce que l'échange ne transforme pas chacun en responsable de résoudre seul toutes les difficultés. L'entraide peut renforcer les personnes tout en faisant apparaître des besoins qui demandent une réponse collective ou professionnelle. Plusieurs participants décrivent des difficultés à obtenir un remplacement ou à comprendre les dispositifs existants. Le groupe peut partager des coordonnées et préparer des questions, mais il ne dispose ni des moyens ni de l'autorité nécessaires pour créer les services manquants. L'animateur propose donc de transmettre une synthèse anonyme aux organismes concernés, avec l'accord des personnes. Les rencontres restent aussi un espace où exprimer la fatigue sans devoir immédiatement trouver une solution. Reconnaître les limites de l'entraide protège les participants contre une nouvelle obligation de performance et permet de formuler plus clairement les demandes de soutien extérieur. Les aidants échangent une méthode utile pour demander un remplacement, mais constatent que le service correspondant manque dans leur zone. Le collectif transmet ce besoin aux organismes compétents sans le présenter comme un échec individuel. Un bilan compare les demandes formulées à la suite des réunions. Plusieurs aidants ont obtenu des renseignements plus précis et certains ont réussi à organiser un échange ponctuel de tâches avec des proches. Mais les demandes d'un service public de remplacement restent sans réponse faute de personnel dans la région. Les animateurs observent que les personnes les plus actives dans le groupe continuent elles aussi à manquer de temps de repos. Ils envisagent de recueillir les difficultés récurrentes dans un document anonyme adressé à l'organisme compétent, tout en maintenant un espace où les participants peuvent échanger des conseils sans devenir gestionnaires du service absent. Une participante suggère de compter le nombre de conseils échangés comme preuve que le problème institutionnel est résolu; le groupe refuse cette équivalence, sans nier l'utilité des informations partagées.","question":"Quelle conclusion distingue l'efficacité de l'entraide de ce qu'elle ne peut pas fournir à elle seule ?","explanation":"B distingue la valeur des conseils et de quelques arrangements ponctuels de l'insuffisance persistante du service de remplacement. A nie les progrès observés en matière d'information et d'entraide; C confond activité du groupe et offre professionnelle effective; D transforme des solutions familiales provisoires en décharge de responsabilité institutionnelle."}]}$paper_17$::jsonb),
('tcf-reading-18','tcf-reading-2026-11-close-reading-v4',$paper_18${"id":"tcf-reading-18","title":"TCF Reading · Test 18","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"B","options":["Six heures","Six heures quarante-cinq","Huit heures","Sept heures quinze"],"passage":"Le départ vers l'île est avancé à sept heures à cause de la marée. Présentez-vous quinze minutes avant.\n\nLes billets déjà achetés restent valables. Le contrôle des réservations se fera directement sur le quai habituel.","question":"À quelle heure faut-il être présent ?","explanation":"Le passage indique : « Le départ vers l'île est avancé à sept heures à cause de la marée. Présentez-vous quinze minutes avant. » Cela justifie la réponse : Six heures quarante-cinq."},{"number":2,"points":3,"correct":"B","options":["Une bouteille de gaz","Un sac de couchage","Un oreiller neuf","Une tente obligatoire"],"passage":"Le refuge ne fournit pas de couverture cette semaine. Apportez un sac de couchage même si votre place est réservée.\n\nLe repas du soir est maintenu.","question":"Quel équipement reste nécessaire ?","explanation":"Le passage indique : « Le refuge ne fournit pas de couverture cette semaine. Apportez un sac de couchage même si votre place est réservée. » Cela justifie la réponse : Un sac de couchage."},{"number":3,"points":3,"correct":"B","options":["La surveillance est assurée par tous les visiteurs","La surveillance commence à onze heures","La baignade est surveillée toute la nuit","La plage ferme à onze heures"],"passage":"La plage surveillée ouvre à onze heures. Avant cet horaire, aucune surveillance de baignade n'est assurée.\n\nLes horaires seront affichés à l'entrée. Renseignez-vous au poste de secours avant de vous installer près de l'eau.","question":"Que précise l'annonce ?","explanation":"Le passage indique : « La plage surveillée ouvre à onze heures. Avant cet horaire, aucune surveillance de baignade n'est assurée. » Cela justifie la réponse : La surveillance commence à onze heures."},{"number":4,"points":3,"correct":"D","options":["La route fermée","Le bord des falaises","Le sommet sans balisage","Le parcours intérieur"],"passage":"Le chemin des falaises est interdit par vent fort. Le parcours intérieur reste accessible.\n\nSuivez les panneaux au départ du parking. La réouverture sera annoncée lorsque les conditions permettront de circuler sans danger.","question":"Quel itinéraire est proposé ?","explanation":"Le passage indique : « Le chemin des falaises est interdit par vent fort. Le parcours intérieur reste accessible. » Cela justifie la réponse : Le parcours intérieur."},{"number":5,"points":9,"correct":"B","options":["Parcourir le plus grand nombre de refuges","Explorer sans porter tout le matériel","Descendre immédiatement en ville","Éviter toute promenade"],"passage":"Je préfère rester deux nuits au même refuge. Nous pourrons observer le lac sans transporter les sacs toute la journée.\n\nNous pourrions laisser une partie de nos affaires dans la chambre et partir avec un petit sac. Réserve deux places si tu es d'accord.","question":"Quel avantage est recherché ?","explanation":"Le passage indique : « Je préfère rester deux nuits au même refuge. Nous pourrons observer le lac sans transporter les sacs toute la journée. » Cela justifie la réponse : Explorer sans porter tout le matériel."},{"number":6,"points":9,"correct":"A","options":["Ne pas les emporter","Les déposer au musée","Les conserver comme souvenirs","Les vendre au retour"],"passage":"La sortie sur l'estran nécessite des chaussures fermées. Les coquillages observés seront laissés sur place.\n\nLe guide expliquera comment se déplacer sans abîmer le milieu. Pensez aussi à emporter de l'eau pour la promenade.","question":"Quelle règle concerne les animaux observés ?","explanation":"Le passage indique : « La sortie sur l'estran nécessite des chaussures fermées. Les coquillages observés seront laissés sur place. » Cela justifie la réponse : Ne pas les emporter."},{"number":7,"points":9,"correct":"C","options":["Éviter de rencontrer le guide","Changer automatiquement de destination","Attendre une meilleure visibilité","Profiter d'un brouillard plus épais"],"passage":"Le guide propose de partir plus tard : le brouillard devrait se lever. Nous garderons le même parcours si les conditions le permettent.\n\nJe vous enverrai la nouvelle heure de rendez-vous ce soir. Attendez ma confirmation avant de rejoindre le parking de départ demain matin.","question":"Pourquoi modifier le départ ?","explanation":"Le passage indique : « Le guide propose de partir plus tard : le brouillard devrait se lever. Nous garderons le même parcours si les conditions le permettent. » Cela justifie la réponse : Attendre une meilleure visibilité."},{"number":8,"points":9,"correct":"A","options":["Prévoir une tenue chaude","Renoncer à toute protection","Se fier uniquement au temps sur le quai","Acheter un vêtement à chaque escale"],"passage":"Pour la croisière d'observation, apportez des vêtements chauds. Le soleil au port ne garantit pas une température agréable en mer.\n\nUn vêtement coupe-vent est conseillé. Les sacs pourront être rangés sous les sièges pendant le trajet.","question":"Quelle précaution est recommandée ?","explanation":"Le passage indique : « Pour la croisière d'observation, apportez des vêtements chauds. Le soleil au port ne garantit pas une température agréable en mer. » Cela justifie la réponse : Prévoir une tenue chaude."},{"number":9,"points":9,"correct":"D","options":["Un accès à tous les étages par ascenseur","Une fermeture complète aux visiteurs","Une montée en voiture","Une découverte sans ascension"],"passage":"La visite du phare comprend un escalier étroit. Une présentation au pied de la tour est proposée aux personnes qui ne peuvent pas monter.\n\nVous pourrez choisir la formule qui vous convient avant d'acheter votre billet.","question":"Quelle solution alternative existe ?","explanation":"Le passage indique : « La visite du phare comprend un escalier étroit. Une présentation au pied de la tour est proposée aux personnes qui ne peuvent pas monter. » Cela justifie la réponse : Une découverte sans ascension."},{"number":10,"points":9,"correct":"A","options":["Essayer le matériel avant de choisir","Obtenir un achat définitif gratuit","Remplacer les conseils du guide par un tirage au sort","Éviter toute observation"],"passage":"Je vais louer des jumelles pour cette sortie, puis décider si j'en achète. Je ne connais pas encore le modèle adapté.\n\nLe magasin permet d'essayer plusieurs grossissements. Je demanderai aussi des conseils sur le poids et le confort pendant une longue marche.","question":"Pourquoi louer d'abord ?","explanation":"Le passage indique : « Je vais louer des jumelles pour cette sortie, puis décider si j'en achète. Je ne connais pas encore le modèle adapté. » Cela justifie la réponse : Essayer le matériel avant de choisir."},{"number":11,"points":15,"correct":"D","options":["Garantir l'absence de changement","Modifier artificiellement la taille du glacier","Éviter de noter les dates","Rendre l'évolution observable de manière comparable"],"passage":"Une équipe suit l'évolution d'un glacier grâce à des photographies prises depuis des repères fixes. Des images sans localisation précise seraient plus difficiles à comparer.\n\nLes observateurs reviennent au même endroit à des périodes comparables et notent les conditions de prise de vue. Le cadrage permet de reconnaître les rochers autour de la glace et d'éviter de confondre un changement d'angle avec un recul réel. Les données sont ensuite rapprochées d'autres mesures réalisées sur le terrain. Une photographie spectaculaire prise par un visiteur peut être intéressante, mais elle ne remplace pas à elle seule cette série documentée.","question":"Pourquoi conserver les mêmes repères ?","explanation":"Le passage indique : « Une équipe suit l'évolution d'un glacier grâce à des photographies prises depuis des repères fixes. Des images sans localisation précise seraient plus difficiles à comparer. » Cela justifie la réponse : Rendre l'évolution observable de manière comparable."},{"number":12,"points":15,"correct":"A","options":["Elles ont une fonction dans le milieu","Elles empêchent toute vie animale","Elles remplacent les poubelles","Elles sont toutes dangereuses à toucher"],"passage":"Des visiteurs ramassent des déchets sur la plage, mais laissent les algues échouées. Elles servent d'abri et de ressource à plusieurs espèces.\n\nLes bénévoles utilisent des sacs séparés pour le plastique, le verre et les autres déchets. Un animateur explique au départ ce qui appartient naturellement au milieu et doit y rester. Les enfants peuvent participer avec un adulte. Les organisateurs fourniront des gants et rappelleront les précautions nécessaires.","question":"Pourquoi ne pas retirer les algues ?","explanation":"Le passage indique : « Des visiteurs ramassent des déchets sur la plage, mais laissent les algues échouées. Elles servent d'abri et de ressource à plusieurs espèces. » Cela justifie la réponse : Elles ont une fonction dans le milieu."},{"number":13,"points":15,"correct":"C","options":["Une reproduction identique chaque jour","L'absence de tout contact professionnel","Le maintien de l'activité portuaire","L'arrêt de tous les navires"],"passage":"Un port propose des visites de ses métiers. Les parcours changent selon les opérations en cours pour ne pas gêner les travailleurs.\n\nLe guide confirme l'itinéraire juste avant le départ après un échange avec les responsables des quais. Un chargement en cours peut conduire le groupe vers un autre secteur, où les visiteurs découvriront une activité différente. Le billet donne accès à une découverte du port en fonctionnement, sans promettre le passage devant chaque équipement. Le programme rappelle donc que les besoins du travail déterminent certaines étapes de la visite, même lorsque des photographies publicitaires montrent un parcours précis.","question":"Quel besoin encadre la visite ?","explanation":"Le passage indique : « Un port propose des visites de ses métiers. Les parcours changent selon les opérations en cours pour ne pas gêner les travailleurs. » Cela justifie la réponse : Le maintien de l'activité portuaire."},{"number":14,"points":15,"correct":"B","options":["Accélérer la formation des roches","Préserver un milieu sensible","Transformer la grotte en parking","Garantir un éclairage permanent"],"passage":"Une réserve limite les groupes dans une grotte. Le passage répété modifie les conditions du lieu et peut fragiliser certaines formations.\n\nLes guides expliquent notamment que la présence des visiteurs peut modifier l'humidité et apporter des éléments extérieurs. Le nombre de places a été fixé à partir d'observations régulières, et sera révisé si l'état du site le nécessite. Une réservation évite aux groupes de se présenter tous au même moment. Les personnes qui ne peuvent pas entrer disposent d'une présentation filmée à l'accueil. La réserve souhaite ainsi rendre la découverte possible tout en surveillant les effets concrets de son ouverture au public.","question":"Pourquoi encadrer la fréquentation ?","explanation":"Le passage indique : « Une réserve limite les groupes dans une grotte. Le passage répété modifie les conditions du lieu et peut fragiliser certaines formations. » Cela justifie la réponse : Préserver un milieu sensible."},{"number":15,"points":15,"correct":"A","options":["Conserver une solution de repli","Suivre uniquement les autres marcheurs","Interdire tout appareil numérique","Éviter d'apprendre les repères"],"passage":"Une association enseigne la lecture d'une carte avant d'utiliser le téléphone en randonnée. Les participants doivent pouvoir s'orienter si la batterie se vide.\n\nL'atelier commence par le repérage de quelques éléments visibles autour du village. Les participants apprennent ensuite à relier ces repères au dessin et à utiliser la légende. Le téléphone reste utile pour préparer le trajet ou confirmer une position, mais ne constitue pas l'unique ressource du groupe. Chaque équipe emporte une carte imprimée protégée de la pluie. Le guide vérifie enfin que chacun comprend le chemin de retour et les points où il sera possible de demander de l'aide.","question":"Quel objectif est poursuivi ?","explanation":"Le passage indique : « Une association enseigne la lecture d'une carte avant d'utiliser le téléphone en randonnée. Les participants doivent pouvoir s'orienter si la batterie se vide. » Cela justifie la réponse : Conserver une solution de repli."},{"number":16,"points":15,"correct":"B","options":["Vendre toutes les captures","Participer à un suivi des animaux","Décorer les billets de bateau","Remplacer les règles de navigation"],"passage":"Des pêcheurs photographient certaines captures puis les relâchent selon le protocole de suivi. Les images servent à identifier les individus observés.\n\nLes participants reçoivent une fiche indiquant les angles de vue nécessaires et les informations à noter. Une image floue ou sans date peut être difficile à exploiter. Les données sont transmises à l'équipe scientifique, qui vérifie si le même animal a été signalé auparavant. Les pêcheurs ne doivent pas prolonger la manipulation pour obtenir une image plus esthétique.","question":"Quel usage est fait des photographies ?","explanation":"Le passage indique : « Des pêcheurs photographient certaines captures puis les relâchent selon le protocole de suivi. Les images servent à identifier les individus observés. » Cela justifie la réponse : Participer à un suivi des animaux."},{"number":17,"points":15,"correct":"C","options":["La lecture des panneaux","La croissance normale des fleurs","L'usure cumulée du milieu","La diversité des itinéraires autorisés"],"passage":"Un parc conseille de rester sur les sentiers même lorsque les plantes semblent résistantes. Des passages dispersés peuvent fragiliser progressivement le sol.\n\nUne empreinte isolée paraît parfois sans conséquence, mais les passages répétés élargissent progressivement les zones dénudées. L'eau s'y écoule autrement et peut emporter les couches les plus fines. Des panneaux montrent l'évolution de plusieurs secteurs suivis depuis quelques années. Les visiteurs sont invités à utiliser les points d'arrêt aménagés pour observer le paysage ou prendre des photographies. Le parc vérifie également que les sentiers officiels restent praticables, afin que cette recommandation soit réellement facile à suivre.","question":"Quel effet veut-on limiter ?","explanation":"Le passage indique : « Un parc conseille de rester sur les sentiers même lorsque les plantes semblent résistantes. Des passages dispersés peuvent fragiliser progressivement le sol. » Cela justifie la réponse : L'usure cumulée du milieu."},{"number":18,"points":15,"correct":"D","options":["Par la vente des bateaux","Par l'arrêt définitif des cours","Par une sortie malgré l'interdiction","Par des apprentissages sans navigation"],"passage":"Une école de voile organise une séance à terre lorsque la météo empêche de sortir. Les élèves travaillent alors les nœuds et la préparation du bateau.\n\nLes moniteurs utilisent un mât d'entraînement et des cordages pour préparer les prochaines navigations. Les élèves repèrent aussi les éléments à contrôler avant le départ. La séance conserve ainsi un objectif pédagogique même sans déplacement sur l'eau. Le centre informe les familles dès que la décision est prise et explique les raisons du changement.","question":"Comment la formation continue-t-elle ?","explanation":"Le passage indique : « Une école de voile organise une séance à terre lorsque la météo empêche de sortir. Les élèves travaillent alors les nœuds et la préparation du bateau. » Cela justifie la réponse : Par des apprentissages sans navigation."},{"number":19,"points":15,"correct":"D","options":["Les relevés actuels suffisent à décrire tous les siècles","Les cartes anciennes sont toutes inutiles","La côte reste identique partout","Le littoral évolue dans le temps"],"passage":"Un musée du littoral présente les variations du trait de côte. Les cartes anciennes sont comparées aux relevés actuels, sans supposer que le rivage a toujours été fixe.\n\nL'exposition présente les sources utilisées et leurs limites de précision. Une ancienne carte peut décrire les accès d'un port sans relever chaque détail de la plage. Les visiteurs découvrent comment les spécialistes croisent plusieurs documents avant de parler d'un déplacement du rivage.","question":"Quelle idée est mise en évidence ?","explanation":"Le passage indique : « Un musée du littoral présente les variations du trait de côte. Les cartes anciennes sont comparées aux relevés actuels, sans supposer que le rivage a toujours été fixe. » Cela justifie la réponse : Le littoral évolue dans le temps."},{"number":20,"points":21,"correct":"C","options":["Fermer tous les équipements existants","Garantir de la neige toute l'année","Construire des offres qui ne dépendent pas uniquement du ski","Transformer chaque habitant en moniteur"],"passage":"Une station de montagne diversifie ses activités au-delà du ski. Les parcours à pied et les rencontres culturelles utilisent des ressources différentes, mais demandent aussi une organisation adaptée. Les accompagnateurs doivent être formés et les itinéraires entretenus en dehors de la saison habituelle. Certains commerces adaptent leurs horaires pour accueillir un public différent. La commune consulte les habitants afin de ne pas concentrer toutes les nouveautés sur les lieux déjà très fréquentés. Elle veut aussi vérifier que les recettes et les emplois ne dépendent pas simplement d'un changement d'affiche.","question":"Quel enjeu accompagne cette diversification ?","explanation":"Le passage indique : « Une station de montagne diversifie ses activités au-delà du ski. Les parcours à pied et les rencontres culturelles utilisent des ressources différentes, mais demandent aussi une organisation adaptée. » Cela justifie la réponse : Construire des offres qui ne dépendent pas uniquement du ski."},{"number":21,"points":21,"correct":"A","options":["Permettre l'accès en préservant des fonctions naturelles","Supprimer la végétation pour mieux la protéger","Interdire toute présence humaine","Remplacer toutes les dunes par du béton"],"passage":"Une commune aménage un accès à la mer sans retirer toute la végétation. Les plantes stabilisent certaines zones et participent au fonctionnement des dunes. Les visiteurs circuleront sur un passage qui évite les secteurs les plus fragiles. Les services techniques prévoient des contrôles après les tempêtes et une signalisation compréhensible depuis le parking. Des habitants avaient demandé un dégagement plus large pour voir directement l'eau ; le projet explique pourquoi cette demande ne peut pas être satisfaite partout.","question":"Quel équilibre est recherché ?","explanation":"Le passage indique : « Une commune aménage un accès à la mer sans retirer toute la végétation. Les plantes stabilisent certaines zones et participent au fonctionnement des dunes. » Cela justifie la réponse : Permettre l'accès en préservant des fonctions naturelles."},{"number":22,"points":21,"correct":"C","options":["S'approcher toujours davantage","Faire sortir les oiseaux de leurs refuges","Limiter l'observation pour respecter les animaux","Éclairer les nids en continu"],"passage":"Des chercheurs observent les oiseaux depuis un abri éloigné. Ils acceptent de voir moins de détails afin de réduire la perturbation des colonies. L'abri permet de rester longtemps au même endroit sans multiplier les déplacements près des nids. Les observations sont notées selon une méthode commune pour être comparées d'une séance à l'autre. Lorsque la visibilité est mauvaise, certaines informations restent inconnues et sont signalées comme telles. Les chercheurs préfèrent conserver cette limite plutôt que s'approcher davantage pour compléter chaque case.","question":"Quel compromis est choisi ?","explanation":"Le passage indique : « Des chercheurs observent les oiseaux depuis un abri éloigné. Ils acceptent de voir moins de détails afin de réduire la perturbation des colonies. » Cela justifie la réponse : Limiter l'observation pour respecter les animaux."},{"number":23,"points":21,"correct":"D","options":["Supprimer toute information de sécurité","Reconstruire systématiquement chaque mètre au même endroit","Garantir l'immobilité de la falaise","Adapter le parcours à l'évolution du site"],"passage":"Une promenade littorale est déplacée après l'érosion d'une portion de falaise. Les responsables expliquent que maintenir exactement l'ancien tracé serait coûteux et dangereux. Le nouveau parcours passe plus à l'intérieur des terres et rejoint le belvédère par une pente douce. Des panneaux expliquent les raisons du déplacement avec des photographies datées. Les habitants pourront signaler les difficultés d'accès rencontrées pendant les premières semaines. Les services surveilleront aussi la partie fermée, car l'installation d'une barrière ne met pas fin au phénomène naturel.","question":"Quelle réponse est adoptée ?","explanation":"Le passage indique : « Une promenade littorale est déplacée après l'érosion d'une portion de falaise. Les responsables expliquent que maintenir exactement l'ancien tracé serait coûteux et dangereux. » Cela justifie la réponse : Adapter le parcours à l'évolution du site."},{"number":24,"points":21,"correct":"C","options":["La longueur du nom du refuge","La couleur des couvertures","La capacité réelle des ressources et des services","Le nombre de photos en ligne"],"passage":"Un refuge mesure ses besoins en eau avant d'augmenter sa capacité. Accueillir plus de personnes n'est possible que si les ressources et les équipements suivent. Les responsables examinent les réserves disponibles en fin de saison et le fonctionnement de l'assainissement. Ils prennent en compte les visiteurs de passage, qui utilisent également les installations. Plusieurs solutions seront comparées avant de décider du nombre de lits supplémentaire. Le projet pourrait être revu à la baisse si les besoins dépassent les possibilités du lieu.","question":"Quelle condition limite l'agrandissement ?","explanation":"Le passage indique : « Un refuge mesure ses besoins en eau avant d'augmenter sa capacité. Accueillir plus de personnes n'est possible que si les ressources et les équipements suivent. » Cela justifie la réponse : La capacité réelle des ressources et des services."},{"number":25,"points":21,"correct":"D","options":["La possibilité d'apprendre à partir de traces et d'indices en l'absence d'animaux visibles.","L'intérêt de respecter le déplacement libre des animaux dans leur milieu.","L'idée qu'un parcours peut être adapté aux conditions observées sur place.","L'exigence de photographier chaque espèce annoncée pour que l'activité soit considérée comme réussie."],"passage":"Une sortie d'observation annonce des espèces possibles, pas une rencontre garantie. Le guide rappelle que les animaux restent libres et que l'absence d'apparition ne signifie pas que le milieu est vide. L'itinéraire suit les conditions du jour et les observations récentes, sans poursuivre les animaux lorsqu'ils s'éloignent. Une partie de la séance est consacrée aux traces, aux habitats et aux techniques de repérage. Les participants repartent donc avec des connaissances même si aucune espèce spectaculaire ne se montre. À la fin de la marche, aucun grand mammifère n'a été aperçu mais les participants savent reconnaître plusieurs empreintes et habitats. Le guide considère ces observations comme un résultat valable.","question":"Quelle attente la sortie demande-t-elle de modifier ?","explanation":"L'annonce promet des espèces possibles, pas une observation garantie. D désigne l'attente erronée; A/C/B sont compatibles avec le guide."},{"number":26,"points":21,"correct":"D","options":["La couche de découverte détermine à elle seule la valeur esthétique de l'objet présenté.","Deux objets comparables appartiennent à la même période dès lors qu'ils proviennent du même chantier.","Une pièce retrouvée dans un remblai récent ne peut avoir été fabriquée dans le passé.","La position et les éléments associés apportent un contexte historique qui peut changer leur interprétation."],"passage":"Une ville portuaire expose des objets trouvés lors d'un chantier. Leur emplacement de découverte est documenté, car un objet isolé de son contexte perd une partie des informations qu'il peut apporter. Les archéologues relèvent aussi les éléments proches et les couches dans lesquelles chaque découverte apparaît. Ces indications peuvent renseigner sur la date, les usages ou les échanges commerciaux. Dans l'exposition, une photographie du chantier accompagne les principales pièces. Deux objets semblables sont retrouvés, l'un dans une couche datée du commerce maritime ancien et l'autre dans des remblais récents. Leur interprétation historique diffère grâce aux relevés d'origine.","question":"Pourquoi la ressemblance matérielle des objets ne suffit-elle pas à leur attribuer le même sens ?","explanation":"La provenance et la couche affectent l'interprétation. D; les autres généralisent sans source."},{"number":27,"points":21,"correct":"B","options":["La fermeture prouve que les animaux ne fréquentent jamais les secteurs ouverts en hiver.","Adapter les périodes d'accès aux besoins écologiques observés sur place.","Le calendrier touristique est désormais le principal critère des ouvertures de sentier.","Les visiteurs doivent renoncer à tout itinéraire lorsque la reproduction commence."],"passage":"Un parc autorise certains accès en hiver et les ferme au printemps pendant la reproduction. La règle suit les besoins du milieu plutôt qu'un calendrier touristique identique toute l'année. Les gardes expliquent les périodes sensibles sur les panneaux et proposent des itinéraires de remplacement. Les dates sont réévaluées à partir des observations, car la reproduction ne commence pas toujours exactement au même moment. Une année, la reproduction commence plus tôt et les gardes avancent de quelques jours la fermeture d'un secteur. Les panneaux expliquent le suivi des espèces et indiquent un passage alternatif.","question":"Que révèle le changement de date d'interdiction ?","explanation":"Les règles suivent les périodes sensibles observées. B; C/D/A ajoutent des effets non établis."},{"number":28,"points":21,"correct":"D","options":["Le témoignage permet de remplacer les données de vent pour estimer la gravité régionale.","Le récit individuel rend impossible toute comparaison de la tempête avec d'autres années.","Les mesures identiques prouvent que les dégâts ont nécessairement touché les mêmes habitations.","Les mesures situent l'épisode; les récits en décrivent les effets locaux."],"passage":"Des habitants comparent les récits d'une grande tempête avec des relevés officiels. Les souvenirs décrivent les effets vécus ; les mesures situent l'événement dans une série plus longue. Les habitants situent les routes coupées, les maisons atteintes et les décisions prises pendant la nuit. Les relevés permettent de comparer la force du vent et la hauteur de l'eau avec d'autres épisodes. Le projet conserve la distinction entre ces sources au lieu de demander à chacune de fournir les mêmes informations. Un témoin décrit l'inondation de sa rue; les relevés montrent que l'intensité régionale était comparable à celle d'un épisode antérieur, mais que les dégâts ont été concentrés dans d'autres quartiers.","question":"Quel apport résulte du rapprochement entre mémoire vécue et mesures ?","explanation":"Les sources ont des portées complémentaires. D; A/C/B les substituent ou surinterprètent."},{"number":29,"points":21,"correct":"A","options":["Observer plus longuement chaque site plutôt que multiplier les étapes.","L'absence d'explications du guide afin de laisser toute la place au silence.","Le nombre maximal de lieux atteints au prix d'arrêts moins fréquents.","La garantie de rencontrer davantage d'espèces grâce à des déplacements plus courts."],"passage":"Une entreprise propose des excursions plus lentes en bateau. Elle réduit le nombre de sites visités pour consacrer davantage de temps à l'observation et à l'explication. Les guides peuvent arrêter le moteur à certains moments pour écouter les sons du milieu. Les clients sont informés du programme avant de réserver afin d'éviter de confondre cette formule avec un circuit rapide. L'excursion lente visite deux criques au lieu de cinq. Certains participants apprécient la durée des observations, d'autres préfèrent un programme plus dense; les deux formules sont clairement présentées avant réservation.","question":"Quel critère distingue principalement l'excursion lente d'une tournée rapide ?","explanation":"Moins de sites permet plus d'observation et d'explication. A; C est l'opposé, D/B ne sont pas justifiés."},{"number":30,"points":26,"correct":"C","options":["Lire les murets comme des éléments purement naturels puisqu'ils font partie de la vue actuelle.","Supposer que le travail humain explique toute évolution de la végétation, indépendamment du climat.","Distinguer des processus naturels et des pratiques d'entretien qui contribuent conjointement à la forme observée.","Considérer qu'un paysage apprécié doit rester inchangé pour conserver son intérêt touristique."],"passage":"La beauté d'un paysage peut donner l'impression d'un espace sans travail humain. Pourtant, terrasses, pâtures et chemins résultent souvent d'un entretien continu. Une visite guidée rend ces activités visibles sans nier les processus naturels qui façonnent aussi le lieu. Des éleveurs expliquent par exemple comment leur activité maintient certains espaces ouverts. Les visiteurs découvrent aussi les difficultés d'accès aux parcelles et les changements liés aux saisons. Cette lecture du paysage fait apparaître des décisions économiques et sociales derrière une vue souvent présentée comme uniquement naturelle. Sur une terrasse cultivée, le maintien des murets dépend du travail des habitants, tandis que la végétation évolue aussi avec les pluies. Le guide évite d'attribuer le paysage à une seule origine.","question":"Quelle interprétation du paysage la visite rend-elle possible ?","explanation":"Le paysage résulte d'interactions entre environnement et activités humaines. C. A/B/D réduisent cette complexité."},{"number":31,"points":26,"correct":"D","options":["Une zone à faible probabilité peut être considérée comme totalement protégée de toute inondation.","La parcelle sera nécessairement touchée cette année si elle apparaît dans une zone à risque.","L'outil indique les conséquences individuelles certaines d'un futur événement climatique.","La carte estime des risques sans prévoir la date exacte d'un sinistre."],"passage":"Une carte de risques n'annonce pas qu'un événement touchera chaque parcelle à une date précise. Elle décrit des zones et des probabilités utiles à la décision. La lire comme une prédiction individuelle certaine conduirait à des attentes que l'outil ne peut pas satisfaire. Les services accompagnent donc la carte d'exemples et d'une explication des marges d'incertitude. Une zone peu exposée ne signifie pas que tout danger y est absent. La carte classe une parcelle dans une zone où l'inondation est peu probable; un agent rappelle que cette faible probabilité ne correspond pas à une absence de danger et ne permet pas de fixer une date.","question":"Quelle lecture de la carte évite une erreur de prévision ?","explanation":"Une carte de risque ne donne pas de certitude parcellaire ou temporelle. D. B/A/C en font une prédiction."},{"number":32,"points":26,"correct":"B","options":["La fréquentation accrue garantit une meilleure connaissance écologique chez tous les visiteurs.","Un bénéfice individuel d'accès peut accroître la pression cumulée sur les lieux fréquentés.","La construction du parking prouve que les visiteurs renoncent à emprunter les chemins existants.","Les déplacements vers le site deviennent nécessairement plus courts pour chaque famille."],"passage":"Un équipement touristique peut faciliter la découverte d'un site tout en augmentant sa fréquentation. Les responsables étudient donc les effets de la nouvelle accessibilité avant d'agrandir davantage. Un aménagement utile individuellement peut créer une pression collective supplémentaire. Un parking plus grand peut ainsi modifier les heures d'arrivée et les déplacements sur les chemins. Les gestionnaires suivent ces changements pendant une saison avant de prévoir de nouvelles capacités. Ils cherchent à comprendre l'ensemble des effets du projet. Le nouveau parking réduit la difficulté d'accès aux sentiers, mais les agents mesurent davantage de passages sur une zone fragile. Le projet est réexaminé avec les effets de cette hausse de fréquentation.","question":"Pourquoi un aménagement facilitant l'accès doit-il aussi être évalué collectivement ?","explanation":"Le parking accroît l'accès et potentiellement la pression sur les sentiers. B. C/A/D extrapolent."},{"number":33,"points":26,"correct":"C","options":["Le nombre d'habitants qui considèrent la digue comme un symbole du passé, indépendamment des risques.","La capacité des ouvrages existants à assurer une protection sans coût ni risque futur.","Les conséquences à long terme, les coûts et les usages préservés par différentes formes d'adaptation.","Une préférence morale entre ceux qui défendent le territoire et ceux qui seraient prêts à le quitter."],"passage":"Un littoral évolue malgré des ouvrages de protection. Certains habitants demandent d'adapter les usages plutôt que renforcer sans cesse les mêmes défenses. Le débat ne sépare pas simplement ceux qui protègent et ceux qui abandonnent : il porte aussi sur ce qui peut être maintenu et à quel coût. Les propositions comparent les dépenses sur plusieurs années et les conséquences pour les habitants concernés. Face à l'érosion, une commune compare le renforcement d'une digue et le déplacement progressif de certains équipements. Elle étudie les coûts, les risques résiduels et les habitants concernés dans chaque scénario.","question":"Quel critère doit structurer le débat entre les deux stratégies ?","explanation":"L'adaptation repose sur les coûts et effets des options, C. D/B/A réduisent le débat à une opposition ou un seul critère."},{"number":34,"points":26,"correct":"C","options":["Le succès d'une station ne peut être mesuré que si toutes les nuitées disparaissent du bilan.","La baisse de consommation d'eau prouve que les dépenses de l'établissement ont diminué dans tous les postes.","Une fréquentation égale ne garantit pas des effets sociaux et environnementaux équivalents.","La durée des contrats dépend uniquement du nombre de visiteurs reçus chaque année."],"passage":"Une station mesure sa réussite au nombre de nuitées. Une association propose aussi d'examiner les ressources consommées et la qualité des emplois. Une hausse de fréquentation peut produire des bénéfices tout en accentuant des contraintes mal décrites par le seul volume des séjours. Le bilan peut distinguer les emplois saisonniers des emplois durables et regarder les déplacements nécessaires pour travailler. Deux saisons affichent le même nombre de nuitées, mais la seconde consomme moins d'eau et stabilise davantage les contrats de travail. L'association considère ce progrès invisible dans les seuls chiffres de fréquentation.","question":"Quelle limite de l'indicateur des nuitées ce cas illustre-t-il ?","explanation":"Les nuitées sont stables alors que d'autres impacts changent. C; D/B/A infèrent sans preuve."},{"number":35,"points":26,"correct":"B","options":["Une visite libre favorise la découverte mais comporte moins de risques écologiques si les visiteurs restent longtemps.","Les conséquences dépendent des modalités d'accès et de protection du site.","Un encadrement pédagogique suffit à préserver le milieu lorsque le nombre de visiteurs augmente fortement.","Les revenus des billets compensent les dommages de passage dès lors qu'ils financent une partie du suivi."],"passage":"La découverte d'un espace naturel peut sensibiliser à sa protection. Elle peut aussi l'abîmer si les conditions de visite sont mal organisées. Le lien entre fréquentation et préservation n'est donc ni automatique ni nécessairement impossible : il dépend des usages et de leur encadrement. Des visites limitées et accompagnées peuvent financer un suivi du site et transmettre des connaissances. À l'inverse, une publicité sans préparation peut concentrer trop de personnes sur des passages fragiles. Une réserve ouvre des parcours balisés avec des guides qui limitent les passages fragiles. Une autre campagne attire des foules sans encadrement; le même intérêt pour la nature n'entraîne pas les mêmes effets sur les sols.","question":"Que permet de distinguer la comparaison des deux dispositifs de visite ?","explanation":"B indique que l'effet d'une visite dépend des conditions d'accès et de protection. A infère moins de risque des visites libres, C suppose que l'encadrement annule l'effet de foule, D traite le financement comme compensation automatique des dommages."},{"number":36,"points":33,"correct":"A","options":["Une portion brève peut imposer des capacités particulières non visibles dans le chiffre de distance.","Le nombre total de randonneurs renseigne davantage sur la difficulté d'un passage que ses caractéristiques physiques.","Des photographies de l'itinéraire donnent une meilleure prévision des conditions du jour que l'étude du terrain.","Une faible distance traduit une faible exposition puisque les passages difficiles restent nécessairement courts."],"passage":"Un sentier réputé facile attire de nombreux débutants. La description indique une faible distance, mais ne mentionne pas un passage très exposé. Des guides demandent de compléter l'information. Une difficulté globale ne se déduit pas d'un seul chiffre lorsque certaines portions exigent des capacités particulières. Le nouveau descriptif séparera la longueur, le dénivelé, la nature du sol et les passages où une chute aurait des conséquences importantes. Des photographies datées montreront les portions qui prêtent le plus à confusion. Les accompagnateurs rappellent aussi que la pluie, la chaleur ou la fatigue peuvent modifier l'expérience d'un même trajet. Ils souhaitent donner aux visiteurs les moyens de comparer le parcours à leurs capacités et à leur équipement. La mention facile pourra rester un repère, mais elle sera accompagnée d'informations qui permettent de comprendre à quelles conditions elle correspond et quand choisir un autre itinéraire. Un itinéraire ne mesure que quatre kilomètres mais présente une courte traversée exposée au vide. Deux visiteurs capables de marcher cette distance n'ont pas nécessairement la même aisance sur ce passage.","question":"Pourquoi la faible longueur du sentier peut-elle induire les débutants en erreur ?","explanation":"A reconnaît qu'un passage exposé peut demander des capacités particulières malgré une faible distance. B confond popularité et difficulté; C privilégie des images datées; D infère la sécurité de la longueur."},{"number":37,"points":33,"correct":"B","options":["Les critères esthétiques mesurent mieux la réussite à long terme que le suivi des fonctions de stabilisation de la dune.","Le fonctionnement écologique peut primer sur l'apparence esthétique immédiate.","Les plantes installées apportent surtout un effet décoratif et influencent peu les mouvements de sable observés.","Les clôtures temporaires attestent que le paysage redeviendra aussi ouvert qu'avant après une seule saison."],"passage":"La restauration d'une dune peut sembler désordonnée : clôtures légères, plantes irrégulières, zones fermées. Certains visiteurs préfèrent un rivage entièrement dégagé. Les gestionnaires expliquent les fonctions du dispositif. Ce qui paraît moins soigné selon des critères décoratifs peut mieux répondre aux besoins du milieu. Les clôtures retiennent le sable et orientent les passages vers des accès précis. Certaines plantes installent leurs racines dans des secteurs qui semblaient auparavant vides, tandis que d'autres apparaissent plus lentement. Des panneaux présentent les étapes attendues de la restauration avec des images prises au même endroit. Les gestionnaires reconnaissent que le changement peut surprendre et organisent des visites pour répondre aux questions. Ils distinguent toutefois la perception esthétique immédiate du fonctionnement écologique observé sur plusieurs saisons. Sur une dune en restauration, les clôtures gênent temporairement la vue mais préservent des zones de végétation qui stabilisent le sable. Les panneaux suivent les changements sur plusieurs saisons.","question":"Pourquoi l'apparence moins ordonnée ne suffit-elle pas à juger l'opération négativement ?","explanation":"B distingue fonctionnement écologique et apparence instantanée. A privilégie l'image au suivi fonctionnel; C réduit le rôle des plantes; D promet un résultat esthétique et un calendrier non établis."},{"number":38,"points":33,"correct":"A","options":["L'affluence créée par la promotion risque de dégrader la tranquillité promise.","Le mécontentement des visiteurs démontre que les photographies initiales montraient un paysage qui n'existait pas.","Une photographie fidèle change de sens lorsque le lieu accueille désormais davantage de personnes à la même heure.","Les itinéraires alternatifs permettront de rétablir la solitude au site principal en transférant les visiteurs ailleurs."],"passage":"Une destination valorise des images de solitude et de nature intacte. Le succès de ces images attire pourtant une fréquentation importante vers quelques lieux précis. La promesse qui motive la visite peut être fragilisée par l'ampleur même du public qu'elle attire. Des files d'attente apparaissent désormais devant les points de vue les plus diffusés sur les réseaux. Les visiteurs cherchent souvent à reproduire exactement la photographie qui leur a donné envie de venir. Les responsables du territoire réfléchissent donc à une communication plus précise sur les périodes fréquentées et les possibilités de découverte ailleurs. Ils ne souhaitent pas simplement déplacer la foule vers un autre endroit fragile. Les habitants et les gestionnaires seront associés au choix des itinéraires et aux limites d'accueil. L'objectif est de rendre l'expérience annoncée compatible avec la capacité réelle des lieux et avec la vie locale. Le lieu célèbre pour ses photos de solitude connaît désormais des files d'attente aux heures de pointe. Certains visiteurs repartent déçus, bien que la publicité ait fidèlement reproduit le paysage avant cette affluence.","question":"Quelle contradiction le succès de la campagne crée-t-il ?","explanation":"A relie la promotion de la solitude à une affluence susceptible de la compromettre. B nie la fidélité initiale; C confond image et conditions d'expérience; D prédit une réussite du déplacement des foules non démontrée."},{"number":39,"points":33,"correct":"C","options":["La progression des ouvertures hivernales, qui reflète directement le nombre de salariés durablement installés indépendamment de leur lieu de résidence.","Le nombre d'offres publiées chaque saison, car il permet de mesurer directement et à lui seul la permanence des emplois proposés par les restaurants ainsi que l'accessibilité des logements pour les personnes recrutées.","Le maintien effectif des salariés dans le temps, associé à leurs conditions de logement et de déplacement, sans attribuer tous les départs aux loyers.","La fréquentation des restaurants pendant la haute saison, même si les emplois proposés ne sont pas régulièrement pourvus en dehors de cette période."],"passage":"Un village de montagne veut conserver ses activités toute l'année. Il développe des offres nouvelles, mais vérifie aussi le logement des salariés et l'accès aux services. Diversifier les loisirs ne suffit pas si les personnes qui font fonctionner le territoire ne peuvent pas y vivre dans des conditions stables. Les commerçants expliquent qu'ils peuvent ouvrir plus longtemps seulement s'ils trouvent du personnel disponible. Les salariés évoquent pour leur part les loyers, les trajets et la fermeture de certains services hors saison. Le conseil municipal examine donc ces questions avec le programme touristique, plutôt que de les traiter après le lancement des nouvelles offres. Une activité supplémentaire peut renforcer le territoire si elle s'appuie sur des conditions de travail et d'habitat durables. Le bilan portera sur la continuité des emplois, l'accès aux besoins quotidiens et les retours des habitants, en complément des chiffres de fréquentation. Un nouveau programme permet l'ouverture de restaurants en hiver, mais les employés recrutés habitent loin faute de logements abordables et doivent conduire plus longtemps. Le conseil examine l'habitat et les services avant d'étendre l'offre. Après le lancement, le nombre d'offres d'emploi d'hiver augmente et davantage de restaurants annoncent une ouverture toute l'année. Pourtant, les contrats les plus courts sont renouvelés difficilement: une enquête auprès des employés constate que plusieurs ne trouvent pas de location dans le village et renoncent après une saison de longs déplacements. Le conseil compare les postes proposés, ceux effectivement pourvus pendant six mois et la résidence des salariés. Il constate que certaines entreprises ont maintenu leurs horaires grâce à du personnel venu de loin, sans que cela établisse une stabilisation des ménages sur place. L'association touristique souhaite retenir seulement le nombre de postes créés; le conseil répond que cet indicateur signale une demande de travail, mais ne permet pas, à lui seul, d'apprécier la continuité de la main-d'œuvre et de la vie locale. Les entretiens ne permettent toutefois pas de chiffrer précisément la part des départs imputable aux seuls loyers.","question":"Quel résultat supplémentaire serait le plus pertinent pour juger la stabilité promise plutôt que la seule extension touristique ?","explanation":"C rapproche les postes réellement occupés dans la durée des logements et déplacements, tout en évitant une cause unique non mesurée. A déduit une installation locale de l'activité des restaurants; B confond offre d'emploi et emploi maintenu, sans apprécier le logement; D reste sur une métrique saisonnière sans mesurer la stabilité recherchée."}]}$paper_18$::jsonb),
('tcf-reading-19','tcf-reading-2026-11-close-reading-v4',$paper_19${"id":"tcf-reading-19","title":"TCF Reading · Test 19","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"A","options":["L'ascenseur","La cour extérieure","Le portail piéton manuel","La boîte aux lettres"],"passage":"L'électricité sera coupée dans le bâtiment de dix à onze heures. L'ascenseur ne pourra pas être utilisé pendant cette période.\n\nMerci de prévoir vos déplacements avant le début de l'intervention. Les escaliers resteront accessibles pendant toute la durée des travaux.","question":"Quel équipement sera indisponible ?","explanation":"Le passage indique : « L'électricité sera coupée dans le bâtiment de dix à onze heures. L'ascenseur ne pourra pas être utilisé pendant cette période. » Cela justifie la réponse : L'ascenseur."},{"number":2,"points":3,"correct":"A","options":["Une facture récente","Une carte de fidélité","Un devis de déménagement","Un relevé de tous les comptes"],"passage":"Le conseiller énergie reçoit gratuitement samedi sur rendez-vous. Apportez une facture récente, sans vos coordonnées bancaires.\n\nLe rendez-vous permet de comprendre vos dépenses et de préparer vos questions sur le logement.","question":"Quel document est utile ?","explanation":"Le passage indique : « Le conseiller énergie reçoit gratuitement samedi sur rendez-vous. Apportez une facture récente, sans vos coordonnées bancaires. » Cela justifie la réponse : Une facture récente."},{"number":3,"points":3,"correct":"A","options":["Laisser les robinets dans l'état demandé","Démonter les radiateurs","Couper tous les tuyaux","Ouvrir toutes les fenêtres obligatoirement"],"passage":"Le test de chauffage aura lieu jeudi matin. Merci de ne pas fermer les robinets pendant l'intervention.\n\nL'équipe passera dans chaque étage. Un avis sera affiché dans le hall lorsque les vérifications seront terminées.","question":"Quelle consigne est donnée ?","explanation":"Le passage indique : « Le test de chauffage aura lieu jeudi matin. Merci de ne pas fermer les robinets pendant l'intervention. » Cela justifie la réponse : Laisser les robinets dans l'état demandé."},{"number":4,"points":3,"correct":"B","options":["Une alimentation électrique personnelle","Un support pédagogique","Une vente automatique de batteries","Un chauffage de la rue"],"passage":"Les panneaux de démonstration ne produisent pas d'électricité pour les visiteurs. Ils servent à expliquer le fonctionnement du système.\n\nUn animateur répondra à vos questions après la présentation. Merci de ne pas manipuler les câbles exposés sur la table.","question":"Quelle est leur fonction ?","explanation":"Le passage indique : « Les panneaux de démonstration ne produisent pas d'électricité pour les visiteurs. Ils servent à expliquer le fonctionnement du système. » Cela justifie la réponse : Un support pédagogique."},{"number":5,"points":9,"correct":"B","options":["Éviter toute analyse du logement","Évaluer les besoins avant de choisir l'équipement","Supprimer les factures existantes","Acheter l'appareil le plus puissant"],"passage":"Je préfère faire vérifier l'isolation avant de changer l'appareil de chauffage. Nous saurons mieux quelle puissance sera nécessaire.\n\nSi nous réduisons d'abord les pertes, nous pourrons comparer des modèles mieux adaptés au logement. Demande au conseiller un rendez-vous la semaine prochaine. Nous comparerons ensuite les devis.","question":"Pourquoi commencer par l'isolation ?","explanation":"Le passage indique : « Je préfère faire vérifier l'isolation avant de changer l'appareil de chauffage. Nous saurons mieux quelle puissance sera nécessaire. » Cela justifie la réponse : Évaluer les besoins avant de choisir l'équipement."},{"number":6,"points":9,"correct":"B","options":["Le nombre de pièces du magasin","Le temps d'usage","La couleur de la prise","La marque du carnet"],"passage":"L'atelier prête un appareil pour mesurer les consommations des petits équipements. Notez la durée d'utilisation avec la valeur affichée.\n\nUn tableau vous aidera à classer les relevés. Rapportez le matériel à la date indiquée sur votre fiche de prêt.","question":"Quelle information faut-il relever en plus ?","explanation":"Le passage indique : « L'atelier prête un appareil pour mesurer les consommations des petits équipements. Notez la durée d'utilisation avec la valeur affichée. » Cela justifie la réponse : Le temps d'usage."},{"number":7,"points":9,"correct":"C","options":["Une certification de tous les appareils","Une obligation d'acheter auprès du conseiller","Une orientation pour préparer les décisions","Un chantier immédiatement terminé"],"passage":"Votre visite conseil ne comprend pas la réalisation des travaux. Vous recevrez des pistes à comparer avec des devis professionnels.\n\nLe document résumera les points observés dans votre logement et les questions à poser aux entreprises. Vous resterez libre de choisir les interventions à engager.","question":"Quel résultat est proposé ?","explanation":"Le passage indique : « Votre visite conseil ne comprend pas la réalisation des travaux. Vous recevrez des pistes à comparer avec des devis professionnels. » Cela justifie la réponse : Une orientation pour préparer les décisions."},{"number":8,"points":9,"correct":"C","options":["Éteindre le magasin pendant ses heures d'ouverture","Supprimer l'enseigne","Réduire l'éclairage nocturne","Ajouter des lampes à l'intérieur"],"passage":"Nous baisserons l'éclairage de la vitrine après la fermeture. L'enseigne restera visible sans garder toutes les lampes allumées.\n\nLe responsable vérifiera le résultat depuis la rue. Merci de conserver le nouvel horaire sur la fiche du magasin.","question":"Quelle modification est prévue ?","explanation":"Le passage indique : « Nous baisserons l'éclairage de la vitrine après la fermeture. L'enseigne restera visible sans garder toutes les lampes allumées. » Cela justifie la réponse : Réduire l'éclairage nocturne."},{"number":9,"points":9,"correct":"D","options":["Le nombre de réunions passées","La couleur des affiches","La date de fondation du fabricant uniquement","Le suivi de l'équipement"],"passage":"Je peux participer à l'achat collectif, mais je veux connaître les conditions d'entretien avant de confirmer.\n\nPeux-tu demander au fournisseur qui intervient en cas de panne et si des frais réguliers sont prévus dans le contrat ?","question":"Quelle information manque pour décider ?","explanation":"Le passage indique : « Je peux participer à l'achat collectif, mais je veux connaître les conditions d'entretien avant de confirmer. » Cela justifie la réponse : Le suivi de l'équipement."},{"number":10,"points":9,"correct":"A","options":["Réduire l'entrée de chaleur","Empêcher toute aération nocturne","Refroidir le trottoir","Augmenter l'éclairage artificiel"],"passage":"La salle reste fraîche le matin. Fermez les volets des fenêtres exposées avant de partir pour limiter la chaleur de l'après-midi.\n\nLa personne qui ouvre le lendemain pourra les relever. Cette organisation doit être suivie par tous les utilisateurs de la salle.","question":"Quel objectif motive cette consigne ?","explanation":"Le passage indique : « La salle reste fraîche le matin. Fermez les volets des fenêtres exposées avant de partir pour limiter la chaleur de l'après-midi. » Cela justifie la réponse : Réduire l'entrée de chaleur."},{"number":11,"points":15,"correct":"C","options":["Choisir la couleur des façades","Supprimer la mesure de consommation","Éviter d'attribuer tout changement aux travaux","Garantir des hivers identiques"],"passage":"Une résidence suit ses consommations avant et après des travaux. Les températures extérieures sont aussi prises en compte pour comparer des périodes différentes.\n\nLe conseil syndical a d'abord constaté une baisse sur les factures et souhaitait l'attribuer entièrement à l'isolation. Le technicien rappelle qu'un hiver plus doux réduit également les besoins. Il rassemble donc les relevés et décrit les conditions de chaque période. Les habitants pourront lire les résultats avec une explication de la méthode et des limites de la comparaison. Cette présentation doit aider à comprendre ce qui semble lié aux interventions réalisées, sans transformer une simple différence entre deux factures en preuve suffisante.","question":"Pourquoi ajouter cette donnée ?","explanation":"Le passage indique : « Une résidence suit ses consommations avant et après des travaux. Les températures extérieures sont aussi prises en compte pour comparer des périodes différentes. » Cela justifie la réponse : Éviter d'attribuer tout changement aux travaux."},{"number":12,"points":15,"correct":"D","options":["Le nom de la rue","Le nombre de voisins","La couleur des factures","L'exposition du toit"],"passage":"Un installateur explique que l'orientation d'un toit influence la production solaire. Deux surfaces identiques ne produiront donc pas nécessairement la même quantité.\n\nLe conseiller observe également les ombres portées par les bâtiments voisins. Il prépare une estimation propre à chaque emplacement, au lieu d'appliquer un rendement unique à tous les projets. Les résultats seront présentés avec leurs hypothèses. Le propriétaire pourra poser ses questions avant de choisir un équipement.","question":"Quel facteur complète la superficie ?","explanation":"Le passage indique : « Un installateur explique que l'orientation d'un toit influence la production solaire. Deux surfaces identiques ne produiront donc pas nécessairement la même quantité. » Cela justifie la réponse : L'exposition du toit."},{"number":13,"points":15,"correct":"D","options":["Déclarer tous les murs défectueux","Choisir uniquement la couleur la plus vive","Remplacer l'examen par une impression","Comprendre le sens des observations"],"passage":"Une bibliothèque d'outils prête une caméra thermique avec une initiation. Les images doivent être interprétées, car une zone colorée n'explique pas seule l'origine d'un défaut.\n\nUne paroi humide, un reflet ou les conditions extérieures peuvent influencer l'apparence d'une image. Le formateur montre plusieurs exemples pris dans des situations connues avant de prêter le matériel. Les utilisateurs notent les circonstances de leurs observations et évitent de conclure immédiatement qu'un élément doit être remplacé. Le prêt vise à mieux repérer les questions à examiner, sans transformer l'appareil en outil capable de fournir automatiquement un diagnostic complet du bâtiment.","question":"Quelle aide est nécessaire ?","explanation":"Le passage indique : « Une bibliothèque d'outils prête une caméra thermique avec une initiation. Les images doivent être interprétées, car une zone colorée n'explique pas seule l'origine d'un défaut. » Cela justifie la réponse : Comprendre le sens des observations."},{"number":14,"points":15,"correct":"D","options":["Augmenter la consommation immédiatement","Remplacer toutes les vitres par des écrans","Fermer l'école chaque été","Réduire le besoin avant d'ajouter un appareil"],"passage":"Une école protège ses fenêtres exposées au soleil avant d'installer un refroidissement supplémentaire. Elle cherche d'abord à limiter la chaleur qui entre.\n\nDes stores extérieurs sont testés dans les classes les plus exposées. Les enseignants notent les moments où l'éblouissement et la température gênent les activités. Le projet prend aussi en compte la lumière nécessaire pour travailler et les conditions d'ouverture des fenêtres. Les résultats serviront à décider des interventions suivantes. La direction préfère vérifier l'effet des protections sur une saison avant de choisir de nouveaux équipements, afin que les dépenses répondent aux besoins effectivement observés dans les salles.","question":"Quelle priorité est donnée ?","explanation":"Le passage indique : « Une école protège ses fenêtres exposées au soleil avant d'installer un refroidissement supplémentaire. Elle cherche d'abord à limiter la chaleur qui entre. » Cela justifie la réponse : Réduire le besoin avant d'ajouter un appareil."},{"number":15,"points":15,"correct":"B","options":["Garantir la réparation de tout appareil","Informer sur les réparations réellement possibles","Vendre des pièces incompatibles","Refuser toute prise de contact"],"passage":"Une entreprise répare des appareils dont les pièces restent disponibles. Elle publie les modèles acceptés pour éviter des déplacements inutiles.\n\nLa liste précise les références et les principales catégories de panne prises en charge. Les clients peuvent envoyer une photographie de l'étiquette avant de transporter un objet lourd. Le réparateur explique ensuite les limites du diagnostic à distance et annonce un devis après examen. Si une pièce indispensable n'est plus disponible, il le signale avant l'intervention. Le service cherche ainsi à prolonger la vie des équipements lorsque c'est possible, tout en donnant une information suffisamment claire sur les cas acceptés.","question":"Pourquoi publier cette liste ?","explanation":"Le passage indique : « Une entreprise répare des appareils dont les pièces restent disponibles. Elle publie les modèles acceptés pour éviter des déplacements inutiles. » Cela justifie la réponse : Informer sur les réparations réellement possibles."},{"number":16,"points":15,"correct":"B","options":["Le nombre de décorations","L'évolution de l'occupation","La taille des boîtes aux lettres","Le prix des plantes"],"passage":"Des habitants partagent une chaufferie. Le suivi distingue la consommation totale et sa répartition, car une variation du nombre d'occupants peut modifier le bilan.\n\nLe bilan indique les périodes d'occupation, les températures retenues et les interventions effectuées sur l'installation. Les habitants peuvent ainsi distinguer une évolution du fonctionnement et une variation des usages. Une réunion annuelle permet de poser des questions sur la facturation. Le responsable présente les règles de calcul avec des exemples, car un chiffre total ne suffit pas toujours à expliquer ce que chaque ménage doit payer.","question":"Quelle information complète le total ?","explanation":"Le passage indique : « Des habitants partagent une chaufferie. Le suivi distingue la consommation totale et sa répartition, car une variation du nombre d'occupants peut modifier le bilan. » Cela justifie la réponse : L'évolution de l'occupation."},{"number":17,"points":15,"correct":"B","options":["Supprimer toute entrée d'air","Maintenir une ventilation adaptée","Ouvrir tous les murs","Éviter de lire les consignes"],"passage":"Un logement rénové reçoit un guide de ventilation. L'amélioration de l'étanchéité ne dispense pas d'un renouvellement d'air correctement organisé.\n\nLe document explique les entrées d'air, les bouches d'extraction et les signes qui doivent conduire à demander une vérification. Les habitants sont invités à ne pas obstruer les dispositifs lorsqu'ils ressentent un courant d'air. Ils peuvent contacter le gestionnaire pour comprendre un réglage ou signaler un bruit anormal. Une séance de présentation est organisée après les travaux. L'équipe souhaite que les gains thermiques s'accompagnent de bonnes conditions d'usage, plutôt que de laisser les occupants découvrir seuls les changements apportés au logement.","question":"Quelle précaution accompagne la rénovation ?","explanation":"Le passage indique : « Un logement rénové reçoit un guide de ventilation. L'amélioration de l'étanchéité ne dispense pas d'un renouvellement d'air correctement organisé. » Cela justifie la réponse : Maintenir une ventilation adaptée."},{"number":18,"points":15,"correct":"C","options":["Un chauffage uniquement décoratif","Une indépendance totale de tous les équipements","Un trajet de chaleur plus court","Une production sans installation"],"passage":"Une commune récupère la chaleur d'un équipement public pour alimenter un bâtiment voisin. La proximité limite les pertes lors du transport.\n\nLes techniciens comparent les heures où la chaleur est disponible avec celles où le bâtiment voisin en a besoin. Ils étudient aussi le fonctionnement du réseau lorsque l'équipement principal s'arrête. Le projet comprend un système complémentaire pour assurer la continuité du service. Avant d'engager les travaux, la commune présentera les coûts, les économies attendues et les principales incertitudes.","question":"Quel avantage présente l'emplacement ?","explanation":"Le passage indique : « Une commune récupère la chaleur d'un équipement public pour alimenter un bâtiment voisin. La proximité limite les pertes lors du transport. » Cela justifie la réponse : Un trajet de chaleur plus court."},{"number":19,"points":15,"correct":"A","options":["Adapter le choix à l'usage","Choisir selon le prix de l'emballage","Ignorer la durée d'éclairage","Installer partout la même puissance sans étude"],"passage":"Un groupe compare des lampes en tenant compte des heures d'éclairage. Une pièce rarement utilisée ne présente pas les mêmes besoins qu'un accueil ouvert toute la journée.\n\nLes participants notent la puissance et la durée d'utilisation avant de calculer une consommation estimée. Ils regardent aussi la qualité de la lumière nécessaire dans chaque espace. Une lampe adaptée à un passage bref n'est pas forcément celle qui convient à un poste de travail.","question":"Quelle démarche est adoptée ?","explanation":"Le passage indique : « Un groupe compare des lampes en tenant compte des heures d'éclairage. Une pièce rarement utilisée ne présente pas les mêmes besoins qu'un accueil ouvert toute la journée. » Cela justifie la réponse : Adapter le choix à l'usage."},{"number":20,"points":21,"correct":"B","options":["Le choix du devis le plus court uniquement","La cohérence entre les étapes","La suppression de toute anticipation","L'ordre alphabétique des entreprises"],"passage":"Une copropriété planifie ses travaux en plusieurs étapes. Elle vérifie que les premières interventions ne compliqueront pas les suivantes, notamment autour des façades et des fenêtres. Le maître d'œuvre présente un ordre possible et les points à vérifier avant chaque chantier. Les habitants comparent cette proposition avec leurs contraintes de financement et d'occupation. Certaines interventions pourront être regroupées pour éviter de reprendre un ouvrage récent. Le calendrier reste révisable, mais les décisions sont documentées pour que les équipes suivantes comprennent les choix déjà faits.","question":"Quelle attention guide le calendrier ?","explanation":"Le passage indique : « Une copropriété planifie ses travaux en plusieurs étapes. Elle vérifie que les premières interventions ne compliqueront pas les suivantes, notamment autour des façades et des fenêtres. » Cela justifie la réponse : La cohérence entre les étapes."},{"number":21,"points":21,"correct":"D","options":["Maintien constant de la température maximale","Réduction fixe sans exception","Suppression de toute occupation","Économie et adaptation aux usages réels"],"passage":"Un système automatique baisse le chauffage dans les salles vides. Les utilisateurs peuvent signaler une occupation imprévue pour éviter un inconfort. Un bouton permet de prolonger temporairement la présence sans modifier le programme de toute la semaine. Les agents examinent les demandes répétées afin de repérer un horaire habituel qui aurait été mal enregistré. Ils expliquent le fonctionnement aux associations qui utilisent les locaux en soirée. L'automatisation reste ainsi liée aux usages réels, avec une possibilité de correction lorsque le calendrier ne décrit pas correctement la situation.","question":"Quel équilibre est recherché ?","explanation":"Le passage indique : « Un système automatique baisse le chauffage dans les salles vides. Les utilisateurs peuvent signaler une occupation imprévue pour éviter un inconfort. » Cela justifie la réponse : Économie et adaptation aux usages réels."},{"number":22,"points":21,"correct":"C","options":["Le nombre de pages du devis uniquement","Le nom du modèle seulement","Les dépenses futures","La taille de l'affiche"],"passage":"Un conseiller compare le coût initial et les dépenses d'entretien de deux solutions. Une installation moins chère peut demander davantage de suivi pendant sa durée de vie. Les documents incluent les contrôles périodiques, les consommables et les interventions possibles en cas de panne. Les ménages peuvent ainsi comparer plusieurs scénarios sur une même durée. L'objectif est de rendre visibles les engagements après l'achat, sans prétendre connaître exactement toutes les dépenses qui surviendront au cours des années suivantes.","question":"Quel critère élargit la comparaison ?","explanation":"Le passage indique : « Un conseiller compare le coût initial et les dépenses d'entretien de deux solutions. Une installation moins chère peut demander davantage de suivi pendant sa durée de vie. » Cela justifie la réponse : Les dépenses futures."},{"number":23,"points":21,"correct":"A","options":["Adapter la protection aux saisons","Éviter toute attention à l'orientation","Assombrir définitivement le logement","Remplacer toutes les fenêtres"],"passage":"Des habitants testent une protection solaire mobile. Ils l'ouvrent en hiver pour laisser entrer la lumière et la ferment selon l'exposition en été. Les participants notent le confort, la luminosité et la facilité de manipulation à différents moments. Les essais ne portent donc pas seulement sur la température maximale. Une protection trop difficile à déplacer pourrait rester inutilisée malgré de bons résultats théoriques. Le groupe souhaite retenir une solution adaptée aux habitudes du logement.","question":"Quel intérêt offre sa mobilité ?","explanation":"Le passage indique : « Des habitants testent une protection solaire mobile. Ils l'ouvrent en hiver pour laisser entrer la lumière et la ferment selon l'exposition en été. » Cela justifie la réponse : Adapter la protection aux saisons."},{"number":24,"points":21,"correct":"C","options":["Un remplacement de tous les agents","Une absence de décision","Une capacité d'interprétation humaine","Un affichage sans explication"],"passage":"Une ville installe des capteurs dans ses bâtiments, puis forme les agents à lire les résultats. Les données seules n'auraient pas permis d'ajuster correctement les réglages. Les premières courbes montraient des écarts sans indiquer immédiatement leur cause. Les agents ont appris à rapprocher les heures de fonctionnement des réservations de salles et des opérations d'entretien. Ils peuvent désormais repérer un réglage oublié ou demander une vérification technique. Le dispositif prévoit un temps régulier pour examiner les informations.","question":"Quel complément est prévu ?","explanation":"Le passage indique : « Une ville installe des capteurs dans ses bâtiments, puis forme les agents à lire les résultats. Les données seules n'auraient pas permis d'ajuster correctement les réglages. » Cela justifie la réponse : Une capacité d'interprétation humaine."},{"number":25,"points":21,"correct":"C","options":["Savoir intervenir sur toute installation grâce à la lecture du compteur.","Réparer les équipements complexes en suivant les mêmes gestes qu'un joint simple.","Déterminer quand agir soi-même et quand la sécurité impose de solliciter un professionnel.","Renoncer à toute observation préalable afin de laisser l'intégralité du diagnostic au spécialiste."],"passage":"Un atelier montre comment détecter de petites fuites d'eau. Les participants apprennent aussi quand faire appel à un professionnel plutôt qu'intervenir eux-mêmes. L'animateur commence par montrer comment relever un compteur lorsque tous les points d'eau sont fermés. Il explique ensuite les limites des petites réparations accessibles avec des outils courants. Les participants repartent avec une liste de signes à surveiller et les informations utiles pour décrire un problème. Une fuite légère est repérée au compteur, mais l'atelier distingue le remplacement simple d'un joint et une anomalie proche d'une installation électrique. L'animateur demande dans le second cas une intervention qualifiée.","question":"Quelle compétence l'atelier ajoute-t-il à la détection technique des fuites ?","explanation":"Le programme enseigne les limites de l'autonomie. C, contrairement aux autres, distingue observation et intervention sûre."},{"number":26,"points":21,"correct":"A","options":["Une quantité totale semblable peut masquer des correspondances différentes entre production et consommation.","Elle détermine directement le prix de chaque appareil installé chez les membres.","Elle remplace l'obligation de documenter l'origine de l'électricité produite.","Elle garantit que deux contrats promettant le même volume ont les mêmes effets physiques."],"passage":"Un collectif achète de l'électricité produite par plusieurs sources. Il demande des informations sur la méthode de comptage pour comprendre les engagements annoncés. Les responsables veulent savoir sur quelle période la production est rapprochée de la consommation et quels documents permettent de le vérifier. Ils souhaitent présenter ces informations aux membres avec des exemples simples. Le contrat sera discuté après cette clarification. Une promesse générale ne leur paraît pas suffisante pour comprendre ce qui sera réellement acheté ni pour comparer honnêtement plusieurs offres. Deux contrats promettent une même quantité annuelle d'électricité renouvelable. L'un compare production et usage heure par heure; l'autre utilise un bilan annuel sans coïncidence temporelle. Le collectif demande que la distinction soit explicitée.","question":"Pourquoi la période de comptage change-t-elle l'interprétation de la garantie ?","explanation":"La temporalité de rapprochement diffère malgré un total annuel identique. A. B/D/C ne décrivent pas cette nuance."},{"number":27,"points":21,"correct":"D","options":["Un contrôle visuel suffit à garantir la résistance de toute structure déposée.","Les matériaux anciens sont nécessairement plus solides que ceux proposés aujourd'hui.","Le réemploi est valable seulement si le matériau revient exactement au même emplacement.","L'état et la compatibilité technique déterminent le réemploi possible."],"passage":"Une rénovation conserve les matériaux encore utilisables. L'équipe vérifie leur état et leur compatibilité avant de décider du réemploi. Les matériaux sont inventoriés avant le démontage, puis stockés de façon à éviter leur dégradation. Certains éléments pourront être utilisés directement, d'autres devront être adaptés ou écartés après contrôle. Le chantier documente ces décisions pour conserver la trace de leur origine et de leurs caractéristiques. Deux poutres déposées paraissent intactes. Le contrôle montre que l'une résiste à la nouvelle charge envisagée, mais que l'autre présente une faiblesse interne. Le chantier ne réemploie que l'élément jugé compatible.","question":"Pourquoi conserver la matière ne constitue-t-il pas une raison suffisante pour réutiliser chaque pièce ?","explanation":"Le réemploi est subordonné à une vérification technique de compatibilité. D. B/A/C imposent des règles non soutenues."},{"number":28,"points":21,"correct":"C","options":["Le changement d'affichage prouve que les appareils électriques personnels sont devenus inutiles.","Le nombre de supports installés a augmenté sans être signalé.","L'accessibilité de l'usage quotidien conditionne la réalisation des bénéfices attendus.","La capacité totale de ventilation a nécessairement doublé."],"passage":"Un immeuble installe un espace de séchage collectif ventilé. Certains habitants réduisent l'usage d'appareils électriques, mais le service doit rester assez accessible pour être utilisé régulièrement. Le gestionnaire étudie les horaires, les modalités d'accès et la durée nécessaire pour libérer les emplacements. Une salle disponible seulement à des moments peu pratiques serait rapidement délaissée. Les résidents peuvent signaler les difficultés pendant une période d'essai. Les règles seront ajustées avant d'installer davantage de supports. La salle de séchage est peu fréquentée malgré des économies potentielles. Après une extension des horaires et des réservations plus simples, les habitants l'utilisent plus régulièrement sans changer le matériel.","question":"Quel facteur explique l'amélioration obtenue sans nouvel investissement technique ?","explanation":"Le fonctionnement pratique conditionne l'adoption. C; D/B/A ajoutent des effets absents."},{"number":29,"points":21,"correct":"D","options":["Le volume de production doit être considéré en parallèle de l'intensité énergétique.","Les deux indicateurs peuvent évoluer différemment durant la même période.","Les procédés sont devenus plus efficaces pour produire un exemplaire.","La consommation totale baisse nécessairement autant que l'intensité énergétique unitaire."],"passage":"Une entreprise affiche ses économies d'énergie par unité produite. Le volume total de production ayant augmenté, elle publie aussi sa consommation globale. Les deux indicateurs sont présentés sur la même page avec une explication de leur différence. Les responsables souhaitent montrer les progrès réalisés dans les procédés sans donner l'impression que les besoins globaux ont forcément diminué. Le public peut ainsi examiner l'effet des gains techniques et celui de l'activité. La consommation par unité baisse de 15 %, mais l'entreprise produit 30 % d'unités en plus. Son besoin total peut donc augmenter malgré l'efficacité accrue du procédé.","question":"Quelle conclusion serait trompeuse à partir de la seule baisse par unité ?","explanation":"Un gain unitaire ne garantit pas un gain global si l'activité augmente. D est l'erreur; C/A/B correspondent aux informations."},{"number":30,"points":26,"correct":"B","options":["Le prix de l'appareil suffit à expliquer la variation des résultats entre les deux lieux.","Les paramètres d'installation et les pratiques réelles peuvent modifier ce que la machine permet d'obtenir.","Un rendement annoncé demeure inutile pour comparer des appareils installés différemment.","Le même modèle fonctionne de façon identique dans tous les bâtiments sous tous les réglages."],"passage":"Un équipement très performant sur le papier peut donner des résultats décevants s'il est mal réglé ou utilisé dans un lieu inadapté. Une évaluation sérieuse doit donc articuler les caractéristiques techniques, l'installation et les usages. Les techniciens relèvent les températures, les horaires et les paramètres réellement employés. Ils vérifient ensuite si les conditions correspondent à celles retenues dans la documentation commerciale. Un écart peut venir de plusieurs facteurs et nécessite parfois plusieurs essais. Deux machines identiques donnent des résultats différents. Dans l'un des bâtiments, les réglages restent ceux de l'installation par défaut; dans l'autre, les horaires ont été adaptés aux usages. Les techniciens vérifient les conditions avant d'attribuer l'écart à l'équipement.","question":"Pourquoi la fiche de performance ne prédit-elle pas à elle seule le résultat sur place ?","explanation":"L'usage et l'installation comptent au-delà de la fiche technique, B. D/C/A sont excessifs ou non étayés."},{"number":31,"points":26,"correct":"C","options":["Il indique que l'économie totale d'énergie est sans intérêt dès qu'un confort nouveau apparaît.","Il prouve que tous les occupants ont augmenté exactement de la même manière leurs températures.","Une partie du gain énergétique a pu être consacrée au confort.","Il démontre que la rénovation n'a amélioré ni l'isolation ni les conditions de vie."],"passage":"Des travaux réduisent les besoins de chauffage. Les occupants gagnent aussi en confort, parfois en chauffant un peu plus qu'avant. Ce bénéfice ne rend pas les travaux inutiles ; il invite à distinguer économie mesurée et amélioration des conditions de vie. Le suivi demande aux habitants de décrire leurs conditions avant et après l'intervention. Une pièce auparavant évitée en hiver peut désormais être utilisée normalement. Avant rénovation, un foyer chauffait peu une pièce inconfortable. Après travaux, il la maintient à une température agréable; la facture baisse moins que prévu, mais la pièce devient utilisable.","question":"Comment interpréter le résultat si l'économie d'énergie reste inférieure au calcul initial ?","explanation":"Le confort accru peut absorber une part de l'économie anticipée. C. D/B/A nient ou généralisent des effets."},{"number":32,"points":26,"correct":"A","options":["Des arbres et des sols conçus sans cohérence avec leurs usages.","La prise en compte conjointe de l'ombre et de la gestion de l'eau.","Le choix d'arbres comme source possible de rafraîchissement.","L'observation de l'endroit où les habitants souhaitent rester durant les heures chaudes."],"passage":"Une ville cherche à rafraîchir une place. Les arbres, l'ombre et les sols perméables demandent une conception commune. Additionner des éléments présentés comme vertueux ne garantit pas leur efficacité si leurs fonctions et leurs conditions d'entretien se contredisent. Un arbre a besoin d'un sol et d'un volume suffisants pour se développer. Une zone ombragée doit aussi correspondre aux endroits où les habitants s'arrêtent. Le projet sera donc examiné comme un ensemble avant le lancement des travaux. Des arbres sont plantés sur une place, mais leurs fosses trop petites empêchent un bon développement. L'ombre prévue ne se forme pas et le sol choisi reste trop imperméable pour leurs besoins.","question":"Quelle erreur de conception explique l'échec malgré l'ajout d'éléments réputés favorables ?","explanation":"Les éléments doivent fonctionner ensemble. A est l'erreur; B/C/D sont des démarches pertinentes."},{"number":33,"points":26,"correct":"B","options":["Elle supprime toute nécessité d'entretien et de réparation dès lors que le calendrier est simplifié.","Un service simple favorise le partage et évite certains achats individuels.","Elle garantit que chaque emprunteur cessera définitivement d'acheter ses propres équipements.","Elle rend inutile le suivi des emprunts et des abandons puisque l'inscription est devenue possible."],"passage":"Le partage d'un équipement réduit parfois les achats individuels. Mais si sa réservation est compliquée, les utilisateurs finissent par acheter leur propre appareil. L'économie de matière dépend donc aussi d'une organisation suffisamment simple pour durer. Les gestionnaires simplifient les créneaux, précisent les conditions de retour et prévoient une réponse en cas de panne. Ils suivent les abandons de réservation pour repérer les obstacles. Une réservation de matériel partagé demande plusieurs confirmations et entraîne des attentes. Une famille achète alors son propre équipement malgré son faible usage; les gestionnaires simplifient le prêt.","question":"Pourquoi l'amélioration du service de réservation peut-elle modifier le bilan matériel du partage ?","explanation":"La facilité d'accès peut conditionner les achats remplacés. B, sans garantie universelle."},{"number":34,"points":26,"correct":"A","options":["Un taux d'aide égal ne signifie pas un reste à charge également accessible.","La valeur de la subvention doit être identique en euros pour produire le même effet.","Le taux de 40 % empêche nécessairement les ménages les plus aisés de rénover.","L'aide devient inutile dès que les conseillers examinent les délais de remboursement."],"passage":"Une aide publique couvre une part du coût des rénovations. Les ménages doivent néanmoins avancer le reste, parfois inaccessible à leur budget. Un taux d'aide identique ne produit donc pas la même possibilité d'agir pour tous. Les conseillers examinent les possibilités d'avance et les délais de versement. Ils observent aussi les dossiers abandonnés, qui n'apparaissent pas dans les chiffres des chantiers terminés. Deux ménages reçoivent une subvention de 40 %. L'un dispose de liquidités pour avancer les 60 % restants; l'autre abandonne le chantier faute de trésorerie en attendant le remboursement.","question":"Quelle limite de l'égalité du pourcentage ressort de cet exemple ?","explanation":"Les contraintes de trésorerie et de reste à charge restent inégales. A; B/C/D ne cadrent pas."},{"number":35,"points":26,"correct":"C","options":["Un calcul de facture directement applicable à toute maison équipée du même type de fenêtre, selon le tarif actuel.","Une comparaison qui révèle les pertes des murs et du toit dès lors que les fenêtres sont testées en laboratoire.","Une comparaison relative à compléter selon les conditions propres au logement.","Un diagnostic individuel possible sans relever les usages réels ni l'étanchéité des autres parties du logement."],"passage":"Une démonstration compare deux fenêtres sous des conditions contrôlées. Elle aide à comprendre leurs performances respectives, mais ne permet pas d'annoncer directement l'économie exacte de chaque logement. Celle-ci dépend aussi des murs, des usages et du climat. Le conseiller utilise donc la démonstration comme point de départ pour expliquer les différences techniques. Une estimation individualisée demandera d'autres informations sur le bâtiment. Les résultats présentés au public précisent les conditions dans lesquelles la comparaison a été effectuée. Une fenêtre réduit davantage les pertes de chaleur dans le test, mais une maison possède aussi de grandes fuites d'air au niveau du toit. Le résultat expérimental ne permet pas de prédire seul sa facture après changement.","question":"Quelle portée faut-il attribuer à la comparaison contrôlée de deux fenêtres ?","explanation":"C limite l'essai à une comparaison technique qu'il faut compléter par les caractéristiques du bâtiment. A/D prétendent à un diagnostic individualisé, B attribue à l'essai des fenêtres des mesures sur le reste de la maison."},{"number":36,"points":33,"correct":"D","options":["Le prix de l'appareil et la durée de garantie, considérés comme estimation des ressources engagées pour sa fabrication.","Les économies annuelles de fonctionnement, déjà suffisantes pour apprécier tous les effets de la fabrication et du transport.","Le poids du carton d'emballage, utilisé comme approximation des matériaux entrant dans la composition du produit.","Fabrication, usages et durée de conservation de l'ancien appareil."],"passage":"Une campagne encourage à remplacer les appareils anciens par des modèles efficaces. Pour un équipement encore peu utilisé, l'énergie et les matériaux nécessaires à la fabrication du nouveau peuvent peser dans le bilan. La décision doit donc considérer le cycle de vie et l'usage, plutôt qu'une comparaison limitée au fonctionnement instantané. Le conseiller propose de comparer plusieurs scénarios : continuer à utiliser l'appareil, le réparer si nécessaire ou le remplacer. Il demande combien de fois il fonctionne et pendant combien de temps. La disponibilité des pièces, les consommables et les possibilités de fin de vie entrent aussi dans l'examen. Un modèle récent peut être intéressant dans certaines situations, sans que le même choix soit préférable pour tous les ménages. Présenter ces conditions aide à décider à partir des besoins réels et des ressources engagées, au lieu de déduire automatiquement la meilleure solution de l'âge inscrit sur l'étiquette. Un appareil neuf consomme moitié moins d'électricité, mais sa fabrication exige des matériaux importants. Dans un ménage qui utilise l'ancien très rarement, le remplacement immédiat pourrait ne pas compenser ces ressources avant longtemps.","question":"Quel bilan manque à la comparaison limitée à l'électricité en fonctionnement ?","explanation":"D étend l'analyse à la fabrication, à l'usage et à la conservation de l'ancien appareil. A/C utilisent des approximations insuffisantes, B confond économie d'utilisation et bilan complet."},{"number":37,"points":33,"correct":"D","options":["Le modèle installé était techniquement efficace mais les économies restaient indépendantes des réglages réellement choisis.","Les utilisateurs connaissaient les commandes courantes mais préféraient des réglages professionnels plus avancés.","La rénovation a supprimé une procédure de secours qui expliquait l'essentiel des économies annoncées.","Un potentiel technique peu utilisé faute de commandes compréhensibles."],"passage":"Un immeuble rénové reçoit un système de commande complexe. Les occupants évitent certains réglages par peur de faire une erreur. L'équipe simplifie l'interface et organise un accompagnement. Une performance théorique ne devient réelle que si les personnes peuvent effectivement piloter les usages attendus. Les premières réunions avaient surtout présenté les capacités techniques du dispositif. Elles n'avaient pas montré les gestes ordinaires, comme modifier un horaire ou revenir à un réglage connu. Des essais avec les habitants révèlent des libellés difficiles à comprendre et des confirmations peu visibles. La nouvelle version distingue les actions courantes des paramètres réservés aux professionnels. Un guide court reste disponible près de la commande et un contact est prévu pour les questions. Les habitants pourront revenir poser leurs questions. Les nouveaux thermostats offrent une programmation fine, mais des résidents craignent de modifier les réglages. Après des essais accompagnés et une interface plus simple, ils utilisent les fonctions prévues sans changer la machine.","question":"Quel décalage explique les performances initialement décevantes ?","explanation":"D décrit l'écart entre potentiel théorique et utilisation effective dû aux commandes difficiles. A nie l'effet du réglage, B inverse les difficultés des utilisateurs, C invente une suppression de secours non évoquée."},{"number":38,"points":33,"correct":"D","options":["La baisse brute mesure la consommation à service constant, même lorsqu'un bâtiment ferme une partie de l'année.","Les deux séries doivent converger si les bâtiments utilisent le même type d'équipement pendant les périodes ouvertes.","Une fermeture temporaire doit être exclue de toute présentation de consommation, même si elle réduit les dépenses réelles.","Parce que le total observé et l'efficacité à activité constante répondent à des questions différentes."],"passage":"Une ville annonce une baisse de consommation dans ses bâtiments. Plusieurs équipements ont pourtant été fermés pendant la période observée. Les responsables recalculent les résultats à usage comparable. Un chiffre peut être exact tout en donnant une interprétation trompeuse s'il ne précise pas ce qui a changé autour de la mesure. Une piscine fermée pour entretien et une salle inutilisée pendant plusieurs mois expliquent une partie de la différence annoncée. Ces fermetures ont bien réduit les dépenses, mais ne démontrent pas à elles seules une meilleure efficacité des installations. Le nouveau bilan sépare donc l'évolution liée aux surfaces et aux horaires de celle observée dans les équipements restés ouverts. Il conserve le chiffre initial en précisant sa signification. Les élus pourront ainsi discuter des économies techniques sur une base comparable, tandis que les habitants disposeront d'une présentation plus claire des services effectivement assurés pendant chacune des périodes étudiées. La consommation totale baisse de 20 %, mais un gymnase reste fermé toute la saison. Le recalcul à surfaces et horaires comparables montre une économie technique plus modeste.","question":"Pourquoi conserver le chiffre brut tout en présentant une seconde comparaison ?","explanation":"D distingue la baisse totale observée et l'évolution d'efficacité à activité comparable. A nie l'effet de fermeture, B exige une convergence injustifiée, C écarte une économie brute pourtant réelle."},{"number":39,"points":33,"correct":"A","options":["La possibilité effective pour les habitants d'influer sur l'affectation des recettes et les règles de décision, en tenant compte des obstacles à leur représentation.","La proximité des installations, qui rend la gouvernance citoyenne dès lors que les résidents connaissent les investisseurs porteurs du projet.","Le nombre de réunions tenues et la présence régulière d'un public nombreux, considérés comme des preuves suffisantes de participation même lorsqu'un petit groupe d'investisseurs conserve le veto sur les décisions financières essentielles.","La part du capital détenue par chaque membre, utilisée comme mesure unique de représentation sans examen des droits de vote."],"passage":"Un projet collectif veut produire de l'énergie près des habitants. Il organise aussi les décisions sur l'investissement et la répartition des bénéfices. Les initiateurs refusent de définir le caractère citoyen du projet par sa seule localisation. La proximité physique ne remplace pas une participation réelle aux choix qui structurent le service. Les réunions abordent notamment l'entrée de nouveaux membres, les droits de vote et l'utilisation des recettes. Les documents financiers sont présentés dans un langage accessible, avec un temps pour poser des questions avant chaque décision. Les fondateurs veulent aussi éviter que seules les personnes ayant beaucoup de temps ou de capital puissent peser sur les orientations. Ils prévoient donc plusieurs formes de contribution et des modalités de représentation. Le projet sera évalué sur la production réalisée, mais également sur la manière dont les habitants peuvent comprendre, discuter et modifier les choix qui engagent leur participation dans la durée. Le projet installe des panneaux sur un terrain proche, mais le conseil définit aussi comment les riverains votent sur l'investissement et l'usage des recettes. Le comité refuse que la seule distance aux habitations suffise à l'appellation citoyenne. Lors d'une assemblée, deux propositions reçoivent un soutien populaire comparable. L'une concerne le tarif de revente; l'autre, l'affectation des bénéfices à un fonds d'aide pour les ménages modestes. Les statuts donnent cependant un droit de veto à trois investisseurs qui détiennent la majorité du capital, même lorsque les autres membres sont plus nombreux. Les fondateurs affichent une forte participation aux réunions, mais constatent que les habitants n'ont pas pu modifier l'affectation des recettes. Ils étudient une réforme distinguant apport financier et capacité de décision, avec des règles d'information préalable et un vote sur les usages des bénéfices. L'association locale précise qu'aucune répartition des voix ne supprimera à elle seule les inégalités de disponibilité pour participer; elle souhaite donc également des mandats de représentation et des comptes rendus accessibles.","question":"Quel critère permettrait de vérifier que la participation dépasse la simple présence aux réunions ?","explanation":"A retient un pouvoir réel sur les décisions financières et les mécanismes de représentation, au-delà de la présence aux assemblées. B substitue proximité à gouvernance; C ne considère pas le veto qui neutralise la participation; D confond apport capitalistique et capacité démocratique effectivement exercée."}]}$paper_19$::jsonb),
('tcf-reading-20','tcf-reading-2026-11-close-reading-v4',$paper_20${"id":"tcf-reading-20","title":"TCF Reading · Test 20","seconds":3600,"version":"tcf-reading-2026-11-close-reading-v4","maxPoints":699,"questions":[{"number":1,"points":3,"correct":"A","options":["Le début des nouvelles parties après seize heures","L'arrivée de tous les visiteurs après quatorze heures","La présence des animateurs","La possibilité de jouer avant seize heures"],"passage":"L'atelier de jeux commence à quatorze heures. Vous pouvez arriver plus tard, mais aucune nouvelle partie ne sera lancée après seize heures.\n\nL'accueil vous indiquera les tables encore disponibles. Les parties déjà commencées pourront se terminer normalement après cette heure.","question":"Quelle limite est annoncée ?","explanation":"Le passage indique : « L'atelier de jeux commence à quatorze heures. Vous pouvez arriver plus tard, mais aucune nouvelle partie ne sera lancée après seize heures. » Cela justifie la réponse : Le début des nouvelles parties après seize heures."},{"number":2,"points":3,"correct":"A","options":["La zone balisée du chantier","Tout le parc","Le jardin voisin","Toutes les allées"],"passage":"Le parc reste ouvert pendant les travaux du kiosque. Seule la zone entourée de barrières est inaccessible.\n\nLes autres allées restent accessibles. Merci de suivre les panneaux temporaires pour rejoindre l'aire de jeux.","question":"Quel espace est fermé ?","explanation":"Le passage indique : « Le parc reste ouvert pendant les travaux du kiosque. Seule la zone entourée de barrières est inaccessible. » Cela justifie la réponse : La zone balisée du chantier."},{"number":3,"points":3,"correct":"B","options":["Acheter le matériel","S'inscrire","Venir chercher son certificat","Payer immédiatement"],"passage":"Les inscriptions au stage ferment demain. Le paiement peut être effectué la semaine suivante.\n\nRemplissez le formulaire en ligne pour réserver votre place. Vous recevrez ensuite les indications nécessaires pour régler les frais.","question":"Quelle démarche est urgente ?","explanation":"Le passage indique : « Les inscriptions au stage ferment demain. Le paiement peut être effectué la semaine suivante. » Cela justifie la réponse : S'inscrire."},{"number":4,"points":3,"correct":"A","options":["Le lieu de rassemblement","La durée de la promenade","Le jour choisi","L'heure du départ"],"passage":"Le rendez-vous de la promenade passe de la mairie à la gare. Le départ reste prévu à dix heures.\n\nLe groupe vous attendra devant l'entrée principale. Merci de transmettre ce changement aux personnes qui viennent avec vous.","question":"Qu'est-ce qui change ?","explanation":"Le passage indique : « Le rendez-vous de la promenade passe de la mairie à la gare. Le départ reste prévu à dix heures. » Cela justifie la réponse : Le lieu de rassemblement."},{"number":5,"points":9,"correct":"B","options":["Prolonger le trajet","Préserver un temps de récupération","Ajouter une visite obligatoire","Organiser une compétition"],"passage":"Je préfère réserver une soirée sans programme après notre voyage. Nous aurons besoin de temps pour nous reposer et ranger les affaires.\n\nOn pourra faire les courses le lendemain matin. Préviens simplement nos amis que nous préférons les retrouver un autre jour de la semaine.","question":"Quelle intention est exprimée ?","explanation":"Le passage indique : « Je préfère réserver une soirée sans programme après notre voyage. Nous aurons besoin de temps pour nous reposer et ranger les affaires. » Cela justifie la réponse : Préserver un temps de récupération."},{"number":6,"points":9,"correct":"D","options":["Une personne ayant déjà terminé","Seulement un vendeur d'outils","Uniquement un professionnel","Une personne avec un projet modeste"],"passage":"Notre atelier fournit les outils de base. Vous pouvez apporter votre projet inachevé, même s'il est très simple.\n\nUn animateur vous aidera à choisir la prochaine étape. Pensez à apporter les pièces déjà réalisées.","question":"Qui est accueilli ?","explanation":"Le passage indique : « Notre atelier fournit les outils de base. Vous pouvez apporter votre projet inachevé, même s'il est très simple. » Cela justifie la réponse : Une personne avec un projet modeste."},{"number":7,"points":9,"correct":"D","options":["Éviter tout échange","Choisir uniquement selon le poids","Vendre tous les ouvrages","Découvrir les livres par la discussion"],"passage":"Je te propose d'échanger nos livres au café. Nous pourrons en parler avant de choisir ceux que nous emporterons.\n\nJ'apporterai les deux romans dont je t'ai parlé et tu pourras les feuilleter tranquillement. Dis-moi quel jour te conviendrait pour nous retrouver la semaine prochaine.","question":"Quel intérêt présente la rencontre ?","explanation":"Le passage indique : « Je te propose d'échanger nos livres au café. Nous pourrons en parler avant de choisir ceux que nous emporterons. » Cela justifie la réponse : Découvrir les livres par la discussion."},{"number":8,"points":9,"correct":"B","options":["Une présence quotidienne obligatoire","Une fréquentation occasionnelle","Une activité réservée aux abonnés","Un accès sans horaire"],"passage":"Le centre propose des entrées sans abonnement pour les personnes qui viennent rarement. Le tarif à la séance reste distinct du forfait.\n\nLes prix sont affichés à l'accueil. Demandez conseil avant de choisir votre formule pour le trimestre.","question":"À quel besoin répond cette formule ?","explanation":"Le passage indique : « Le centre propose des entrées sans abonnement pour les personnes qui viennent rarement. Le tarif à la séance reste distinct du forfait. » Cela justifie la réponse : Une fréquentation occasionnelle."},{"number":9,"points":9,"correct":"B","options":["Parce que la salle a été vendue","Pour permettre davantage de participation","Parce que le rangement est terminé","Pour supprimer toute consultation"],"passage":"Nous reportons le rangement collectif : trop de voisins sont absents dimanche. Une nouvelle date sera choisie par sondage.\n\nChacun pourra indiquer plusieurs disponibilités. Nous confirmerons ensuite le créneau retenu et la liste du matériel à apporter.","question":"Pourquoi le rendez-vous est-il reporté ?","explanation":"Le passage indique : « Nous reportons le rangement collectif : trop de voisins sont absents dimanche. Une nouvelle date sera choisie par sondage. » Cela justifie la réponse : Pour permettre davantage de participation."},{"number":10,"points":9,"correct":"A","options":["Laisser du temps sans objectif productif","Transformer chaque pause en tâche","Renoncer à tout repos","Organiser toutes les journées de la même façon"],"passage":"Je ne veux pas remplir toutes mes pauses avec des activités utiles. Certaines resteront simplement des moments de repos.\n\nJe me sens mieux lorsque je peux parfois marcher sans objectif ou regarder par la fenêtre. Cela m'aide à reprendre ensuite mes tâches.","question":"Quel choix est défendu ?","explanation":"Le passage indique : « Je ne veux pas remplir toutes mes pauses avec des activités utiles. Certaines resteront simplement des moments de repos. » Cela justifie la réponse : Laisser du temps sans objectif productif."},{"number":11,"points":15,"correct":"A","options":["Définir la fonction du meuble","Acheter un meuble neuf","Vendre immédiatement les outils","Choisir une couleur au hasard"],"passage":"Un atelier transforme des meubles récupérés. Les participants décident d'abord de l'usage recherché avant de choisir la décoration.\n\nUne petite armoire pourra par exemple devenir un rangement pour les chaussures ou un support pour des plantes. Les dimensions et la solidité sont vérifiées avant de commencer. Les animateurs montrent comment démonter une pièce et préparer les surfaces sans abîmer le reste du meuble. La couleur est discutée ensuite, en fonction du lieu où l'objet sera installé. Les participants repartent avec une fiche des gestes réalisés pour pouvoir entretenir leur réalisation. Le projet associe ainsi choix pratique, apprentissage technique et transformation esthétique.","question":"Quelle étape est prioritaire ?","explanation":"Le passage indique : « Un atelier transforme des meubles récupérés. Les participants décident d'abord de l'usage recherché avant de choisir la décoration. » Cela justifie la réponse : Définir la fonction du meuble."},{"number":12,"points":15,"correct":"C","options":["Venir uniquement regarder","S'inscrire dans une autre ville","Emprunter les pièces","Acheter une table"],"passage":"Une ville installe des tables d'échecs dans un parc. Les habitants peuvent apporter leurs pièces ; un prêt est aussi proposé à l'accueil voisin.\n\nLes tables sont accessibles sans réservation aux heures d'ouverture du parc. Un panneau explique comment emprunter le matériel et où le rapporter après la partie. Des bénévoles proposent parfois une initiation aux débutants. Les dates seront affichées sur le panneau près des tables.","question":"Quelle solution évite d'avoir son propre matériel ?","explanation":"Le passage indique : « Une ville installe des tables d'échecs dans un parc. Les habitants peuvent apporter leurs pièces ; un prêt est aussi proposé à l'accueil voisin. » Cela justifie la réponse : Emprunter les pièces."},{"number":13,"points":15,"correct":"B","options":["Le déplacement le plus rapide","L'attention au quotidien proche","La recherche exclusive de records","L'évitement de toute observation"],"passage":"Un groupe propose des promenades sans destination spectaculaire. Les participants découvrent les détails des rues ordinaires à un rythme lent.\n\nLe guide invite le groupe à observer une façade, une plante entre les pavés ou les sons d'une place. Les arrêts sont choisis selon ce qui attire l'attention pendant la marche. Aucune liste de monuments à voir absolument n'est distribuée au départ. Les participants peuvent partager un souvenir lié au quartier ou demander de revenir sur un détail. La promenade propose ainsi une autre façon de regarder un environnement familier, sans exiger un long déplacement ni la recherche d'un événement exceptionnel à chaque étape.","question":"Quel regard est encouragé ?","explanation":"Le passage indique : « Un groupe propose des promenades sans destination spectaculaire. Les participants découvrent les détails des rues ordinaires à un rythme lent. » Cela justifie la réponse : L'attention au quotidien proche."},{"number":14,"points":15,"correct":"B","options":["Supprimer les livres de loisir","Accueillir différents usages du lieu","Réserver tout le bâtiment aux candidats","Fermer pendant les examens"],"passage":"Une bibliothèque élargit ses horaires pendant les examens. Elle réserve cependant des espaces aux lecteurs qui ne préparent pas d'épreuve.\n\nLes étudiants disposent de davantage de tables pour réviser, mais le prêt, la lecture sur place et les visites habituelles continuent. Des panneaux distinguent les zones silencieuses des espaces où l'on peut discuter doucement. L'équipe observe les besoins à différents moments de la journée pour ajuster l'organisation. Elle souhaite répondre à l'affluence particulière de la période sans laisser penser que les autres usages doivent disparaître.","question":"Quel équilibre est recherché ?","explanation":"Le passage indique : « Une bibliothèque élargit ses horaires pendant les examens. Elle réserve cependant des espaces aux lecteurs qui ne préparent pas d'épreuve. » Cela justifie la réponse : Accueillir différents usages du lieu."},{"number":15,"points":15,"correct":"B","options":["Une réalisation automatique de chaque idée","Sa faisabilité dans le cadre du centre","L'absence de toute discussion","Le choix exclusif des adultes sans consultation"],"passage":"Un centre de loisirs demande aux adolescents de proposer les activités. L'équipe vérifie ensuite les moyens nécessaires et les règles de sécurité.\n\nLes jeunes commencent par présenter ce qu'ils aimeraient découvrir et la manière dont ils souhaitent participer. Les animateurs les aident à estimer le budget, le temps de préparation et les besoins d'encadrement. Une proposition trop ambitieuse peut être adaptée plutôt que rejetée sans discussion. Le programme final indiquera ce qui a été retenu et les raisons des principaux choix. Cette étape doit permettre aux adolescents de voir les conséquences concrètes de leur contribution, tout en comprenant les responsabilités qui accompagnent l'organisation d'une activité collective.","question":"Quelle limite encadre la proposition ?","explanation":"Le passage indique : « Un centre de loisirs demande aux adolescents de proposer les activités. L'équipe vérifie ensuite les moyens nécessaires et les règles de sécurité. » Cela justifie la réponse : Sa faisabilité dans le cadre du centre."},{"number":16,"points":15,"correct":"D","options":["Éviter toute évaluation","Augmenter artificiellement le nombre de réunions","Mesurer uniquement la taille des salles","Vérifier si le travail a simplement été déplacé"],"passage":"Une entreprise expérimente une semaine de réunions plus courtes. Elle recueille ensuite les tâches reportées en dehors des réunions pour évaluer le résultat réel.\n\nCertains échanges supprimés de l'ordre du jour peuvent en effet réapparaître dans des messages individuels ou dans des discussions tardives. Les salariés notent ces déplacements pendant la période d'essai. L'équipe compare le temps total consacré à la coordination et la qualité des décisions obtenues. Elle cherche une organisation plus utile, sans considérer la seule durée inscrite au calendrier comme une preuve suffisante d'amélioration.","question":"Pourquoi regarder aussi ces tâches ?","explanation":"Le passage indique : « Une entreprise expérimente une semaine de réunions plus courtes. Elle recueille ensuite les tâches reportées en dehors des réunions pour évaluer le résultat réel. » Cela justifie la réponse : Vérifier si le travail a simplement été déplacé."},{"number":17,"points":15,"correct":"C","options":["Encourager à venir malgré l'annulation","Remplacer les dates par des photos","Informer ceux qui avaient vu la première annonce","Masquer les changements"],"passage":"Des habitants partagent un agenda de quartier. Les événements annulés y restent visibles avec une mention claire, pour éviter les déplacements inutiles.\n\nUne couleur et une date de modification permettent de distinguer une annulation d'un événement encore confirmé. Les habitants peuvent consulter l'agenda sur leur téléphone ou sur un affichage à l'accueil du centre. L'équipe vérifie régulièrement les informations les plus proches, car une fiche oubliée peut rester visible longtemps. Le service vise à faciliter la participation en donnant des renseignements fiables, y compris lorsqu'une activité ne pourra finalement pas avoir lieu.","question":"Pourquoi conserver cette trace ?","explanation":"Le passage indique : « Des habitants partagent un agenda de quartier. Les événements annulés y restent visibles avec une mention claire, pour éviter les déplacements inutiles. » Cela justifie la réponse : Informer ceux qui avaient vu la première annonce."},{"number":18,"points":15,"correct":"D","options":["Remplacer systématiquement chaque vêtement","Réparer tout objet sans exception","Éviter d'observer la matière","Reconnaître les limites d'une réparation"],"passage":"Un atelier de couture accueille les réparations courantes. Les animateurs conseillent aussi de renoncer lorsque le tissu est trop fragile pour supporter une nouvelle intervention.\n\nLes participants apportent leurs vêtements et expliquent l'usage qu'ils souhaitent en faire. L'équipe examine les coutures et la matière avant de proposer une technique. Une petite reprise peut suffire dans certains cas, tandis qu'une zone très usée risquerait de se déchirer juste à côté de la réparation. Les animateurs montrent comment reconnaître ces limites et envisager d'autres usages du tissu.","question":"Quelle compétence est également transmise ?","explanation":"Le passage indique : « Un atelier de couture accueille les réparations courantes. Les animateurs conseillent aussi de renoncer lorsque le tissu est trop fragile pour supporter une nouvelle intervention. » Cela justifie la réponse : Reconnaître les limites d'une réparation."},{"number":19,"points":15,"correct":"D","options":["Supprimer toute règle","Désigner un perdant obligatoire","Récompenser uniquement le plus rapide","Réussir ensemble"],"passage":"Une association propose des jeux coopératifs. Les participants cherchent une solution commune plutôt que l'élimination des autres.\n\nLes animateurs choisissent des règles où les informations et les ressources doivent être partagées. Certains groupes découvrent qu'une personne a organisé toutes les actions sans vraiment écouter les autres. La séance suivante peut alors modifier la répartition des rôles. Réussir ensemble ne signifie donc pas seulement atteindre un résultat, mais aussi apprendre comment chacun trouve sa place dans la recherche commune.","question":"Quel objectif organise le jeu ?","explanation":"Le passage indique : « Une association propose des jeux coopératifs. Les participants cherchent une solution commune plutôt que l'élimination des autres. » Cela justifie la réponse : Réussir ensemble."},{"number":20,"points":21,"correct":"D","options":["Tout temps d'attente est totalement libre","Tous les loisirs demandent le même temps","Les responsabilités disparaissent hors du bureau","L'absence de travail visible ne signifie pas une liberté complète"],"passage":"Une enquête sur les loisirs distingue le temps libre apparent et le temps réellement disponible. Attendre un proche tout en restant responsable de son retour n'offre pas les mêmes possibilités qu'une période sans contrainte. Les chercheurs demandent ce que les personnes peuvent faire pendant ces périodes et si elles doivent pouvoir s'interrompre immédiatement. Une heure passée à attendre près d'un établissement ne permet pas toujours de rejoindre une activité éloignée. Le rapport distingue donc les durées sur le calendrier et les possibilités concrètes d'en disposer, pour éviter de présenter comme équivalentes des situations très différentes.","question":"Quelle distinction est faite ?","explanation":"Le passage indique : « Une enquête sur les loisirs distingue le temps libre apparent et le temps réellement disponible. Attendre un proche tout en restant responsable de son retour n'offre pas les mêmes possibilités qu'une période sans contrainte. » Cela justifie la réponse : L'absence de travail visible ne signifie pas une liberté complète."},{"number":21,"points":21,"correct":"D","options":["La valeur de tous les équipements","Le programme de l'année suivante seulement","Le résultat garanti du trimestre","La manière de vivre l'activité dans le groupe"],"passage":"Un centre autorise les participants à assister à une séance avant de s'engager pour un trimestre. L'essai aide à apprécier l'ambiance autant que le contenu. La personne peut observer les échanges, essayer le matériel et poser des questions à l'animateur. Aucune décision immédiate n'est demandée à la sortie. Le centre présente également les horaires, les frais et les conditions d'absence afin que l'engagement soit bien compris. Les retours des visiteurs serviront à améliorer l'accueil.","question":"Quel aspect peut être évalué avant l'inscription ?","explanation":"Le passage indique : « Un centre autorise les participants à assister à une séance avant de s'engager pour un trimestre. L'essai aide à apprécier l'ambiance autant que le contenu. » Cela justifie la réponse : La manière de vivre l'activité dans le groupe."},{"number":22,"points":21,"correct":"C","options":["Remplacer la rue chaque semaine","Garantir un projet définitif sans essai","Permettre une expérimentation réversible","Interdire toute participation"],"passage":"Un quartier transforme une rue en espace de jeux quelques dimanches. Les aménagements restent démontables pour observer l'usage avant une décision plus durable. Les équipes relèvent les moments de forte présence et les difficultés signalées par les riverains. Elles observent aussi si des enfants de différents âges peuvent trouver leur place. Les barrières et les tables seront retirées après chaque journée. Le bilan permettra de discuter d'une éventuelle installation permanente avec davantage d'informations.","question":"Pourquoi choisir du matériel démontable ?","explanation":"Le passage indique : « Un quartier transforme une rue en espace de jeux quelques dimanches. Les aménagements restent démontables pour observer l'usage avant une décision plus durable. » Cela justifie la réponse : Permettre une expérimentation réversible."},{"number":23,"points":21,"correct":"A","options":["Mieux distinguer accès à l'information et interruption","Imposer une réaction immédiate à chacun","Rendre les informations confidentielles","Supprimer tous les messages"],"passage":"Une équipe supprime les alertes non urgentes sur son outil commun. Les informations restent consultables, mais n'interrompent plus automatiquement chaque personne. Les messages nécessitant une réponse rapide gardent un canal identifié. Pour les autres, les membres consultent les nouvelles à des moments choisis dans la journée. Une période d'essai permettra de vérifier qu'aucune information importante n'est perdue. Les responsables souhaitent réduire les interruptions sans empêcher la coordination. Ils expliquent donc les nouvelles règles et les situations dans lesquelles une alerte reste nécessaire.","question":"Quel changement est recherché ?","explanation":"Le passage indique : « Une équipe supprime les alertes non urgentes sur son outil commun. Les informations restent consultables, mais n'interrompent plus automatiquement chaque personne. » Cela justifie la réponse : Mieux distinguer accès à l'information et interruption."},{"number":24,"points":21,"correct":"B","options":["La suppression des rencontres libres","Un accueil sans programme imposé","Une obligation permanente d'apprendre","Un accès réservé aux animateurs"],"passage":"Un lieu associatif ouvre des plages sans activité organisée. Les habitants peuvent s'y rencontrer sans devoir participer à un atelier. Des sièges, de l'eau et quelques documents sont disponibles, mais aucune production n'est attendue. Une personne de l'équipe accueille les nouveaux visiteurs et explique les règles du lieu. Certains viennent discuter quelques minutes, d'autres lisent ou attendent un voisin. Les responsables veulent conserver ces usages simples dans le programme, car toutes les rencontres ne commencent pas par une inscription à une activité précise.","question":"Quel besoin est reconnu ?","explanation":"Le passage indique : « Un lieu associatif ouvre des plages sans activité organisée. Les habitants peuvent s'y rencontrer sans devoir participer à un atelier. » Cela justifie la réponse : Un accueil sans programme imposé."},{"number":25,"points":21,"correct":"A","options":["Comparer l'état initial et le retour pour distinguer les pertes récentes.","Elle supprime le besoin d'examiner l'état du jeu lorsqu'il revient.","Elle garantit qu'une pièce manquante sera retrouvée avant le prêt suivant.","Elle détermine le nombre de joueurs autorisés selon les pièces présentes."],"passage":"Des bénévoles gèrent une collection de jeux. Ils notent les pièces manquantes avant le prêt, afin de distinguer un état ancien d'une perte récente. La fiche accompagne la boîte et peut être complétée au retour. Une pièce déjà absente est signalée clairement afin que le prochain emprunteur sache si le jeu reste utilisable. L'équipe peut ainsi rechercher une solution de remplacement sans attribuer automatiquement le problème au dernier utilisateur. Une boîte revient avec une carte en moins; la fiche du départ indiquait déjà cette absence. L'équipe distingue ainsi un défaut connu d'une nouvelle perte et propose un remplacement sans accuser à tort l'emprunteur.","question":"Quelle information la fiche de prêt rend-elle possible lors du retour ?","explanation":"Le suivi avant et après évite les responsabilités mal attribuées. A; C/B/D ne sont pas ses effets."},{"number":26,"points":21,"correct":"C","options":["Les ateliers sont gratuits uniquement si le participant devient client du magasin.","Tout produit apporté peut être remplacé gratuitement pour éviter un nouvel achat.","L'atelier est gratuit sans achat, mais limité aux produits éligibles.","Les modèles concernés sont décidés après la réparation pour adapter la publicité."],"passage":"Un magasin organise des ateliers de réparation gratuits. Il précise quels produits sont concernés et ne conditionne pas l'accès à un nouvel achat. Les participants peuvent vérifier leur modèle avant de se déplacer grâce à une liste disponible à l'accueil. Les animateurs précisent aussi les opérations qu'ils ne peuvent pas réaliser sur place. Le magasin espère faire connaître son service, mais les places ne sont pas réservées aux clients qui commandent un autre produit. Une cliente vient faire réparer un appareil éligible sans acheter de nouvel article. Une autre, dont le modèle n'est pas pris en charge, reçoit une explication avant de réserver sa place.","question":"Quelle différence le magasin distingue-t-il dans les conditions de participation ?","explanation":"L'atelier est sans achat obligatoire mais limité à certains modèles et opérations. C; B/A/D confondent ces conditions."},{"number":27,"points":21,"correct":"A","options":["La surestimation d'usages visibles uniquement à une heure au détriment de ceux pratiqués à d'autres moments.","La présence de plusieurs groupes au même endroit, qui empêche de comparer leurs demandes.","Le nombre de personnes interrogées, qui doit rester identique quel que soit le moment de la journée.","L'influence des opinions écrites, qui doivent être exclues des consultations présentielles."],"passage":"Une commune consulte les usagers d'un parc en semaine et le week-end. Les profils présents diffèrent selon les horaires. Des retraités, des salariés et des familles ne fréquentent pas nécessairement les mêmes zones au même moment. Les enquêteurs varient donc les jours et les points de rencontre. Le projet d'aménagement s'appuiera sur ces observations et sur les contributions écrites, plutôt que sur un seul après-midi de consultation. Une enquête menée le mardi matin recueille surtout les avis des retraités. Le samedi, des salariés et des familles signalent d'autres usages du même parc. La commune maintient les deux sessions.","question":"Quel biais la diversité des créneaux cherche-t-elle à réduire ?","explanation":"Les populations changent selon les horaires. A. B/D/C ne décrivent pas la sous-représentation temporelle."},{"number":28,"points":21,"correct":"C","options":["Elle garantit seulement la disponibilité d'un bus à n'importe quelle heure de la journée.","Elle ne sert qu'aux personnes qui possèdent déjà leur propre véhicule.","Les possibilités de retour et leurs horaires font partie du trajet réellement praticable.","Elle ne renseigne pas sur la difficulté des jeux pratiqués pendant l'activité."],"passage":"Un club propose des sorties courtes proches des transports. Les nouveaux participants peuvent rejoindre facilement l'activité sans posséder de voiture. Le descriptif indique la distance à parcourir depuis l'arrêt et les horaires possibles pour le retour. Un contact est prévu en cas de changement. Le club souhaite ainsi que la facilité annoncée soit réelle pendant tout le trajet, pas seulement entre le point de départ de la marche et son arrivée. Une sortie commence à proximité d'un bus, mais le dernier départ est avancé le week-end. Le club vérifie désormais l'horaire du retour avant de présenter l'activité comme accessible sans voiture.","question":"Pourquoi la proximité d'un arrêt au départ ne suffit-elle pas à garantir l'accessibilité ?","explanation":"Le retour doit aussi être possible. C. D/A/B sont des conclusions erronées."},{"number":29,"points":21,"correct":"A","options":["Expliquer les gestes pour sécuriser l'usage et le retour du matériel.","Il transfère au bénévole toutes les opérations futures de l'emprunteur.","Il supprime la nécessité de vérifier l'appareil lorsque son prêt a été expliqué.","Il permet de limiter les prêts aux personnes déjà expertes, indépendamment de leur besoin."],"passage":"Une bibliothèque d'objets prépare des fiches simples. Un prêt devient plus utile lorsque les personnes savent installer, utiliser et rapporter correctement l'équipement. Les bénévoles montrent les gestes essentiels lors de la première remise du matériel. Les fiches rappellent les vérifications et les situations où il faut demander de l'aide. Les emprunteurs peuvent signaler une consigne difficile à comprendre pour qu'elle soit reformulée. Une perceuse partagée revient endommagée après une mauvaise installation. L'association ajoute un bref essai pratique et un guide de retour, puis vérifie que les consignes sont comprises.","question":"Quel rôle l'accompagnement ajoute-t-il à la simple disponibilité de l'objet ?","explanation":"Le prêt efficace demande connaissance des gestes et du retour. A; D/B/C ignorent la progression vers l'autonomie."},{"number":30,"points":26,"correct":"D","options":["Considérer que l'accessibilité influence les choix, même lorsqu'un loisir est apprécié.","Demander aux participants quelles activités les intéresseraient si l'offre locale était différente.","Distinguer les horaires et le coût des préférences exprimées par les personnes interrogées.","Confondre une activité accessible et celle véritablement préférée par chacun."],"passage":"Les loisirs sont parfois décrits comme un choix purement personnel. Les horaires, l'offre locale, le coût et les responsabilités familiales orientent pourtant les possibilités. Étudier les goûts sans regarder ces conditions risque de confondre préférence et adaptation à des contraintes. Une personne qui choisit une activité proche peut en apprécier le contenu tout en ayant renoncé à d'autres possibilités trop coûteuses ou éloignées. Les entretiens demandent donc aussi quelles propositions auraient intéressé les participants dans d'autres conditions. Deux personnes choisissent une activité locale. L'une la préfère à toute autre; l'autre aurait souhaité un sport plus éloigné mais n'a pas de voiture. Le choix observé ne révèle pas à lui seul la préférence initiale.","question":"Quelle erreur ferait l'enquêteur en interprétant les deux inscriptions comme un goût identique ?","explanation":"L'une choisit par goût, l'autre par contrainte. D est la mauvaise interprétation; A/B/C sont des précautions fondées."},{"number":31,"points":26,"correct":"A","options":["Il ne mesure pas le temps supplémentaire de préparation, d'apprentissage et de correction.","Il prouve que toutes les tâches du service se réalisent désormais en moins de dix minutes.","Il rend la formation initiale inutile dès qu'une opération automatique est rapide.","Il établit que les erreurs proviennent nécessairement de l'utilisateur et non du logiciel."],"passage":"Un service promet de faire gagner du temps. Il demande toutefois à l'utilisateur de saisir régulièrement des données et de corriger les erreurs. Le gain doit être évalué sur l'ensemble des tâches, pas seulement sur celle que le service accomplit automatiquement. L'évaluation note aussi le temps nécessaire pour apprendre le fonctionnement et vérifier les résultats. Une tâche réalisée en quelques secondes peut déplacer une partie du travail vers d'autres moments. Le logiciel réalise la saisie en deux minutes au lieu de dix, mais exige quinze minutes de préparation hebdomadaire et plusieurs corrections. Le bilan inclut désormais ces tâches auparavant invisibles.","question":"Pourquoi le gain de huit minutes affiché pour une étape peut-il être trompeur ?","explanation":"Les tâches déplacées ou nouvelles doivent être comptées, A. B/C/D surinterprètent un seul temps."},{"number":32,"points":26,"correct":"C","options":["Renoncer à toute règle afin que chaque groupe trouve naturellement une solution.","Supprimer l'une des activités pour éviter toute négociation sur les horaires.","Organiser les contraintes entre usages différents plutôt que présumer une compatibilité spontanée.","Réserver toute la place aux activités les plus nombreuses lors de la première consultation."],"passage":"Une place publique accueille des usages variés qui ne s'accordent pas spontanément : repos, jeux, passage et manifestations. Un aménagement réussi ne supprime pas forcément les différences ; il peut organiser leur coexistence par des espaces, des horaires et des règles discutées. Les habitants discutent des nuisances, des accès et des moments où certaines activités peuvent se dérouler. Il cherche à rendre les usages compatibles, sans supposer qu'un même espace répondra spontanément à toutes les attentes. Les réunions publiques et les jeux d'enfants se gênent à certaines heures, mais peuvent coexister si les espaces et les horaires sont discutés. La commune élabore un calendrier partagé avec les usagers.","question":"Quelle approche de l'espace commun ce projet privilégie-t-il ?","explanation":"La pluralité demande coordination et règles. C. B/D/A privilégient un seul usage ou nient l'organisation."},{"number":33,"points":26,"correct":"D","options":["Elles démontrent que le projet n'a pas de valeur tant qu'il demande plusieurs essais.","Elles prouvent que toutes les méthodes rapides sont pédagogiquement inférieures.","Elles doivent être imposées à tous les participants avec un nombre identique de tentatives.","Elles peuvent constituer une part du processus d'apprentissage, non seulement un retard à supprimer."],"passage":"Un atelier valorise le fait de terminer un projet lentement. Les participants découvrent des gestes qu'une solution rapide aurait évités. La durée n'est pas automatiquement un défaut lorsqu'elle fait partie de ce que l'activité permet d'apprendre ou d'éprouver. Les animateurs laissent une place aux essais et aux reprises, sans fixer un objectif identique pour chaque séance. Les participants peuvent expliquer ce qu'ils ont découvert pendant le travail. Lorsqu'un participant reprend plusieurs fois une pièce de bois, il apprend à identifier les défauts d'assemblage. Terminer plus vite aurait évité ces essais et une partie de l'apprentissage.","question":"Quelle fonction les reprises jouent-elles dans cette activité ?","explanation":"Les reprises font découvrir le geste, D. A/B/C exagèrent."},{"number":34,"points":26,"correct":"B","options":["Elle garantit que les événements imprévisibles pourront être traités en dehors de tout planning.","Elle efface les marges utiles aux imprévus et au repos, fragilisant l'organisation.","Elle empêche de planifier à l'avance les activités principales déjà prévues.","Elle réduit nécessairement le nombre de tâches terminées même en l'absence d'incidents."],"passage":"Un agenda collectif rend visibles les activités d'un groupe, mais peut devenir envahissant si chaque créneau libre paraît disponible pour une nouvelle tâche. Les membres décident de protéger aussi des périodes sans rendez-vous. Une absence de rendez-vous peut correspondre à un besoin de repos ou à une réserve pour les imprévus. Le calendrier indique désormais les périodes qui doivent rester protégées. Une équipe voit des cases libres et y ajoute de nouvelles missions. Les membres n'ont alors plus de temps pour traiter un incident urgent ni récupérer après une période chargée. Des plages protégées sont instaurées.","question":"Quel risque présente l'assimilation de toute case vide à un créneau disponible ?","explanation":"La réserve protège la résilience du programme. B. A/D/C ne suivent pas le scénario."},{"number":35,"points":26,"correct":"C","options":["Une sortie rare renseigne moins sur la valeur qu'une activité hebdomadaire, sauf lorsqu'elle rassemble beaucoup d'autres personnes.","La diversité des loisirs permet d'estimer l'attachement de chaque participant plus précisément que la fréquence seule.","La valeur vécue diffère parfois de la fréquence mesurée.","Une personne aux sorties nombreuses est généralement plus satisfaite même lorsqu'elle ne décrit pas le même attachement."],"passage":"Une enquête mesure le nombre d'activités pratiquées. Des participants ayant peu d'activités déclarent pourtant y être très attachés. La richesse d'un loisir ne se confond pas toujours avec la diversité ou la fréquence mesurable des sorties. Les entretiens demandent ce que l'activité apporte : une relation, une découverte ou un moment attendu dans la semaine. Ces réponses complètent les données de fréquentation. Une personne participe à une seule rencontre mensuelle, mais dit qu'elle compte beaucoup pour elle. Une autre multiplie les sorties sans retrouver le même sentiment d'attachement.","question":"Quelle conclusion évite de réduire l'expérience de loisir à sa fréquence ?","explanation":"C distingue le sens vécu de la quantité d'activités. A/B/D continuent à inférer l'importance affective depuis le nombre ou la diversité sans tenir compte des témoignages."},{"number":36,"points":33,"correct":"C","options":["Les séances sans réservation améliorent l'accueil mais rendent superflues les activités régulières pour les publics déjà inscrits.","La diversité des disciplines permet à chacun de trouver un sujet, ce qui compense les horaires difficiles.","Des modalités d'inscription semblables excluent certains publics malgré des sujets variés.","Une programmation étoffée peut éloigner des publics si elle exige une préparation plus longue de chaque participant."],"passage":"La multiplication des activités proposées peut donner l'impression d'un choix toujours plus large. Mais si toutes exigent réservation anticipée et présence régulière, les personnes aux horaires imprévisibles restent exclues. La diversité des contenus ne garantit pas une diversité des conditions de participation. Les responsables interrogent les personnes qui ont abandonné une inscription ou qui consultent les programmes sans jamais réserver. Certaines travaillent sur des créneaux changeants, d'autres ne peuvent pas prévoir longtemps à l'avance leurs possibilités de déplacement. Le centre teste donc des séances indépendantes, des places accessibles le jour même et des engagements plus courts. Ces formules seront évaluées avec les activités régulières, qui répondent à d'autres besoins. Il ne s'agit pas d'imposer un modèle unique, mais d'offrir plusieurs manières d'entrer dans les propositions et de rendre les contraintes visibles dès la présentation du programme. Un centre affiche vingt activités mais exige une inscription trois semaines avant chacune. Les salariés à horaires variables restent absents; des séances à accès spontané permettent ensuite une autre forme de participation.","question":"Pourquoi le nombre d'activités proposées n'est-il pas un indicateur suffisant d'ouverture du programme ?","explanation":"C décrit des conditions d'inscription semblables qui restent excluantes malgré la variété. A oppose deux formats complémentaires; B suppose que le choix de sujet compense l'accès; D attribue le problème à la préparation plutôt qu'aux horaires et réservations."},{"number":37,"points":33,"correct":"C","options":["Une subvention publique transforme les contributions volontaires en dépenses automatiquement facturées aux visiteurs.","L'absence de prix exige de financer le lieu principalement par le temps des bénévoles, sans moyens extérieurs.","Un accès gratuit peut demander des ressources pour faire fonctionner le lieu.","Une partie des recettes volontaires suffit pour déduire que l'accueil et l'entretien n'entraînent plus de frais réguliers."],"passage":"Un lieu de rencontre souhaite rester ouvert sans obligation d'achat. Pour durer, il doit néanmoins financer le local et l'accueil. Les organisateurs rendent ces coûts visibles et recherchent plusieurs soutiens. L'absence de paiement à l'entrée ne signifie pas l'absence de ressources nécessaires à l'existence du service. Le budget distingue le loyer, les charges, l'entretien et le temps des personnes qui assurent la présence sur place. Une partie peut être soutenue par la commune et une autre par des contributions volontaires ou des partenariats. Les décisions doivent toutefois préserver l'accueil des visiteurs qui ne peuvent pas donner. Les organisateurs publient donc des informations régulières sur les besoins et sur l'utilisation des aides reçues. Cette transparence permet de discuter des choix, notamment des horaires d'ouverture, sans faire peser silencieusement toute la continuité du lieu sur quelques bénévoles ou sur des dépenses personnelles invisibles. Le lieu ne facture aucun billet, mais le loyer augmente et les permanences exigent du temps de travail. Les organisateurs présentent un budget et sollicitent des soutiens qui n'imposent pas de contribution aux visiteurs.","question":"Quelle distinction économique la transparence budgétaire cherche-t-elle à faire comprendre ?","explanation":"C différencie la gratuité pour les visiteurs et les coûts pour assurer le service. A invente une facturation, B impose une source de ressources, D infère à tort une disparition des dépenses."},{"number":38,"points":33,"correct":"D","options":["Un temps non assigné représente une charge supplémentaire si aucune activité nouvelle ne vient immédiatement l'occuper.","La réserve remplace le classement des urgences, qui devient moins important quand le planning comporte des plages libres.","Une marge inscrite au calendrier limite le nombre d'incidents techniques pouvant se produire dans la semaine.","Une réserve de temps absorbe les variations de charge imprévues."],"passage":"Une équipe mesure le temps gagné par un nouvel outil et souhaite remplir immédiatement les minutes libérées. Certains salariés proposent d'en conserver une partie pour traiter les imprévus. Un planning occupé en permanence devient fragile face à la moindre variation. Une marge non affectée peut contribuer au bon fonctionnement plutôt que représenter un temps perdu. Les salariés décrivent des demandes urgentes, des absences et des problèmes techniques impossibles à prévoir précisément. Lorsque toutes les heures sont attribuées, ces événements déplacent les tâches vers la fin de journée ou obligent à abandonner une priorité sans discussion. L'équipe teste donc une réserve et observe comment elle est utilisée. Les responsables regarderont les délais, la qualité du travail et la fatigue, plutôt que le seul taux d'occupation du calendrier. Un nouveau logiciel libère trente minutes de travail quotidien; la direction les remplit immédiatement de nouvelles tâches. Au premier incident, tout le programme déborde et les heures supplémentaires augmentent.","question":"Pourquoi une réserve de temps peut-elle être productive même sans tâche assignée ?","explanation":"D reconnaît l'utilité d'une capacité d'absorption devant les imprévus. A confond réserve et dépense inutile, B remplace la priorisation, C suppose une prévention d'incidents au lieu de leur gestion."},{"number":39,"points":33,"correct":"C","options":["Maintenir l'ouverture chaque samedi tant que les demandes restent nombreuses, puis rechercher les remplaçants lorsque des absences se présentent.","Compter le prêt passé et la subvention annuelle comme deux financements récurrents avant de fixer la fréquence définitive des permanences.","Retenir provisoirement la cadence compatible avec les équipes et les ressources garanties, puis réévaluer l'extension quand le financement et les relais seront établis.","Confier le calendrier annuel aux bénévoles de l'essai puisque leur mobilisation initiale prouve qu'ils pourront assurer les permanences régulières sans nouveau financement ni formation d'équipes supplémentaires."],"passage":"Un quartier lance une initiative temporaire qui rencontre un grand succès. Les habitants veulent la prolonger, mais les bénévoles n'ont pas prévu un engagement permanent. Le projet doit être réorganisé et financé autrement. Le succès d'une expérience ne garantit pas que les conditions qui l'ont rendue possible puissent durer sans transformation. Pendant l'essai, les organisateurs avaient utilisé du matériel prêté et consacré plusieurs week-ends exceptionnels à la préparation. Ces ressources ne seront pas disponibles chaque mois. Le groupe établit donc un budget, clarifie les responsabilités et recherche des relais avant d'annoncer un calendrier durable. Les habitants seront informés des changements nécessaires, y compris d'une éventuelle réduction de fréquence. Cette préparation ne retire rien à la valeur de l'expérience initiale : elle distingue ce qu'une mobilisation ponctuelle a permis de réaliser et ce qu'une organisation régulière devra pouvoir soutenir sans épuiser les personnes qui la font vivre. Pendant l'essai, une équipe a pu utiliser des véhicules prêtés et travailler tous les samedis. Une activité permanente exigerait des véhicules financés et des remplaçants prévus dans le calendrier. Six mois après l'essai, les habitants réclament une ouverture hebdomadaire. Le collectif chiffre deux formules: chaque samedi nécessiterait deux véhicules et quatre personnes formées, alors qu'une ouverture deux fois par mois pourrait fonctionner avec un véhicule financé et une équipe de remplacement. Le nombre de demandes reste élevé dans les deux scénarios. Une subvention peut financer l'achat d'un véhicule, mais elle n'est accordée que pour un an; le prêt initial de matériel est terminé. Une partie des anciens bénévoles accepte de venir ponctuellement, pas de garantir un samedi sur deux. Deux associations proposent d'alterner les permanences à condition qu'un calendrier écrit et un budget de maintenance soient adoptés. Les organisateurs refusent de compter une promesse ponctuelle comme un engagement régulier et préfèrent annoncer une fréquence plus basse mais soutenable. Ils précisent que la satisfaction des habitants pendant l'essai ne permet ni de prévoir les disponibilités futures ni d'assurer le financement de la deuxième année.","question":"Quelle décision traduit le mieux la différence entre une forte demande et une capacité durable à assurer le service ?","explanation":"C tient compte du décalage entre la demande soutenue et les ressources vérifiables: un véhicule financé, des permanences alternées et des remplaçants dans une cadence réduite; la subvention d'un an et les disponibilités ponctuelles ne garantissent pas un fonctionnement plus fréquent. A/D prennent l'intérêt ou la mobilisation initiale pour des capacités permanentes; B assimile prêt passé et aide limitée à des financements récurrents."}]}$paper_20$::jsonb);

